//! Runtime errors surfaced by the interpreter.

use miette::Diagnostic;
use thiserror::Error;

#[derive(Debug, Error, Diagnostic)]
pub enum RuntimeError {
    #[error("undefined variable `{name}` — it is not in scope")]
    Undefined {
        name: String,
        #[label("not defined; declare it with `local` or check the spelling")]
        span: std::ops::Range<usize>,
    },

    #[error("cannot assign to undeclared variable `{name}` — use `local {name} = ...` to declare it first")]
    AssignUndeclared {
        name: String,
        #[label("declare with `local` before assigning")]
        span: std::ops::Range<usize>,
    },

    #[error("invalid assignment target")]
    InvalidAssignTarget {
        #[label("only identifiers and member/index access can be assigned to")]
        span: std::ops::Range<usize>,
    },

    #[error("type error: {message}")]
    TypeError {
        message: String,
        #[label("type mismatch or invalid operation")]
        span: std::ops::Range<usize>,
    },

    #[error("argument error: {message}")]
    ArgumentError {
        message: String,
        #[help]
        help: Option<String>,
        #[label("invalid or missing call argument")]
        span: std::ops::Range<usize>,
    },

    #[error("cannot mix `integer` and `float` in arithmetic — type mismatch")]
    NumericMix {
        #[label("convert using int() or float() to make types compatible")]
        span: std::ops::Range<usize>,
    },

    #[error("division by zero — cannot divide by 0")]
    DivisionByZero {
        #[label("ensure the divisor is not zero")]
        span: std::ops::Range<usize>,
    },

    #[error("numeric `for` loop requires a non-zero step value")]
    ZeroStep {
        #[label("step cannot be 0 — use a positive or negative number")]
        span: std::ops::Range<usize>,
    },

    #[error("`{which}` is only valid inside a loop")]
    LoopControlOutsideLoop {
        which: &'static str,
        #[label("move this inside a `for`, `while`, or `repeat` loop")]
        span: std::ops::Range<usize>,
    },

    #[error("`return` is only valid inside a function")]
    ReturnOutsideFunction {
        #[label("move this statement inside a `fn` definition")]
        span: std::ops::Range<usize>,
    },

    #[error("force-unwrapped a `nil` value")]
    #[diagnostic(help("use `??` to provide a fallback, or check with `if x != nil` before unwrapping"))]
    ForceUnwrapNil {
        #[label("this expression was `nil` when `!` was applied")]
        span: std::ops::Range<usize>,
    },

    #[error("`{thing}` is not yet implemented")]
    Unsupported {
        thing: &'static str,
        #[label("this feature will be supported in a future version")]
        span: std::ops::Range<usize>,
    },

    #[error("import error: {message}")]
    ImportError {
        message: String,
        #[label("could not resolve this import")]
        span: std::ops::Range<usize>,
    },

    /// An error that bubbled up from an imported module. Carries its own
    /// `NamedSource` so miette renders the snippet from the *imported* file
    /// rather than the importer's source. The original error is preserved
    /// as a nested `#[diagnostic_source]` so the user sees both the import
    /// site (in the parent file) and the actual offending line.
    #[error("error in imported module `{module_label}`")]
    ImportFailed {
        module_label: String,
        #[label("imported here")]
        import_span: std::ops::Range<usize>,
        #[diagnostic_source]
        inner: Box<dyn miette::Diagnostic + Send + Sync + 'static>,
    },

    /// A runtime error fired while executing code defined in an imported
    /// module *after* it had finished loading (e.g. a method called from
    /// the entry file later on). Carries the imported module's source so
    /// miette renders the snippet from the right file even though no
    /// `import` statement is on the call stack at the moment of failure.
    #[error("runtime error in `{module_label}`")]
    InModule {
        module_label: String,
        #[diagnostic_source]
        inner: Box<dyn miette::Diagnostic + Send + Sync + 'static>,
    },

    /// A `throw` expression that hasn't been caught yet. Propagates through
    /// `Result<_, RuntimeError>` until either a matching `try ... catch`
    /// captures it, or it reaches the top of the program (where it becomes
    /// an unhandled exception). The actual thrown `Value` is parked in a
    /// thread-local slot (see `crate::eval::stmt::thrown_slot`) because
    /// `RuntimeError` must be `Send + Sync` for miette.
    #[error("uncaught exception: {value}")]
    #[diagnostic(help("wrap the throwing code in `try ... catch e: <Type> ... end` to handle it"))]
    Thrown {
        /// Display form of the thrown value.
        value: String,
        #[label("uncaught `throw`")]
        span: std::ops::Range<usize>,
    },
}

/// Convenience constructor — most non-`Local`/`Expr` statements still funnel
/// through this until the matching phase lands.
pub fn unsupported(thing: &'static str, span: std::ops::Range<usize>) -> RuntimeError {
    RuntimeError::Unsupported { thing, span }
}

/// Diagnostic wrapper that carries an imported module's `NamedSource` so
/// miette renders the offending snippet from *that* file. Used as the
/// `#[diagnostic_source]` of [`RuntimeError::ImportFailed`].
#[derive(Debug, Error, Diagnostic)]
#[error("{message}")]
pub struct ImportedDiagnostic {
    /// The inner error's `Display` text (e.g. the parser/typecheck/runtime
    /// message). Shown as the primary error line.
    pub message: String,
    /// Source file the error happened in. Drives the snippet miette
    /// underlines.
    #[source_code]
    pub src: miette::NamedSource<String>,
    /// Primary offending span inside `src`.
    #[label("{label}")]
    pub span: miette::SourceSpan,
    /// Label text rendered under the span (often "here").
    pub label: String,
}

impl ImportedDiagnostic {
    /// Build an `ImportedDiagnostic` from any `miette::Diagnostic` plus the
    /// source it came from. Pulls the first label off the inner diagnostic
    /// if any, otherwise falls back to a zero-length span at the start.
    pub fn from_inner(
        inner: &dyn miette::Diagnostic,
        file_label: String,
        source_text: String,
    ) -> Self {
        let (span, label) = inner
            .labels()
            .and_then(|mut it| it.next())
            .map(|l| {
                let s: miette::SourceSpan =
                    (l.offset(), l.len()).into();
                (s, l.label().unwrap_or("here").to_string())
            })
            .unwrap_or_else(|| ((0usize, 0usize).into(), "here".to_string()));

        // Compose the message: prefer the inner's `Display`; append the
        // help text if any (so e.g. typecheck hints survive the relay).
        let mut message = inner.to_string();
        if let Some(help) = inner.help() {
            let help_str = help.to_string();
            if !help_str.is_empty() {
                message.push_str("\n  help: ");
                message.push_str(&help_str);
            }
        }

        Self {
            message,
            src: miette::NamedSource::new(file_label, source_text),
            span,
            label,
        }
    }
}

//! Runtime errors surfaced by the interpreter.
//!
//! Kept disjoint from the compile-time error families:
//!
//! * `saule_lexer::LexerError` — lexing
//! * `saule_parser::ParseError` — parsing
//! * `saule_semantic::SemanticError` — structural / control-flow / definite
//!   assignment (catches what would otherwise fire as `Undefined`,
//!   `AssignUndeclared`, `LoopControlOutsideLoop`, or `ReturnOutsideFunction`
//!   at runtime)
//! * `saule_typeck::TypeCheckError` — types, nullability, match exhaustiveness
//! * `RuntimeError` (this file) — only genuinely-dynamic failures: division
//!   by zero, force-unwrap of `nil`, uncaught `throw`, file-I/O, etc.
//!
//! A few "structural" variants (`Undefined`, `LoopControlOutsideLoop`, …)
//! are kept here as defensive guards for callers that invoke [`crate::run`]
//! directly without running the semantic pass first; the standard pipeline
//! (CLI, module loader) ensures they never fire in practice.

use miette::Diagnostic;
use thiserror::Error;

#[derive(Debug, Error, Diagnostic)]
pub enum RuntimeError {
    #[error("undefined variable `{name}` — it is not in scope")]
    Undefined {
        name: String,
        #[label("not defined; declare it with `local` or check the spelling")]
        span: std::ops::Range<usize>,
    },

    #[error("cannot assign to undeclared variable `{name}` — use `local {name} = ...` to declare it first")]
    AssignUndeclared {
        name: String,
        #[label("declare with `local` before assigning")]
        span: std::ops::Range<usize>,
    },

    #[error("invalid assignment target")]
    InvalidAssignTarget {
        #[label("only identifiers and member/index access can be assigned to")]
        span: std::ops::Range<usize>,
    },

    #[error("type error: {message}")]
    TypeError {
        message: String,
        #[label("type mismatch or invalid operation")]
        span: std::ops::Range<usize>,
    },

    #[error("argument error: {message}")]
    ArgumentError {
        message: String,
        #[help]
        help: Option<String>,
        #[label("invalid or missing call argument")]
        span: std::ops::Range<usize>,
    },

    #[error("cannot mix `integer` and `float` in arithmetic — type mismatch")]
    NumericMix {
        #[label("convert using int() or float() to make types compatible")]
        span: std::ops::Range<usize>,
    },

    #[error("division by zero — cannot divide by 0")]
    DivisionByZero {
        #[label("ensure the divisor is not zero")]
        span: std::ops::Range<usize>,
    },

    #[error("numeric `for` loop requires a non-zero step value")]
    ZeroStep {
        #[label("step cannot be 0 — use a positive or negative number")]
        span: std::ops::Range<usize>,
    },

    #[error("`{which}` is only valid inside a loop")]
    LoopControlOutsideLoop {
        which: &'static str,
        #[label("move this inside a `for`, `while`, or `repeat` loop")]
        span: std::ops::Range<usize>,
    },

    #[error("`return` is only valid inside a function")]
    ReturnOutsideFunction {
        #[label("move this statement inside a `fn` definition")]
        span: std::ops::Range<usize>,
    },

    #[error("force-unwrapped a `nil` value")]
    #[diagnostic(help("use `??` to provide a fallback, or check with `if x != nil` before unwrapping"))]
    ForceUnwrapNil {
        #[label("this expression was `nil` when `!` was applied")]
        span: std::ops::Range<usize>,
    },

    #[error("`{thing}` is not yet implemented")]
    Unsupported {
        thing: &'static str,
        #[label("this feature will be supported in a future version")]
        span: std::ops::Range<usize>,
    },

    #[error("import error: {message}")]
    ImportError {
        message: String,
        #[label("could not resolve this import")]
        span: std::ops::Range<usize>,
    },

    /// An error that bubbled up from an imported module. Carries its own
    /// `NamedSource` so miette renders the snippet from the *imported* file
    /// rather than the importer's source. The original error is preserved
    /// as a nested `#[diagnostic_source]` so the user sees both the import
    /// site (in the parent file) and the actual offending line.
    #[error("error in imported module `{module_label}`")]
    ImportFailed {
        module_label: String,
        #[label("imported here")]
        import_span: std::ops::Range<usize>,
        #[diagnostic_source]
        inner: Box<dyn miette::Diagnostic + Send + Sync + 'static>,
    },

    /// A runtime error fired while executing code defined in an imported
    /// module *after* it had finished loading (e.g. a method called from
    /// the entry file later on). Carries the imported module's source so
    /// miette renders the snippet from the right file even though no
    /// `import` statement is on the call stack at the moment of failure.
    #[error("runtime error in `{module_label}`")]
    InModule {
        module_label: String,
        #[diagnostic_source]
        inner: Box<dyn miette::Diagnostic + Send + Sync + 'static>,
    },

    /// A `throw` expression that hasn't been caught yet. Propagates through
    /// `Result<_, RuntimeError>` until either a matching `try ... catch`
    /// captures it, or it reaches the top of the program (where it becomes
    /// an unhandled exception). The actual thrown `Value` is parked in a
    /// thread-local slot (see `crate::eval::stmt::thrown_slot`) because
    /// `RuntimeError` must be `Send + Sync` for miette.
    #[error("uncaught exception: {value}")]
    #[diagnostic(help("wrap the throwing code in `try ... catch e: <Type> ... end` to handle it"))]
    Thrown {
        /// Display form of the thrown value.
        value: String,
        #[label("uncaught `throw`")]
        span: std::ops::Range<usize>,
    },
}

/// Convenience constructor — most non-`Local`/`Expr` statements still funnel
/// through this until the matching phase lands.
pub fn unsupported(thing: &'static str, span: std::ops::Range<usize>) -> RuntimeError {
    RuntimeError::Unsupported { thing, span }
}

/// Diagnostic wrapper that carries an imported module's `NamedSource` so
/// miette renders the offending snippet from *that* file. Used as the
/// `#[diagnostic_source]` of [`RuntimeError::ImportFailed`].
#[derive(Debug, Error, Diagnostic)]
#[error("{message}")]
pub struct ImportedDiagnostic {
    /// The inner error's `Display` text (e.g. the parser/typecheck/runtime
    /// message). Shown as the primary error line.
    pub message: String,
    /// Source file the error happened in. Drives the snippet miette
    /// underlines.
    #[source_code]
    pub src: miette::NamedSource<String>,
    /// Primary offending span inside `src`.
    #[label("{label}")]
    pub span: miette::SourceSpan,
    /// Label text rendered under the span (often "here").
    pub label: String,
}

impl ImportedDiagnostic {
    /// Build an `ImportedDiagnostic` from any `miette::Diagnostic` plus the
    /// source it came from. Pulls the first label off the inner diagnostic
    /// if any, otherwise falls back to a zero-length span at the start.
    pub fn from_inner(
        inner: &dyn miette::Diagnostic,
        file_label: String,
        source_text: String,
    ) -> Self {
        let (span, label) = inner
            .labels()
            .and_then(|mut it| it.next())
            .map(|l| {
                let s: miette::SourceSpan =
                    (l.offset(), l.len()).into();
                (s, l.label().unwrap_or("here").to_string())
            })
            .unwrap_or_else(|| ((0usize, 0usize).into(), "here".to_string()));

        // Compose the message: prefer the inner's `Display`; append the
        // help text if any (so e.g. typecheck hints survive the relay).
        let mut message = inner.to_string();
        if let Some(help) = inner.help() {
            let help_str = help.to_string();
            if !help_str.is_empty() {
                message.push_str("\n  help: ");
                message.push_str(&help_str);
            }
        }

        Self {
            message,
            src: miette::NamedSource::new(file_label, source_text),
            span,
            label,
        }
    }
}

//! Expression-level checks: nullable-receiver detection, private-member
//! access, native-call argument checking, lightweight type inference, and
//! the `?? != nil` style flow narrowing.

use saule_ast::{BinOp, CallArg, Expr, LambdaBody, Spanned, TableEntry, Type};

use super::TypeCheckError;
use super::funcs;
use super::matches::check_match;
use super::state::{
    Scope, class_implements, current_class, is_interface, is_subtype_named, is_type_param,
    lookup_member, with_classes, with_enums,
};
use super::stmt::{check_stmt, seed_params};
use super::to_source_span;

// ──────────────────────────────────────────────────────────────────────────────
// Expression checker — walks expressions looking for `obj.member` /
// `obj.method(...)` where `obj` has a statically-known nullable type.
// ──────────────────────────────────────────────────────────────────────────────

pub(super) fn check_expr(
    expr: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    match &expr.value {
        Expr::Member { obj, name } => {
            check_expr(obj, scope, errors);
            report_if_nullable_receiver(obj, name, scope, errors);
            report_if_private(obj, name, scope, errors);
            report_if_unknown_member(obj, name, scope, errors);
        }
        Expr::MethodCall { obj, method, args } => {
            check_expr(obj, scope, errors);
            report_if_nullable_receiver(obj, method, scope, errors);
            report_if_private(obj, method, scope, errors);
            report_if_unknown_member(obj, method, scope, errors);
            for a in args {
                check_arg(a, scope, errors);
            }
        }
        Expr::Call { callee, args } => {
            // `obj.method(args)` is parsed as Call(Member { obj, name }, args)
            // — same nullable-receiver rule applies.
            if let Expr::Member { obj, name } = &callee.value {
                check_expr(obj, scope, errors);
                report_if_nullable_receiver(obj, name, scope, errors);
                report_if_private(obj, name, scope, errors);
                report_if_unknown_member(obj, name, scope, errors);
                report_if_enum_variant_arity(obj, name, args, errors, expr.span.clone());
            } else {
                check_expr(callee, scope, errors);
                report_if_user_function_arity(callee, args, errors, expr.span.clone());
            }
            for a in args {
                check_arg(a, scope, errors);
            }
            // If the callee resolves to a known native signature, check the
            // argument types positionally. Named arguments are skipped (those
            // aren't supported on natives anyway, and they error at runtime).
            if let Some(qname) = native_callee_name(callee)
                && let Some(sig) = crate::sigs::lookup(&qname)
            {
                check_native_args(&qname, &sig, args, scope, errors, expr.span.clone());
            }
        }
        Expr::SafeMember { obj, .. } => check_expr(obj, scope, errors),
        Expr::Index { obj, index } => {
            check_expr(obj, scope, errors);
            check_expr(index, scope, errors);
        }
        Expr::Unary { rhs, .. } => check_expr(rhs, scope, errors),
        Expr::Binary { op, lhs, rhs } => {
            check_expr(lhs, scope, errors);
            check_expr(rhs, scope, errors);
            check_binary_op(*op, lhs, rhs, scope, errors);
        }
        Expr::ForceUnwrap(inner) => check_expr(inner, scope, errors),
        Expr::Table(items) => {
            for entry in items {
                match entry {
                    TableEntry::Positional(e) => check_expr(e, scope, errors),
                    TableEntry::Field { key, value } => {
                        check_expr(key, scope, errors);
                        check_expr(value, scope, errors);
                    }
                }
            }
        }
        Expr::Lambda { params, body, .. } => {
            for p in params {
                super::stmt::reject_nil_in_binding_type(&p.ty, p.span.clone(), errors);
            }
            let mut lscope = scope.clone();
            seed_params(&mut lscope, params);
            match body {
                LambdaBody::Expr(e) => check_expr(e, &lscope, errors),
                LambdaBody::Block(stmts) => {
                    for s in stmts {
                        check_stmt(s, &mut lscope, errors);
                    }
                }
            }
        }
        Expr::Match { scrutinee, arms } => {
            check_match(expr, scrutinee, arms, scope, errors);
        }
        Expr::Pipe { source, stages } => {
            check_pipe(source, stages, scope, errors);
        }
        _ => {}
    }
}

pub(super) fn check_arg(arg: &CallArg, scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    match arg {
        CallArg::Positional(e) | CallArg::Named { value: e, .. } => check_expr(e, scope, errors),
    }
}

/// Check positional arguments of a native call against the registered
/// signature. Skips named arguments (natives don't support them; the runtime
/// will surface that as an error).
///
/// Heuristics intentionally lenient:
///   * `any` and `T?` parameters accept anything (incl. nil) — they're the
///     "I'll figure it out" slots.
///   * Variadic / over-supplied calls aren't penalised when the declared
///     param list runs out — many natives accept `...rest` (variadic) which
///     isn't expressed in the sig yet.
///   * If `infer` can't produce a type for the argument, we skip silently.
pub(super) fn check_native_args(
    callee: &str,
    sig: &crate::sigs::NativeSig,
    args: &[CallArg],
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
    call_span: std::ops::Range<usize>,
) {
    // Count required positional params (every param up to the first
    // nullable / `any` is required — nullable+`any` slots are optional).
    let required: usize = sig
        .params
        .iter()
        .take_while(|p| !is_nullable(p) && !is_any(p))
        .count();
    let positional: Vec<&CallArg> = args
        .iter()
        .filter(|a| matches!(a, CallArg::Positional(_)))
        .collect();
    if positional.len() < required {
        errors.push(TypeCheckError::NativeArity {
            callee: callee.to_string(),
            expected: required,
            found: positional.len(),
            span: to_source_span(call_span.clone()),
        });
        return;
    }

    // Reject extras when the native is not variadic. Don't bail though —
    // continue checking the known positions for type mismatches.
    if sig.variadic.is_none() && positional.len() > sig.params.len() {
        errors.push(TypeCheckError::NativeArity {
            callee: callee.to_string(),
            expected: sig.params.len(),
            found: positional.len(),
            span: to_source_span(call_span),
        });
    }

    for (i, arg) in args.iter().enumerate() {
        // Pick the expected type for slot `i`:
        //   - within declared params: use `params[i]`
        //   - past the end: use the variadic element type (or stop if absent)
        let expected = match sig.params.get(i) {
            Some(t) => t,
            None => match &sig.variadic {
                Some(t) => t,
                None => break,
            },
        };
        let value_expr = match arg {
            CallArg::Positional(e) => e,
            CallArg::Named { .. } => continue,
        };
        if is_any(expected) {
            continue;
        }
        let Some(found_ty) = infer(value_expr, scope) else {
            continue;
        };
        if !types_compatible(expected, &found_ty) {
            errors.push(TypeCheckError::NativeArgTypeMismatch {
                callee: callee.to_string(),
                arg: i + 1,
                expected: type_to_string(expected),
                found: type_to_string(&found_ty),
                span: to_source_span(value_expr.span.clone()),
            });
        }
    }
}

pub(super) fn is_any(t: &Type) -> bool {
    matches!(t, Type::Named(n) if n == "any")
}

fn report_if_nullable_receiver(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(ty) = infer(obj, scope)
        && is_nullable(&ty)
    {
        errors.push(TypeCheckError::NullableMemberAccess {
            ty: type_to_string(&ty),
            member: member.to_string(),
            span: to_source_span(obj.span.clone()),
        });
    }
}

/// Reject access to `local` (private) members from outside the owning class.
/// `self.foo` is allowed only when the *owning* class of `foo` is the class
/// currently being checked — a private field inherited from a parent is
/// **not** visible to the child.
fn report_if_private(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    // Resolve the class name we're reading the member off:
    //   * `self.member` → the current class (lookup walks the parent chain).
    //   * `obj.member` where `obj` is an *instance* → infer the receiver type.
    //   * `Class.member` where the receiver is the class itself
    //     (e.g. `Bank.secret`) → use the ident directly.
    let class_name = match &obj.value {
        Expr::Self_ => match current_class() {
            Some(n) => n,
            None => return,
        },
        Expr::Ident(n) if with_classes(|reg| reg.contains_key(n)) => n.clone(),
        _ => match infer(obj, scope) {
            Some(ty) => match strip_nullable(ty) {
                Type::Named(n) => n,
                _ => return,
            },
            None => return,
        },
    };
    let Some((owning, is_private)) = lookup_member(&class_name, member) else {
        return;
    };
    if is_private && current_class().as_deref() != Some(owning.as_str()) {
        errors.push(TypeCheckError::PrivateMemberAccess {
            class: owning,
            member: member.to_string(),
            span: to_source_span(obj.span.end..obj.span.end + member.len() + 1),
        });
    }
}

/// Emit [`TypeCheckError::UnknownMember`] / [`UnknownEnumVariant`] when the
/// receiver's static type is a known class or enum but the member name
/// isn't present. Unknown receivers, generic params, primitives, and types
/// `infer` couldn't resolve are conservatively ignored so we don't generate
/// false positives.
fn report_if_unknown_member(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    // `self.super(...)` is a magic parent-ctor delegation form, not a
    // real member access. Same for the bare-receiver counterpart.
    if member == "super" {
        return;
    }

    // Resolve the receiver to either:
    //   * an enum *class* (lookup the variant) — only via a bare Ident
    //     receiver, since `Color.Red` is the access path; OR
    //   * a regular class (lookup the member, walking inheritance).
    //
    // Receivers whose inferred type is an enum-valued local (e.g.
    // `local s: Status = Status.Alive` then `s.describe()`) intentionally
    // fall through: we don't yet track enum method names statically, so
    // emitting here would generate false positives.
    let (receiver_name, is_enum_class) = match &obj.value {
        Expr::Self_ => match current_class() {
            Some(n) => (n, false),
            None => return,
        },
        Expr::Ident(n) if with_classes(|r| r.contains_key(n)) => (n.clone(), false),
        Expr::Ident(n) if with_enums(|r| r.contains_key(n)) => (n.clone(), true),
        _ => match infer(obj, scope) {
            Some(ty) => match strip_nullable(ty) {
                Type::Named(n) => {
                    if with_classes(|r| r.contains_key(&n)) {
                        (n, false)
                    } else {
                        // Enum-typed locals, primitives, generics, etc.
                        return;
                    }
                }
                _ => return,
            },
            None => return,
        },
    };

    if is_enum_class {
        let known = with_enums(|r| {
            r.get(&receiver_name).is_some_and(|info| info.variants.contains_key(member))
        });
        if !known {
            errors.push(TypeCheckError::UnknownEnumVariant {
                enum_name: receiver_name,
                variant: member.to_string(),
                span: to_source_span(obj.span.end..obj.span.end + member.len() + 1),
            });
        }
    } else if lookup_member(&receiver_name, member).is_none() {
        errors.push(TypeCheckError::UnknownMember {
            receiver: receiver_name,
            member: member.to_string(),
            span: to_source_span(obj.span.end..obj.span.end + member.len() + 1),
        });
    }
}

/// Emit [`TypeCheckError::EnumVariantArity`] for `Enum.Variant(args)` calls
/// when the variant is a known tuple-style variant with a fixed arity.
fn report_if_enum_variant_arity(
    obj: &Spanned<Expr>,
    variant: &str,
    args: &[CallArg],
    errors: &mut Vec<TypeCheckError>,
    span: std::ops::Range<usize>,
) {
    let Expr::Ident(enum_name) = &obj.value else { return };
    let Some(arity) = with_enums(|r| {
        r.get(enum_name).and_then(|info| info.variants.get(variant).copied())
    }) else {
        return;
    };
    // Arity 0 means a bare/valued variant — those aren't constructed with
    // call syntax, but we'd still error elsewhere. Skip to avoid noise.
    if arity == 0 {
        return;
    }
    if args.len() != arity {
        errors.push(TypeCheckError::EnumVariantArity {
            enum_name: enum_name.clone(),
            variant: variant.to_string(),
            expected: arity,
            found: args.len(),
            span: to_source_span(span),
        });
    }
}

/// Emit [`TypeCheckError::FunctionArity`] for direct calls to top-level
/// user-defined functions when the supplied positional-argument count
/// can't match the declared signature.
fn report_if_user_function_arity(
    callee: &Spanned<Expr>,
    args: &[CallArg],
    errors: &mut Vec<TypeCheckError>,
    span: std::ops::Range<usize>,
) {
    let Expr::Ident(name) = &callee.value else { return };
    let Some(info) = funcs::lookup(name) else { return };

    // Skip when any argument is named — those may legitimately fill in
    // defaults out of order. The runtime still validates names.
    if args.iter().any(|a| matches!(a, CallArg::Named { .. })) {
        return;
    }

    let positional = args.len();
    if info.variadic {
        // With a variadic last param, `total - 1 - defaults` is the
        // minimum required positional count.
        let min_required = info.total.saturating_sub(1).saturating_sub(info.defaults);
        if positional < min_required {
            errors.push(TypeCheckError::FunctionArity {
                callee: name.clone(),
                expected: min_required,
                found: positional,
                span: to_source_span(span),
            });
        }
        return;
    }

    let min_required = info.total.saturating_sub(info.defaults);
    if positional < min_required || positional > info.total {
        errors.push(TypeCheckError::FunctionArity {
            callee: name.clone(),
            expected: info.total,
            found: positional,
            span: to_source_span(span),
        });
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Assignment compatibility — only flags the cases we can prove are wrong.
// ──────────────────────────────────────────────────────────────────────────────

/// Reject `lhs ?? rhs` when the fallback's type is incompatible with the
/// stripped base type of the left-hand side. Stays conservative: if either
/// side's type can't be inferred, or either side is `any`, the check is
/// skipped (matches how the rest of the typechecker handles `any`).
pub(super) fn check_coalesce_fallback(
    lhs: &Spanned<Expr>,
    rhs: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let (Some(lt), Some(rt)) = (infer(lhs, scope), infer(rhs, scope)) else {
        return;
    };
    let base = strip_nullable(lt);
    // `nil` fallback collapses to `T?` and is always fine.
    if matches!(&rt, Type::Named(n) if n == "nil") {
        return;
    }
    // Literal-`nil` lhs (or any expression typed exactly as `nil`) is a
    // degenerate `??` — the fallback is always taken, so any type is
    // valid. Don't second-guess it.
    if matches!(&base, Type::Named(n) if n == "nil") {
        return;
    }
    // Don't flag when either side is `any` — that's the explicit escape
    // hatch; flagging would just spam diagnostics in dynamic code.
    if is_any(&base) || is_any(&strip_nullable(rt.clone())) {
        return;
    }
    if !types_compatible(&base, &strip_nullable(rt.clone())) {
        errors.push(TypeCheckError::CoalesceFallbackTypeMismatch {
            expected: type_to_string(&base),
            found: type_to_string(&rt),
            span: to_source_span(rhs.span.clone()),
        });
    }
}

/// True for numeric scalars: `integer`, `float`, the `number` sentinel, and
/// `any` (which acts as a wildcard).
fn is_numeric_like(ty: &Type) -> bool {
    matches!(ty, Type::Named(n) if n == "integer" || n == "float" || n == "number" || n == "any")
}

/// True for operands of `..` (string concatenation). Saule follows Lua and
/// coerces numbers to strings, so all numeric types are accepted too.
fn is_concat_like(ty: &Type) -> bool {
    is_string_like(ty) || is_numeric_like(ty)
}

/// Friendly printable name of a binary operator, used in diagnostics.
fn binop_name(op: BinOp) -> &'static str {
    match op {
        BinOp::Add => "+",
        BinOp::Sub => "-",
        BinOp::Mul => "*",
        BinOp::Div => "/",
        BinOp::Mod => "%",
        BinOp::Eq => "==",
        BinOp::NotEq => "!=",
        BinOp::Lt => "<",
        BinOp::LtEq => "<=",
        BinOp::Gt => ">",
        BinOp::GtEq => ">=",
        BinOp::And => "and",
        BinOp::Or => "or",
        BinOp::Concat => "..",
        BinOp::Coalesce => "??",
    }
}

/// Per-operator type validation. Each branch checks just enough to flag
/// obvious mistakes (string + integer, table < 5, "x" and y, etc.) while
/// staying conservative for `any`, `nil`, and uninferable expressions.
pub(super) fn check_binary_op(
    op: BinOp,
    lhs: &Spanned<Expr>,
    rhs: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    match op {
        BinOp::Coalesce => check_coalesce_fallback(lhs, rhs, scope, errors),
        BinOp::Eq | BinOp::NotEq => check_equality_compat(op, lhs, rhs, scope, errors),
        BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod => {
            let name = binop_name(op);
            check_operand_kind(name, "`integer` or `float`", is_numeric_like, lhs, scope, errors);
            check_operand_kind(name, "`integer` or `float`", is_numeric_like, rhs, scope, errors);
            check_numeric_kinds_match(lhs, rhs, scope, errors);
        }
        BinOp::And | BinOp::Or => {
            // Saule follows Lua semantics for `and`/`or`: they short-circuit
            // on truthiness and accept any value (`nil or "x"` → `"x"`),
            // so the operands aren't type-restricted.
        }
        BinOp::Concat => {
            check_operand_kind("..", "`string` or numeric", is_concat_like, lhs, scope, errors);
            check_operand_kind("..", "`string` or numeric", is_concat_like, rhs, scope, errors);
        }
        BinOp::Lt | BinOp::LtEq | BinOp::Gt | BinOp::GtEq => {
            check_ordering_operands(op, lhs, rhs, scope, errors);
        }
    }
}

/// Check that a single operand satisfies a predicate; emit if not. Stays
/// silent when inference fails, the operand is `any`, or the operand is
/// `nil` (nullable misuse is reported elsewhere).
fn check_operand_kind(
    op: &'static str,
    expected: &'static str,
    pred: impl Fn(&Type) -> bool,
    arg: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let Some(t) = infer(arg, scope) else {
        return;
    };
    let base = strip_nullable(t.clone());
    if is_any(&base) {
        return;
    }
    if matches!(&base, Type::Named(n) if n == "nil") {
        return;
    }
    if !pred(&base) {
        errors.push(TypeCheckError::BinaryOperandTypeMismatch {
            op,
            expected,
            found: type_to_string(&t),
            span: to_source_span(arg.span.clone()),
        });
    }
}

/// `<`, `<=`, `>`, `>=` require both sides to be in the same family —
/// numeric/numeric or string/string. Anything else is flagged on the side
/// that breaks the family.
fn check_ordering_operands(
    op: BinOp,
    lhs: &Spanned<Expr>,
    rhs: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let name = binop_name(op);
    // First, each side individually must be orderable (numeric or string).
    check_operand_kind(name, "`integer`, `float`, or `string`", is_orderable, lhs, scope, errors);
    check_operand_kind(name, "`integer`, `float`, or `string`", is_orderable, rhs, scope, errors);
    // Then, both sides must agree on the family.
    let (Some(lt), Some(rt)) = (infer(lhs, scope), infer(rhs, scope)) else {
        return;
    };
    let lb = strip_nullable(lt.clone());
    let rb = strip_nullable(rt.clone());
    if is_any(&lb) || is_any(&rb) {
        return;
    }
    if matches!(&lb, Type::Named(n) if n == "nil")
        || matches!(&rb, Type::Named(n) if n == "nil")
    {
        return;
    }
    let l_num = is_numeric_like(&lb);
    let r_num = is_numeric_like(&rb);
    let l_str = is_string_like(&lb);
    let r_str = is_string_like(&rb);
    let same_family = (l_num && r_num) || (l_str && r_str);
    if !same_family && (l_num || l_str) && (r_num || r_str) {
        // Both individually orderable but in different families — flag rhs
        // with the lhs family as the expected one.
        let expected = if l_num {
            "`integer` or `float`"
        } else {
            "`string`"
        };
        errors.push(TypeCheckError::BinaryOperandTypeMismatch {
            op: name,
            expected,
            found: type_to_string(&rt),
            span: to_source_span(rhs.span.clone()),
        });
    }
}

fn is_orderable(ty: &Type) -> bool {
    is_numeric_like(ty) || is_string_like(ty)
}

/// Saule is strict on numeric kinds — `integer` and `float` never mix
/// implicitly. When both operands have a known *concrete* numeric kind
/// (i.e. not the `number` sentinel, not `any`, not generic), flag the
/// pair when they disagree. The error mirrors `RuntimeError::NumericMix`
/// so the user sees the same diagnostic at compile time.
fn check_numeric_kinds_match(
    lhs: &Spanned<Expr>,
    rhs: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let (Some(lt), Some(rt)) = (infer(lhs, scope), infer(rhs, scope)) else {
        return;
    };
    let lb = strip_nullable(lt);
    let rb = strip_nullable(rt);
    let kind = |t: &Type| -> Option<&'static str> {
        if let Type::Named(n) = t {
            match n.as_str() {
                "integer" => Some("integer"),
                "float" => Some("float"),
                _ => None,
            }
        } else {
            None
        }
    };
    let (Some(lk), Some(rk)) = (kind(&lb), kind(&rb)) else {
        return;
    };
    if lk != rk {
        // Span covers both sides so the underline brackets the whole
        // expression — matches the runtime diagnostic.
        let span_start = lhs.span.start.min(rhs.span.start);
        let span_end = lhs.span.end.max(rhs.span.end);
        errors.push(TypeCheckError::NumericMix {
            span: to_source_span(span_start..span_end),
        });
    }
}

/// Reject equality comparisons whose two sides have provably-disjoint
/// types (e.g. comparing a `table?` value to a string literal). Skips when
/// either side involves `any` or `nil`, since `T? == nil` is the idiomatic
/// nullability check.
pub(super) fn check_equality_compat(
    op: BinOp,
    lhs: &Spanned<Expr>,
    rhs: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let (Some(lt), Some(rt)) = (infer(lhs, scope), infer(rhs, scope)) else {
        return;
    };
    let lb = strip_nullable(lt.clone());
    let rb = strip_nullable(rt.clone());
    // `nil` on either side is legitimate — `x == nil` is how you check
    // nullability.
    if matches!(&lb, Type::Named(n) if n == "nil")
        || matches!(&rb, Type::Named(n) if n == "nil")
    {
        return;
    }
    if is_any(&lb) || is_any(&rb) {
        return;
    }
    // Compatible in either direction → OK.
    if types_compatible(&lb, &rb) || types_compatible(&rb, &lb) {
        return;
    }
    let result = if matches!(op, BinOp::Eq) { "false" } else { "true" };
    // Span covers both sides.
    let span_start = lhs.span.start.min(rhs.span.start);
    let span_end = lhs.span.end.max(rhs.span.end);
    errors.push(TypeCheckError::DisjointEquality {
        left: type_to_string(&lt),
        right: type_to_string(&rt),
        result,
        span: to_source_span(span_start..span_end),
    });
}

pub(super) fn check_assignment_compat(
    decl_ty: &Type,
    value: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    // When the value is `lhs ?? rhs`, the declared type tells us what the
    // whole expression is supposed to produce — use its stripped base as
    // the expected type for the fallback. This catches mismatches even
    // when `lhs` has lost type info (e.g. returns `any?`).
    if let Expr::Binary { op: BinOp::Coalesce, rhs, .. } = &value.value {
        let expected_base = strip_nullable(decl_ty.clone());
        if !matches!(&expected_base, Type::Named(n) if n == "nil" || n == "any")
            && let Some(rt) = infer(rhs, scope)
        {
            let rt_base = strip_nullable(rt.clone());
            let rt_is_nil = matches!(&rt_base, Type::Named(n) if n == "nil");
            let rt_is_any = is_any(&rt_base);
            if !rt_is_nil && !rt_is_any && !types_compatible(&expected_base, &rt_base) {
                errors.push(TypeCheckError::CoalesceFallbackTypeMismatch {
                    expected: type_to_string(&expected_base),
                    found: type_to_string(&rt),
                    span: to_source_span(rhs.span.clone()),
                });
            }
        }
    }

    if is_nullable(decl_ty) {
        return;
    }
    if matches!(value.value, Expr::Nil) {
        errors.push(TypeCheckError::NilToNonNullable {
            ty: type_to_string(decl_ty),
            span: to_source_span(value.span.clone()),
        });
        return;
    }

    // Table-aware checks for table literals assigned to a typed table.
    // Splits the literal into its positional and field halves so each can
    // be validated against the declared table shape independently.
    if let (Type::Table { key, value: elem_ty }, Expr::Table(items)) = (decl_ty, &value.value) {
        let has_positional = items.iter().any(|e| matches!(e, TableEntry::Positional(_)));
        let has_field = items.iter().any(|e| matches!(e, TableEntry::Field { .. }));

        // `{a, b, c}` literal cannot fill a map-typed table whose key is not
        // integer-compatible.
        if let Some(k) = key
            && !is_integer_like(k)
            && has_positional
        {
            errors.push(TypeCheckError::TableArrayLiteralForMap {
                key: type_to_string(k),
                value: type_to_string(elem_ty),
                span: to_source_span(value.span.clone()),
            });
            return;
        }
        // Field entries (`name: ...`) require the table to declare a key
        // type compatible with `string`. Array-typed `table<T>` rejects them.
        if has_field {
            let key_ok = match key {
                None => false,
                Some(k) => is_string_like(k),
            };
            if !key_ok {
                errors.push(TypeCheckError::TableArrayLiteralForMap {
                    key: key.as_deref().map(type_to_string).unwrap_or_else(|| "integer".to_string()),
                    value: type_to_string(elem_ty),
                    span: to_source_span(value.span.clone()),
                });
                return;
            }
        }
        // Each value must match the declared value type.
        for item in items {
            match item {
                TableEntry::Positional(e) | TableEntry::Field { value: e, .. } => {
                    check_element_compat(elem_ty, e, scope, errors);
                }
            }
        }
        return;
    }

    if let Some(value_ty) = infer(value, scope)
        && is_nullable(&value_ty)
    {
        errors.push(TypeCheckError::NullableToNonNullable {
            from: type_to_string(&value_ty),
            to: type_to_string(decl_ty),
            span: to_source_span(value.span.clone()),
        });
    }
}

/// Index key must match the table's declared key type.
pub(super) fn check_table_key_compat(
    expected: &Type,
    index: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(idx_ty) = infer(index, scope)
        && !types_compatible(expected, &idx_ty)
    {
        errors.push(TypeCheckError::TableKeyTypeMismatch {
            expected: type_to_string(expected),
            found: type_to_string(&idx_ty),
            span: to_source_span(index.span.clone()),
        });
    }
}

/// True for `integer` and `any` — the key types that an array-style literal
/// can satisfy.
fn is_integer_like(ty: &Type) -> bool {
    matches!(ty, Type::Named(n) if n == "integer" || n == "any")
}

/// True for `string` and `any` — the key types that a field-style literal
/// (`name: expr` / `"text": expr`) can satisfy.
fn is_string_like(ty: &Type) -> bool {
    matches!(ty, Type::Named(n) if n == "string" || n == "any")
}

/// Element-of-table compatibility — accepts literals/`Ident`s whose inferred
/// type matches, and stays quiet otherwise (conservative).
pub(super) fn check_element_compat(
    expected: &Type,
    value: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(value_ty) = infer(value, scope)
        && !types_compatible(expected, &value_ty)
    {
        errors.push(TypeCheckError::TableElementTypeMismatch {
            expected: type_to_string(expected),
            found: type_to_string(&value_ty),
            span: to_source_span(value.span.clone()),
        });
    }
}

/// Conservative type compatibility — names match (or either is `any`), or
/// `value_ty` is `Nullable` of a compatible inner, etc.
pub(super) fn types_compatible(expected: &Type, value_ty: &Type) -> bool {
    // Suppress `is_interface` unused-warning when state moves; reference here.
    let _ = is_interface;
    match (expected, value_ty) {
        // Same-name primitives, plus `any` on either side, plus `nil` on the
        // value side (nil is universally assignable; nullable-rejection is
        // handled separately by `NullableToNonNullable`).
        (Type::Named(a), Type::Named(b)) => {
            if a == b || a == "any" || b == "any" || b == "nil" {
                return true;
            }
            // Generic type parameters in scope match anything — they're
            // effectively `any` from the body's point of view.
            if is_type_param(a) || is_type_param(b) {
                return true;
            }
            // `number` is the sentinel used in native sigs to mean
            // "integer or float" — accept either.
            if a == "number" && (b == "integer" || b == "float" || b == "number") {
                return true;
            }
            // Class/interface subtyping: a value of type `b` is assignable to
            // a slot of type `a` if `b` is a subtype of `a` (class implements
            // interface, class extends class, interface extends interface).
            if is_subtype_named(b, a) {
                let _ = class_implements; // keep import even if unused later
                return true;
            }
            false
        }
        // `table<any>` (or `table<any, any>`) matches any table — used by
        // native sigs like `Table.insert(t, ...)` to mean "any table".
        (
            Type::Table { key: ek, value: ev },
            Type::Table { key: vk, value: vv },
        ) => {
            let key_ok = match (ek, vk) {
                (None, None) => true,
                (Some(a), Some(b)) => types_compatible(a, b),
                // Cross-shape (`table<T>` vs `table<K, V>`) only when one
                // side is the `any` wildcard.
                _ => is_any(ev),
            };
            key_ok && (is_any(ev) || types_compatible(ev, vv))
        }
        // Expected table, but value is the bare type-name `table`, `any` or
        // `nil` — accept (caller has erased the element type, or it's nil).
        (Type::Table { .. }, Type::Named(n)) if n == "table" || n == "any" || n == "nil" => true,
        // Expected `any` / `table` / `nil` named slot, value is a table —
        // accept (we widen to the named slot).
        (Type::Named(n), Type::Table { .. }) if n == "table" || n == "any" => true,
        (Type::Nullable(a), b) => types_compatible(a, b),
        (a, Type::Nullable(b)) => types_compatible(a, b),
        // Function / Tuple shapes — only equal-shape is strictly compatible,
        // but the checker doesn't track those precisely yet. Accept rather
        // than emit false positives.
        (Type::Function { .. }, Type::Function { .. }) => true,
        (Type::Tuple(_), Type::Tuple(_)) => true,
        // Different kinds (e.g. table vs integer) — reject.
        _ => false,
    }
}

/// Reject `if`/`while`/`until` conditions that the type system can prove are
/// not `boolean`. Conservative: when `infer` can't determine a type, we skip
/// silently so calls and dynamic expressions keep working.
pub(super) fn check_boolean_cond(
    construct: &'static str,
    cond: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let Some(ty) = infer(cond, scope) else {
        return;
    };
    let is_bool = matches!(&ty, Type::Named(n) if n == "boolean" || n == "any");
    if !is_bool {
        errors.push(TypeCheckError::NonBooleanCondition {
            construct,
            found: type_to_string(&ty),
            span: to_source_span(cond.span.clone()),
        });
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Lightweight type inference.
//
// Returns `Some(ty)` only when we can prove the type. Anything we can't see
// through (calls, member reads on unknown classes, indexing) returns `None`,
// and callers treat that as "don't know, don't complain".
// ──────────────────────────────────────────────────────────────────────────────

pub(super) fn infer(expr: &Spanned<Expr>, scope: &Scope) -> Option<Type> {
    match &expr.value {
        Expr::Nil => Some(Type::Named("nil".into())),
        Expr::Int(_) => Some(Type::Named("integer".into())),
        Expr::Float(_) => Some(Type::Named("float".into())),
        Expr::Bool(_) => Some(Type::Named("boolean".into())),
        Expr::Str(_) => Some(Type::Named("string".into())),
        Expr::Ident(n) => scope.lookup(n).cloned(),
        Expr::SafeMember { .. } => Some(Type::Nullable(Box::new(Type::Named("any".into())))),
        Expr::ForceUnwrap(inner) => match infer(inner, scope)? {
            Type::Nullable(t) => Some(*t),
            other => Some(other),
        },
        Expr::Binary { op, lhs, rhs } => match op {
            BinOp::Coalesce => {
                // `lhs ?? rhs`: result is non-nullable iff `rhs` is non-nullable.
                match (infer(lhs, scope), infer(rhs, scope)) {
                    (Some(lt), Some(rt)) => {
                        let base = strip_nullable(lt);
                        if is_nullable(&rt) {
                            Some(Type::Nullable(Box::new(base)))
                        } else {
                            Some(base)
                        }
                    }
                    _ => None,
                }
            }
            BinOp::Eq | BinOp::NotEq | BinOp::Lt | BinOp::LtEq | BinOp::Gt | BinOp::GtEq => {
                Some(Type::Named("boolean".into()))
            }
            BinOp::And | BinOp::Or => None,
            BinOp::Concat => Some(Type::Named("string".into())),
            BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod => {
                infer(lhs, scope).or_else(|| infer(rhs, scope))
            }
        },
        // `Foo(args)` where `Foo` is a known class → produces a `Foo`.
        // Otherwise, look up the qualified callee name in:
        //   1. the local class registry as a user-defined method
        //      (`Foo.bar(...)` → return type of `Foo.bar`); or
        //   2. the native signature table (`String.byte`, `Math.tointeger`,
        //      `assert`).
        Expr::Call { callee, .. } => {
            if let Expr::Ident(n) = &callee.value
                && with_classes(|reg| reg.contains_key(n))
            {
                return Some(Type::Named(n.clone()));
            }
            // `Class.method(args)` — receiver is the class itself.
            if let Expr::Member { obj, name } = &callee.value
                && let Expr::Ident(class_name) = &obj.value
                && let Some(sig) = saule_semantic::lookup_method(class_name, name)
            {
                return sig.return_ty;
            }
            // `instance.method(args)` — receiver inferred to a class.
            if let Expr::Member { obj, name } = &callee.value
                && let Some(ty) = infer(obj, scope)
                && let Type::Named(class_name) = strip_nullable(ty)
                && let Some(sig) = saule_semantic::lookup_method(&class_name, name)
            {
                return sig.return_ty;
            }
            if let Some(qname) = native_callee_name(callee)
                && let Some(sig) = crate::sigs::lookup(&qname)
            {
                return first_or_tuple(sig.returns);
            }
            None
        }
        // `obj:method(args)` — same lookup as the `obj.method(args)` case.
        Expr::MethodCall { obj, method, .. } => {
            if let Some(ty) = infer(obj, scope)
                && let Type::Named(class_name) = strip_nullable(ty)
                && let Some(sig) = saule_semantic::lookup_method(&class_name, method)
            {
                return sig.return_ty;
            }
            None
        }
        // A `match` expression has the type of its (unified) arm bodies. We
        // only need an approximation, so return the first arm-body type we
        // can infer.
        Expr::Match { arms, .. } => arms.iter().find_map(|a| match &a.body {
            saule_ast::MatchBody::Expr(e) => infer(e, scope),
            saule_ast::MatchBody::Block(_) => None,
        }),
        _ => None,
    }
}

pub(super) fn strip_nullable(ty: Type) -> Type {
    match ty {
        Type::Nullable(t) => *t,
        other => other,
    }
}

/// Build a qualified callee name suitable for `stdlib::sigs::lookup`:
/// `assert` or `String.byte`.
fn native_callee_name(callee: &Spanned<Expr>) -> Option<String> {
    match &callee.value {
        Expr::Ident(n) => Some(n.clone()),
        Expr::Member { obj, name } => {
            if let Expr::Ident(class) = &obj.value {
                Some(format!("{class}.{name}"))
            } else {
                None
            }
        }
        _ => None,
    }
}

/// Collapse a returns-list into a single inferred type: single returns stay
/// as-is, multi-returns become a `Type::Tuple`.
fn first_or_tuple(returns: Vec<Type>) -> Option<Type> {
    match returns.len() {
        0 => None,
        1 => returns.into_iter().next(),
        _ => Some(Type::Tuple(returns)),
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Flow narrowing.
//
// `narrow_truthy(cond, scope)` — apply the assumptions that hold when `cond`
// is true. Today: `x != nil` and `nil != x` strip `Nullable` off `x`. `and`
// chains compose.
//
// `narrow_falsy(cond, scope)` — apply the assumptions when `cond` is false.
// Used by the else-branch: `if x == nil then ... else ... end` narrows `x`
// in the else.
// ──────────────────────────────────────────────────────────────────────────────

pub(super) fn narrow_truthy(cond: &Spanned<Expr>, scope: &mut Scope) {
    match &cond.value {
        Expr::Binary {
            op: BinOp::NotEq,
            lhs,
            rhs,
        } => {
            if let Some(name) = pick_ident_compared_to_nil(lhs, rhs)
                && let Some(Type::Nullable(t)) = scope.lookup(name).cloned()
            {
                scope.bind(name.to_string(), *t);
            }
        }
        Expr::Binary {
            op: BinOp::And,
            lhs,
            rhs,
        } => {
            narrow_truthy(lhs, scope);
            narrow_truthy(rhs, scope);
        }
        _ => {}
    }
}

pub(super) fn narrow_falsy(cond: &Spanned<Expr>, scope: &mut Scope) {
    if let Expr::Binary {
        op: BinOp::Eq,
        lhs,
        rhs,
    } = &cond.value
        && let Some(name) = pick_ident_compared_to_nil(lhs, rhs)
        && let Some(Type::Nullable(t)) = scope.lookup(name).cloned()
    {
        scope.bind(name.to_string(), *t);
    }
}

/// If `lhs` / `rhs` is `(Ident(x), Nil)` in either order, return `Some(x)`.
fn pick_ident_compared_to_nil<'a>(
    lhs: &'a Spanned<Expr>,
    rhs: &'a Spanned<Expr>,
) -> Option<&'a str> {
    match (&lhs.value, &rhs.value) {
        (Expr::Ident(n), Expr::Nil) => Some(n),
        (Expr::Nil, Expr::Ident(n)) => Some(n),
        _ => None,
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Misc helpers.
// ──────────────────────────────────────────────────────────────────────────────

pub(super) fn type_to_string(ty: &Type) -> String {
    match ty {
        Type::Named(n) => n.clone(),
        Type::Nullable(inner) => format!("{}?", type_to_string(inner)),
        Type::Table { key: None, value } => format!("table<{}>", type_to_string(value)),
        Type::Table {
            key: Some(k),
            value,
        } => format!("table<{}, {}>", type_to_string(k), type_to_string(value)),
        other => format!("{:?}", other),
    }
}

pub(super) fn is_nullable(ty: &Type) -> bool {
    match ty {
        Type::Nullable(_) => true,
        Type::Named(n) => n == "nil",
        _ => false,
    }
}

//! Expression-level checks: nullable-receiver detection, private-member
//! access, native-call argument checking, lightweight type inference, and
//! the `?? != nil` style flow narrowing.

use saule_ast::{BinOp, CallArg, Expr, LambdaBody, PipeStage, Spanned, TableEntry, Type};

use super::TypeCheckError;
use super::funcs;
use super::matches::check_match;
use super::state::{
    Scope, class_implements, current_class, is_interface, is_subtype_named, is_type_param,
    lookup_member, with_classes, with_enums,
};
use super::stmt::{check_stmt, seed_params};
use super::to_source_span;

// ──────────────────────────────────────────────────────────────────────────────
// Expression checker — walks expressions looking for `obj.member` /
// `obj.method(...)` where `obj` has a statically-known nullable type.
// ──────────────────────────────────────────────────────────────────────────────

pub(super) fn check_expr(
    expr: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    match &expr.value {
        Expr::Member { obj, name } => {
            check_expr(obj, scope, errors);
            report_if_nullable_receiver(obj, name, scope, errors);
            report_if_private(obj, name, scope, errors);
            report_if_unknown_member(obj, name, scope, errors);
        }
        Expr::MethodCall { obj, method, args } => {
            check_expr(obj, scope, errors);
            report_if_nullable_receiver(obj, method, scope, errors);
            report_if_private(obj, method, scope, errors);
            report_if_unknown_member(obj, method, scope, errors);
            for a in args {
                check_arg(a, scope, errors);
            }
        }
        Expr::Call { callee, args } => {
            // `obj.method(args)` is parsed as Call(Member { obj, name }, args)
            // — same nullable-receiver rule applies.
            if let Expr::Member { obj, name } = &callee.value {
                check_expr(obj, scope, errors);
                report_if_nullable_receiver(obj, name, scope, errors);
                report_if_private(obj, name, scope, errors);
                report_if_unknown_member(obj, name, scope, errors);
                report_if_enum_variant_arity(obj, name, args, errors, expr.span.clone());
            } else {
                check_expr(callee, scope, errors);
                report_if_user_function_arity(callee, args, errors, expr.span.clone());
            }
            for a in args {
                check_arg(a, scope, errors);
            }
            // If the callee resolves to a known native signature, check the
            // argument types positionally. Named arguments are skipped (those
            // aren't supported on natives anyway, and they error at runtime).
            if let Some(qname) = native_callee_name(callee)
                && let Some(sig) = crate::sigs::lookup(&qname)
            {
                check_native_args(&qname, &sig, args, scope, errors, expr.span.clone());
            }
        }
        Expr::SafeMember { obj, .. } => check_expr(obj, scope, errors),
        Expr::Index { obj, index } => {
            check_expr(obj, scope, errors);
            check_expr(index, scope, errors);
        }
        Expr::Unary { rhs, .. } => check_expr(rhs, scope, errors),
        Expr::Binary { op, lhs, rhs } => {
            check_expr(lhs, scope, errors);
            check_expr(rhs, scope, errors);
            check_binary_op(*op, lhs, rhs, scope, errors);
        }
        Expr::ForceUnwrap(inner) => check_expr(inner, scope, errors),
        Expr::Table(items) => {
            for entry in items {
                match entry {
                    TableEntry::Positional(e) => check_expr(e, scope, errors),
                    TableEntry::Field { key, value } => {
                        check_expr(key, scope, errors);
                        check_expr(value, scope, errors);
                    }
                }
            }
        }
        Expr::Lambda { params, body, .. } => {
            for p in params {
                super::stmt::reject_nil_in_binding_type(&p.ty, p.span.clone(), errors);
            }
            let mut lscope = scope.clone();
            seed_params(&mut lscope, params);
            match body {
                LambdaBody::Expr(e) => check_expr(e, &lscope, errors),
                LambdaBody::Block(stmts) => {
                    for s in stmts {
                        check_stmt(s, &mut lscope, errors);
                    }
                }
            }
        }
        Expr::Match { scrutinee, arms } => {
            check_match(expr, scrutinee, arms, scope, errors);
        }
        Expr::Pipe { source, stages } => {
            check_pipe(source, stages, scope, errors);
        }
        _ => {}
    }
}

pub(super) fn check_arg(arg: &CallArg, scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    match arg {
        CallArg::Positional(e) | CallArg::Named { value: e, .. } => check_expr(e, scope, errors),
    }
}

/// Check positional arguments of a native call against the registered
/// signature. Skips named arguments (natives don't support them; the runtime
/// will surface that as an error).
///
/// Heuristics intentionally lenient:
///   * `any` and `T?` parameters accept anything (incl. nil) — they're the
///     "I'll figure it out" slots.
///   * Variadic / over-supplied calls aren't penalised when the declared
///     param list runs out — many natives accept `...rest` (variadic) which
///     isn't expressed in the sig yet.
///   * If `infer` can't produce a type for the argument, we skip silently.
pub(super) fn check_native_args(
    callee: &str,
    sig: &crate::sigs::NativeSig,
    args: &[CallArg],
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
    call_span: std::ops::Range<usize>,
) {
    // Count required positional params (every param up to the first
    // nullable / `any` is required — nullable+`any` slots are optional).
    let required: usize = sig
        .params
        .iter()
        .take_while(|p| !is_nullable(p) && !is_any(p))
        .count();
    let positional: Vec<&CallArg> = args
        .iter()
        .filter(|a| matches!(a, CallArg::Positional(_)))
        .collect();
    if positional.len() < required {
        errors.push(TypeCheckError::NativeArity {
            callee: callee.to_string(),
            expected: required,
            found: positional.len(),
            span: to_source_span(call_span.clone()),
        });
        return;
    }

    // Reject extras when the native is not variadic. Don't bail though —
    // continue checking the known positions for type mismatches.
    if sig.variadic.is_none() && positional.len() > sig.params.len() {
        errors.push(TypeCheckError::NativeArity {
            callee: callee.to_string(),
            expected: sig.params.len(),
            found: positional.len(),
            span: to_source_span(call_span),
        });
    }

    for (i, arg) in args.iter().enumerate() {
        // Pick the expected type for slot `i`:
        //   - within declared params: use `params[i]`
        //   - past the end: use the variadic element type (or stop if absent)
        let expected = match sig.params.get(i) {
            Some(t) => t,
            None => match &sig.variadic {
                Some(t) => t,
                None => break,
            },
        };
        let value_expr = match arg {
            CallArg::Positional(e) => e,
            CallArg::Named { .. } => continue,
        };
        if is_any(expected) {
            continue;
        }
        let Some(found_ty) = infer(value_expr, scope) else {
            continue;
        };
        if !types_compatible(expected, &found_ty) {
            errors.push(TypeCheckError::NativeArgTypeMismatch {
                callee: callee.to_string(),
                arg: i + 1,
                expected: type_to_string(expected),
                found: type_to_string(&found_ty),
                span: to_source_span(value_expr.span.clone()),
            });
        }
    }
}

pub(super) fn is_any(t: &Type) -> bool {
    matches!(t, Type::Named(n) if n == "any")
}

fn report_if_nullable_receiver(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(ty) = infer(obj, scope)
        && is_nullable(&ty)
    {
        errors.push(TypeCheckError::NullableMemberAccess {
            ty: type_to_string(&ty),
            member: member.to_string(),
            span: to_source_span(obj.span.clone()),
        });
    }
}

/// Reject access to `local` (private) members from outside the owning class.
/// `self.foo` is allowed only when the *owning* class of `foo` is the class
/// currently being checked — a private field inherited from a parent is
/// **not** visible to the child.
fn report_if_private(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    // Resolve the class name we're reading the member off:
    //   * `self.member` → the current class (lookup walks the parent chain).
    //   * `obj.member` where `obj` is an *instance* → infer the receiver type.
    //   * `Class.member` where the receiver is the class itself
    //     (e.g. `Bank.secret`) → use the ident directly.
    let class_name = match &obj.value {
        Expr::Self_ => match current_class() {
            Some(n) => n,
            None => return,
        },
        Expr::Ident(n) if with_classes(|reg| reg.contains_key(n)) => n.clone(),
        _ => match infer(obj, scope) {
            Some(ty) => match strip_nullable(ty) {
                Type::Named(n) => n,
                _ => return,
            },
            None => return,
        },
    };
    let Some((owning, is_private)) = lookup_member(&class_name, member) else {
        return;
    };
    if is_private && current_class().as_deref() != Some(owning.as_str()) {
        errors.push(TypeCheckError::PrivateMemberAccess {
            class: owning,
            member: member.to_string(),
            span: to_source_span(obj.span.end..obj.span.end + member.len() + 1),
        });
    }
}

/// Emit [`TypeCheckError::UnknownMember`] / [`UnknownEnumVariant`] when the
/// receiver's static type is a known class or enum but the member name
/// isn't present. Unknown receivers, generic params, primitives, and types
/// `infer` couldn't resolve are conservatively ignored so we don't generate
/// false positives.
fn report_if_unknown_member(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    // `self.super(...)` is a magic parent-ctor delegation form, not a
    // real member access. Same for the bare-receiver counterpart.
    if member == "super" {
        return;
    }

    // Resolve the receiver to either:
    //   * an enum *class* (lookup the variant) — only via a bare Ident
    //     receiver, since `Color.Red` is the access path; OR
    //   * a regular class (lookup the member, walking inheritance).
    //
    // Receivers whose inferred type is an enum-valued local (e.g.
    // `local s: Status = Status.Alive` then `s.describe()`) intentionally
    // fall through: we don't yet track enum method names statically, so
    // emitting here would generate false positives.
    let (receiver_name, is_enum_class) = match &obj.value {
        Expr::Self_ => match current_class() {
            Some(n) => (n, false),
            None => return,
        },
        Expr::Ident(n) if with_classes(|r| r.contains_key(n)) => (n.clone(), false),
        Expr::Ident(n) if with_enums(|r| r.contains_key(n)) => (n.clone(), true),
        _ => match infer(obj, scope) {
            Some(ty) => match strip_nullable(ty) {
                Type::Named(n) => {
                    if with_classes(|r| r.contains_key(&n)) {
                        (n, false)
                    } else {
                        // Enum-typed locals, primitives, generics, etc.
                        return;
                    }
                }
                _ => return,
            },
            None => return,
        },
    };

    if is_enum_class {
        let known = with_enums(|r| {
            r.get(&receiver_name).is_some_and(|info| info.variants.contains_key(member))
        });
        if !known {
            errors.push(TypeCheckError::UnknownEnumVariant {
                enum_name: receiver_name,
                variant: member.to_string(),
                span: to_source_span(obj.span.end..obj.span.end + member.len() + 1),
            });
        }
    } else if lookup_member(&receiver_name, member).is_none() {
        errors.push(TypeCheckError::UnknownMember {
            receiver: receiver_name,
            member: member.to_string(),
            span: to_source_span(obj.span.end..obj.span.end + member.len() + 1),
        });
    }
}

/// Emit [`TypeCheckError::EnumVariantArity`] for `Enum.Variant(args)` calls
/// when the variant is a known tuple-style variant with a fixed arity.
fn report_if_enum_variant_arity(
    obj: &Spanned<Expr>,
    variant: &str,
    args: &[CallArg],
    errors: &mut Vec<TypeCheckError>,
    span: std::ops::Range<usize>,
) {
    let Expr::Ident(enum_name) = &obj.value else { return };
    let Some(arity) = with_enums(|r| {
        r.get(enum_name).and_then(|info| info.variants.get(variant).copied())
    }) else {
        return;
    };
    // Arity 0 means a bare/valued variant — those aren't constructed with
    // call syntax, but we'd still error elsewhere. Skip to avoid noise.
    if arity == 0 {
        return;
    }
    if args.len() != arity {
        errors.push(TypeCheckError::EnumVariantArity {
            enum_name: enum_name.clone(),
            variant: variant.to_string(),
            expected: arity,
            found: args.len(),
            span: to_source_span(span),
        });
    }
}

/// Emit [`TypeCheckError::FunctionArity`] for direct calls to top-level
/// user-defined functions when the supplied positional-argument count
/// can't match the declared signature.
fn report_if_user_function_arity(
    callee: &Spanned<Expr>,
    args: &[CallArg],
    errors: &mut Vec<TypeCheckError>,
    span: std::ops::Range<usize>,
) {
    let Expr::Ident(name) = &callee.value else { return };
    let Some(info) = funcs::lookup(name) else { return };

    // Skip when any argument is named — those may legitimately fill in
    // defaults out of order. The runtime still validates names.
    if args.iter().any(|a| matches!(a, CallArg::Named { .. })) {
        return;
    }

    let positional = args.len();
    if info.variadic {
        // With a variadic last param, `total - 1 - defaults` is the
        // minimum required positional count.
        let min_required = info.total.saturating_sub(1).saturating_sub(info.defaults);
        if positional < min_required {
            errors.push(TypeCheckError::FunctionArity {
                callee: name.clone(),
                expected: min_required,
                found: positional,
                span: to_source_span(span),
            });
        }
        return;
    }

    let min_required = info.total.saturating_sub(info.defaults);
    if positional < min_required || positional > info.total {
        errors.push(TypeCheckError::FunctionArity {
            callee: name.clone(),
            expected: info.total,
            found: positional,
            span: to_source_span(span),
        });
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Assignment compatibility — only flags the cases we can prove are wrong.
// ──────────────────────────────────────────────────────────────────────────────

/// Reject `lhs ?? rhs` when the fallback's type is incompatible with the
/// stripped base type of the left-hand side. Stays conservative: if either
/// side's type can't be inferred, or either side is `any`, the check is
/// skipped (matches how the rest of the typechecker handles `any`).
pub(super) fn check_coalesce_fallback(
    lhs: &Spanned<Expr>,
    rhs: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let (Some(lt), Some(rt)) = (infer(lhs, scope), infer(rhs, scope)) else {
        return;
    };
    let base = strip_nullable(lt);
    // `nil` fallback collapses to `T?` and is always fine.
    if matches!(&rt, Type::Named(n) if n == "nil") {
        return;
    }
    // Literal-`nil` lhs (or any expression typed exactly as `nil`) is a
    // degenerate `??` — the fallback is always taken, so any type is
    // valid. Don't second-guess it.
    if matches!(&base, Type::Named(n) if n == "nil") {
        return;
    }
    // Don't flag when either side is `any` — that's the explicit escape
    // hatch; flagging would just spam diagnostics in dynamic code.
    if is_any(&base) || is_any(&strip_nullable(rt.clone())) {
        return;
    }
    if !types_compatible(&base, &strip_nullable(rt.clone())) {
        errors.push(TypeCheckError::CoalesceFallbackTypeMismatch {
            expected: type_to_string(&base),
            found: type_to_string(&rt),
            span: to_source_span(rhs.span.clone()),
        });
    }
}

/// True for numeric scalars: `integer`, `float`, the `number` sentinel, and
/// `any` (which acts as a wildcard).
fn is_numeric_like(ty: &Type) -> bool {
    matches!(ty, Type::Named(n) if n == "integer" || n == "float" || n == "number" || n == "any")
}

/// True for operands of `..` (string concatenation). Saule follows Lua and
/// coerces numbers to strings, so all numeric types are accepted too.
fn is_concat_like(ty: &Type) -> bool {
    is_string_like(ty) || is_numeric_like(ty)
}

/// Friendly printable name of a binary operator, used in diagnostics.
fn binop_name(op: BinOp) -> &'static str {
    match op {
        BinOp::Add => "+",
        BinOp::Sub => "-",
        BinOp::Mul => "*",
        BinOp::Div => "/",
        BinOp::Mod => "%",
        BinOp::Eq => "==",
        BinOp::NotEq => "!=",
        BinOp::Lt => "<",
        BinOp::LtEq => "<=",
        BinOp::Gt => ">",
        BinOp::GtEq => ">=",
        BinOp::And => "and",
        BinOp::Or => "or",
        BinOp::Concat => "..",
        BinOp::Coalesce => "??",
    }
}

/// Per-operator type validation. Each branch checks just enough to flag
/// obvious mistakes (string + integer, table < 5, "x" and y, etc.) while
/// staying conservative for `any`, `nil`, and uninferable expressions.
pub(super) fn check_binary_op(
    op: BinOp,
    lhs: &Spanned<Expr>,
    rhs: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    match op {
        BinOp::Coalesce => check_coalesce_fallback(lhs, rhs, scope, errors),
        BinOp::Eq | BinOp::NotEq => check_equality_compat(op, lhs, rhs, scope, errors),
        BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod => {
            let name = binop_name(op);
            check_operand_kind(name, "`integer` or `float`", is_numeric_like, lhs, scope, errors);
            check_operand_kind(name, "`integer` or `float`", is_numeric_like, rhs, scope, errors);
            check_numeric_kinds_match(lhs, rhs, scope, errors);
        }
        BinOp::And | BinOp::Or => {
            // Saule follows Lua semantics for `and`/`or`: they short-circuit
            // on truthiness and accept any value (`nil or "x"` → `"x"`),
            // so the operands aren't type-restricted.
        }
        BinOp::Concat => {
            check_operand_kind("..", "`string` or numeric", is_concat_like, lhs, scope, errors);
            check_operand_kind("..", "`string` or numeric", is_concat_like, rhs, scope, errors);
        }
        BinOp::Lt | BinOp::LtEq | BinOp::Gt | BinOp::GtEq => {
            check_ordering_operands(op, lhs, rhs, scope, errors);
        }
    }
}

/// Check that a single operand satisfies a predicate; emit if not. Stays
/// silent when inference fails, the operand is `any`, or the operand is
/// `nil` (nullable misuse is reported elsewhere).
fn check_operand_kind(
    op: &'static str,
    expected: &'static str,
    pred: impl Fn(&Type) -> bool,
    arg: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let Some(t) = infer(arg, scope) else {
        return;
    };
    let base = strip_nullable(t.clone());
    if is_any(&base) {
        return;
    }
    if matches!(&base, Type::Named(n) if n == "nil") {
        return;
    }
    if !pred(&base) {
        errors.push(TypeCheckError::BinaryOperandTypeMismatch {
            op,
            expected,
            found: type_to_string(&t),
            span: to_source_span(arg.span.clone()),
        });
    }
}

/// `<`, `<=`, `>`, `>=` require both sides to be in the same family —
/// numeric/numeric or string/string. Anything else is flagged on the side
/// that breaks the family.
fn check_ordering_operands(
    op: BinOp,
    lhs: &Spanned<Expr>,
    rhs: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let name = binop_name(op);
    // First, each side individually must be orderable (numeric or string).
    check_operand_kind(name, "`integer`, `float`, or `string`", is_orderable, lhs, scope, errors);
    check_operand_kind(name, "`integer`, `float`, or `string`", is_orderable, rhs, scope, errors);
    // Then, both sides must agree on the family.
    let (Some(lt), Some(rt)) = (infer(lhs, scope), infer(rhs, scope)) else {
        return;
    };
    let lb = strip_nullable(lt.clone());
    let rb = strip_nullable(rt.clone());
    if is_any(&lb) || is_any(&rb) {
        return;
    }
    if matches!(&lb, Type::Named(n) if n == "nil")
        || matches!(&rb, Type::Named(n) if n == "nil")
    {
        return;
    }
    let l_num = is_numeric_like(&lb);
    let r_num = is_numeric_like(&rb);
    let l_str = is_string_like(&lb);
    let r_str = is_string_like(&rb);
    let same_family = (l_num && r_num) || (l_str && r_str);
    if !same_family && (l_num || l_str) && (r_num || r_str) {
        // Both individually orderable but in different families — flag rhs
        // with the lhs family as the expected one.
        let expected = if l_num {
            "`integer` or `float`"
        } else {
            "`string`"
        };
        errors.push(TypeCheckError::BinaryOperandTypeMismatch {
            op: name,
            expected,
            found: type_to_string(&rt),
            span: to_source_span(rhs.span.clone()),
        });
    }
}

fn is_orderable(ty: &Type) -> bool {
    is_numeric_like(ty) || is_string_like(ty)
}

/// Saule is strict on numeric kinds — `integer` and `float` never mix
/// implicitly. When both operands have a known *concrete* numeric kind
/// (i.e. not the `number` sentinel, not `any`, not generic), flag the
/// pair when they disagree. The error mirrors `RuntimeError::NumericMix`
/// so the user sees the same diagnostic at compile time.
fn check_numeric_kinds_match(
    lhs: &Spanned<Expr>,
    rhs: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let (Some(lt), Some(rt)) = (infer(lhs, scope), infer(rhs, scope)) else {
        return;
    };
    let lb = strip_nullable(lt);
    let rb = strip_nullable(rt);
    let kind = |t: &Type| -> Option<&'static str> {
        if let Type::Named(n) = t {
            match n.as_str() {
                "integer" => Some("integer"),
                "float" => Some("float"),
                _ => None,
            }
        } else {
            None
        }
    };
    let (Some(lk), Some(rk)) = (kind(&lb), kind(&rb)) else {
        return;
    };
    if lk != rk {
        // Span covers both sides so the underline brackets the whole
        // expression — matches the runtime diagnostic.
        let span_start = lhs.span.start.min(rhs.span.start);
        let span_end = lhs.span.end.max(rhs.span.end);
        errors.push(TypeCheckError::NumericMix {
            span: to_source_span(span_start..span_end),
        });
    }
}

/// Reject equality comparisons whose two sides have provably-disjoint
/// types (e.g. comparing a `table?` value to a string literal). Skips when
/// either side involves `any` or `nil`, since `T? == nil` is the idiomatic
/// nullability check.
pub(super) fn check_equality_compat(
    op: BinOp,
    lhs: &Spanned<Expr>,
    rhs: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let (Some(lt), Some(rt)) = (infer(lhs, scope), infer(rhs, scope)) else {
        return;
    };
    let lb = strip_nullable(lt.clone());
    let rb = strip_nullable(rt.clone());
    // `nil` on either side is legitimate — `x == nil` is how you check
    // nullability.
    if matches!(&lb, Type::Named(n) if n == "nil")
        || matches!(&rb, Type::Named(n) if n == "nil")
    {
        return;
    }
    if is_any(&lb) || is_any(&rb) {
        return;
    }
    // Compatible in either direction → OK.
    if types_compatible(&lb, &rb) || types_compatible(&rb, &lb) {
        return;
    }
    let result = if matches!(op, BinOp::Eq) { "false" } else { "true" };
    // Span covers both sides.
    let span_start = lhs.span.start.min(rhs.span.start);
    let span_end = lhs.span.end.max(rhs.span.end);
    errors.push(TypeCheckError::DisjointEquality {
        left: type_to_string(&lt),
        right: type_to_string(&rt),
        result,
        span: to_source_span(span_start..span_end),
    });
}

pub(super) fn check_assignment_compat(
    decl_ty: &Type,
    value: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    // When the value is `lhs ?? rhs`, the declared type tells us what the
    // whole expression is supposed to produce — use its stripped base as
    // the expected type for the fallback. This catches mismatches even
    // when `lhs` has lost type info (e.g. returns `any?`).
    if let Expr::Binary { op: BinOp::Coalesce, rhs, .. } = &value.value {
        let expected_base = strip_nullable(decl_ty.clone());
        if !matches!(&expected_base, Type::Named(n) if n == "nil" || n == "any")
            && let Some(rt) = infer(rhs, scope)
        {
            let rt_base = strip_nullable(rt.clone());
            let rt_is_nil = matches!(&rt_base, Type::Named(n) if n == "nil");
            let rt_is_any = is_any(&rt_base);
            if !rt_is_nil && !rt_is_any && !types_compatible(&expected_base, &rt_base) {
                errors.push(TypeCheckError::CoalesceFallbackTypeMismatch {
                    expected: type_to_string(&expected_base),
                    found: type_to_string(&rt),
                    span: to_source_span(rhs.span.clone()),
                });
            }
        }
    }

    if is_nullable(decl_ty) {
        return;
    }
    if matches!(value.value, Expr::Nil) {
        errors.push(TypeCheckError::NilToNonNullable {
            ty: type_to_string(decl_ty),
            span: to_source_span(value.span.clone()),
        });
        return;
    }

    // Table-aware checks for table literals assigned to a typed table.
    // Splits the literal into its positional and field halves so each can
    // be validated against the declared table shape independently.
    if let (Type::Table { key, value: elem_ty }, Expr::Table(items)) = (decl_ty, &value.value) {
        let has_positional = items.iter().any(|e| matches!(e, TableEntry::Positional(_)));
        let has_field = items.iter().any(|e| matches!(e, TableEntry::Field { .. }));

        // `{a, b, c}` literal cannot fill a map-typed table whose key is not
        // integer-compatible.
        if let Some(k) = key
            && !is_integer_like(k)
            && has_positional
        {
            errors.push(TypeCheckError::TableArrayLiteralForMap {
                key: type_to_string(k),
                value: type_to_string(elem_ty),
                span: to_source_span(value.span.clone()),
            });
            return;
        }
        // Field entries (`name: ...`) require the table to declare a key
        // type compatible with `string`. Array-typed `table<T>` rejects them.
        if has_field {
            let key_ok = match key {
                None => false,
                Some(k) => is_string_like(k),
            };
            if !key_ok {
                errors.push(TypeCheckError::TableArrayLiteralForMap {
                    key: key.as_deref().map(type_to_string).unwrap_or_else(|| "integer".to_string()),
                    value: type_to_string(elem_ty),
                    span: to_source_span(value.span.clone()),
                });
                return;
            }
        }
        // Each value must match the declared value type.
        for item in items {
            match item {
                TableEntry::Positional(e) | TableEntry::Field { value: e, .. } => {
                    check_element_compat(elem_ty, e, scope, errors);
                }
            }
        }
        return;
    }

    if let Some(value_ty) = infer(value, scope)
        && is_nullable(&value_ty)
    {
        errors.push(TypeCheckError::NullableToNonNullable {
            from: type_to_string(&value_ty),
            to: type_to_string(decl_ty),
            span: to_source_span(value.span.clone()),
        });
    }
}

/// Index key must match the table's declared key type.
pub(super) fn check_table_key_compat(
    expected: &Type,
    index: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(idx_ty) = infer(index, scope)
        && !types_compatible(expected, &idx_ty)
    {
        errors.push(TypeCheckError::TableKeyTypeMismatch {
            expected: type_to_string(expected),
            found: type_to_string(&idx_ty),
            span: to_source_span(index.span.clone()),
        });
    }
}

/// True for `integer` and `any` — the key types that an array-style literal
/// can satisfy.
fn is_integer_like(ty: &Type) -> bool {
    matches!(ty, Type::Named(n) if n == "integer" || n == "any")
}

/// True for `string` and `any` — the key types that a field-style literal
/// (`name: expr` / `"text": expr`) can satisfy.
fn is_string_like(ty: &Type) -> bool {
    matches!(ty, Type::Named(n) if n == "string" || n == "any")
}

/// Element-of-table compatibility — accepts literals/`Ident`s whose inferred
/// type matches, and stays quiet otherwise (conservative).
pub(super) fn check_element_compat(
    expected: &Type,
    value: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(value_ty) = infer(value, scope)
        && !types_compatible(expected, &value_ty)
    {
        errors.push(TypeCheckError::TableElementTypeMismatch {
            expected: type_to_string(expected),
            found: type_to_string(&value_ty),
            span: to_source_span(value.span.clone()),
        });
    }
}

/// Conservative type compatibility — names match (or either is `any`), or
/// `value_ty` is `Nullable` of a compatible inner, etc.
pub(super) fn types_compatible(expected: &Type, value_ty: &Type) -> bool {
    // Suppress `is_interface` unused-warning when state moves; reference here.
    let _ = is_interface;
    match (expected, value_ty) {
        // Same-name primitives, plus `any` on either side, plus `nil` on the
        // value side (nil is universally assignable; nullable-rejection is
        // handled separately by `NullableToNonNullable`).
        (Type::Named(a), Type::Named(b)) => {
            if a == b || a == "any" || b == "any" || b == "nil" {
                return true;
            }
            // Generic type parameters in scope match anything — they're
            // effectively `any` from the body's point of view.
            if is_type_param(a) || is_type_param(b) {
                return true;
            }
            // `number` is the sentinel used in native sigs to mean
            // "integer or float" — accept either.
            if a == "number" && (b == "integer" || b == "float" || b == "number") {
                return true;
            }
            // Class/interface subtyping: a value of type `b` is assignable to
            // a slot of type `a` if `b` is a subtype of `a` (class implements
            // interface, class extends class, interface extends interface).
            if is_subtype_named(b, a) {
                let _ = class_implements; // keep import even if unused later
                return true;
            }
            false
        }
        // `table<any>` (or `table<any, any>`) matches any table — used by
        // native sigs like `Table.insert(t, ...)` to mean "any table".
        (
            Type::Table { key: ek, value: ev },
            Type::Table { key: vk, value: vv },
        ) => {
            let key_ok = match (ek, vk) {
                (None, None) => true,
                (Some(a), Some(b)) => types_compatible(a, b),
                // Cross-shape (`table<T>` vs `table<K, V>`) only when one
                // side is the `any` wildcard.
                _ => is_any(ev),
            };
            key_ok && (is_any(ev) || types_compatible(ev, vv))
        }
        // Expected table, but value is the bare type-name `table`, `any` or
        // `nil` — accept (caller has erased the element type, or it's nil).
        (Type::Table { .. }, Type::Named(n)) if n == "table" || n == "any" || n == "nil" => true,
        // Expected `any` / `table` / `nil` named slot, value is a table —
        // accept (we widen to the named slot).
        (Type::Named(n), Type::Table { .. }) if n == "table" || n == "any" => true,
        (Type::Nullable(a), b) => types_compatible(a, b),
        (a, Type::Nullable(b)) => types_compatible(a, b),
        // Function / Tuple shapes — only equal-shape is strictly compatible,
        // but the checker doesn't track those precisely yet. Accept rather
        // than emit false positives.
        (Type::Function { .. }, Type::Function { .. }) => true,
        (Type::Tuple(_), Type::Tuple(_)) => true,
        // Different kinds (e.g. table vs integer) — reject.
        _ => false,
    }
}

/// Reject `if`/`while`/`until` conditions that the type system can prove are
/// not `boolean`. Conservative: when `infer` can't determine a type, we skip
/// silently so calls and dynamic expressions keep working.
pub(super) fn check_boolean_cond(
    construct: &'static str,
    cond: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let Some(ty) = infer(cond, scope) else {
        return;
    };
    let is_bool = matches!(&ty, Type::Named(n) if n == "boolean" || n == "any");
    if !is_bool {
        errors.push(TypeCheckError::NonBooleanCondition {
            construct,
            found: type_to_string(&ty),
            span: to_source_span(cond.span.clone()),
        });
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Lightweight type inference.
//
// Returns `Some(ty)` only when we can prove the type. Anything we can't see
// through (calls, member reads on unknown classes, indexing) returns `None`,
// and callers treat that as "don't know, don't complain".
// ──────────────────────────────────────────────────────────────────────────────

pub(super) fn infer(expr: &Spanned<Expr>, scope: &Scope) -> Option<Type> {
    match &expr.value {
        Expr::Nil => Some(Type::Named("nil".into())),
        Expr::Int(_) => Some(Type::Named("integer".into())),
        Expr::Float(_) => Some(Type::Named("float".into())),
        Expr::Bool(_) => Some(Type::Named("boolean".into())),
        Expr::Str(_) => Some(Type::Named("string".into())),
        Expr::Ident(n) => scope.lookup(n).cloned(),
        Expr::SafeMember { .. } => Some(Type::Nullable(Box::new(Type::Named("any".into())))),
        Expr::ForceUnwrap(inner) => match infer(inner, scope)? {
            Type::Nullable(t) => Some(*t),
            other => Some(other),
        },
        Expr::Binary { op, lhs, rhs } => match op {
            BinOp::Coalesce => {
                // `lhs ?? rhs`: result is non-nullable iff `rhs` is non-nullable.
                match (infer(lhs, scope), infer(rhs, scope)) {
                    (Some(lt), Some(rt)) => {
                        let base = strip_nullable(lt);
                        if is_nullable(&rt) {
                            Some(Type::Nullable(Box::new(base)))
                        } else {
                            Some(base)
                        }
                    }
                    _ => None,
                }
            }
            BinOp::Eq | BinOp::NotEq | BinOp::Lt | BinOp::LtEq | BinOp::Gt | BinOp::GtEq => {
                Some(Type::Named("boolean".into()))
            }
            BinOp::And | BinOp::Or => None,
            BinOp::Concat => Some(Type::Named("string".into())),
            BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod => {
                infer(lhs, scope).or_else(|| infer(rhs, scope))
            }
        },
        // `Foo(args)` where `Foo` is a known class → produces a `Foo`.
        // Otherwise, look up the qualified callee name in:
        //   1. the local class registry as a user-defined method
        //      (`Foo.bar(...)` → return type of `Foo.bar`); or
        //   2. the native signature table (`String.byte`, `Math.tointeger`,
        //      `assert`).
        Expr::Call { callee, .. } => {
            if let Expr::Ident(n) = &callee.value
                && with_classes(|reg| reg.contains_key(n))
            {
                return Some(Type::Named(n.clone()));
            }
            // `Class.method(args)` — receiver is the class itself.
            if let Expr::Member { obj, name } = &callee.value
                && let Expr::Ident(class_name) = &obj.value
                && let Some(sig) = saule_semantic::lookup_method(class_name, name)
            {
                return sig.return_ty;
            }
            // `instance.method(args)` — receiver inferred to a class.
            if let Expr::Member { obj, name } = &callee.value
                && let Some(ty) = infer(obj, scope)
                && let Type::Named(class_name) = strip_nullable(ty)
                && let Some(sig) = saule_semantic::lookup_method(&class_name, name)
            {
                return sig.return_ty;
            }
            if let Some(qname) = native_callee_name(callee)
                && let Some(sig) = crate::sigs::lookup(&qname)
            {
                return first_or_tuple(sig.returns);
            }
            None
        }
        // `obj:method(args)` — same lookup as the `obj.method(args)` case.
        Expr::MethodCall { obj, method, .. } => {
            if let Some(ty) = infer(obj, scope)
                && let Type::Named(class_name) = strip_nullable(ty)
                && let Some(sig) = saule_semantic::lookup_method(&class_name, method)
            {
                return sig.return_ty;
            }
            None
        }
        // A `match` expression has the type of its (unified) arm bodies. We
        // only need an approximation, so return the first arm-body type we
        // can infer.
        Expr::Match { arms, .. } => arms.iter().find_map(|a| match &a.body {
            saule_ast::MatchBody::Expr(e) => infer(e, scope),
            saule_ast::MatchBody::Block(_) => None,
        }),
        _ => None,
    }
}

pub(super) fn strip_nullable(ty: Type) -> Type {
    match ty {
        Type::Nullable(t) => *t,
        other => other,
    }
}

/// Build a qualified callee name suitable for `stdlib::sigs::lookup`:
/// `assert` or `String.byte`.
fn native_callee_name(callee: &Spanned<Expr>) -> Option<String> {
    match &callee.value {
        Expr::Ident(n) => Some(n.clone()),
        Expr::Member { obj, name } => {
            if let Expr::Ident(class) = &obj.value {
                Some(format!("{class}.{name}"))
            } else {
                None
            }
        }
        _ => None,
    }
}

/// Collapse a returns-list into a single inferred type: single returns stay
/// as-is, multi-returns become a `Type::Tuple`.
fn first_or_tuple(returns: Vec<Type>) -> Option<Type> {
    match returns.len() {
        0 => None,
        1 => returns.into_iter().next(),
        _ => Some(Type::Tuple(returns)),
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Flow narrowing.
//
// `narrow_truthy(cond, scope)` — apply the assumptions that hold when `cond`
// is true. Today: `x != nil` and `nil != x` strip `Nullable` off `x`. `and`
// chains compose.
//
// `narrow_falsy(cond, scope)` — apply the assumptions when `cond` is false.
// Used by the else-branch: `if x == nil then ... else ... end` narrows `x`
// in the else.
// ──────────────────────────────────────────────────────────────────────────────

pub(super) fn narrow_truthy(cond: &Spanned<Expr>, scope: &mut Scope) {
    match &cond.value {
        Expr::Binary {
            op: BinOp::NotEq,
            lhs,
            rhs,
        } => {
            if let Some(name) = pick_ident_compared_to_nil(lhs, rhs)
                && let Some(Type::Nullable(t)) = scope.lookup(name).cloned()
            {
                scope.bind(name.to_string(), *t);
            }
        }
        Expr::Binary {
            op: BinOp::And,
            lhs,
            rhs,
        } => {
            narrow_truthy(lhs, scope);
            narrow_truthy(rhs, scope);
        }
        _ => {}
    }
}

pub(super) fn narrow_falsy(cond: &Spanned<Expr>, scope: &mut Scope) {
    if let Expr::Binary {
        op: BinOp::Eq,
        lhs,
        rhs,
    } = &cond.value
        && let Some(name) = pick_ident_compared_to_nil(lhs, rhs)
        && let Some(Type::Nullable(t)) = scope.lookup(name).cloned()
    {
        scope.bind(name.to_string(), *t);
    }
}

/// If `lhs` / `rhs` is `(Ident(x), Nil)` in either order, return `Some(x)`.
fn pick_ident_compared_to_nil<'a>(
    lhs: &'a Spanned<Expr>,
    rhs: &'a Spanned<Expr>,
) -> Option<&'a str> {
    match (&lhs.value, &rhs.value) {
        (Expr::Ident(n), Expr::Nil) => Some(n),
        (Expr::Nil, Expr::Ident(n)) => Some(n),
        _ => None,
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Misc helpers.
// ──────────────────────────────────────────────────────────────────────────────

pub(super) fn type_to_string(ty: &Type) -> String {
    match ty {
        Type::Named(n) => n.clone(),
        Type::Nullable(inner) => format!("{}?", type_to_string(inner)),
        Type::Table { key: None, value } => format!("table<{}>", type_to_string(value)),
        Type::Table {
            key: Some(k),
            value,
        } => format!("table<{}, {}>", type_to_string(k), type_to_string(value)),
        other => format!("{:?}", other),
    }
}

pub(super) fn is_nullable(ty: &Type) -> bool {
    match ty {
        Type::Nullable(_) => true,
        Type::Named(n) => n == "nil",
        _ => false,
    }
}

//! Tests moved out of src/lib.rs.
use saule_interpreter::{PipelineError, RuntimeError, Value, check_and_run};
use saule_lexer::Lexer;
use saule_parser::parse;
use saule_semantic::SemanticError;
use std::rc::Rc;

fn eval(src: &str) -> Result<Value, PipelineError> {
    let toks = Lexer::new(src).tokenize().expect("lex");
    let module = parse(toks).expect("parse");
    check_and_run(&module)
}

// ── Phase 1 regression coverage ──────────────────────────────────────────

#[test]
fn integer_arithmetic() {
    assert_eq!(eval("1 + 2 * 3").unwrap(), Value::Int(7));
}

#[test]
fn float_arithmetic() {
    match eval("1.5 + 2.5").unwrap() {
        Value::Float(f) => assert_eq!(f, 4.0),
        v => panic!("expected float, got {v:?}"),
    }
}

#[test]
fn mixing_int_and_float_errors() {
    assert!(matches!(
        eval("1 + 2.0").unwrap_err(),
        PipelineError::Runtime(RuntimeError::NumericMix { .. })
    ));
}

#[test]
fn local_then_lookup() {
    assert_eq!(
        eval("local x: integer = 10\nx * 2").unwrap(),
        Value::Int(20)
    );
}

#[test]
fn string_concat_and_length() {
    assert_eq!(
        eval(r#""foo" .. "bar""#).unwrap(),
        Value::Str(Rc::new("foobar".into()))
    );
    assert_eq!(eval(r#"#"hello""#).unwrap(), Value::Int(5));
}

#[test]
fn comparison_and_logic() {
    assert_eq!(eval("1 < 2 and 3 >= 3").unwrap(), Value::Bool(true));
    assert_eq!(
        eval(r#"nil or "fallback""#).unwrap(),
        Value::Str(Rc::new("fallback".into()))
    );
}

#[test]
fn null_coalescing() {
    assert_eq!(
        eval(r#"nil ?? "x""#).unwrap(),
        Value::Str(Rc::new("x".into()))
    );
    assert_eq!(
        eval(r#""y" ?? "x""#).unwrap(),
        Value::Str(Rc::new("y".into()))
    );
}

#[test]
fn print_native_call() {
    assert_eq!(eval(r#"print("hello", 1, true)"#).unwrap(), Value::Nil);
}

#[test]
fn undefined_variable_errors() {
    assert!(matches!(
        eval("nope").unwrap_err(),
        PipelineError::Semantic(SemanticError::UndefinedName { .. })
    ));
}

#[test]
fn division_by_zero() {
    assert!(matches!(
        eval("1 / 0").unwrap_err(),
        PipelineError::Runtime(RuntimeError::DivisionByZero { .. })
    ));
}

#[test]
fn type_builtin() {
    assert_eq!(
        eval("type(42)").unwrap(),
        Value::Str(Rc::new("integer".into()))
    );
    assert_eq!(
        eval(r#"type("hi")"#).unwrap(),
        Value::Str(Rc::new("string".into()))
    );
}

// ── Phase 2: assignment ──────────────────────────────────────────────────

#[test]
fn assignment_updates_local() {
    let src = "local x: integer = 1\nx = x + 41\nx";
    assert_eq!(eval(src).unwrap(), Value::Int(42));
}

#[test]
fn assign_to_undeclared_errors() {
    let src = "x = 1";
    assert!(matches!(
        eval(src).unwrap_err(),
        PipelineError::Semantic(SemanticError::AssignToUndeclared { .. })
    ));
}

// ── Phase 2: if / elseif / else ──────────────────────────────────────────

#[test]
fn if_then_branch() {
    let src = r#"
        local x: integer = 0
        if true then
          x = 1
        else
          x = 2
        end
        x
    "#;
    assert_eq!(eval(src).unwrap(), Value::Int(1));
}

#[test]
fn if_elseif_else_chain() {
    let src = r#"
        local n: integer = 7
        local kind: string = ""
        if n < 0 then
          kind = "neg"
        elseif n == 0 then
          kind = "zero"
        elseif n < 10 then
          kind = "small"
        else
          kind = "big"
        end
        kind
    "#;
    assert_eq!(eval(src).unwrap(), Value::Str(Rc::new("small".into())));
}

#[test]
fn if_body_introduces_scope() {
    // `tmp` is declared inside the `if` body and must NOT leak out.
    let src = r#"
        local x: integer = 0
        if true then
          local tmp: integer = 9
          x = tmp
        end
        tmp
    "#;
    assert!(matches!(
        eval(src).unwrap_err(),
        PipelineError::Semantic(SemanticError::UndefinedName { .. })
    ));
}

// ── Phase 2: while + break + continue ────────────────────────────────────

#[test]
fn while_counts_to_ten() {
    let src = r#"
        local i: integer = 0
        local sum: integer = 0
        while i < 10 do
          i = i + 1
          sum = sum + i
        end
        return sum
    "#;
    assert_eq!(eval(src).unwrap(), Value::Int(55));
}

#[test]
fn break_exits_loop_early() {
    let src = r#"
        local i: integer = 0
        while true do
          i = i + 1
          if i == 5 then
            break
          end
        end
        return i
    "#;
    assert_eq!(eval(src).unwrap(), Value::Int(5));
}

#[test]
fn continue_skips_rest_of_iteration() {
    // Sum of odd numbers 1..=9 = 25.
    let src = r#"
        local i: integer = 0
        local sum: integer = 0
        while i < 10 do
          i = i + 1
          if i % 2 == 0 then
            continue
          end
          sum = sum + i
        end
        return sum
    "#;
    assert_eq!(eval(src).unwrap(), Value::Int(25));
}

// ── Phase 2: repeat / until ──────────────────────────────────────────────

#[test]
fn repeat_until_runs_at_least_once() {
    let src = r#"
        local i: integer = 0
        repeat
          i = i + 1
        until i >= 3
        return i
    "#;
    assert_eq!(eval(src).unwrap(), Value::Int(3));
}

// ── Phase 2: numeric for ─────────────────────────────────────────────────

#[test]
fn numeric_for_default_step() {
    let src = r#"
        local sum: integer = 0
        for i: integer = 1, 5 do
          sum = sum + i
        end

        return sum
    "#;
    assert_eq!(eval(src).unwrap(), Value::Int(15));
}

#[test]
fn numeric_for_negative_step() {
    let src = r#"
        local sum: integer = 0
        for i: integer = 10, 1, -1 do
          sum = sum + i
        end
        sum
    "#;
    assert_eq!(eval(src).unwrap(), Value::Int(55));
}

#[test]
fn numeric_for_zero_step_errors() {
    let src = r#"
        for i: integer = 1, 5, 0 do
          break
        end
    "#;
    assert!(matches!(
        eval(src).unwrap_err(),
        PipelineError::Runtime(RuntimeError::ZeroStep { .. })
    ));
}

// ── Phase 2: stray loop-control statements ───────────────────────────────

#[test]
fn break_outside_loop_errors() {
    assert!(matches!(
        eval("break").unwrap_err(),
        PipelineError::Semantic(SemanticError::LoopControlOutsideLoop { which: "break", .. })
    ));
}

// ── Phase 3: user-defined functions ────────────────────────────────────────

#[test]
fn calls_named_function() {
    let src = r#"
        fn add(a: integer, b: integer) -> integer
          return a + b
        end
        add(2, 3)
    "#;
    assert_eq!(eval(src).unwrap(), Value::Int(5));
}

#[test]
fn function_with_no_explicit_return_is_nil() {
    let src = r#"
        fn nothing() -> nil
        end
        nothing()
    "#;
    assert_eq!(eval(src).unwrap(), Value::Nil);
}

#[test]
fn recursion_factorial() {
    let src = r#"
        fn fact(n: integer) -> integer
          if n <= 1 then
            return 1
          end
          return n * fact(n - 1)
        end
        fact(6)
    "#;
    assert_eq!(eval(src).unwrap(), Value::Int(720));
}

#[test]
fn closures_capture_lexical_scope() {
    // `make_adder` returns a lambda that adds its captured `n`.
    let src = r#"
        fn make_adder(n: integer) -> fn(integer) -> integer
          return (x: integer) => x + n
        end
        local add10 = make_adder(10)
        local add100 = make_adder(100)
        add10(5) + add100(5)
    "#;
    assert_eq!(eval(src).unwrap(), Value::Int(120));
}

#[test]
fn default_parameter_value() {
    let src = r#"
        fn greet(name: string = "world") -> string
          return "hello, " .. name
        end
        greet()
    "#;
    assert_eq!(
        eval(src).unwrap(),
        Value::Str(Rc::new("hello, world".into()))
    );
}

#[test]
fn missing_argument_errors() {
    let src = r#"
        fn add(a: integer, b: integer) -> integer
          return a + b
        end
        add(1)
    "#;
    // Caught at the typeck phase now: `saule_typeck` validates direct
    // calls to top-level functions against their declared arity.
    assert!(matches!(
        eval(src).unwrap_err(),
        PipelineError::Typeck(saule_typeck::TypeCheckError::FunctionArity { .. })
    ));
}

#[test]
fn lambda_assigned_and_called() {
    let src = r#"
        local sq = (x: integer) => x * x
        sq(9)
    "#;
    assert_eq!(eval(src).unwrap(), Value::Int(81));
}

#[test]
fn higher_order_function() {
    let src = r#"
        fn apply(f: fn(integer) -> integer, x: integer) -> integer
          return f(x)
        end
        apply((n: integer) => n + 1, 41)
    "#;
    assert_eq!(eval(src).unwrap(), Value::Int(42));
}

#[test]
fn function_type_name_is_function() {
    let src = r#"
        fn id(x: integer) -> integer return x end
        type(id)
    "#;
    assert_eq!(eval(src).unwrap(), Value::Str(Rc::new("function".into())));
}

#[test]
fn calling_non_callable_errors() {
    let src = r#"
        local x: integer = 5
        x()
    "#;
    assert!(matches!(
        eval(src).unwrap_err(),
        PipelineError::Runtime(RuntimeError::TypeError { .. })
    ));
}

// ────────────────────────────────────────────────────────────────────────
// Specification-driven tests for the rest of the language.
//
// Every test below mirrors a feature described in README.md. They are
// intentionally written *before* the supporting code so we can run
// them and see exactly which features the interpreter still needs to
// grow into. Tests that depend on features not yet implemented will
// currently fail — that's the point.
//
// `try_eval` swallows lex / parse / runtime failures into a single
// `Result<Value, String>` so failures show up as clean assertion
// messages instead of panics in unrelated spots.
// ────────────────────────────────────────────────────────────────────────

fn try_eval(src: &str) -> Result<Value, String> {
    let toks = Lexer::new(src)
        .tokenize()
        .map_err(|e| format!("lex error: {e:?}"))?;
    let module = parse(toks).map_err(|e| format!("parse error: {e:?}"))?;
    check_and_run(&module).map_err(|e| format!("{e:?}"))
}

fn assert_int(src: &str, expected: i64) {
    match try_eval(src) {
        Ok(Value::Int(n)) => assert_eq!(n, expected, "src: {src}"),
        Ok(other) => panic!("expected Int({expected}), got {other:?} — src: {src}"),
        Err(e) => panic!("evaluation failed ({e}) — src: {src}"),
    }
}
fn assert_float(src: &str, expected: f64) {
    match try_eval(src) {
        Ok(Value::Float(f)) => assert!((f - expected).abs() < 1e-9, "got {f}, want {expected}"),
        Ok(other) => panic!("expected Float({expected}), got {other:?} — src: {src}"),
        Err(e) => panic!("evaluation failed ({e}) — src: {src}"),
    }
}
fn assert_str(src: &str, expected: &str) {
    match try_eval(src) {
        Ok(Value::Str(s)) => assert_eq!(&*s, expected, "src: {src}"),
        Ok(other) => panic!("expected Str({expected:?}), got {other:?} — src: {src}"),
        Err(e) => panic!("evaluation failed ({e}) — src: {src}"),
    }
}
fn assert_bool(src: &str, expected: bool) {
    match try_eval(src) {
        Ok(Value::Bool(b)) => assert_eq!(b, expected, "src: {src}"),
        Ok(other) => panic!("expected Bool({expected}), got {other:?} — src: {src}"),
        Err(e) => panic!("evaluation failed ({e}) — src: {src}"),
    }
}
fn assert_nil(src: &str) {
    match try_eval(src) {
        Ok(Value::Nil) => {}
        Ok(other) => panic!("expected Nil, got {other:?} — src: {src}"),
        Err(e) => panic!("evaluation failed ({e}) — src: {src}"),
    }
}
fn assert_errs(src: &str) {
    if let Ok(v) = try_eval(src) {
        panic!("expected error, got {v:?} — src: {src}");
    }
}

// ── §Types & §Casting ───────────────────────────────────────────────────

mod casts {
    use super::*;

    #[test]
    fn int_truncates_positive_toward_zero() {
        assert_int("int(7.9)", 7);
    }
    #[test]
    fn int_truncates_negative_toward_zero() {
        // README: "truncation not rounding"; -3.7 → -3, NOT -4.
        assert_int("int(-3.7)", -3);
    }
    #[test]
    fn int_of_whole_float() {
        assert_int("int(10.0)", 10);
    }
    #[test]
    fn float_promotes_integer() {
        assert_float("float(5)", 5.0);
    }
    #[test]
    fn cast_enables_mixed_arithmetic() {
        // README example: `float(health) - dmg`.
        let src = r#"
            local health: integer = 100
            local dmg: float = 10.5
            float(health) - dmg
        "#;
        assert_float(src, 89.5);
    }
    #[test]
    fn cast_back_to_integer() {
        let src = r#"
            local health: integer = 100
            local dmg: float = 10.5
            health - int(dmg)
        "#;
        assert_int(src, 90);
    }
    #[test]
    fn int_of_string_errors() {
        assert_errs(r#"int("abc")"#);
    }
    #[test]
    fn float_of_string_errors() {
        assert_errs(r#"float("abc")"#);
    }
    #[test]
    fn int_with_no_args_errors() {
        assert_errs("int()");
    }
}

// ── §Tables ─────────────────────────────────────────────────────────────

mod tables {
    use super::*;

    #[test]
    fn empty_table_literal_has_zero_length() {
        assert_int("local t = {}\n#t", 0);
    }
    #[test]
    fn array_literal_with_elements() {
        assert_int("local t = {10, 20, 30}\nt[2]", 20);
    }
    #[test]
    fn length_of_populated_table() {
        assert_int("#{1,2,3,4,5}", 5);
    }
    #[test]
    fn out_of_bounds_index_returns_nil() {
        assert_nil("local t = {1,2,3}\nt[99]");
    }
    #[test]
    fn zero_index_returns_nil() {
        assert_nil("local t = {1,2,3}\nt[0]");
    }
    #[test]
    fn negative_index_returns_nil() {
        assert_nil("local t = {1,2,3}\nt[-1]");
    }
    #[test]
    fn index_assignment_updates_element() {
        assert_int("local t = {1,2,3}\nt[2] = 99\nt[2]", 99);
    }
    #[test]
    fn append_idiom_grows_table() {
        // README pattern: `result[#result + 1] = item`.
        let src = r#"
            local t = {1, 2}
            t[#t + 1] = 3
            t[#t + 1] = 4
            #t
        "#;
        assert_int(src, 4);
    }
    #[test]
    fn nested_table_access() {
        assert_int("local g = {{1,2,3},{4,5,6}}\ng[2][3]", 6);
    }
    #[test]
    fn tables_have_reference_identity() {
        // Aliased tables share storage.
        let src = r#"
            local a = {1,2,3}
            local b = a
            b[1] = 99
            a[1]
        "#;
        assert_int(src, 99);
    }
    #[test]
    fn tables_passed_to_fn_are_shared() {
        let src = r#"
            fn modify(t: table<integer>)
                t[1] = 42
            end
            local t = {1, 2, 3}
            modify(t)
            t[1]
        "#;
        assert_int(src, 42);
    }
    #[test]
    fn indexing_non_table_errors() {
        assert_errs("local x = 5\nx[1]");
    }
    #[test]
    fn index_assign_on_non_table_errors() {
        assert_errs("local x = 5\nx[1] = 9");
    }
    #[test]
    fn type_of_table_is_table() {
        assert_str("type({1,2,3})", "table");
    }
}

// ── §Loops (for-in) ─────────────────────────────────────────────────────

mod for_in {
    use super::*;

    #[test]
    fn one_var_iterates_values() {
        let src = r#"
            local sum: integer = 0
            for v: integer in {1, 2, 3, 4} do
                sum = sum + v
            end
            sum
        "#;
        assert_int(src, 10);
    }
    #[test]
    fn two_vars_iterate_index_and_value() {
        let src = r#"
            local sum: integer = 0
            for i: integer, v: integer in {10, 20, 30} do
                sum = sum + i + v
            end
            sum
        "#;
        // (1+10)+(2+20)+(3+30) = 66
        assert_int(src, 66);
    }
    #[test]
    fn empty_table_runs_body_zero_times() {
        let src = r#"
            local hit: integer = 0
            for v: integer in {} do
                hit = hit + 1
            end
            hit
        "#;
        assert_int(src, 0);
    }
    #[test]
    fn break_inside_for_in() {
        let src = r#"
            local last: integer = 0
            for v: integer in {1,2,3,4,5} do
                if v == 3 then break end
                last = v
            end
            last
        "#;
        assert_int(src, 2);
    }
    #[test]
    fn continue_inside_for_in() {
        let src = r#"
            local sum: integer = 0
            for v: integer in {1,2,3,4,5} do
                if v % 2 == 0 then continue end
                sum = sum + v
            end
            sum
        "#;
        assert_int(src, 9);
    }
}

// ── §Functions: multiple return values ──────────────────────────────────

mod multi_return {
    use super::*;

    #[test]
    fn multi_return_destructured() {
        let src = r#"
            fn pair() -> (integer, integer)
                return 7, 9
            end
            local a: integer, b: integer = pair()
            a + b
        "#;
        assert_int(src, 16);
    }
    #[test]
    fn multi_return_through_named_function_call() {
        let src = r#"
            fn minMax(items: table<integer>) -> (integer, integer)
                local lo: integer = items[1]
                local hi: integer = items[1]
                for v: integer in items do
                    if v < lo then lo = v end
                    if v > hi then hi = v end
                end
                return lo, hi
            end
            local lo: integer, hi: integer = minMax({3,1,7,2,9})
            lo * 100 + hi
        "#;
        assert_int(src, 109);
    }
    #[test]
    fn multi_return_min_max() {
        // README example.
        let src = r#"
            fn minMax(items: table<integer>) -> (integer, integer)
                local lo: integer = items[1]
                local hi: integer = items[1]
                for v: integer in items do
                    if v < lo then lo = v end
                    if v > hi then hi = v end
                end
                return lo, hi
            end
            local lo: integer, hi: integer = minMax({3,1,7,2,9})
            hi - lo
        "#;
        assert_int(src, 8);
    }
    #[test]
    fn single_binding_of_multi_return_takes_first() {
        let src = r#"
            fn pair() -> (integer, integer)
                return 11, 22
            end
            local x: integer = pair()
            x
        "#;
        assert_int(src, 11);
    }
}

// ── §Functions: named parameters ────────────────────────────────────────

mod named_params {
    use super::*;

    #[test]
    fn call_with_named_arguments() {
        let src = r#"
            fn setup(width: integer, height: integer, title: string) -> string
                return title .. " " .. width .. "x" .. height
            end

            setup(width: 1920, height: 1080, title: "Game")
        "#;
        assert_str(src, "Game 1920x1080");
    }
    #[test]
    fn named_args_in_any_order() {
        let src = r#"
            fn make(a: integer, b: integer, c: integer) -> integer
                return a * 100 + b * 10 + c
            end
            make(c: 3, a: 1, b: 2)
        "#;
        assert_int(src, 123);
    }
    #[test]
    fn named_with_default() {
        let src = r#"
            fn fmt(x: integer, suffix: string = "px") -> string
                return x .. suffix
            end
            fmt(x: 16)
        "#;
        assert_str(src, "16px");
    }
}

// ── §Functions: variadic ────────────────────────────────────────────────

mod variadic {
    use super::*;

    #[test]
    fn variadic_sums_integers() {
        // README example.
        let src = r#"
            fn sum(...values: integer) -> integer
                local total: integer = 0
                for v: integer in values do
                    total = total + v
                end
                return total
            end
            sum(1, 2, 3, 4, 5)
        "#;
        assert_int(src, 15);
    }
    #[test]
    fn variadic_with_zero_extras() {
        let src = r#"
            fn sum(...values: integer) -> integer
                local total: integer = 0
                for v: integer in values do total = total + v end
                return total
            end
            sum()
        "#;
        assert_int(src, 0);
    }
    #[test]
    fn variadic_after_fixed_param() {
        let src = r#"
            fn label(prefix: string, ...vs: integer) -> string
                local s: string = prefix
                for v: integer in vs do s = s .. " " .. v end
                return s
            end
            label("ids:", 7, 8, 9)
        "#;
        assert_str(src, "ids: 7 8 9");
    }
}

// ── §Functions: piping with `then` ──────────────────────────────────────

mod piping {
    use super::*;

    #[test]
    fn pipe_threads_value_into_first_arg() {
        let src = r#"
            fn double(x: integer) -> integer return x * 2 end
            fn inc(x: integer) -> integer return x + 1 end
            local r: integer = 10 then double() then inc()
            r
        "#;
        assert_int(src, 21);
    }
    #[test]
    fn pipe_with_extra_args() {
        let src = r#"
            fn add(a: integer, b: integer) -> integer return a + b end
            local r: integer = 1 then add(41)
            r
        "#;
        assert_int(src, 42);
    }
}

// ── §Classes & §Inheritance ─────────────────────────────────────────────

mod classes {
    use super::*;

    #[test]
    fn construct_and_read_field() {
        let src = r#"
            class Point
                x: integer
                y: integer
                fn init(x: integer, y: integer)
                    self.x = x
                    self.y = y
                end
            end
            local p: Point =Point(3, 4)
            p.x + p.y
        "#;
        assert_int(src, 7);
    }
    #[test]
    fn method_call_with_self() {
        let src = r#"
            class Greeter
                name: string

                fn init(name: string)
                    self.name = name
                end

                fn greet(self) -> string
                    return "hi " .. self.name
                end
            end
            local g: Greeter = Greeter("ada")
            g.greet()
        "#;
        assert_str(src, "hi ada");
    }
    #[test]
    fn method_can_mutate_self() {
        let src = r#"
            class Counter
                n: integer
                fn init()
                    self.n = 0
                end
                fn tick(self)
                    self.n = self.n + 1
                end
            end
            local c: Counter = Counter()
            c.tick() c.tick() c.tick()
            c.n
        "#;
        assert_int(src, 3);
    }
    #[test]
    fn static_field_access() {
        let src = r#"
            class Player
                static maxHealth: integer = 100
            end
            Player.maxHealth
        "#;
        assert_int(src, 100);
    }
    #[test]
    fn static_method_call() {
        let src = r#"
            class Player
                static maxHealth: integer = 100
                static fn getMax() -> integer
                    return Player.maxHealth
                end
            end
            Player.getMax()
        "#;
        assert_int(src, 100);
    }
    #[test]
    fn static_field_is_shared_and_mutable() {
        let src = r#"
            class Player
                static maxHealth: integer = 100
            end
            Player.maxHealth = 200
            Player.maxHealth
        "#;
        assert_int(src, 200);
    }
    #[test]
    fn instance_identity_is_per_object() {
        let src = r#"
            class Box
                v: integer
                fn init(v: integer)
                    self.v = v
                end
            end
            local a: Box = Box(1)
            local b: Box = Box(1)
            a == b
        "#;
        assert_bool(src, false);
    }
    #[test]
    fn field_default_value() {
        // README shows `static maxHealth: integer = 100` and class fields
        // typically initialized in the constructor; but README also uses
        // `static score: integer = 0` in a constructor signature. Test
        // that a static default is observable before any instance exists.
        let src = r#"
            class Cfg
                static debug: boolean = true
            end
            Cfg.debug
        "#;
        assert_bool(src, true);
    }
    #[test]
    fn type_of_instance_is_instance() {
        // Saule uses class names as runtime type tags; `type(p)` should
        // yield the class name (or at least something non-empty).
        let src = r#"
            class Foo end
            type(Foo())
        "#;
        // We only assert it's a string of "Foo" or similar; the exact
        // format will be locked once classes are implemented.
        assert_str(src, "Foo");
    }
}

mod inheritance {
    use super::*;

    #[test]
    fn child_inherits_parent_method() {
        let src = r#"
            class Entity
                name: string
                fn init(name: string)
                    self.name = name
                end
                fn getName(self) -> string return self.name end
            end
            class Player extends Entity
                fn init(name: string)
                    self.super(name)
                end
            end
            local p: Player = Player("arthur")
            p.getName()
        "#;
        assert_str(src, "arthur");
    }
    #[test]
    fn super_calls_parent_constructor() {
        let src = r#"
            class A
                a: integer
                fn init(a: integer)
                    self.a = a
                end
            end
            class B extends A
                b: integer

                fn init(a: integer, b: integer)
                    self.super(a)
                    self.b = b
                end
            end

            local x: B = B(10, 20)
            x.a + x.b
        "#;
        assert_int(src, 30);
    }
    #[test]
    fn child_overrides_parent_method() {
        let src = r#"
            class A
                fn label(self) -> string return "A" end
            end
            class B extends A
                fn label(self) -> string return "B" end
            end
            (B()).label()
        "#;
        assert_str(src, "B");
    }
}

// ── §Interfaces ─────────────────────────────────────────────────────────

mod interfaces {
    use super::*;

    #[test]
    fn class_implements_interface_at_runtime() {
        // Interfaces are erased at runtime; calling the contract method
        // through an interface-typed local must still dispatch correctly.
        let src = r#"
            interface Greetable
                fn greet(self) -> string
            end
            class Person implements Greetable
                name: string
                fn init(n: string)
                    self.name = n
                end
                fn greet(self) -> string return "hello " .. self.name end
            end
            local g: Greetable = Person("rust")
            g.greet()
        "#;
        assert_str(src, "hello rust");
    }
}

// ── §Enums ──────────────────────────────────────────────────────────────

mod enums {
    use super::*;

    #[test]
    fn enum_variant_equality() {
        let src = r#"
            enum Direction
                North
                South
                East
                West
            end
            Direction.North == Direction.North
        "#;
        assert_bool(src, true);
    }
    #[test]
    fn enum_variants_are_distinct() {
        let src = r#"
            enum Direction
                North
                South
            end
            Direction.North == Direction.South
        "#;
        assert_bool(src, false);
    }
    #[test]
    fn valued_enum_exposes_value() {
        let src = r#"
            enum Status
                Alive = "alive"
                Dead = "dead"
            end
            Status.Alive.value
        "#;
        assert_str(src, "alive");
    }
    #[test]
    fn enum_method_dispatch() {
        // README example.
        let src = r#"
            enum Status
                Alive = "alive"
                Dead = "dead"
                fn describe(self) -> string
                    return "Status is: " .. self.value
                end
            end
            (Status.Alive).describe()
        "#;
        assert_str(src, "Status is: alive");
    }
}

// ── §Null Safety ────────────────────────────────────────────────────────

mod null_safety {
    use super::*;

    #[test]
    fn safe_member_on_nil_returns_nil() {
        let src = r#"
            class P
                name: string
                fn init(n: string)
                    self.name = n
                end
            end
            local p: P? = nil
            p?.name
        "#;
        assert_nil(src);
    }
    #[test]
    fn safe_member_on_value_returns_field() {
        let src = r#"
            class P
                name: string
                fn init(n: string)
                    self.name = n
                end
            end
            local p: P? = P("ada")
            p?.name
        "#;
        assert_str(src, "ada");
    }
    #[test]
    fn null_coalesce_with_nil() {
        let src = r#"
            local x: string? = nil
            x ?? "fallback"
        "#;
        assert_str(src, "fallback");
    }
    #[test]
    fn null_coalesce_with_value() {
        let src = r#"
            local x: string? = "real"
            x ?? "fallback"
        "#;
        assert_str(src, "real");
    }
    #[test]
    fn force_unwrap_on_value_returns_value() {
        let src = r#"
            local x: string? = "ok"
            x!
        "#;
        assert_str(src, "ok");
    }
    #[test]
    fn force_unwrap_on_nil_errors() {
        assert_errs("local x: string? = nil\nx!");
    }
    #[test]
    fn combined_safe_call_and_coalesce() {
        let src = r#"
            class P
                name: string
                fn init(n: string)
                    self.name = n
                end
                fn getName(self) -> string return self.name end
            end
            local p: P? = nil
            local n: string = p?.getName() ?? "Unknown"
            n
        "#;
        assert_str(src, "Unknown");
    }
}

// ── §Error Handling ─────────────────────────────────────────────────────

mod error_handling {
    use super::*;

    #[test]
    fn try_catches_thrown_string() {
        let src = r#"
            local caught: string = ""
            try
                throw "boom"
            catch e: string
                caught = e
            end
            caught
        "#;
        assert_str(src, "boom");
    }
    #[test]
    fn try_body_completes_without_throw() {
        let src = r#"
            local x: integer = 0
            try
                x = 42
            catch e: string
                x = -1
            end
            x
        "#;
        assert_int(src, 42);
    }
    #[test]
    fn nested_try_catch() {
        let src = r#"
            local outer: string = "none"
            try
                try
                    throw "inner"
                catch e: string
                    throw "wrapped: " .. e
                end
            catch e: string
                outer = e
            end
            outer
        "#;
        assert_str(src, "wrapped: inner");
    }
    #[test]
    fn uncaught_throw_bubbles_as_error() {
        assert_errs(r#"throw "kaboom""#);
    }
    #[test]
    fn throw_from_inside_function_caught_outside() {
        let src = r#"
            fn bad()
                throw "no good"
            end
            local msg: string = ""
            try
                bad()
            catch e: string
                msg = e
            end
            msg
        "#;
        assert_str(src, "no good");
    }
}

// ── §Loops (numeric-for `continue`/`break` already covered earlier) ─────

mod loops {
    use super::*;

    #[test]
    fn numeric_for_with_step_5() {
        let src = r#"
            local sum: integer = 0
            for i: integer = 0, 20, 5 do
                sum = sum + i
            end
            sum
        "#;
        // 0+5+10+15+20 = 50
