// ── §Null Safety ────────────────────────────────────────────────────────

mod null_safety {
    use super::*;

    #[test]
    fn safe_member_on_nil_returns_nil() {
        let src = r#"
            class P
                name: string
                fn init(n: string)
                    self.name = n
                end
            end
            local p: P? = nil
            p?.name
        "#;
        assert_nil(src);
    }
    #[test]
    fn safe_member_on_value_returns_field() {
        let src = r#"
            class P
                name: string
                fn init(n: string)
                    self.name = n
                end
            end
            local p: P? = P("ada")
            p?.name
        "#;
        assert_str(src, "ada");
    }
    #[test]
    fn null_coalesce_with_nil() {
        let src = r#"
            local x: string? = nil
            x ?? "fallback"
        "#;
        assert_str(src, "fallback");
    }
    #[test]
    fn null_coalesce_with_value() {
        let src = r#"
            local x: string? = "real"
            x ?? "fallback"
        "#;
        assert_str(src, "real");
    }
    #[test]
    fn force_unwrap_on_value_returns_value() {
        let src = r#"
            local x: string? = "ok"
            x!
        "#;
        assert_str(src, "ok");
    }
    #[test]
    fn force_unwrap_on_nil_errors() {
        assert_errs("local x: string? = nil\nx!");
    }
    #[test]
    fn combined_safe_call_and_coalesce() {
        let src = r#"
            class P
                name: string
                fn init(n: string)
                    self.name = n
                end
                fn getName(self) -> string return self.name end
            end
            local p: P? = nil
            local n: string = p?.getName() ?? "Unknown"
            n
        "#;
        assert_str(src, "Unknown");
    }
}

// ── §Error Handling ─────────────────────────────────────────────────────

mod error_handling {
    use super::*;

    #[test]
    fn try_catches_thrown_string() {
