            try
                throw "boom"
            catch e: string
                caught = e
            end
            caught
        "#;
        assert_str(src, "boom");
    }
    #[test]
    fn try_body_completes_without_throw() {
        let src = r#"
            local x: integer = 0
            try
                x = 42
            catch e: string
                x = -1
            end
            x
        "#;
        assert_int(src, 42);
    }
    #[test]
    fn nested_try_catch() {
        let src = r#"
            local outer: string = "none"
            try
                try
                    throw "inner"
                catch e: string
                    throw "wrapped: " .. e
                end
            catch e: string
                outer = e
            end
            outer
        "#;
        assert_str(src, "wrapped: inner");
    }
    #[test]
    fn uncaught_throw_bubbles_as_error() {
        assert_errs(r#"throw "kaboom""#);
    }
    #[test]
    fn throw_from_inside_function_caught_outside() {
        let src = r#"
            fn bad()
                throw "no good"
            end
            local msg: string = ""
            try
                bad()
            catch e: string
                msg = e
            end
            msg
        "#;
        assert_str(src, "no good");
    }
}

