//! `Io` static class + `File` value type + `IoMode`/`IoSeek` enums.
//!
//! Design choices:
//!
//! * `Io` is a static class (like `Math` / `String` / `Table`) with statics
//!   `stdin` / `stdout` / `stderr` and methods `open` / `lines` / `read` /
//!   `write`.
//!
//! * File handles are first-class `Value::File` values. Their methods —
//!   `read` / `write` / `lines` / `seek` / `flush` / `close` — are dispatched
//!   by the evaluator via [`dispatch_file_method`] rather than living on a
//!   regular `ClassObject`. A phantom `File` class is still registered so the
//!   typechecker recognises `File` as a type name.
//!
//! * Mode and seek-whence are real Saule **enums** (`IoMode`, `IoSeek`),
//!   registered programmatically. Natives read the variant's `.value` string
//!   to drive the underlying `OpenOptions` / `SeekFrom`.

use std::cell::RefCell;
use std::collections::HashMap;
use std::fs::OpenOptions;
use std::io::{BufRead, BufReader, Read, Seek, SeekFrom, Write};
use std::rc::Rc;

use crate::env::Environment;
use crate::value::{
    ClassObject, EnumObject, EnumVariantObject, FieldDef, FileHandle, NativeClosure, Value,
};

// ─── installation ──────────────────────────────────────────────────────────

pub fn install(env: &Rc<RefCell<Environment>>) {
    install_enum(env, "IoMode", &[
        ("Read",         "r"),
        ("Write",        "w"),
        ("Append",       "a"),
        ("ReadWrite",    "r+"),
        ("WriteRead",    "w+"),
        ("AppendRead",   "a+"),
        ("ReadBinary",   "rb"),
        ("WriteBinary",  "wb"),
        ("AppendBinary", "ab"),
    ]);
    install_enum(env, "IoSeek", &[
        ("Set", "set"),
        ("Cur", "cur"),
        ("End", "end"),
    ]);

    // Phantom `File` class — only needed so the typechecker recognises
    // `File` as a type name in `local f: File = ...`. Method dispatch happens
    // in `dispatch_file_method`, not through this class.
    let file_class = ClassObject {
        name: "File".to_string(),
        parent: None,
        field_defs: Vec::<FieldDef>::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(HashMap::new()),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("File".to_string(), Value::Class(Rc::new(file_class)));

    // `Io` class — statics + native methods.
    let mut static_fields = HashMap::new();
    static_fields.insert(
        "stdin".to_string(),
        Value::File(Rc::new(RefCell::new(FileHandle::Stdin(BufReader::new(
            std::io::stdin(),
        ))))),
    );
    static_fields.insert(
        "stdout".to_string(),
        Value::File(Rc::new(RefCell::new(FileHandle::Stdout))),
    );
    static_fields.insert(
        "stderr".to_string(),
        Value::File(Rc::new(RefCell::new(FileHandle::Stderr))),
    );
    static_fields.insert("open".to_string(),  native_multi("Io.open",  io_open));
    static_fields.insert("lines".to_string(), native_multi("Io.lines", io_lines));
    static_fields.insert("read".to_string(),  native_multi("Io.read",  io_read));
    static_fields.insert("write".to_string(), native_multi("Io.write", io_write));

    let io_class = ClassObject {
        name: "Io".to_string(),
        parent: None,
        field_defs: Vec::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(static_fields),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("Io".to_string(), Value::Class(Rc::new(io_class)));
}

/// Register native signatures for the typechecker (lazy, via `sigs::lookup`).
pub fn register_sigs() {
    use crate::stdlib::sigs::{register, t_named, t_nullable};
    let s = || t_named("string");
    let i = || t_named("integer");
    let nil = || t_named("nil");
    let file_opt = || t_nullable(t_named("File"));
    let file = || t_named("File");
    let str_opt = || t_nullable(s());

    register("Io.open",  vec![s(), t_named("IoMode")], vec![file_opt()]);
    register("Io.lines", vec![t_nullable(s())],        vec![t_named("any")]);
    register("Io.read",  vec![s()],                    vec![str_opt()]);
    register("Io.write", vec![s()],                    vec![nil()]);

    // File method signatures — only consulted by typeck when it learns to
    // route `file.method(...)`. Pre-registering keeps the contract visible.
    register("File.read",  vec![s()],            vec![str_opt()]);
    register("File.write", vec![s()],            vec![nil()]);
    register("File.lines", vec![],               vec![t_named("any")]);
    register("File.seek",  vec![t_named("IoSeek"), i()], vec![i()]);
    register("File.flush", vec![],               vec![nil()]);
    register("File.close", vec![],               vec![nil()]);
    // Suppress unused warnings for the helpers we didn't reach for.
    let _ = file;
}

// ─── enum helper ───────────────────────────────────────────────────────────

fn install_enum(env: &Rc<RefCell<Environment>>, name: &str, variants: &[(&str, &str)]) {
    let mut variant_dict = HashMap::new();
    for (vname, vvalue) in variants {
        variant_dict.insert(
            (*vname).to_string(),
            Rc::new(EnumVariantObject {
                enum_name: name.to_string(),
                variant_name: (*vname).to_string(),
                value: Some(Value::Str(Rc::new((*vvalue).to_string()))),
                enum_obj: RefCell::new(None),
            }),
        );
    }
    let final_enum = Rc::new(EnumObject {
        name: name.to_string(),
        variants: variant_dict.clone(),
        methods: HashMap::new(),
    });
    for v in variant_dict.values() {
        *v.enum_obj.borrow_mut() = Some(final_enum.clone());
    }
    env.borrow_mut()
        .define(name.to_string(), Value::Enum(final_enum));
}

// ─── native helpers ────────────────────────────────────────────────────────

fn native_multi(
    name: &'static str,
    func: fn(&[Value]) -> Result<Vec<Value>, String>,
) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name,
        func: Box::new(move |args| func(args)),
    }))
}

fn expect_string(name: &str, args: &[Value], idx: usize) -> Result<String, String> {
    match args.get(idx) {
        Some(Value::Str(s)) => Ok((**s).clone()),
        Some(other) => Err(format!(
            "{name} expects a string at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

/// Extract the underlying string value from an `IoMode` / `IoSeek` variant,
/// or accept a raw string (handy for tests and ad-hoc calls).
fn extract_enum_string(name: &str, args: &[Value], idx: usize) -> Result<String, String> {
    match args.get(idx) {
        Some(Value::EnumVariant(ev)) => match &ev.value {
            Some(Value::Str(s)) => Ok((**s).clone()),
            _ => Err(format!(
                "{name}: enum variant `{}.{}` has no string value",
                ev.enum_name, ev.variant_name
            )),
        },
        Some(Value::Str(s)) => Ok((**s).clone()),
        Some(other) => Err(format!(
            "{name} expects an enum variant or string at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

// ─── Io.open ─────────────────────────���─────────────────────────────────────

fn io_open(args: &[Value]) -> Result<Vec<Value>, String> {
    let path = expect_string("Io.open", args, 0)?;
    let mode = if args.len() >= 2 {
        extract_enum_string("Io.open", args, 1)?
    } else {
        "r".to_string()
    };

    let mut opts = OpenOptions::new();
    let (readable, writable) = match mode.as_str() {
        "r"  | "rb"            => { opts.read(true);                                      (true,  false) }
        "w"  | "wb"            => { opts.write(true).create(true).truncate(true);         (false, true ) }
        "a"  | "ab"            => { opts.append(true).create(true);                       (false, true ) }
        "r+" | "rb+" | "r+b"   => { opts.read(true).write(true);                          (true,  true ) }
        "w+" | "wb+" | "w+b"   => { opts.read(true).write(true).create(true).truncate(true); (true, true ) }
        "a+" | "ab+" | "a+b"   => { opts.read(true).append(true).create(true);            (true,  true ) }
        other => return Err(format!("Io.open: unknown mode `{other}`")),
    };

    match opts.open(&path) {
        Ok(file) => {
            let reader = if readable {
                let cloned = file.try_clone().map_err(|e| e.to_string())?;
                Some(BufReader::new(cloned))
            } else {
                None
            };
            let writer = if writable { Some(file) } else { None };
            Ok(vec![Value::File(Rc::new(RefCell::new(FileHandle::Open {
                path,
                reader,
                writer,
            })))])
        }
        // Lua semantics: failure returns nil (we drop the OS errno from the
        // tuple — `Result<File>` would be the richer alternative).
        Err(_) => Ok(vec![Value::Nil]),
    }
}

// ─── Io.lines ──────────────────────────────────────────────────────────────

fn io_lines(args: &[Value]) -> Result<Vec<Value>, String> {
    let path = match args.first() {
        Some(Value::Str(s)) => (**s).clone(),
        Some(Value::Nil) | None => {
            // No path → iterate stdin.
            let reader = Rc::new(RefCell::new(BufReader::new(std::io::stdin())));
            return Ok(vec![lines_step_stdin(reader)]);
        }
        Some(other) => {
            return Err(format!(
                "Io.lines expects a string path or nil, got `{}`",
                other.type_name()
            ));
        }
    };

    let file = std::fs::File::open(&path).map_err(|e| format!("Io.lines: {e}"))?;
    let reader = Rc::new(RefCell::new(BufReader::new(file)));
    Ok(vec![lines_step_file(reader)])
}

fn lines_step_file(reader: Rc<RefCell<BufReader<std::fs::File>>>) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name: "Io.lines#step",
        func: Box::new(move |_| {
            let mut buf = String::new();
            let mut r = reader.borrow_mut();
            match r.read_line(&mut buf) {
                Ok(0) => Ok(vec![Value::Nil]),
                Ok(_) => {
                    strip_trailing_newline(&mut buf);
                    Ok(vec![Value::Str(Rc::new(buf))])
                }
                Err(e) => Err(format!("Io.lines: read error: {e}")),
            }
        }),
    }))
}

fn lines_step_stdin(reader: Rc<RefCell<BufReader<std::io::Stdin>>>) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name: "Io.lines#stdin-step",
        func: Box::new(move |_| {
            let mut buf = String::new();
            let mut r = reader.borrow_mut();
            match r.read_line(&mut buf) {
                Ok(0) => Ok(vec![Value::Nil]),
                Ok(_) => {
                    strip_trailing_newline(&mut buf);
                    Ok(vec![Value::Str(Rc::new(buf))])
                }
                Err(e) => Err(format!("Io.lines: read error: {e}")),
            }
        }),
    }))
}

fn strip_trailing_newline(s: &mut String) {
    if s.ends_with('\n') {
        s.pop();
        if s.ends_with('\r') {
            s.pop();
        }
    }
}

// ─── Io.read / Io.write — operate on stdin / stdout ────────────────────────

fn io_read(args: &[Value]) -> Result<Vec<Value>, String> {
    let format = if args.is_empty() {
        "l".to_string()
    } else {
        expect_string("Io.read", args, 0)?
    };
    read_format(&format, &mut ReadSource::Stdin)
}

fn io_write(args: &[Value]) -> Result<Vec<Value>, String> {
    let mut out = std::io::stdout();
    for v in args {
        let _ = out.write_all(v.to_display_string().as_bytes());
    }
    let _ = out.flush();
    Ok(vec![Value::Nil])
}

// ─── shared read format ────────────────────────────────────────────────────

enum ReadSource<'a> {
    Stdin,
    BufFile(&'a mut BufReader<std::fs::File>),
    BufStdin(&'a mut BufReader<std::io::Stdin>),
}

fn read_format(fmt: &str, src: &mut ReadSource<'_>) -> Result<Vec<Value>, String> {
    // Lua-style format characters: "l" line w/o newline, "L" line w/ newline,
    // "a" everything, "n" integer (best-effort).
    let fmt = fmt.trim_start_matches('*');
    match fmt {
        "l" | "L" => {
            let mut buf = String::new();
            let bytes = read_line_src(src, &mut buf)?;
            if bytes == 0 {
                return Ok(vec![Value::Nil]);
            }
            if fmt == "l" {
                strip_trailing_newline(&mut buf);
            }
            Ok(vec![Value::Str(Rc::new(buf))])
        }
        "a" => {
            let mut buf = String::new();
            read_all_src(src, &mut buf)?;
            Ok(vec![Value::Str(Rc::new(buf))])
        }
        "n" => {
            let mut buf = String::new();
            let bytes = read_line_src(src, &mut buf)?;
            if bytes == 0 {
                return Ok(vec![Value::Nil]);
            }
            match buf.trim().parse::<i64>() {
                Ok(n) => Ok(vec![Value::Int(n)]),
                Err(_) => Ok(vec![Value::Nil]),
            }
        }
        other => Err(format!("Io.read: unsupported format `{other}`")),
    }
}

fn read_line_src(src: &mut ReadSource<'_>, buf: &mut String) -> Result<usize, String> {
    let r = match src {
        ReadSource::Stdin => {
            let stdin = std::io::stdin();
            return stdin
                .lock()
                .read_line(buf)
                .map_err(|e| e.to_string());
        }
        ReadSource::BufFile(r) => r.read_line(buf),
        ReadSource::BufStdin(r) => r.read_line(buf),
    };
    r.map_err(|e| e.to_string())
}

fn read_all_src(src: &mut ReadSource<'_>, buf: &mut String) -> Result<(), String> {
    match src {
        ReadSource::Stdin => {
            std::io::stdin().lock().read_to_string(buf).map_err(|e| e.to_string())?;
        }
        ReadSource::BufFile(r) => {
            r.read_to_string(buf).map_err(|e| e.to_string())?;
        }
        ReadSource::BufStdin(r) => {
            r.read_to_string(buf).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

// ─── file method dispatch ──────────────────────────────────────────────────

/// Route `file.METHOD(args...)` calls. Called from `dispatch_member_call_multi`.
pub fn dispatch_file_method(
    handle: &Rc<RefCell<FileHandle>>,
    method: &str,
    args: &[&Value],
) -> Result<Vec<Value>, String> {
    let args: Vec<Value> = args.iter().map(|v| (*v).clone()).collect();
    match method {
        "read"  => file_read(handle, &args),
        "write" => file_write(handle, &args),
        "lines" => file_lines(handle, &args),
        "seek"  => file_seek(handle, &args),
        "flush" => file_flush(handle, &args),
        "close" => file_close(handle, &args),
        other   => Err(format!(
            "no method `{other}` on file — valid: read / write / lines / seek / flush / close"
        )),
    }
}

fn require_open<'a>(
    handle: &'a mut std::cell::RefMut<'_, FileHandle>,
) -> Result<&'a mut FileHandle, String> {
    if matches!(**handle, FileHandle::Closed) {
        return Err("file is closed".to_string());
    }
    Ok(&mut **handle)
}

fn file_read(handle: &Rc<RefCell<FileHandle>>, args: &[Value]) -> Result<Vec<Value>, String> {
    let format = if args.is_empty() {
        "l".to_string()
    } else {
        expect_string("File.read", args, 0)?
    };
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { reader: Some(r), .. } => {
            let mut src = ReadSource::BufFile(r);
            read_format(&format, &mut src)
        }
        FileHandle::Stdin(r) => {
            let mut src = ReadSource::BufStdin(r);
            read_format(&format, &mut src)
        }
        FileHandle::Open { reader: None, .. } => Err("file is not opened for reading".to_string()),
        FileHandle::Stdout | FileHandle::Stderr => {
            Err("cannot read from stdout/stderr".to_string())
        }
        FileHandle::Closed => unreachable!(),
    }
}

fn file_write(handle: &Rc<RefCell<FileHandle>>, args: &[Value]) -> Result<Vec<Value>, String> {
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { writer: Some(w), .. } => {
            for v in args {
                w.write_all(v.to_display_string().as_bytes())
                    .map_err(|e| e.to_string())?;
            }
            Ok(vec![Value::Nil])
        }
        FileHandle::Stdout => {
            let mut out = std::io::stdout();
            for v in args {
                let _ = out.write_all(v.to_display_string().as_bytes());
            }
            let _ = out.flush();
            Ok(vec![Value::Nil])
        }
        FileHandle::Stderr => {
            let mut err = std::io::stderr();
            for v in args {
                let _ = err.write_all(v.to_display_string().as_bytes());
            }
            let _ = err.flush();
            Ok(vec![Value::Nil])
        }
        FileHandle::Open { writer: None, .. } => {
            Err("file is not opened for writing".to_string())
        }
        FileHandle::Stdin(_) => Err("cannot write to stdin".to_string()),
        FileHandle::Closed => unreachable!(),
    }
}

fn file_lines(handle: &Rc<RefCell<FileHandle>>, _args: &[Value]) -> Result<Vec<Value>, String> {
    // Build a step closure that re-borrows the same handle each iteration.
    let h = handle.clone();
    Ok(vec![Value::NativeClosure(Rc::new(NativeClosure {
        name: "File.lines#step",
        func: Box::new(move |_| {
            let mut handle = h.borrow_mut();
            match &mut *handle {
                FileHandle::Open { reader: Some(r), .. } => {
                    let mut buf = String::new();
                    match r.read_line(&mut buf) {
                        Ok(0) => Ok(vec![Value::Nil]),
                        Ok(_) => {
                            strip_trailing_newline(&mut buf);
                            Ok(vec![Value::Str(Rc::new(buf))])
                        }
                        Err(e) => Err(format!("File.lines: {e}")),
                    }
                }
                FileHandle::Stdin(r) => {
                    let mut buf = String::new();
                    match r.read_line(&mut buf) {
                        Ok(0) => Ok(vec![Value::Nil]),
                        Ok(_) => {
                            strip_trailing_newline(&mut buf);
                            Ok(vec![Value::Str(Rc::new(buf))])
                        }
                        Err(e) => Err(format!("File.lines: {e}")),
                    }
                }
                FileHandle::Closed => Err("File.lines: file is closed".to_string()),
                _ => Err("File.lines: file is not readable".to_string()),
            }
        }),
    }))])
}

fn file_seek(handle: &Rc<RefCell<FileHandle>>, args: &[Value]) -> Result<Vec<Value>, String> {
    let whence = if args.is_empty() {
        "cur".to_string()
    } else {
        extract_enum_string("File.seek", args, 0)?
    };
    let offset = if args.len() >= 2 {
        match &args[1] {
            Value::Int(n) => *n,
            other => return Err(format!(
                "File.seek expects an integer offset, got `{}`",
                other.type_name()
            )),
        }
    } else { 0 };

    let from = match whence.as_str() {
        "set" => SeekFrom::Start(offset.max(0) as u64),
        "cur" => SeekFrom::Current(offset),
        "end" => SeekFrom::End(offset),
        other => return Err(format!("File.seek: invalid whence `{other}`")),
    };
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { reader, writer, .. } => {
            // Prefer seeking the writer if present (matches Lua's behaviour
            // on r+/w+/a+: the file shares the OS cursor).
            let pos = if let Some(w) = writer {
                w.seek(from).map_err(|e| e.to_string())?
            } else if let Some(r) = reader {
                // BufReader seeks its inner File, then reseeks its buffer.
                r.seek(from).map_err(|e| e.to_string())?
            } else {
                return Err("file has no seekable backing".to_string());
            };
            Ok(vec![Value::Int(pos as i64)])
        }
        _ => Err("File.seek: not supported on standard streams".to_string()),
    }
}

fn file_flush(handle: &Rc<RefCell<FileHandle>>, _args: &[Value]) -> Result<Vec<Value>, String> {
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { writer: Some(w), .. } => {
            w.flush().map_err(|e| e.to_string())?;
            Ok(vec![Value::Nil])
        }
        FileHandle::Stdout => { let _ = std::io::stdout().flush(); Ok(vec![Value::Nil]) }
        FileHandle::Stderr => { let _ = std::io::stderr().flush(); Ok(vec![Value::Nil]) }
        _ => Ok(vec![Value::Nil]),
    }
}

fn file_close(handle: &Rc<RefCell<FileHandle>>, _args: &[Value]) -> Result<Vec<Value>, String> {
    let mut h = handle.borrow_mut();
    // Standard streams are no-ops on close to match Lua.
    if matches!(*h, FileHandle::Stdout | FileHandle::Stderr | FileHandle::Stdin(_)) {
        return Ok(vec![Value::Nil]);
    }
    *h = FileHandle::Closed;
    Ok(vec![Value::Nil])
}

//! `Io` static class + `File` value type + `IoMode`/`IoSeek` enums.
//!
//! Design choices:
//!
//! * `Io` is a static class (like `Math` / `String` / `Table`) with statics
//!   `stdin` / `stdout` / `stderr` and methods `open` / `lines` / `read` /
//!   `write`.
//!
//! * File handles are first-class `Value::File` values. Their methods —
//!   `read` / `write` / `lines` / `seek` / `flush` / `close` — are dispatched
//!   by the evaluator via [`dispatch_file_method`] rather than living on a
//!   regular `ClassObject`. A phantom `File` class is still registered so the
//!   typechecker recognises `File` as a type name.
//!
//! * Mode and seek-whence are real Saule **enums** (`IoMode`, `IoSeek`),
//!   registered programmatically. Natives read the variant's `.value` string
//!   to drive the underlying `OpenOptions` / `SeekFrom`.

use std::cell::RefCell;
use std::collections::HashMap;
use std::fs::OpenOptions;
use std::io::{BufRead, BufReader, Read, Seek, SeekFrom, Write};
use std::rc::Rc;

use crate::env::Environment;
use crate::value::{
    ClassObject, EnumObject, EnumVariantObject, FieldDef, FileHandle, NativeClosure, Value,
};

// ─── installation ──────────────────────────────────────────────────────────

pub fn install(env: &Rc<RefCell<Environment>>) {
    install_enum(env, "IoMode", &[
        ("Read",         "r"),
        ("Write",        "w"),
        ("Append",       "a"),
        ("ReadWrite",    "r+"),
        ("WriteRead",    "w+"),
        ("AppendRead",   "a+"),
        ("ReadBinary",   "rb"),
        ("WriteBinary",  "wb"),
        ("AppendBinary", "ab"),
    ]);
    install_enum(env, "IoSeek", &[
        ("Set", "set"),
        ("Cur", "cur"),
        ("End", "end"),
    ]);

    // Phantom `File` class — only needed so the typechecker recognises
    // `File` as a type name in `local f: File = ...`. Method dispatch happens
    // in `dispatch_file_method`, not through this class.
    let file_class = ClassObject {
        name: "File".to_string(),
        parent: None,
        field_defs: Vec::<FieldDef>::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(HashMap::new()),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("File".to_string(), Value::Class(Rc::new(file_class)));

    // `Io` class — statics + native methods.
    let mut static_fields = HashMap::new();
    static_fields.insert(
        "stdin".to_string(),
        Value::File(Rc::new(RefCell::new(FileHandle::Stdin(BufReader::new(
            std::io::stdin(),
        ))))),
    );
    static_fields.insert(
        "stdout".to_string(),
        Value::File(Rc::new(RefCell::new(FileHandle::Stdout))),
    );
    static_fields.insert(
        "stderr".to_string(),
        Value::File(Rc::new(RefCell::new(FileHandle::Stderr))),
    );
    static_fields.insert("open".to_string(),  native_multi("Io.open",  io_open));
    static_fields.insert("lines".to_string(), native_multi("Io.lines", io_lines));
    static_fields.insert("read".to_string(),  native_multi("Io.read",  io_read));
    static_fields.insert("write".to_string(), native_multi("Io.write", io_write));

    let io_class = ClassObject {
        name: "Io".to_string(),
        parent: None,
        field_defs: Vec::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(static_fields),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("Io".to_string(), Value::Class(Rc::new(io_class)));
}

/// Register native signatures for the typechecker (lazy, via `sigs::lookup`).
pub fn register_sigs() {
    use crate::stdlib::sigs::{register, t_named, t_nullable};
    let s = || t_named("string");
    let i = || t_named("integer");
    let nil = || t_named("nil");
    let file_opt = || t_nullable(t_named("File"));
    let file = || t_named("File");
    let str_opt = || t_nullable(s());

    register("Io.open",  vec![s(), t_named("IoMode")], vec![file_opt()]);
    register("Io.lines", vec![t_nullable(s())],        vec![t_named("any")]);
    register("Io.read",  vec![s()],                    vec![str_opt()]);
    register("Io.write", vec![s()],                    vec![nil()]);

    // File method signatures — only consulted by typeck when it learns to
    // route `file.method(...)`. Pre-registering keeps the contract visible.
    register("File.read",  vec![s()],            vec![str_opt()]);
    register("File.write", vec![s()],            vec![nil()]);
    register("File.lines", vec![],               vec![t_named("any")]);
    register("File.seek",  vec![t_named("IoSeek"), i()], vec![i()]);
    register("File.flush", vec![],               vec![nil()]);
    register("File.close", vec![],               vec![nil()]);
    // Suppress unused warnings for the helpers we didn't reach for.
    let _ = file;
}

// ─── enum helper ───────────────────────────────────────────────────────────

fn install_enum(env: &Rc<RefCell<Environment>>, name: &str, variants: &[(&str, &str)]) {
    let mut variant_dict = HashMap::new();
    for (vname, vvalue) in variants {
        variant_dict.insert(
            (*vname).to_string(),
            Rc::new(EnumVariantObject {
                enum_name: name.to_string(),
                variant_name: (*vname).to_string(),
                value: Some(Value::Str(Rc::new((*vvalue).to_string()))),
                enum_obj: RefCell::new(None),
            }),
        );
    }
    let final_enum = Rc::new(EnumObject {
        name: name.to_string(),
        variants: variant_dict.clone(),
        methods: HashMap::new(),
    });
    for v in variant_dict.values() {
        *v.enum_obj.borrow_mut() = Some(final_enum.clone());
    }
    env.borrow_mut()
        .define(name.to_string(), Value::Enum(final_enum));
}

// ─── native helpers ────────────────────────────────────────────────────────

fn native_multi(
    name: &'static str,
    func: fn(&[Value]) -> Result<Vec<Value>, String>,
) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name,
        func: Box::new(move |args| func(args)),
    }))
}

fn expect_string(name: &str, args: &[Value], idx: usize) -> Result<String, String> {
    match args.get(idx) {
        Some(Value::Str(s)) => Ok((**s).clone()),
        Some(other) => Err(format!(
            "{name} expects a string at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

/// Extract the underlying string value from an `IoMode` / `IoSeek` variant,
/// or accept a raw string (handy for tests and ad-hoc calls).
fn extract_enum_string(name: &str, args: &[Value], idx: usize) -> Result<String, String> {
    match args.get(idx) {
        Some(Value::EnumVariant(ev)) => match &ev.value {
            Some(Value::Str(s)) => Ok((**s).clone()),
            _ => Err(format!(
                "{name}: enum variant `{}.{}` has no string value",
                ev.enum_name, ev.variant_name
            )),
        },
        Some(Value::Str(s)) => Ok((**s).clone()),
        Some(other) => Err(format!(
            "{name} expects an enum variant or string at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

// ─── Io.open ─────────────────────────���─────────────────────────────────────

fn io_open(args: &[Value]) -> Result<Vec<Value>, String> {
    let path = expect_string("Io.open", args, 0)?;
    let mode = if args.len() >= 2 {
        extract_enum_string("Io.open", args, 1)?
    } else {
        "r".to_string()
    };

    let mut opts = OpenOptions::new();
    let (readable, writable) = match mode.as_str() {
        "r"  | "rb"            => { opts.read(true);                                      (true,  false) }
        "w"  | "wb"            => { opts.write(true).create(true).truncate(true);         (false, true ) }
        "a"  | "ab"            => { opts.append(true).create(true);                       (false, true ) }
        "r+" | "rb+" | "r+b"   => { opts.read(true).write(true);                          (true,  true ) }
        "w+" | "wb+" | "w+b"   => { opts.read(true).write(true).create(true).truncate(true); (true, true ) }
        "a+" | "ab+" | "a+b"   => { opts.read(true).append(true).create(true);            (true,  true ) }
        other => return Err(format!("Io.open: unknown mode `{other}`")),
    };

    match opts.open(&path) {
        Ok(file) => {
            let reader = if readable {
                let cloned = file.try_clone().map_err(|e| e.to_string())?;
                Some(BufReader::new(cloned))
            } else {
                None
            };
            let writer = if writable { Some(file) } else { None };
            Ok(vec![Value::File(Rc::new(RefCell::new(FileHandle::Open {
                path,
                reader,
                writer,
            })))])
        }
        // Lua semantics: failure returns nil (we drop the OS errno from the
        // tuple — `Result<File>` would be the richer alternative).
        Err(_) => Ok(vec![Value::Nil]),
    }
}

// ─── Io.lines ──────────────────────────────────────────────────────────────

fn io_lines(args: &[Value]) -> Result<Vec<Value>, String> {
    let path = match args.first() {
        Some(Value::Str(s)) => (**s).clone(),
        Some(Value::Nil) | None => {
            // No path → iterate stdin.
            let reader = Rc::new(RefCell::new(BufReader::new(std::io::stdin())));
            return Ok(vec![lines_step_stdin(reader)]);
        }
        Some(other) => {
            return Err(format!(
                "Io.lines expects a string path or nil, got `{}`",
                other.type_name()
            ));
        }
    };

    let file = std::fs::File::open(&path).map_err(|e| format!("Io.lines: {e}"))?;
    let reader = Rc::new(RefCell::new(BufReader::new(file)));
    Ok(vec![lines_step_file(reader)])
}

fn lines_step_file(reader: Rc<RefCell<BufReader<std::fs::File>>>) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name: "Io.lines#step",
        func: Box::new(move |_| {
            let mut buf = String::new();
            let mut r = reader.borrow_mut();
            match r.read_line(&mut buf) {
                Ok(0) => Ok(vec![Value::Nil]),
                Ok(_) => {
                    strip_trailing_newline(&mut buf);
                    Ok(vec![Value::Str(Rc::new(buf))])
                }
                Err(e) => Err(format!("Io.lines: read error: {e}")),
            }
        }),
    }))
}

fn lines_step_stdin(reader: Rc<RefCell<BufReader<std::io::Stdin>>>) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name: "Io.lines#stdin-step",
        func: Box::new(move |_| {
            let mut buf = String::new();
            let mut r = reader.borrow_mut();
            match r.read_line(&mut buf) {
                Ok(0) => Ok(vec![Value::Nil]),
                Ok(_) => {
                    strip_trailing_newline(&mut buf);
                    Ok(vec![Value::Str(Rc::new(buf))])
                }
                Err(e) => Err(format!("Io.lines: read error: {e}")),
            }
        }),
    }))
}

fn strip_trailing_newline(s: &mut String) {
    if s.ends_with('\n') {
        s.pop();
        if s.ends_with('\r') {
            s.pop();
        }
    }
}

// ─── Io.read / Io.write — operate on stdin / stdout ────────────────────────

fn io_read(args: &[Value]) -> Result<Vec<Value>, String> {
    let format = if args.is_empty() {
        "l".to_string()
    } else {
        expect_string("Io.read", args, 0)?
    };
    read_format(&format, &mut ReadSource::Stdin)
}

fn io_write(args: &[Value]) -> Result<Vec<Value>, String> {
    let mut out = std::io::stdout();
    for v in args {
        let _ = out.write_all(v.to_display_string().as_bytes());
    }
    let _ = out.flush();
    Ok(vec![Value::Nil])
}

// ─── shared read format ────────────────────────────────────────────────────

enum ReadSource<'a> {
    Stdin,
    BufFile(&'a mut BufReader<std::fs::File>),
    BufStdin(&'a mut BufReader<std::io::Stdin>),
}

fn read_format(fmt: &str, src: &mut ReadSource<'_>) -> Result<Vec<Value>, String> {
    // Lua-style format characters: "l" line w/o newline, "L" line w/ newline,
    // "a" everything, "n" integer (best-effort).
    let fmt = fmt.trim_start_matches('*');
    match fmt {
        "l" | "L" => {
            let mut buf = String::new();
            let bytes = read_line_src(src, &mut buf)?;
            if bytes == 0 {
                return Ok(vec![Value::Nil]);
            }
            if fmt == "l" {
                strip_trailing_newline(&mut buf);
            }
            Ok(vec![Value::Str(Rc::new(buf))])
        }
        "a" => {
            let mut buf = String::new();
            read_all_src(src, &mut buf)?;
            Ok(vec![Value::Str(Rc::new(buf))])
        }
        "n" => {
            let mut buf = String::new();
            let bytes = read_line_src(src, &mut buf)?;
            if bytes == 0 {
                return Ok(vec![Value::Nil]);
            }
            match buf.trim().parse::<i64>() {
                Ok(n) => Ok(vec![Value::Int(n)]),
                Err(_) => Ok(vec![Value::Nil]),
            }
        }
        other => Err(format!("Io.read: unsupported format `{other}`")),
    }
}

fn read_line_src(src: &mut ReadSource<'_>, buf: &mut String) -> Result<usize, String> {
    let r = match src {
        ReadSource::Stdin => {
            let stdin = std::io::stdin();
            return stdin
                .lock()
                .read_line(buf)
                .map_err(|e| e.to_string());
        }
        ReadSource::BufFile(r) => r.read_line(buf),
        ReadSource::BufStdin(r) => r.read_line(buf),
    };
    r.map_err(|e| e.to_string())
}

fn read_all_src(src: &mut ReadSource<'_>, buf: &mut String) -> Result<(), String> {
    match src {
        ReadSource::Stdin => {
            std::io::stdin().lock().read_to_string(buf).map_err(|e| e.to_string())?;
        }
        ReadSource::BufFile(r) => {
            r.read_to_string(buf).map_err(|e| e.to_string())?;
        }
        ReadSource::BufStdin(r) => {
            r.read_to_string(buf).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

// ─── file method dispatch ──────────────────────────────────────────────────

/// Route `file.METHOD(args...)` calls. Called from `dispatch_member_call_multi`.
pub fn dispatch_file_method(
    handle: &Rc<RefCell<FileHandle>>,
    method: &str,
    args: &[Value],
) -> Result<Vec<Value>, String> {
    match method {
        "read"  => file_read(handle, args),
        "write" => file_write(handle, args),
        "lines" => file_lines(handle, args),
        "seek"  => file_seek(handle, args),
        "flush" => file_flush(handle, args),
        "close" => file_close(handle, args),
        other   => Err(format!(
            "no method `{other}` on file — valid: read / write / lines / seek / flush / close"
        )),
    }
}

fn require_open<'a>(
    handle: &'a mut std::cell::RefMut<'_, FileHandle>,
) -> Result<&'a mut FileHandle, String> {
    if matches!(**handle, FileHandle::Closed) {
        return Err("file is closed".to_string());
    }
    Ok(&mut **handle)
}

fn file_read(handle: &Rc<RefCell<FileHandle>>, args: &[Value]) -> Result<Vec<Value>, String> {
    let format = if args.is_empty() {
        "l".to_string()
    } else {
        expect_string("File.read", args, 0)?
    };
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { reader: Some(r), .. } => {
            let mut src = ReadSource::BufFile(r);
            read_format(&format, &mut src)
        }
        FileHandle::Stdin(r) => {
            let mut src = ReadSource::BufStdin(r);
            read_format(&format, &mut src)
        }
        FileHandle::Open { reader: None, .. } => Err("file is not opened for reading".to_string()),
        FileHandle::Stdout | FileHandle::Stderr => {
            Err("cannot read from stdout/stderr".to_string())
        }
        FileHandle::Closed => unreachable!(),
    }
}

fn file_write(handle: &Rc<RefCell<FileHandle>>, args: &[Value]) -> Result<Vec<Value>, String> {
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { writer: Some(w), .. } => {
            for v in args {
                w.write_all(v.to_display_string().as_bytes())
                    .map_err(|e| e.to_string())?;
            }
            Ok(vec![Value::Nil])
        }
        FileHandle::Stdout => {
            let mut out = std::io::stdout();
            for v in args {
                let _ = out.write_all(v.to_display_string().as_bytes());
            }
            let _ = out.flush();
            Ok(vec![Value::Nil])
        }
        FileHandle::Stderr => {
            let mut err = std::io::stderr();
            for v in args {
                let _ = err.write_all(v.to_display_string().as_bytes());
            }
            let _ = err.flush();
            Ok(vec![Value::Nil])
        }
        FileHandle::Open { writer: None, .. } => {
            Err("file is not opened for writing".to_string())
        }
        FileHandle::Stdin(_) => Err("cannot write to stdin".to_string()),
        FileHandle::Closed => unreachable!(),
    }
}

fn file_lines(handle: &Rc<RefCell<FileHandle>>, _args: &[Value]) -> Result<Vec<Value>, String> {
    // Build a step closure that re-borrows the same handle each iteration.
    let h = handle.clone();
    Ok(vec![Value::NativeClosure(Rc::new(NativeClosure {
        name: "File.lines#step",
        func: Box::new(move |_| {
            let mut handle = h.borrow_mut();
            match &mut *handle {
                FileHandle::Open { reader: Some(r), .. } => {
                    let mut buf = String::new();
                    match r.read_line(&mut buf) {
                        Ok(0) => Ok(vec![Value::Nil]),
                        Ok(_) => {
                            strip_trailing_newline(&mut buf);
                            Ok(vec![Value::Str(Rc::new(buf))])
                        }
                        Err(e) => Err(format!("File.lines: {e}")),
                    }
                }
                FileHandle::Stdin(r) => {
                    let mut buf = String::new();
                    match r.read_line(&mut buf) {
                        Ok(0) => Ok(vec![Value::Nil]),
                        Ok(_) => {
                            strip_trailing_newline(&mut buf);
                            Ok(vec![Value::Str(Rc::new(buf))])
                        }
                        Err(e) => Err(format!("File.lines: {e}")),
                    }
                }
                FileHandle::Closed => Err("File.lines: file is closed".to_string()),
                _ => Err("File.lines: file is not readable".to_string()),
            }
        }),
    }))])
}

fn file_seek(handle: &Rc<RefCell<FileHandle>>, args: &[Value]) -> Result<Vec<Value>, String> {
    let whence = if args.is_empty() {
        "cur".to_string()
    } else {
        extract_enum_string("File.seek", args, 0)?
    };
    let offset = if args.len() >= 2 {
        match &args[1] {
            Value::Int(n) => *n,
            other => return Err(format!(
                "File.seek expects an integer offset, got `{}`",
                other.type_name()
            )),
        }
    } else { 0 };

    let from = match whence.as_str() {
        "set" => SeekFrom::Start(offset.max(0) as u64),
        "cur" => SeekFrom::Current(offset),
        "end" => SeekFrom::End(offset),
        other => return Err(format!("File.seek: invalid whence `{other}`")),
    };
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { reader, writer, .. } => {
            // Prefer seeking the writer if present (matches Lua's behaviour
            // on r+/w+/a+: the file shares the OS cursor).
            let pos = if let Some(w) = writer {
                w.seek(from).map_err(|e| e.to_string())?
            } else if let Some(r) = reader {
                // BufReader seeks its inner File, then reseeks its buffer.
                r.seek(from).map_err(|e| e.to_string())?
            } else {
                return Err("file has no seekable backing".to_string());
            };
            Ok(vec![Value::Int(pos as i64)])
        }
        _ => Err("File.seek: not supported on standard streams".to_string()),
    }
}

fn file_flush(handle: &Rc<RefCell<FileHandle>>, _args: &[Value]) -> Result<Vec<Value>, String> {
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { writer: Some(w), .. } => {
            w.flush().map_err(|e| e.to_string())?;
            Ok(vec![Value::Nil])
        }
        FileHandle::Stdout => { let _ = std::io::stdout().flush(); Ok(vec![Value::Nil]) }
        FileHandle::Stderr => { let _ = std::io::stderr().flush(); Ok(vec![Value::Nil]) }
        _ => Ok(vec![Value::Nil]),
    }
}

fn file_close(handle: &Rc<RefCell<FileHandle>>, _args: &[Value]) -> Result<Vec<Value>, String> {
    let mut h = handle.borrow_mut();
    // Standard streams are no-ops on close to match Lua.
    if matches!(*h, FileHandle::Stdout | FileHandle::Stderr | FileHandle::Stdin(_)) {
        return Ok(vec![Value::Nil]);
    }
    *h = FileHandle::Closed;
    Ok(vec![Value::Nil])
}

//! Saule source pretty-printer.
//!
//! Walks a parsed [`saule_ast::Module`] and renders it back to canonical
//! Saule source: 2-space indent, one statement per line, blank line between
//! top-level declarations.
//!
//! ## Comment preservation
//!
//! [`format_module`] discards comments — the AST never sees them. To round
//! trip comments, use [`format_module_with_comments`] together with the
//! lexer's `tokenize_with_trivia` entry point: extract every
//! [`saule_lexer::Token::LineComment`] / `BlockComment` into a [`Comment`]
//! and pass it in.
//!
//! Interleaving is best-effort but covers the common shapes:
//!
//! * Comments before a statement / declaration are emitted on their own
//!   line at the surrounding indent.
//! * A comment that sits on the same source line as the statement it
//!   trails is re-emitted as a same-line trailing comment.
//! * Comments at the tail of a block (just before the closing `end`) are
//!   drained at the right indent so they don't leak past the block.
//! * Blank lines between source comments are preserved when ≥ 2 newlines
//!   separated them in the original source.

use std::{collections::VecDeque, fmt::Write, ops::Range};

use saule_ast::{
    BinOp, CallArg, ClassMember, Decl, EnumVariant, Expr, ImportNames, LambdaBody, MatchArm,
    MatchBody, Method, MethodSig, Module, Param, Pattern, PipeStage, Spanned, Stmt, TableEntry,
    Type, UnaryOp,
};

/// A single source comment extracted from the lexer's trivia stream.
/// `text` is the verbatim payload between the comment delimiters (no
/// `--` / `--[[` / `]]`), matching what `tokenize_with_trivia` emits.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Comment {
    pub span: Range<usize>,
    pub kind: CommentKind,
    pub text: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CommentKind {
    /// `-- text` to end of line.
    Line,
    /// `--[[ text ]]` (may span multiple source lines).
    Block,
}

/// Render a parsed module back to source, dropping any comments. Use
/// [`format_module_with_comments`] to preserve them. The result always
/// ends with exactly one trailing newline (or is empty for an empty
/// module).
pub fn format_module(module: &Module) -> String {
    let mut p = Printer::new("", &[]);
    p.module(module);
    p.finish()
}

/// Like [`format_module`] but threads `comments` (sorted or not, by span
/// start) back into the output. `source` is the original text, used to
/// tell same-line trailing comments from leading ones and to preserve
/// blank-line gaps.
pub fn format_module_with_comments(module: &Module, source: &str, comments: &[Comment]) -> String {
    let mut p = Printer::new(source, comments);
    p.module(module);
    p.finish()
}

struct Printer<'a> {
    out: String,
    indent: usize,
    /// Set right after a newline so the next `write_str` knows to prepend
    /// the current indentation. Avoids trailing whitespace on blank lines.
    needs_indent: bool,
    /// Original source text. Only consulted for newline-counting between
    /// byte positions when interleaving comments; empty when comments are
    /// disabled.
    source: &'a str,
    /// Pending comments, ordered by `span.start`. Drained as the printer
    /// reaches the corresponding source positions.
    comments: VecDeque<&'a Comment>,
    /// Highest source offset we've "consumed" so far — either the end of
    /// the last comment we drained, or 0. Used for blank-line preservation
    /// between consecutive comments.
    last_pos: usize,
}

const INDENT: &str = "  ";

/// Soft target for one rendered line. The `Expr::Pipe` layout uses this to
/// decide whether a `when(...):a():b()` chain fits inline or should be
/// broken across multiple lines. Anything past this threshold flips to
/// the column-aligned multi-line shape.
const MAX_LINE_WIDTH: usize = 100;

impl<'a> Printer<'a> {
    fn new(source: &'a str, comments: &'a [Comment]) -> Self {
        let mut queue: VecDeque<&'a Comment> = comments.iter().collect();
        // Tolerate unsorted inputs.
        queue
            .make_contiguous()
            .sort_by_key(|c| c.span.start);
        Self {
            out: String::new(),
            indent: 0,
            needs_indent: false,
            source,
            comments: queue,
            last_pos: 0,
        }
    }

    fn finish(mut self) -> String {
        // Guarantee exactly one trailing newline.
        while self.out.ends_with("\n\n") {
            self.out.pop();
        }
        if !self.out.is_empty() && !self.out.ends_with('\n') {
            self.out.push('\n');
        }
        self.out
    }

    fn write(&mut self, s: &str) {
        if self.needs_indent {
            for _ in 0..self.indent {
                self.out.push_str(INDENT);
            }
            self.needs_indent = false;
        }
        self.out.push_str(s);
    }

    fn writef(&mut self, args: std::fmt::Arguments<'_>) {
        if self.needs_indent {
            for _ in 0..self.indent {
                self.out.push_str(INDENT);
            }
            self.needs_indent = false;
        }
        let _ = self.out.write_fmt(args);
    }

    fn newline(&mut self) {
        self.out.push('\n');
        self.needs_indent = true;
    }

    fn blank_line(&mut self) {
        // Don't emit duplicate blank lines or a blank line at the start.
        if self.out.is_empty() {
            return;
        }
        if !self.out.ends_with('\n') {
            self.out.push('\n');
        }
        if !self.out.ends_with("\n\n") {
            self.out.push('\n');
        }
        self.needs_indent = true;
    }

    // ---- comment interleaving ---------------------------------------------

    /// Emit every queued comment whose start lies strictly before `pos`,
    /// one per line at the current indent. Preserves blank-line gaps
    /// between consecutive source comments (≥ 2 newlines in the original
    /// source → blank line in the output).
    fn drain_before(&mut self, pos: usize) {
        while let Some(c) = self.comments.front() {
            if c.span.start >= pos {
                break;
            }
            let c = self.comments.pop_front().unwrap();
            // If the printer's current line already has content, this
            // comment can't be a "leading" one — push it to its own line
            // first. (Happens when called mid-construct; rare but cheap.)
            if !self.out.is_empty() && !self.out.ends_with('\n') {
                self.newline();
            }
            // Blank-line preservation between comments / from start of file.
            if self.newlines_in_source(self.last_pos, c.span.start) >= 2 {
                self.blank_line();
            }
            self.write_comment(c);
            self.newline();
            self.last_pos = c.span.end;
        }
    }

    /// If the next pending comment starts on the same source line as
    /// `after_pos`, emit it as a same-line trailing comment (preceded by
    /// two spaces) and consume it. Returns `true` if a comment was
    /// emitted, so callers can skip their own trailing newline logic if
    /// they want.
    fn try_trailing(&mut self, after_pos: usize) -> bool {
        let Some(c) = self.comments.front() else {
            return false;
        };
        if c.span.start < after_pos {
            // Pathological: drain_before should have handled it. Be safe.
            return false;
        }
        if self.newlines_in_source(after_pos, c.span.start) > 0 {
            return false;
        }
        let c = self.comments.pop_front().unwrap();
        self.out.push_str("  ");
        self.write_comment(c);
        self.last_pos = c.span.end;
        true
    }

    fn write_comment(&mut self, c: &Comment) {
        // `write_str` would apply indentation; we want indent only on the
        // first line. Manage it manually.
        if self.needs_indent {
            for _ in 0..self.indent {
                self.out.push_str(INDENT);
            }
            self.needs_indent = false;
        }
        match c.kind {
            CommentKind::Line => {
                self.out.push_str("--");
                self.out.push_str(&c.text);
            }
            CommentKind::Block => {
                self.out.push_str("--[[");
                self.out.push_str(&c.text);
                self.out.push_str("]]");
            }
        }
    }

    /// Count `\n` bytes in `source[from..to]`. Returns 0 if either bound
    /// is out of range or if `from > to`. Used to distinguish same-line
    /// trailing comments from leading ones, and to preserve blank lines.
    fn newlines_in_source(&self, from: usize, to: usize) -> usize {
        if from > to || to > self.source.len() {
            return 0;
        }
        self.source.as_bytes()[from..to]
            .iter()
            .filter(|&&b| b == b'\n')
            .count()
    }

    // ---- top-level ---------------------------------------------------------

    fn module(&mut self, m: &Module) {
        for (i, s) in m.stmts.iter().enumerate() {
            self.drain_before(s.span.start);
            if i > 0 {
                let prev_end = m.stmts[i - 1].span.end;
                // Preserve user-written blank lines between top-level
                // statements (≥ 2 newlines in the source gap).
                if self.newlines_in_source(prev_end, s.span.start) >= 2 {
                    self.blank_line();
                } else if needs_top_separator(&m.stmts[i - 1].value, &s.value) {
                    self.blank_line();
                }
            }
            self.stmt(s);
            self.try_trailing(s.span.end);
            self.newline();
        }
        // Trailing comments at end-of-file (after the last statement).
        self.drain_before(usize::MAX);
    }

    // ---- statements --------------------------------------------------------

    /// Print a block body and drain any comments that lie inside it
    /// before returning. `block_end` is the byte offset where the
    /// enclosing construct closes (typically the parent statement's
    /// `span.end`, which sits just past the `end` keyword).
    fn block(&mut self, body: &[Spanned<Stmt>], block_end: usize) {
        self.indent += 1;
        for (i, s) in body.iter().enumerate() {
            self.drain_before(s.span.start);
            // Preserve user-written blank lines inside blocks.
            if i > 0 {
                let prev_end = body[i - 1].span.end;
                if self.newlines_in_source(prev_end, s.span.start) >= 2 {
                    self.blank_line();
                }
            }
            self.stmt(s);
            self.try_trailing(s.span.end);
            self.newline();
        }
        // Comments hanging between the last stmt and the closing keyword.
        self.drain_before(block_end);
        self.indent -= 1;
    }

    fn stmt(&mut self, s: &Spanned<Stmt>) {
        match &s.value {
            Stmt::Local { name, ty, value } => {
                self.write("local ");
                self.write(name);
                if let Some(t) = ty {
                    self.write(": ");
                    self.ty(t);
                }
                if let Some(v) = value {
                    self.write(" = ");
                    self.expr(v, 0);
                }
            }
            Stmt::LocalMulti { names, values } => {
                self.write("local ");
                for (i, (n, t)) in names.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.write(n);
                    if let Some(t) = t {
                        self.write(": ");
                        self.ty(t);
                    }
                }
                if !values.is_empty() {
                    self.write(" = ");
                    self.expr_list(values);
                }
            }
            Stmt::Assign { target, value } => {
                self.expr(target, 0);
                self.write(" = ");
                self.expr(value, 0);
            }
            Stmt::AssignMulti { targets, values } => {
                self.expr_list(targets);
                self.write(" = ");
                self.expr_list(values);
            }
            Stmt::Expr(e) => self.expr(e, 0),

            Stmt::If {
                cond,
                then_block,
                elseifs,
                else_block,
            } => {
                self.write("if ");
                self.expr(cond, 0);
                self.write(" then");
                self.newline();
                // Ceiling for each chunk: start of the next chunk's
                // keyword (approximated by next cond / next stmt).
                let then_ceiling = next_if_chunk_start(elseifs, else_block, s.span.end);
                self.block(then_block, then_ceiling);
                for (i, (c, body)) in elseifs.iter().enumerate() {
                    self.drain_before(c.span.start);
                    self.write("elseif ");
                    self.expr(c, 0);
                    self.write(" then");
                    self.newline();
                    let ceiling = next_if_chunk_start(&elseifs[i + 1..], else_block, s.span.end);
                    self.block(body, ceiling);
                }
                if let Some(eb) = else_block {
                    let else_start = eb.first().map(|st| st.span.start).unwrap_or(s.span.end);
                    self.drain_before(else_start);
                    self.write("else");
                    self.newline();
                    self.block(eb, s.span.end);
                }
                self.write("end");
            }
            Stmt::While { cond, body } => {
                self.write("while ");
                self.expr(cond, 0);
                self.write(" do");
                self.newline();
                self.block(body, s.span.end);
                self.write("end");
            }
            Stmt::Repeat { body, cond } => {
                self.write("repeat");
                self.newline();
                // `until` sits after the body; use cond.span.start as the
                // body's ceiling so trailing comments don't escape past
                // the `until`.
                self.block(body, cond.span.start);
                self.write("until ");
                self.expr(cond, 0);
            }
            Stmt::ForNumeric {
                var,
                var_ty,
                from,
                to,
                step,
                body,
            } => {
                // Lua-style numeric `for`: `for i = from, to[, step] do ... end`.
                self.write("for ");
                self.write(var);
                if let Some(t) = var_ty {
                    self.write(": ");
                    self.ty(t);
                }
                self.write(" = ");
                self.expr(from, 0);
                self.write(", ");
                self.expr(to, 0);
                if let Some(st) = step {
                    self.write(", ");
                    self.expr(st, 0);
                }
                self.write(" do");
                self.newline();
                self.block(body, s.span.end);
                self.write("end");
            }
            Stmt::ForIn { vars, iter, body } => {
                self.write("for ");
                for (i, (n, t)) in vars.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.write(n);
                    if let Some(t) = t {
                        self.write(": ");
                        self.ty(t);
                    }
                }
                self.write(" in ");
                self.expr(iter, 0);
                self.write(" do");
                self.newline();
                self.block(body, s.span.end);
                self.write("end");
            }
            Stmt::Return(vs) => {
                self.write("return");
                if !vs.is_empty() {
                    self.write(" ");
                    self.expr_list(vs);
                }
            }
            Stmt::Throw(e) => {
                self.write("throw ");
                self.expr(e, 0);
            }
            Stmt::Try {
                body,
                catch_var,
                catch_ty,
                catch_body,
            } => {
                self.write("try");
                self.newline();
                let catch_start = catch_body
                    .first()
                    .map(|st| st.span.start)
                    .unwrap_or(s.span.end);
                self.block(body, catch_start);
                self.writef(format_args!("catch {catch_var}: "));
                self.ty(catch_ty);
                self.newline();
                self.block(catch_body, s.span.end);
                self.write("end");
            }
            Stmt::Break => self.write("break"),
            Stmt::Continue => self.write("continue"),
            Stmt::Decl(d) => self.decl(&d.value, d.span.end),
        }
    }

    // ---- declarations ------------------------------------------------------

    fn decl(&mut self, d: &Decl, decl_end: usize) {
        match d {
            Decl::Function {
                exported,
                is_local,
                name,
                type_params,
                params,
                return_ty,
                body,
            } => {
                if *exported {
                    self.write("export ");
                } else if *is_local {
                    self.write("local ");
                }
                self.write("fn ");
                self.write(name);
                self.type_params(type_params);
                self.write("(");
                self.params(params);
                self.write(")");
                if let Some(rt) = return_ty {
                    self.write(" -> ");
                    self.ty(rt);
                }
                self.newline();
                self.block(body, decl_end);
                self.write("end");
            }
            Decl::Class {
                exported,
                name,
                extends,
                implements,
                members,
            } => {
                if *exported {
                    self.write("export ");
                }
                self.write("class ");
                self.write(name);
                if let Some(p) = extends {
                    self.write(" extends ");
                    self.write(p);
                }
                if !implements.is_empty() {
                    self.write(" implements ");
                    for (i, n) in implements.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.write(n);
                    }
                }
                self.newline();
                self.class_body(members, decl_end);
                self.write("end");
            }
            Decl::Interface {
                exported,
                name,
                extends,
                methods,
            } => {
                if *exported {
                    self.write("export ");
                }
                self.write("interface ");
                self.write(name);
                if !extends.is_empty() {
                    self.write(" extends ");
                    for (i, n) in extends.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.write(n);
                    }
                }
                self.newline();
                self.indent += 1;
                for m in methods {
                    self.drain_before(m.span.start);
                    self.method_sig(m);
                    self.try_trailing(m.span.end);
                    self.newline();
                }
                self.drain_before(decl_end);
                self.indent -= 1;
                self.write("end");
            }
            Decl::Enum {
                exported,
                name,
                variants,
                methods,
            } => {
                if *exported {
                    self.write("export ");
                }
                self.write("enum ");
                self.write(name);
                self.newline();
                self.indent += 1;
                for (i, v) in variants.iter().enumerate() {
                    self.drain_before(v.span.start);
                    self.enum_variant(&v.value);
                    if i + 1 < variants.len() {
                        self.write(",");
                    }
                    self.try_trailing(v.span.end);
                    self.newline();
                }
                if !methods.is_empty() {
                    let first_method_start = methods[0].span.start;
                    self.drain_before(first_method_start);
                    self.blank_line();
                    for (i, m) in methods.iter().enumerate() {
                        if i > 0 {
                            self.drain_before(m.span.start);
                            self.blank_line();
                        }
                        self.method(m);
                        self.try_trailing(m.span.end);
                        self.newline();
                    }
                }
                self.drain_before(decl_end);
                self.indent -= 1;
                self.write("end");
            }
            Decl::Import { names, path } => {
                self.write("import ");
                match names {
                    ImportNames::All => self.write("*"),
                    ImportNames::List(ns) => {
                        for (i, (orig, alias)) in ns.iter().enumerate() {
                            if i > 0 {
                                self.write(", ");
                            }
                            self.write(orig);
                            if let Some(a) = alias {
                                self.writef(format_args!(" as {a}"));
                            }
                        }
                    }
                }
                self.writef(format_args!(" from {}", quote_str(path)));
            }
        }
    }

    fn class_body(&mut self, members: &[Spanned<ClassMember>], class_end: usize) {
        self.indent += 1;
        let mut prev_was_method = false;
        for (i, m) in members.iter().enumerate() {
            self.drain_before(m.span.start);
            let is_method = matches!(m.value, ClassMember::Method(_));
            if i > 0 {
                let prev_end = members[i - 1].span.end;
                // Preserve user-written blank lines between class
                // members. The structural rule (blank between methods
                // and around method boundaries) still applies on top.
                if self.newlines_in_source(prev_end, m.span.start) >= 2 {
                    self.blank_line();
                } else if is_method || prev_was_method {
                    self.blank_line();
                }
            }
            self.class_member(&m.value);
            self.try_trailing(m.span.end);
            self.newline();
            prev_was_method = is_method;
        }
        self.drain_before(class_end);
        self.indent -= 1;
    }

    fn class_member(&mut self, m: &ClassMember) {
        match m {
            ClassMember::Field {
                is_static,
                is_private,
                name,
                ty,
                default,
            } => {
                if *is_static {
                    self.write("static ");
                }
                if *is_private {
                    self.write("local ");
                }
                self.write(name);
                self.write(": ");
                self.ty(ty);
                if let Some(d) = default {
                    self.write(" = ");
                    self.expr(d, 0);
                }
            }
            ClassMember::Method(m) => self.method(m),
        }
    }

    fn method(&mut self, m: &Method) {
        if m.is_static {
            self.write("static ");
        }
        if m.is_private {
            self.write("local ");
        }
        self.write("fn ");
        self.write(&m.name);
        self.type_params(&m.type_params);
        self.write("(");
        self.params(&m.params);
        self.write(")");
        if let Some(rt) = &m.return_ty {
            self.write(" -> ");
            self.ty(rt);
        }
        self.newline();
        self.block(&m.body, m.span.end);
        self.write("end");
    }

    fn method_sig(&mut self, m: &MethodSig) {
        self.write("fn ");
        self.write(&m.name);
        self.write("(");
        self.params(&m.params);
        self.write(")");
        if let Some(rt) = &m.return_ty {
            self.write(" -> ");
            self.ty(rt);
        }
    }

    fn enum_variant(&mut self, v: &EnumVariant) {
        match v {
            EnumVariant::Bare(n) => self.write(n),
            EnumVariant::Valued(n, e) => {
                self.write(n);
                self.write(" = ");
                self.expr(e, 0);
            }
            EnumVariant::Tuple { name, fields } => {
                self.write(name);
                self.write("(");
                self.params(fields);
                self.write(")");
            }
        }
    }

    fn type_params(&mut self, tps: &[String]) {
        if tps.is_empty() {
            return;
        }
        self.write("<");
        for (i, t) in tps.iter().enumerate() {
            if i > 0 {
                self.write(", ");
            }
            self.write(t);
        }
        self.write(">");
    }

    fn params(&mut self, ps: &[Param]) {
        for (i, p) in ps.iter().enumerate() {
            if i > 0 {
                self.write(", ");
            }
            if p.variadic {
                self.write("...");
            }
            self.write(&p.name);
            self.write(": ");
            self.ty(&p.ty);
            if let Some(d) = &p.default {
                self.write(" = ");
                self.expr(d, 0);
            }
        }
    }

    // ---- expressions -------------------------------------------------------

    fn expr_list(&mut self, es: &[Spanned<Expr>]) {
        for (i, e) in es.iter().enumerate() {
            if i > 0 {
                self.write(", ");
            }
            self.expr(e, 0);
        }
    }

    /// Print an expression. `parent_prec` is the binding strength of the
    /// surrounding context; if our own precedence is lower we wrap in
    /// parens to preserve grouping.
    fn expr(&mut self, e: &Spanned<Expr>, parent_prec: u8) {
        let outer_end = e.span.end;
        match &e.value {
            Expr::Int(n) => self.writef(format_args!("{n}")),
            Expr::Float(f) => self.write(&format_float(*f)),
            Expr::Bool(b) => self.write(if *b { "true" } else { "false" }),
            Expr::Str(s) => self.write(&quote_str(s)),
            Expr::Nil => self.write("nil"),
            Expr::Ident(n) => self.write(n),
            Expr::Self_ => self.write("self"),

            Expr::Unary { op, rhs } => {
                let (sym, space) = match op {
                    UnaryOp::Neg => ("-", false),
                    UnaryOp::Not => ("not", true),
                    UnaryOp::Len => ("#", false),
                };
                self.write(sym);
                if space {
                    self.write(" ");
                }
                // Unary binds tighter than any binary, so wrap operands of
                // strictly lower precedence than `MAX_PREC`.
                self.expr(rhs, MAX_PREC);
            }
            Expr::Binary { op, lhs, rhs } => {
                let (p, right_assoc) = bin_prec(*op);
                if p < parent_prec {
                    self.write("(");
                }
                let left_min = if right_assoc { p + 1 } else { p };
                let right_min = if right_assoc { p } else { p + 1 };
                self.expr(lhs, left_min);
                self.writef(format_args!(" {} ", bin_sym(*op)));
                self.expr(rhs, right_min);
                if p < parent_prec {
                    self.write(")");
                }
            }

            Expr::Member { obj, name } => {
                self.expr(obj, MAX_PREC);
                self.write(".");
                self.write(name);
            }
            Expr::SafeMember { obj, name } => {
                self.expr(obj, MAX_PREC);
                self.write("?.");
                self.write(name);
            }
            Expr::Index { obj, index } => {
                self.expr(obj, MAX_PREC);
                self.write("[");
                self.expr(index, 0);
                self.write("]");
            }
            Expr::Call { callee, args } => {
                self.expr(callee, MAX_PREC);
                self.write("(");
                self.call_args(args);
                self.write(")");
            }
            Expr::MethodCall { obj, method, args } => {
                self.expr(obj, MAX_PREC);
                self.write(":");
                self.write(method);
                self.write("(");
                self.call_args(args);
                self.write(")");
            }
            Expr::ForceUnwrap(inner) => {
                self.expr(inner, MAX_PREC);
                self.write("!");
            }

            Expr::Table(entries) => {
                if entries.is_empty() {
                    self.write("{}");
                } else {
                    self.write("{");
                    for (i, ent) in entries.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        match ent {
                            TableEntry::Positional(e) => self.expr(e, 0),
                            TableEntry::Field { key, value } => {
                                if let Expr::Str(s) = &key.value {
                                    if is_ident(s) {
                                        self.write(s);
                                    } else {
                                        self.write(&quote_str(s));
                                    }
                                } else {
                                    self.expr(key, 0);
                                }
                                self.write(": ");
                                self.expr(value, 0);
                            }
                        }
                    }
                    self.write("}");
                }
            }

            Expr::Lambda {
                params,
                return_ty,
                body,
            } => match body {
                // Arrow lambdas: `x => expr` (single any-typed param, no
                // return type) or `(params) => expr`. The parser has no
                // `fn(...) => expr` form, so block bodies must use `fn`.
                LambdaBody::Expr(e) => {
                    if is_bare_arrow_param(params, return_ty) {
                        self.write(&params[0].name);
                    } else {
                        self.write("(");
                        self.params(params);
                        self.write(")");
                        if let Some(rt) = return_ty {
                            self.write(" -> ");
                            self.ty(rt);
                        }
                    }
                    self.write(" => ");
                    self.expr(e, 0);
                }
                LambdaBody::Block(stmts) => {
                    self.write("fn(");
                    self.params(params);
                    self.write(")");
                    if let Some(rt) = return_ty {
                        self.write(" -> ");
                        self.ty(rt);
                    }
                    self.newline();
                    self.block(stmts, outer_end);
                    self.write("end");
                }
            },

            Expr::Match { scrutinee, arms } => {
                self.write("match ");
                self.expr(scrutinee, 0);
                self.newline();
                self.indent += 1;
                for (i, a) in arms.iter().enumerate() {
                    // Blank line between arms — keeps multi-statement
                    // arms visually distinct. The first arm stays right
                    // under `match` with no extra leading blank.
                    if i > 0 {
                        self.newline();
                    }
                    self.drain_before(a.span.start);
                    self.match_arm(a);
                    self.try_trailing(a.span.end);
                    self.newline();
                }
                self.drain_before(outer_end);
                self.indent -= 1;
                self.write("end");
            }

            // `when(source):stage1(args):stage2(args)…` — colon pipeline.
            //
            // Layout:
            //   * Inline by default when the whole chain fits within
            //     [`MAX_LINE_WIDTH`] from the current column. Reads as
            //     `when(x):a():b()`.
            //   * Multi-line when (a) the inline form is too wide, or
            //     (b) the source already broke before *any* `:` — the
            //     user's intent wins, so explicit multi-line stays
            //     multi-line even on tiny chains.
            //   * Multi-line indent: every `:` is aligned to the column
            //     where the `w` of `when` lives, so the method names
            //     line up just past the keyword:
            //
            //         local r: integer = when({1, 2, 3})
            //                            :a()
            //                            :b()
            Expr::Pipe { source, stages } => {
                let when_col = self.current_column();
                let force_ml = self.pipe_has_source_break(source, stages);
                let inline = self.render_pipe_inline(source, stages);
                let too_wide = when_col + inline.len() > MAX_LINE_WIDTH;
                if !force_ml && !too_wide {
                    self.write(&inline);
                } else {
                    self.write("when(");
                    self.expr(source, 0);
                    self.write(")");
                    for stage in stages {
                        self.newline();
                        // Skip the indent prefix the next `write` would
                        // emit and lay down `when_col` spaces directly so
                        // `:` lands exactly under the original `w`.
                        self.needs_indent = false;
                        for _ in 0..when_col {
                            self.out.push(' ');
                        }
                        self.write(":");
                        self.write(&stage.name);
                        self.write("(");
                        self.call_args(&stage.args);
                        self.write(")");
                    }
                }
            }
        }
    }

    fn call_args(&mut self, args: &[CallArg]) {
        for (i, a) in args.iter().enumerate() {
            if i > 0 {
                self.write(", ");
            }
            match a {
                CallArg::Positional(e) => self.expr(e, 0),
                CallArg::Named { name, value } => {
                    self.writef(format_args!("{name}: "));
                    self.expr(value, 0);
                }
            }
        }
    }

    fn match_arm(&mut self, a: &MatchArm) {
        self.write("case ");
        self.pattern(&a.pattern.value);
        if let Some(g) = &a.guard {
            self.write(" when ");
            self.expr(g, 0);
        }
        self.write(" then");
        match &a.body {
            MatchBody::Expr(e) => {
                self.write(" ");
                self.expr(e, 0);
            }
            // Multi-statement arms have no per-arm `end` in Saule — the
            // arm runs until the next `case` or the enclosing `match`'s
            // closing `end`. Indent the body one level past the arm and
            // emit statements without a trailing newline; the caller in
            // `match_expr` handles the separator to the next `case`/`end`.
            MatchBody::Block(stmts) => {
                self.newline();
                self.indent += 1;
                for (i, s) in stmts.iter().enumerate() {
                    self.drain_before(s.span.start);
                    if i > 0 {
                        let prev_end = stmts[i - 1].span.end;
                        if self.newlines_in_source(prev_end, s.span.start) >= 2 {
                            self.blank_line();
                        }
                    }
                    self.stmt(s);
                    self.try_trailing(s.span.end);
                    if i + 1 < stmts.len() {
                        self.newline();
                    }
                }
                self.indent -= 1;
            }
        }
    }

    fn pattern(&mut self, p: &Pattern) {
        match p {
            Pattern::Wildcard => self.write("_"),
            Pattern::Bind(n) => self.write(n),
            Pattern::Nil => self.write("nil"),
            Pattern::Int(n) => self.writef(format_args!("{n}")),
            Pattern::Float(f) => self.write(&format_float(*f)),
            Pattern::Bool(b) => self.write(if *b { "true" } else { "false" }),
            Pattern::Str(s) => self.write(&quote_str(s)),
            Pattern::Variant {
                enum_name,
                variant,
                fields,
            } => {
                self.writef(format_args!("{enum_name}.{variant}"));
                if !fields.is_empty() {
                    self.write("(");
                    for (i, f) in fields.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.pattern(&f.value);
                    }
                    self.write(")");
                }
            }
            Pattern::Tuple(ps) => {
                self.write("(");
                for (i, sp) in ps.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.pattern(&sp.value);
                }
                self.write(")");
            }
        }
    }

    // ---- types -------------------------------------------------------------

    fn ty(&mut self, t: &Type) {
        match t {
            Type::Named(n) => self.write(n),
            Type::Nullable(inner) => {
                self.ty(inner);
                self.write("?");
            }
            Type::Table { key, value } => match key {
                Some(k) => {
                    self.write("table<");
                    self.ty(k);
                    self.write(", ");
                    self.ty(value);
                    self.write(">");
                }
                None => {
                    self.write("table<");
                    self.ty(value);
                    self.write(">");
                }
            },
            Type::Tuple(ts) => {
                self.write("(");
                for (i, t) in ts.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.ty(t);
                }
                self.write(")");
            }
            Type::Function { params, ret } => {
                self.write("fn(");
                for (i, t) in params.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.ty(t);
                }
                self.write(") -> ");
                self.ty(ret);
            }
        }
    }
}

// ---- precedence / formatting helpers ---------------------------------------

/// Higher than every `bin_prec`, used as the lower bound for operands of
/// unary / postfix expressions so they always parenthesize inner binaries.
const MAX_PREC: u8 = 100;

/// (precedence, right_associative) for each binary operator, mirroring the
/// parser's Pratt table closely enough that re-parsing produces the same
/// tree.
fn bin_prec(op: BinOp) -> (u8, bool) {
    match op {
        BinOp::Or | BinOp::Coalesce => (1, false),
        BinOp::And => (2, false),
        BinOp::Eq | BinOp::NotEq | BinOp::Lt | BinOp::LtEq | BinOp::Gt | BinOp::GtEq => (3, false),
        BinOp::Concat => (4, true),
        BinOp::Add | BinOp::Sub => (5, false),
        BinOp::Mul | BinOp::Div | BinOp::Mod => (6, false),
    }
}

fn bin_sym(op: BinOp) -> &'static str {
    match op {
        BinOp::Add => "+",
        BinOp::Sub => "-",
        BinOp::Mul => "*",
        BinOp::Div => "/",
        BinOp::Mod => "%",
        BinOp::Eq => "==",
        BinOp::NotEq => "!=",
        BinOp::Lt => "<",
        BinOp::LtEq => "<=",
        BinOp::Gt => ">",
        BinOp::GtEq => ">=",
        BinOp::And => "and",
        BinOp::Or => "or",
        BinOp::Concat => "..",
        BinOp::Coalesce => "??",
    }
}

/// Render an `f64` so it always reads back as a float (i.e. `1.0` rather
/// than `1`) and round-trips through `parse::<f64>()` losslessly for
/// finite values.
fn format_float(f: f64) -> String {
    if !f.is_finite() {
        // Saule has no syntax for these; keep something readable.
        return format!("{f}");
    }
    let s = format!("{f}");
    if s.contains('.') || s.contains('e') || s.contains('E') {
        s
    } else {
        format!("{s}.0")
    }
}

fn quote_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\x{:02x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Whether a single-param lambda came from the `name => expr` shortcut
/// (no type annotation, no return type, default-`any`). Matches the
/// parser's reconstruction so re-parsing produces the same AST.
fn is_bare_arrow_param(params: &[Param], return_ty: &Option<Type>) -> bool {
    if return_ty.is_some() || params.len() != 1 {
        return false;
    }
    let p = &params[0];
    !p.variadic
        && p.default.is_none()
        && matches!(&p.ty, Type::Named(n) if n == "any")
}

fn is_ident(s: &str) -> bool {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if c.is_ascii_alphabetic() || c == '_' => {}
        _ => return false,
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}

/// Whether two adjacent top-level statements should be separated by a
/// blank line. Declarations get breathing room; tight runs of locals or
/// expression statements stay compact.
fn needs_top_separator(prev: &Stmt, next: &Stmt) -> bool {
    let p_is_decl = matches!(prev, Stmt::Decl(_));
    let n_is_decl = matches!(next, Stmt::Decl(_));
    p_is_decl || n_is_decl
}

/// The byte offset where the next chunk of an `if … elseif … else … end`
/// starts. Used as the body-block ceiling when draining comments so they
/// don't escape past the `elseif` / `else` keyword.
fn next_if_chunk_start(
    remaining_elseifs: &[(Spanned<Expr>, Vec<Spanned<Stmt>>)],
    else_block: &Option<Vec<Spanned<Stmt>>>,
    fallback: usize,
) -> usize {
    if let Some((cond, _)) = remaining_elseifs.first() {
        return cond.span.start;
    }
    if let Some(eb) = else_block {
        if let Some(first) = eb.first() {
            return first.span.start;
        }
    }
    fallback
}

//! Saule source pretty-printer.
//!
//! Walks a parsed [`saule_ast::Module`] and renders it back to canonical
//! Saule source: 2-space indent, one statement per line, blank line between
//! top-level declarations.
//!
//! ## Comment preservation
//!
//! [`format_module`] discards comments — the AST never sees them. To round
//! trip comments, use [`format_module_with_comments`] together with the
//! lexer's `tokenize_with_trivia` entry point: extract every
//! [`saule_lexer::Token::LineComment`] / `BlockComment` into a [`Comment`]
//! and pass it in.
//!
//! Interleaving is best-effort but covers the common shapes:
//!
//! * Comments before a statement / declaration are emitted on their own
//!   line at the surrounding indent.
//! * A comment that sits on the same source line as the statement it
//!   trails is re-emitted as a same-line trailing comment.
//! * Comments at the tail of a block (just before the closing `end`) are
//!   drained at the right indent so they don't leak past the block.
//! * Blank lines between source comments are preserved when ≥ 2 newlines
//!   separated them in the original source.

use std::{collections::VecDeque, fmt::Write, ops::Range};

use saule_ast::{
    BinOp, CallArg, ClassMember, Decl, EnumVariant, Expr, ImportNames, LambdaBody, MatchArm,
    MatchBody, Method, MethodSig, Module, Param, Pattern, PipeStage, Spanned, Stmt, TableEntry,
    Type, UnaryOp,
};

/// A single source comment extracted from the lexer's trivia stream.
/// `text` is the verbatim payload between the comment delimiters (no
/// `--` / `--[[` / `]]`), matching what `tokenize_with_trivia` emits.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Comment {
    pub span: Range<usize>,
    pub kind: CommentKind,
    pub text: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CommentKind {
    /// `-- text` to end of line.
    Line,
    /// `--[[ text ]]` (may span multiple source lines).
    Block,
}

/// Render a parsed module back to source, dropping any comments. Use
/// [`format_module_with_comments`] to preserve them. The result always
/// ends with exactly one trailing newline (or is empty for an empty
/// module).
pub fn format_module(module: &Module) -> String {
    let mut p = Printer::new("", &[]);
    p.module(module);
    p.finish()
}

/// Like [`format_module`] but threads `comments` (sorted or not, by span
/// start) back into the output. `source` is the original text, used to
/// tell same-line trailing comments from leading ones and to preserve
/// blank-line gaps.
pub fn format_module_with_comments(module: &Module, source: &str, comments: &[Comment]) -> String {
    let mut p = Printer::new(source, comments);
    p.module(module);
    p.finish()
}

struct Printer<'a> {
    out: String,
    indent: usize,
    /// Set right after a newline so the next `write_str` knows to prepend
    /// the current indentation. Avoids trailing whitespace on blank lines.
    needs_indent: bool,
    /// Original source text. Only consulted for newline-counting between
    /// byte positions when interleaving comments; empty when comments are
    /// disabled.
    source: &'a str,
    /// Pending comments, ordered by `span.start`. Drained as the printer
    /// reaches the corresponding source positions.
    comments: VecDeque<&'a Comment>,
    /// Highest source offset we've "consumed" so far — either the end of
    /// the last comment we drained, or 0. Used for blank-line preservation
    /// between consecutive comments.
    last_pos: usize,
}

const INDENT: &str = "  ";

/// Soft target for one rendered line. The `Expr::Pipe` layout uses this to
/// decide whether a `when(...):a():b()` chain fits inline or should be
/// broken across multiple lines. Anything past this threshold flips to
/// the column-aligned multi-line shape.
const MAX_LINE_WIDTH: usize = 100;

impl<'a> Printer<'a> {
    fn new(source: &'a str, comments: &'a [Comment]) -> Self {
        let mut queue: VecDeque<&'a Comment> = comments.iter().collect();
        // Tolerate unsorted inputs.
        queue
            .make_contiguous()
            .sort_by_key(|c| c.span.start);
        Self {
            out: String::new(),
            indent: 0,
            needs_indent: false,
            source,
            comments: queue,
            last_pos: 0,
        }
    }

    fn finish(mut self) -> String {
        // Guarantee exactly one trailing newline.
        while self.out.ends_with("\n\n") {
            self.out.pop();
        }
        if !self.out.is_empty() && !self.out.ends_with('\n') {
            self.out.push('\n');
        }
        self.out
    }

    fn write(&mut self, s: &str) {
        if self.needs_indent {
            for _ in 0..self.indent {
                self.out.push_str(INDENT);
            }
            self.needs_indent = false;
        }
        self.out.push_str(s);
    }

    fn writef(&mut self, args: std::fmt::Arguments<'_>) {
        if self.needs_indent {
            for _ in 0..self.indent {
                self.out.push_str(INDENT);
            }
            self.needs_indent = false;
        }
        let _ = self.out.write_fmt(args);
    }

    fn newline(&mut self) {
        self.out.push('\n');
        self.needs_indent = true;
    }

    fn blank_line(&mut self) {
        // Don't emit duplicate blank lines or a blank line at the start.
        if self.out.is_empty() {
            return;
        }
        if !self.out.ends_with('\n') {
            self.out.push('\n');
        }
        if !self.out.ends_with("\n\n") {
            self.out.push('\n');
        }
        self.needs_indent = true;
    }

    // ---- comment interleaving ---------------------------------------------

    /// Emit every queued comment whose start lies strictly before `pos`,
    /// one per line at the current indent. Preserves blank-line gaps
    /// between consecutive source comments (≥ 2 newlines in the original
    /// source → blank line in the output).
    fn drain_before(&mut self, pos: usize) {
        while let Some(c) = self.comments.front() {
            if c.span.start >= pos {
                break;
            }
            let c = self.comments.pop_front().unwrap();
            // If the printer's current line already has content, this
            // comment can't be a "leading" one — push it to its own line
            // first. (Happens when called mid-construct; rare but cheap.)
            if !self.out.is_empty() && !self.out.ends_with('\n') {
                self.newline();
            }
            // Blank-line preservation between comments / from start of file.
            if self.newlines_in_source(self.last_pos, c.span.start) >= 2 {
                self.blank_line();
            }
            self.write_comment(c);
            self.newline();
            self.last_pos = c.span.end;
        }
    }

    /// If the next pending comment starts on the same source line as
    /// `after_pos`, emit it as a same-line trailing comment (preceded by
    /// two spaces) and consume it. Returns `true` if a comment was
    /// emitted, so callers can skip their own trailing newline logic if
    /// they want.
    fn try_trailing(&mut self, after_pos: usize) -> bool {
        let Some(c) = self.comments.front() else {
            return false;
        };
        if c.span.start < after_pos {
            // Pathological: drain_before should have handled it. Be safe.
            return false;
        }
        if self.newlines_in_source(after_pos, c.span.start) > 0 {
            return false;
        }
        let c = self.comments.pop_front().unwrap();
        self.out.push_str("  ");
        self.write_comment(c);
        self.last_pos = c.span.end;
        true
    }

    fn write_comment(&mut self, c: &Comment) {
        // `write_str` would apply indentation; we want indent only on the
        // first line. Manage it manually.
        if self.needs_indent {
            for _ in 0..self.indent {
                self.out.push_str(INDENT);
            }
            self.needs_indent = false;
        }
        match c.kind {
            CommentKind::Line => {
                self.out.push_str("--");
                self.out.push_str(&c.text);
            }
            CommentKind::Block => {
                self.out.push_str("--[[");
                self.out.push_str(&c.text);
                self.out.push_str("]]");
            }
        }
    }

    /// Count `\n` bytes in `source[from..to]`. Returns 0 if either bound
    /// is out of range or if `from > to`. Used to distinguish same-line
    /// trailing comments from leading ones, and to preserve blank lines.
    fn newlines_in_source(&self, from: usize, to: usize) -> usize {
        if from > to || to > self.source.len() {
            return 0;
        }
        self.source.as_bytes()[from..to]
            .iter()
            .filter(|&&b| b == b'\n')
            .count()
    }

    // ---- top-level ---------------------------------------------------------

    fn module(&mut self, m: &Module) {
        for (i, s) in m.stmts.iter().enumerate() {
            self.drain_before(s.span.start);
            if i > 0 {
                let prev_end = m.stmts[i - 1].span.end;
                // Preserve user-written blank lines between top-level
                // statements (≥ 2 newlines in the source gap).
                if self.newlines_in_source(prev_end, s.span.start) >= 2 {
                    self.blank_line();
                } else if needs_top_separator(&m.stmts[i - 1].value, &s.value) {
                    self.blank_line();
                }
            }
            self.stmt(s);
            self.try_trailing(s.span.end);
            self.newline();
        }
        // Trailing comments at end-of-file (after the last statement).
        self.drain_before(usize::MAX);
    }

    // ---- statements --------------------------------------------------------

    /// Print a block body and drain any comments that lie inside it
    /// before returning. `block_end` is the byte offset where the
    /// enclosing construct closes (typically the parent statement's
    /// `span.end`, which sits just past the `end` keyword).
    fn block(&mut self, body: &[Spanned<Stmt>], block_end: usize) {
        self.indent += 1;
        for (i, s) in body.iter().enumerate() {
            self.drain_before(s.span.start);
            // Preserve user-written blank lines inside blocks.
            if i > 0 {
                let prev_end = body[i - 1].span.end;
                if self.newlines_in_source(prev_end, s.span.start) >= 2 {
                    self.blank_line();
                }
            }
            self.stmt(s);
            self.try_trailing(s.span.end);
            self.newline();
        }
        // Comments hanging between the last stmt and the closing keyword.
        self.drain_before(block_end);
        self.indent -= 1;
    }

    fn stmt(&mut self, s: &Spanned<Stmt>) {
        match &s.value {
            Stmt::Local { name, ty, value } => {
                self.write("local ");
                self.write(name);
                if let Some(t) = ty {
                    self.write(": ");
                    self.ty(t);
                }
                if let Some(v) = value {
                    self.write(" = ");
                    self.expr(v, 0);
                }
            }
            Stmt::LocalMulti { names, values } => {
                self.write("local ");
                for (i, (n, t)) in names.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.write(n);
                    if let Some(t) = t {
                        self.write(": ");
                        self.ty(t);
                    }
                }
                if !values.is_empty() {
                    self.write(" = ");
                    self.expr_list(values);
                }
            }
            Stmt::Assign { target, value } => {
                self.expr(target, 0);
                self.write(" = ");
                self.expr(value, 0);
            }
            Stmt::AssignMulti { targets, values } => {
                self.expr_list(targets);
                self.write(" = ");
                self.expr_list(values);
            }
            Stmt::Expr(e) => self.expr(e, 0),

            Stmt::If {
                cond,
                then_block,
                elseifs,
                else_block,
            } => {
                self.write("if ");
                self.expr(cond, 0);
                self.write(" then");
                self.newline();
                // Ceiling for each chunk: start of the next chunk's
                // keyword (approximated by next cond / next stmt).
                let then_ceiling = next_if_chunk_start(elseifs, else_block, s.span.end);
                self.block(then_block, then_ceiling);
                for (i, (c, body)) in elseifs.iter().enumerate() {
                    self.drain_before(c.span.start);
                    self.write("elseif ");
                    self.expr(c, 0);
                    self.write(" then");
                    self.newline();
                    let ceiling = next_if_chunk_start(&elseifs[i + 1..], else_block, s.span.end);
                    self.block(body, ceiling);
                }
                if let Some(eb) = else_block {
                    let else_start = eb.first().map(|st| st.span.start).unwrap_or(s.span.end);
                    self.drain_before(else_start);
                    self.write("else");
                    self.newline();
                    self.block(eb, s.span.end);
                }
                self.write("end");
            }
            Stmt::While { cond, body } => {
                self.write("while ");
                self.expr(cond, 0);
                self.write(" do");
                self.newline();
                self.block(body, s.span.end);
                self.write("end");
            }
            Stmt::Repeat { body, cond } => {
                self.write("repeat");
                self.newline();
                // `until` sits after the body; use cond.span.start as the
                // body's ceiling so trailing comments don't escape past
                // the `until`.
                self.block(body, cond.span.start);
                self.write("until ");
                self.expr(cond, 0);
            }
            Stmt::ForNumeric {
                var,
                var_ty,
                from,
                to,
                step,
                body,
            } => {
                // Lua-style numeric `for`: `for i = from, to[, step] do ... end`.
                self.write("for ");
                self.write(var);
                if let Some(t) = var_ty {
                    self.write(": ");
                    self.ty(t);
                }
                self.write(" = ");
                self.expr(from, 0);
                self.write(", ");
                self.expr(to, 0);
                if let Some(st) = step {
                    self.write(", ");
                    self.expr(st, 0);
                }
                self.write(" do");
                self.newline();
                self.block(body, s.span.end);
                self.write("end");
            }
            Stmt::ForIn { vars, iter, body } => {
                self.write("for ");
                for (i, (n, t)) in vars.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.write(n);
                    if let Some(t) = t {
                        self.write(": ");
                        self.ty(t);
                    }
                }
                self.write(" in ");
                self.expr(iter, 0);
                self.write(" do");
                self.newline();
                self.block(body, s.span.end);
                self.write("end");
            }
            Stmt::Return(vs) => {
                self.write("return");
                if !vs.is_empty() {
                    self.write(" ");
                    self.expr_list(vs);
                }
            }
            Stmt::Throw(e) => {
                self.write("throw ");
                self.expr(e, 0);
            }
            Stmt::Try {
                body,
                catch_var,
                catch_ty,
                catch_body,
            } => {
                self.write("try");
                self.newline();
                let catch_start = catch_body
                    .first()
                    .map(|st| st.span.start)
                    .unwrap_or(s.span.end);
                self.block(body, catch_start);
                self.writef(format_args!("catch {catch_var}: "));
                self.ty(catch_ty);
                self.newline();
                self.block(catch_body, s.span.end);
                self.write("end");
            }
            Stmt::Break => self.write("break"),
            Stmt::Continue => self.write("continue"),
            Stmt::Decl(d) => self.decl(&d.value, d.span.end),
        }
    }

    // ---- declarations ------------------------------------------------------

    fn decl(&mut self, d: &Decl, decl_end: usize) {
        match d {
            Decl::Function {
                exported,
                is_local,
                name,
                type_params,
                params,
                return_ty,
                body,
            } => {
                if *exported {
                    self.write("export ");
                } else if *is_local {
                    self.write("local ");
                }
                self.write("fn ");
                self.write(name);
                self.type_params(type_params);
                self.write("(");
                self.params(params);
                self.write(")");
                if let Some(rt) = return_ty {
                    self.write(" -> ");
                    self.ty(rt);
                }
                self.newline();
                self.block(body, decl_end);
                self.write("end");
            }
            Decl::Class {
                exported,
                name,
                extends,
                implements,
                members,
            } => {
                if *exported {
                    self.write("export ");
                }
                self.write("class ");
                self.write(name);
                if let Some(p) = extends {
                    self.write(" extends ");
                    self.write(p);
                }
                if !implements.is_empty() {
                    self.write(" implements ");
                    for (i, n) in implements.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.write(n);
                    }
                }
                self.newline();
                self.class_body(members, decl_end);
                self.write("end");
            }
            Decl::Interface {
                exported,
                name,
                extends,
                methods,
            } => {
                if *exported {
                    self.write("export ");
                }
                self.write("interface ");
                self.write(name);
                if !extends.is_empty() {
                    self.write(" extends ");
                    for (i, n) in extends.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.write(n);
                    }
                }
                self.newline();
                self.indent += 1;
                for m in methods {
                    self.drain_before(m.span.start);
                    self.method_sig(m);
                    self.try_trailing(m.span.end);
                    self.newline();
                }
                self.drain_before(decl_end);
                self.indent -= 1;
                self.write("end");
            }
            Decl::Enum {
                exported,
                name,
                variants,
                methods,
            } => {
                if *exported {
                    self.write("export ");
                }
                self.write("enum ");
                self.write(name);
                self.newline();
                self.indent += 1;
                for (i, v) in variants.iter().enumerate() {
                    self.drain_before(v.span.start);
                    self.enum_variant(&v.value);
                    if i + 1 < variants.len() {
                        self.write(",");
                    }
                    self.try_trailing(v.span.end);
                    self.newline();
                }
                if !methods.is_empty() {
                    let first_method_start = methods[0].span.start;
                    self.drain_before(first_method_start);
                    self.blank_line();
                    for (i, m) in methods.iter().enumerate() {
                        if i > 0 {
                            self.drain_before(m.span.start);
                            self.blank_line();
                        }
                        self.method(m);
                        self.try_trailing(m.span.end);
                        self.newline();
                    }
                }
                self.drain_before(decl_end);
                self.indent -= 1;
                self.write("end");
            }
            Decl::Import { names, path } => {
                self.write("import ");
                match names {
                    ImportNames::All => self.write("*"),
                    ImportNames::List(ns) => {
                        for (i, (orig, alias)) in ns.iter().enumerate() {
                            if i > 0 {
                                self.write(", ");
                            }
                            self.write(orig);
                            if let Some(a) = alias {
                                self.writef(format_args!(" as {a}"));
                            }
                        }
                    }
                }
                self.writef(format_args!(" from {}", quote_str(path)));
            }
        }
    }

    fn class_body(&mut self, members: &[Spanned<ClassMember>], class_end: usize) {
        self.indent += 1;
        let mut prev_was_method = false;
        for (i, m) in members.iter().enumerate() {
            self.drain_before(m.span.start);
            let is_method = matches!(m.value, ClassMember::Method(_));
            if i > 0 {
                let prev_end = members[i - 1].span.end;
                // Preserve user-written blank lines between class
                // members. The structural rule (blank between methods
                // and around method boundaries) still applies on top.
                if self.newlines_in_source(prev_end, m.span.start) >= 2 {
                    self.blank_line();
                } else if is_method || prev_was_method {
                    self.blank_line();
                }
            }
            self.class_member(&m.value);
            self.try_trailing(m.span.end);
            self.newline();
            prev_was_method = is_method;
        }
        self.drain_before(class_end);
        self.indent -= 1;
    }

    fn class_member(&mut self, m: &ClassMember) {
        match m {
            ClassMember::Field {
                is_static,
                is_private,
                name,
                ty,
                default,
            } => {
                if *is_static {
                    self.write("static ");
                }
                if *is_private {
                    self.write("local ");
                }
                self.write(name);
                self.write(": ");
                self.ty(ty);
                if let Some(d) = default {
                    self.write(" = ");
                    self.expr(d, 0);
                }
            }
            ClassMember::Method(m) => self.method(m),
        }
    }

    fn method(&mut self, m: &Method) {
        if m.is_static {
            self.write("static ");
        }
        if m.is_private {
            self.write("local ");
        }
        self.write("fn ");
        self.write(&m.name);
        self.type_params(&m.type_params);
        self.write("(");
        self.params(&m.params);
        self.write(")");
        if let Some(rt) = &m.return_ty {
            self.write(" -> ");
            self.ty(rt);
        }
        self.newline();
        self.block(&m.body, m.span.end);
        self.write("end");
    }

    fn method_sig(&mut self, m: &MethodSig) {
        self.write("fn ");
        self.write(&m.name);
        self.write("(");
        self.params(&m.params);
        self.write(")");
        if let Some(rt) = &m.return_ty {
            self.write(" -> ");
            self.ty(rt);
        }
    }

    fn enum_variant(&mut self, v: &EnumVariant) {
        match v {
            EnumVariant::Bare(n) => self.write(n),
            EnumVariant::Valued(n, e) => {
                self.write(n);
                self.write(" = ");
                self.expr(e, 0);
            }
            EnumVariant::Tuple { name, fields } => {
                self.write(name);
                self.write("(");
                self.params(fields);
                self.write(")");
            }
        }
    }

    fn type_params(&mut self, tps: &[String]) {
        if tps.is_empty() {
            return;
        }
        self.write("<");
        for (i, t) in tps.iter().enumerate() {
            if i > 0 {
                self.write(", ");
            }
            self.write(t);
        }
        self.write(">");
    }

    fn params(&mut self, ps: &[Param]) {
        for (i, p) in ps.iter().enumerate() {
            if i > 0 {
                self.write(", ");
            }
            if p.variadic {
                self.write("...");
            }
            self.write(&p.name);
            self.write(": ");
            self.ty(&p.ty);
            if let Some(d) = &p.default {
                self.write(" = ");
                self.expr(d, 0);
            }
        }
    }

    // ---- expressions -------------------------------------------------------

    fn expr_list(&mut self, es: &[Spanned<Expr>]) {
        for (i, e) in es.iter().enumerate() {
            if i > 0 {
                self.write(", ");
            }
            self.expr(e, 0);
        }
    }

    /// Print an expression. `parent_prec` is the binding strength of the
    /// surrounding context; if our own precedence is lower we wrap in
    /// parens to preserve grouping.
    fn expr(&mut self, e: &Spanned<Expr>, parent_prec: u8) {
        let outer_end = e.span.end;
        match &e.value {
            Expr::Int(n) => self.writef(format_args!("{n}")),
            Expr::Float(f) => self.write(&format_float(*f)),
            Expr::Bool(b) => self.write(if *b { "true" } else { "false" }),
            Expr::Str(s) => self.write(&quote_str(s)),
            Expr::Nil => self.write("nil"),
            Expr::Ident(n) => self.write(n),
            Expr::Self_ => self.write("self"),

            Expr::Unary { op, rhs } => {
                let (sym, space) = match op {
                    UnaryOp::Neg => ("-", false),
                    UnaryOp::Not => ("not", true),
                    UnaryOp::Len => ("#", false),
                };
                self.write(sym);
                if space {
                    self.write(" ");
                }
                // Unary binds tighter than any binary, so wrap operands of
                // strictly lower precedence than `MAX_PREC`.
                self.expr(rhs, MAX_PREC);
            }
            Expr::Binary { op, lhs, rhs } => {
                let (p, right_assoc) = bin_prec(*op);
                if p < parent_prec {
                    self.write("(");
                }
                let left_min = if right_assoc { p + 1 } else { p };
                let right_min = if right_assoc { p } else { p + 1 };
                self.expr(lhs, left_min);
                self.writef(format_args!(" {} ", bin_sym(*op)));
                self.expr(rhs, right_min);
                if p < parent_prec {
                    self.write(")");
                }
            }

            Expr::Member { obj, name } => {
                self.expr(obj, MAX_PREC);
                self.write(".");
                self.write(name);
            }
            Expr::SafeMember { obj, name } => {
                self.expr(obj, MAX_PREC);
                self.write("?.");
                self.write(name);
            }
            Expr::Index { obj, index } => {
                self.expr(obj, MAX_PREC);
                self.write("[");
                self.expr(index, 0);
                self.write("]");
            }
            Expr::Call { callee, args } => {
                self.expr(callee, MAX_PREC);
                self.write("(");
                self.call_args(args);
                self.write(")");
            }
            Expr::MethodCall { obj, method, args } => {
                self.expr(obj, MAX_PREC);
                self.write(":");
                self.write(method);
                self.write("(");
                self.call_args(args);
                self.write(")");
            }
            Expr::ForceUnwrap(inner) => {
                self.expr(inner, MAX_PREC);
                self.write("!");
            }

            Expr::Table(entries) => {
                if entries.is_empty() {
                    self.write("{}");
                } else {
                    self.write("{");
                    for (i, ent) in entries.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        match ent {
                            TableEntry::Positional(e) => self.expr(e, 0),
                            TableEntry::Field { key, value } => {
                                if let Expr::Str(s) = &key.value {
                                    if is_ident(s) {
                                        self.write(s);
                                    } else {
                                        self.write(&quote_str(s));
                                    }
                                } else {
                                    self.expr(key, 0);
                                }
                                self.write(": ");
                                self.expr(value, 0);
                            }
                        }
                    }
                    self.write("}");
                }
            }

            Expr::Lambda {
                params,
                return_ty,
                body,
            } => match body {
                // Arrow lambdas: `x => expr` (single any-typed param, no
                // return type) or `(params) => expr`. The parser has no
                // `fn(...) => expr` form, so block bodies must use `fn`.
                LambdaBody::Expr(e) => {
                    if is_bare_arrow_param(params, return_ty) {
                        self.write(&params[0].name);
                    } else {
                        self.write("(");
                        self.params(params);
                        self.write(")");
                        if let Some(rt) = return_ty {
                            self.write(" -> ");
                            self.ty(rt);
                        }
                    }
                    self.write(" => ");
                    self.expr(e, 0);
                }
                LambdaBody::Block(stmts) => {
                    self.write("fn(");
                    self.params(params);
                    self.write(")");
                    if let Some(rt) = return_ty {
                        self.write(" -> ");
                        self.ty(rt);
                    }
                    self.newline();
                    self.block(stmts, outer_end);
                    self.write("end");
                }
            },

            Expr::Match { scrutinee, arms } => {
                self.write("match ");
                self.expr(scrutinee, 0);
                self.newline();
                self.indent += 1;
                for (i, a) in arms.iter().enumerate() {
                    // Blank line between arms — keeps multi-statement
                    // arms visually distinct. The first arm stays right
                    // under `match` with no extra leading blank.
                    if i > 0 {
                        self.newline();
                    }
                    self.drain_before(a.span.start);
                    self.match_arm(a);
                    self.try_trailing(a.span.end);
                    self.newline();
                }
                self.drain_before(outer_end);
                self.indent -= 1;
                self.write("end");
            }

            // `when(source):stage1(args):stage2(args)…` — colon pipeline.
            //
            // Layout:
            //   * Inline by default when the whole chain fits within
            //     [`MAX_LINE_WIDTH`] from the current column. Reads as
            //     `when(x):a():b()`.
            //   * Multi-line when (a) the inline form is too wide, or
            //     (b) the source already broke before *any* `:` — the
            //     user's intent wins, so explicit multi-line stays
            //     multi-line even on tiny chains.
            //   * Multi-line indent: every `:` is aligned to the column
            //     where the `w` of `when` lives, so the method names
            //     line up just past the keyword:
            //
            //         local r: integer = when({1, 2, 3})
            //                            :a()
            //                            :b()
            Expr::Pipe { source, stages } => {
                let when_col = self.current_column();
                let force_ml = self.pipe_has_source_break(source, stages);
                let inline = self.render_pipe_inline(source, stages);
                let too_wide = when_col + inline.len() > MAX_LINE_WIDTH;
                if !force_ml && !too_wide {
                    self.write(&inline);
                } else {
                    self.write("when(");
                    self.expr(source, 0);
                    self.write(")");
                    for stage in stages {
                        self.newline();
                        // Skip the indent prefix the next `write` would
                        // emit and lay down `when_col` spaces directly so
                        // `:` lands exactly under the original `w`.
                        self.needs_indent = false;
                        for _ in 0..when_col {
                            self.out.push(' ');
                        }
                        self.write(":");
                        self.write(&stage.name);
                        self.write("(");
                        self.call_args(&stage.args);
                        self.write(")");
                    }
                }
            }
        }
    }

    fn call_args(&mut self, args: &[CallArg]) {
        }
    }

    fn match_arm(&mut self, a: &MatchArm) {
        self.write("case ");
        self.pattern(&a.pattern.value);
        if let Some(g) = &a.guard {
            self.write(" when ");
            self.expr(g, 0);
        }
        self.write(" then");
        match &a.body {
            MatchBody::Expr(e) => {
                self.write(" ");
                self.expr(e, 0);
            }
            // Multi-statement arms have no per-arm `end` in Saule — the
            // arm runs until the next `case` or the enclosing `match`'s
            // closing `end`. Indent the body one level past the arm and
            // emit statements without a trailing newline; the caller in
            // `match_expr` handles the separator to the next `case`/`end`.
            MatchBody::Block(stmts) => {
                self.newline();
                self.indent += 1;
                for (i, s) in stmts.iter().enumerate() {
                    self.drain_before(s.span.start);
                    if i > 0 {
                        let prev_end = stmts[i - 1].span.end;
                        if self.newlines_in_source(prev_end, s.span.start) >= 2 {
                            self.blank_line();
                        }
                    }
                    self.stmt(s);
                    self.try_trailing(s.span.end);
                    if i + 1 < stmts.len() {
                        self.newline();
                    }
                }
                self.indent -= 1;
            }
        }
    }

    fn pattern(&mut self, p: &Pattern) {
        match p {
            Pattern::Wildcard => self.write("_"),
            Pattern::Bind(n) => self.write(n),
            Pattern::Nil => self.write("nil"),
            Pattern::Int(n) => self.writef(format_args!("{n}")),
            Pattern::Float(f) => self.write(&format_float(*f)),
            Pattern::Bool(b) => self.write(if *b { "true" } else { "false" }),
            Pattern::Str(s) => self.write(&quote_str(s)),
            Pattern::Variant {
                enum_name,
                variant,
                fields,
            } => {
                self.writef(format_args!("{enum_name}.{variant}"));
                if !fields.is_empty() {
                    self.write("(");
                    for (i, f) in fields.iter().enumerate() {
                        if i > 0 {
                            self.write(", ");
                        }
                        self.pattern(&f.value);
                    }
                    self.write(")");
                }
            }
            Pattern::Tuple(ps) => {
                self.write("(");
                for (i, sp) in ps.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.pattern(&sp.value);
                }
                self.write(")");
            }
        }
    }

    // ---- types -------------------------------------------------------------

    fn ty(&mut self, t: &Type) {
        match t {
            Type::Named(n) => self.write(n),
            Type::Nullable(inner) => {
                self.ty(inner);
                self.write("?");
            }
            Type::Table { key, value } => match key {
                Some(k) => {
                    self.write("table<");
                    self.ty(k);
                    self.write(", ");
                    self.ty(value);
                    self.write(">");
                }
                None => {
                    self.write("table<");
                    self.ty(value);
                    self.write(">");
                }
            },
            Type::Tuple(ts) => {
                self.write("(");
                for (i, t) in ts.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.ty(t);
                }
                self.write(")");
            }
            Type::Function { params, ret } => {
                self.write("fn(");
                for (i, t) in params.iter().enumerate() {
                    if i > 0 {
                        self.write(", ");
                    }
                    self.ty(t);
                }
                self.write(") -> ");
                self.ty(ret);
            }
        }
    }
}

// ---- precedence / formatting helpers ---------------------------------------

/// Higher than every `bin_prec`, used as the lower bound for operands of
/// unary / postfix expressions so they always parenthesize inner binaries.
const MAX_PREC: u8 = 100;

/// (precedence, right_associative) for each binary operator, mirroring the
/// parser's Pratt table closely enough that re-parsing produces the same
/// tree.
fn bin_prec(op: BinOp) -> (u8, bool) {
    match op {
        BinOp::Or | BinOp::Coalesce => (1, false),
        BinOp::And => (2, false),
        BinOp::Eq | BinOp::NotEq | BinOp::Lt | BinOp::LtEq | BinOp::Gt | BinOp::GtEq => (3, false),
        BinOp::Concat => (4, true),
        BinOp::Add | BinOp::Sub => (5, false),
        BinOp::Mul | BinOp::Div | BinOp::Mod => (6, false),
    }
}

fn bin_sym(op: BinOp) -> &'static str {
    match op {
        BinOp::Add => "+",
        BinOp::Sub => "-",
        BinOp::Mul => "*",
        BinOp::Div => "/",
        BinOp::Mod => "%",
        BinOp::Eq => "==",
        BinOp::NotEq => "!=",
        BinOp::Lt => "<",
        BinOp::LtEq => "<=",
        BinOp::Gt => ">",
        BinOp::GtEq => ">=",
        BinOp::And => "and",
        BinOp::Or => "or",
        BinOp::Concat => "..",
        BinOp::Coalesce => "??",
    }
}

/// Render an `f64` so it always reads back as a float (i.e. `1.0` rather
/// than `1`) and round-trips through `parse::<f64>()` losslessly for
/// finite values.
fn format_float(f: f64) -> String {
    if !f.is_finite() {
        // Saule has no syntax for these; keep something readable.
        return format!("{f}");
    }
    let s = format!("{f}");
    if s.contains('.') || s.contains('e') || s.contains('E') {
        s
    } else {
        format!("{s}.0")
    }
}

fn quote_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\x{:02x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Whether a single-param lambda came from the `name => expr` shortcut
/// (no type annotation, no return type, default-`any`). Matches the
/// parser's reconstruction so re-parsing produces the same AST.
fn is_bare_arrow_param(params: &[Param], return_ty: &Option<Type>) -> bool {
    if return_ty.is_some() || params.len() != 1 {
        return false;
    }
    let p = &params[0];
    !p.variadic
        && p.default.is_none()
        && matches!(&p.ty, Type::Named(n) if n == "any")
}

fn is_ident(s: &str) -> bool {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) if c.is_ascii_alphabetic() || c == '_' => {}
        _ => return false,
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}

/// Whether two adjacent top-level statements should be separated by a
/// blank line. Declarations get breathing room; tight runs of locals or
/// expression statements stay compact.
fn needs_top_separator(prev: &Stmt, next: &Stmt) -> bool {
    let p_is_decl = matches!(prev, Stmt::Decl(_));
    let n_is_decl = matches!(next, Stmt::Decl(_));
    p_is_decl || n_is_decl
}

/// The byte offset where the next chunk of an `if … elseif … else … end`
/// starts. Used as the body-block ceiling when draining comments so they
/// don't escape past the `elseif` / `else` keyword.
fn next_if_chunk_start(
    remaining_elseifs: &[(Spanned<Expr>, Vec<Spanned<Stmt>>)],
    else_block: &Option<Vec<Spanned<Stmt>>>,
    fallback: usize,
) -> usize {
    if let Some((cond, _)) = remaining_elseifs.first() {
        return cond.span.start;
    }
    if let Some(eb) = else_block {
        if let Some(first) = eb.first() {
            return first.span.start;
        }
    }
    fallback
}

use std::{
    fs,
    path::{Path, PathBuf},
    process,
};

use miette::{NamedSource, Report};
use saule_interpreter::{Environment, Value, module::ModuleLoader};

const USAGE: &str = "\
Usage:
  saule run <file.sau>       run a single Saule source file
  saule run                  run the project in the current directory
  saule init <name>          scaffold a new Saule project in ./<name>
  saule --help | -h          show this help
  saule --version | -V       print the version";

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();

    let head = args.first().map(String::as_str).unwrap_or("");
    match head {
        "" | "-h" | "--help" => {
            println!("{USAGE}");
        }
        "-v" | "--version" => {
            println!("saule {}", env!("CARGO_PKG_VERSION"));
        }
        "init" => match args.get(1) {
            Some(name) => cmd_init(name),
            None => {
                eprintln!("error: `init` needs a project name\n\n{USAGE}");
                process::exit(2);
            }
        },
        "run" => match args.get(1) {
            Some(path) => run_file(PathBuf::from(path), false),
            None => run_project(&PathBuf::from(".")),
        },
        other => {
            eprintln!("Error: Unknown Command `{other}`\n\n{USAGE}");
            process::exit(2);
        }
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// `saule init <name>` — scaffold a new project.
// ──────────────────────────────────────────────────────────────────────────────

fn cmd_init(name: &str) {
    let root = PathBuf::from(name);
    if root.exists() {
        eprintln!("error: `{name}` already exists");
        process::exit(1);
    }
    if let Err(e) = fs::create_dir_all(root.join("src")) {
        eprintln!("error creating project directory: {e}");
        process::exit(1);
    }

    let config = format!("name: \"{name}\"\nversion: \"0.1.0\"\nentry: \"src/main.sau\"\n");

    let main_sau = "\
--[[
Entry point.

The `Main` class with a `static fn main()` is the default entry point for a Saule.
]] 

class Greeter
    local who: string

    fn init(who: string)
        self.who = who
    end

    fn greet()
        println(\"hi, \" .. self.who)
    end
end

class Main
    static fn main()
        local g: Greeter = Greeter(\"world\")
        g.greet()
    end
end
";

    let gitignore = "*.log\n";

    let readme = format!("# {name}\n\nA Saule project. Run with:\n\n```sh\nsaule run\n```\n");

    let write = |relpath: &str, contents: &str| -> Result<(), std::io::Error> {
        fs::write(root.join(relpath), contents)
    };

    if let Err(e) = write("saule.config", &config)
        .and_then(|_| write("src/main.sau", main_sau))
        .and_then(|_| write(".gitignore", gitignore))
        .and_then(|_| write("README.md", &readme))
    {
        eprintln!("error writing project files: {e}");
        process::exit(1);
    }

    println!("Created project `{name}`");
    println!("  cd {name}");
    println!("  saule run");
}

// ──────────────────────────────────────────────────────────────────────────────
// `saule run` (no args) — read `saule.config` from cwd, run the file named
// by its `entry:` key. The file must declare `class Main` with a
// `static fn main()`, which is the program entry point.
// ──────────────────────────────────────────────────────────────────────────────

fn run_project(dir: &Path) {
    let config_path = dir.join("saule.config");
    if !config_path.exists() {
        eprintln!(
            "error: no `saule.config` in `{}`\n\nRun `saule init <name>` to create one, or pass a file path.",
            dir.display()
        );
        process::exit(1);
    }

    let config = match read_config(&config_path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("error reading {}: {e}", config_path.display());
            process::exit(1);
        }
    };

    let entry = config
        .get("entry")
        .map(String::as_str)
        .unwrap_or("src/main.sau");
    run_file(dir.join(entry), true);
}

/// Parse the tiny `key: "value"` config format. Unknown keys are kept;
/// blank lines and `--` line comments are ignored.
fn read_config(path: &Path) -> std::io::Result<std::collections::HashMap<String, String>> {
    let text = fs::read_to_string(path)?;
    let mut out = std::collections::HashMap::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with("--") {
            continue;
        }
        let Some((key, value)) = line.split_once(':') else {
            continue;
        };
        let key = key.trim().to_string();
        let value = value.trim().trim_matches('"').to_string();
        out.insert(key, value);
    }
    Ok(out)
}

fn run_file(path: PathBuf, require_main: bool) {
    if !path.exists() {
        eprintln!("error: file '{}' does not exist", path.display());
        process::exit(1);
    }
    let source = fs::read_to_string(&path).unwrap_or_else(|err| {
        eprintln!("error reading file '{}': {}", path.display(), err);
        process::exit(1);
    });

    let name = path
        .file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| path.display().to_string());

    let module_dir = path
        .canonicalize()
        .ok()
        .and_then(|p| p.parent().map(Path::to_path_buf))
        .or_else(|| path.parent().map(Path::to_path_buf));

    if let Err(report) = run_source(&name, source, require_main, module_dir) {
        eprintln!("{report:?}");
        process::exit(1);
    }
}

fn run_source(
    name: &str,
    source: String,
    require_main: bool,
    module_dir: Option<PathBuf>,
) -> Result<(), Report> {
    let make_src = || NamedSource::new(name.to_string(), source.clone());

    let tokens = saule_lexer::Lexer::new(&source)
        .tokenize()
        .map_err(|e| Report::new(e).with_source_code(make_src()))?;

    let module =
        saule_parser::parse(tokens).map_err(|e| Report::new(e).with_source_code(make_src()))?;

    // Static checks run *before* evaluation so we fail fast on declarative
    // errors (missing field initializers etc.) without ever executing user
    // code. Today the checker is intentionally narrow; see `typeck`.
    let errors = saule_interpreter::typeck::check(&module);
    if let Some(first) = errors.into_iter().next() {
        return Err(Report::new(first).with_source_code(make_src()));
    }

    // Execute the file's top-level statements so declarations register.
    // The environment carries the file's directory plus a shared module
    // loader so `import "..."` can resolve relative paths and dedupe
    // already-loaded modules.
    let loader = ModuleLoader::new();
    let env = Environment::with_prelude_and_context(module_dir, Some(loader));
    saule_interpreter::run_in(&module, &env)
        .map_err(|e| Report::new(e).with_source_code(make_src()))?;

    // Project entry point: `class Main` with `static fn main()`.
    // When required (project mode), missing it is a hard error.
    // For single-file mode it's invoked when present as a convenience.
    let main_class = match env.borrow().get("Main") {
        Some(Value::Class(c)) => Some(c),
        _ => None,
    };
    match main_class {
        Some(c) if c.lookup_static_method("main").is_some() => {
            saule_interpreter::call_class_static_method(&c, "main", &[])
                .map_err(|e| Report::new(e).with_source_code(make_src()))?;
        }
        _ if require_main => {
            eprintln!(
                "error: `{name}` must declare `class Main` with a `static fn main()` entry point"
            );
            process::exit(1);
        }
        _ => {}
    }

    Ok(())
}

use std::{
    fs,
    path::{Path, PathBuf},
    process,
};

use miette::{NamedSource, Report};
use saule_interpreter::{Environment, Value, module::ModuleLoader};

const USAGE: &str = "\
Usage:
  saule run <file.sau>       run a single Saule source file
  saule run                  run the project in the current directory
  saule init <name>          scaffold a new Saule project in ./<name>
  saule --help | -h          show this help
  saule --version | -V       print the version";

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();

    let head = args.first().map(String::as_str).unwrap_or("");
    match head {
        "" | "-h" | "--help" => {
            println!("{USAGE}");
        }
        "-v" | "--version" => {
            println!("saule {}", env!("CARGO_PKG_VERSION"));
        }
        "init" => match args.get(1) {
            Some(name) => cmd_init(name),
            None => {
                eprintln!("error: `init` needs a project name\n\n{USAGE}");
                process::exit(2);
            }
        },
        "run" => match args.get(1) {
            Some(path) => {
                // Everything after the file path is script argv, exposed via
                // `Os.args()`.
                saule_interpreter::stdlib::os::set_script_args(
                    args.iter().skip(2).cloned().collect(),
                );
                run_file(PathBuf::from(path), false);
            }
            None => {
                // Project mode: script-args is everything after `run`.
                saule_interpreter::stdlib::os::set_script_args(
                    args.iter().skip(1).cloned().collect(),
                );
                run_project(&PathBuf::from("."));
            }
        },
        other => {
            eprintln!("Error: Unknown Command `{other}`\n\n{USAGE}");
            process::exit(2);
        }
    }
}

