//! Math prelude functions and constants.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use std::thread_local;

use crate::env::Environment;
use crate::stdlib::{expect_arity, expect_min_arity};
use crate::value::{ClassObject, Value};

pub fn install(env: &std::rc::Rc<std::cell::RefCell<Environment>>) {
    let mut static_fields = HashMap::new();
    static_fields.insert("abs".to_string(), native("Math.abs", math_abs));
    static_fields.insert("acos".to_string(), native("Math.acos", math_acos));
    static_fields.insert("asin".to_string(), native("Math.asin", math_asin));
    static_fields.insert("atan".to_string(), native("Math.atan", math_atan));
    static_fields.insert("min".to_string(), native("Math.min", math_min));
    static_fields.insert("max".to_string(), native("Math.max", math_max));
    static_fields.insert("cos".to_string(), native("Math.cos", math_cos));
    static_fields.insert("sin".to_string(), native("Math.sin", math_sin));
    static_fields.insert("tan".to_string(), native("Math.tan", math_tan));
    static_fields.insert("deg".to_string(), native("Math.deg", math_deg));
    static_fields.insert("rad".to_string(), native("Math.rad", math_rad));
    static_fields.insert("exp".to_string(), native("Math.exp", math_exp));
    static_fields.insert("floor".to_string(), native("Math.floor", math_floor));
    static_fields.insert("ceil".to_string(), native("Math.ceil", math_ceil));
    static_fields.insert("fmod".to_string(), native("Math.fmod", math_fmod));
    static_fields.insert("log".to_string(), native("Math.log", math_log));
    static_fields.insert("modf".to_string(), native("Math.modf", math_modf));
    static_fields.insert("random".to_string(), native("Math.random", math_random));
    static_fields.insert(
        "randomseed".to_string(),
        native("Math.randomseed", math_randomseed),
    );
    static_fields.insert(
        "tointeger".to_string(),
        native("Math.tointeger", math_tointeger),
    );
    static_fields.insert("type".to_string(), native("Math.type", math_type));
    static_fields.insert("ult".to_string(), native("Math.ult", math_ult));
    static_fields.insert("round".to_string(), native("Math.round", math_round));
    static_fields.insert("sqrt".to_string(), native("Math.sqrt", math_sqrt));
    static_fields.insert("pow".to_string(), native("Math.pow", math_pow));
    static_fields.insert("clamp".to_string(), native("Math.clamp", math_clamp));
    static_fields.insert("sign".to_string(), native("Math.sign", math_sign));
    static_fields.insert("pi".to_string(), Value::Float(std::f64::consts::PI));
    static_fields.insert("huge".to_string(), Value::Float(f64::INFINITY));
    static_fields.insert("maxinteger".to_string(), Value::Int(i64::MAX));
    static_fields.insert("mininteger".to_string(), Value::Int(i64::MIN));
    static_fields.insert("e".to_string(), Value::Float(std::f64::consts::E));

    let class = ClassObject {
        name: "Math".to_string(),
        parent: None,
        field_defs: Vec::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(static_fields),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("Math".to_string(), Value::Class(Rc::new(class)));
}

/// Register native signatures for the typechecker (lazy, via `sigs::lookup`).
pub fn register_sigs() {
    use crate::stdlib::sigs::{register, t_named, t_nullable, t_number};
    let any = || t_named("any");
    let n   = t_number;
    let i   = || t_named("integer");
    let f   = || t_named("float");
    let b   = || t_named("boolean");
    let s   = || t_named("string");

    // `tointeger` / `type` accept anything by design (they return nil for
    // values that can't be coerced / aren't numeric).
    register("Math.tointeger",   vec![any()],               vec![t_nullable(i())]);
    register("Math.type",        vec![any()],               vec![t_nullable(s())]);

    // Definitely-integer returns; require a number in.
    register("Math.floor",       vec![n()],                 vec![i()]);
    register("Math.ceil",        vec![n()],                 vec![i()]);
    register("Math.round",       vec![n()],                 vec![i()]);
    register("Math.maxinteger",  vec![],                    vec![i()]);
    register("Math.mininteger",  vec![],                    vec![i()]);
    register("Math.sign",        vec![n()],                 vec![i()]);

    // Definitely-float returns; require a number in.
    register("Math.sqrt",        vec![n()],                 vec![f()]);
    register("Math.sin",         vec![n()],                 vec![f()]);
    register("Math.cos",         vec![n()],                 vec![f()]);
    register("Math.tan",         vec![n()],                 vec![f()]);
    register("Math.asin",        vec![n()],                 vec![f()]);
    register("Math.acos",        vec![n()],                 vec![f()]);
    // `atan(y)` and `atan(y, x)` are both valid (the 2-arg form is atan2).
    register("Math.atan",        vec![n(), t_nullable(n())], vec![f()]);
    register("Math.exp",         vec![n()],                 vec![f()]);
    register("Math.log",         vec![n()],                 vec![f()]);
    register("Math.deg",         vec![n()],                 vec![f()]);
    register("Math.rad",         vec![n()],                 vec![f()]);
    register("Math.huge",        vec![],                    vec![f()]);
    register("Math.pi",          vec![],                    vec![f()]);
    register("Math.e",           vec![],                    vec![f()]);

    // Boolean.
    register("Math.ult",         vec![i(), i()],            vec![b()]);

    // `abs`, `min`, `max`, `pow`, `clamp`, `fmod`, `modf`, `random` can be
    // either integer or float depending on input — left unregistered so the
    // checker stays conservative (`None`) rather than narrowing wrongly.
}

fn native(name: &'static str, func: fn(&[Value]) -> Result<Value, String>) -> Value {
    Value::Native(Rc::new(crate::value::NativeFn { name, func }))
}

#[derive(Clone, Copy)]
enum Number {
    Int(i64),
    Float(f64),
}

thread_local! {
    static RNG_STATE: RefCell<u64> = const { RefCell::new(0x6a09e667f3bcc909) };
}

fn next_u64() -> u64 {
    RNG_STATE.with(|cell| {
        let mut state = cell.borrow_mut();
        let mut x = *state;
        if x == 0 {
            x = 0x9e3779b97f4a7c15;
        }
        // xorshift64*
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        let out = x.wrapping_mul(0x2545f4914f6cdd1d);
        *state = x;
        out
    })
}

fn random_unit() -> f64 {
    // Use top 53 bits for an IEEE754 fraction in [0, 1).
    let bits = next_u64() >> 11;
    (bits as f64) * (1.0 / ((1u64 << 53) as f64))
}

impl Number {
    fn as_f64(self) -> f64 {
        match self {
            Number::Int(n) => n as f64,
            Number::Float(f) => f,
        }
    }
}

fn number_at(args: &[Value], idx: usize, fn_name: &str) -> Result<Number, String> {
    match args.get(idx) {
        Some(Value::Int(n)) => Ok(Number::Int(*n)),
        Some(Value::Float(f)) => Ok(Number::Float(*f)),
        Some(v) => Err(format!(
            "{fn_name} expects numeric arguments; arg #{} is `{}`",
            idx + 1,
            v.type_name()
        )),
        None => Err(format!("{fn_name} missing arg #{}", idx + 1)),
    }
}

fn math_abs(args: &[Value]) -> Result<Value, String> {
    expect_arity("abs", args, 1)?;
    match number_at(args, 0, "abs")? {
        Number::Int(n) => Ok(Value::Int(n.abs())),
        Number::Float(f) => Ok(Value::Float(f.abs())),
    }
}

fn math_acos(args: &[Value]) -> Result<Value, String> {
    expect_arity("acos", args, 1)?;
    Ok(Value::Float(number_at(args, 0, "acos")?.as_f64().acos()))
}

fn math_asin(args: &[Value]) -> Result<Value, String> {
    expect_arity("asin", args, 1)?;
    Ok(Value::Float(number_at(args, 0, "asin")?.as_f64().asin()))
}

fn math_atan(args: &[Value]) -> Result<Value, String> {
    if args.len() != 1 && args.len() != 2 {
        return Err(format!("atan expects 1 or 2 arguments, got {}", args.len()));
    }
    let y = number_at(args, 0, "atan")?.as_f64();
    if args.len() == 1 {
        Ok(Value::Float(y.atan()))
    } else {
        let x = number_at(args, 1, "atan")?.as_f64();
        Ok(Value::Float(y.atan2(x)))
    }
}

fn math_min(args: &[Value]) -> Result<Value, String> {
    expect_min_arity("min", args, 1)?;
    let mut min = number_at(args, 0, "min")?.as_f64();
    for i in 1..args.len() {
        min = min.min(number_at(args, i, "min")?.as_f64());
    }
    Ok(Value::Float(min))
}

fn math_max(args: &[Value]) -> Result<Value, String> {
    expect_min_arity("max", args, 1)?;
    let mut max = number_at(args, 0, "max")?.as_f64();
    for i in 1..args.len() {
        max = max.max(number_at(args, i, "max")?.as_f64());
    }
    Ok(Value::Float(max))
}

fn math_cos(args: &[Value]) -> Result<Value, String> {
    expect_arity("cos", args, 1)?;
    Ok(Value::Float(number_at(args, 0, "cos")?.as_f64().cos()))
}

fn math_sin(args: &[Value]) -> Result<Value, String> {
    expect_arity("sin", args, 1)?;
    Ok(Value::Float(number_at(args, 0, "sin")?.as_f64().sin()))
}

fn math_tan(args: &[Value]) -> Result<Value, String> {
    expect_arity("tan", args, 1)?;
    Ok(Value::Float(number_at(args, 0, "tan")?.as_f64().tan()))
}

fn math_deg(args: &[Value]) -> Result<Value, String> {
    expect_arity("deg", args, 1)?;
    Ok(Value::Float(
        number_at(args, 0, "deg")?.as_f64() * 180.0 / std::f64::consts::PI,
    ))
}

fn math_rad(args: &[Value]) -> Result<Value, String> {
    expect_arity("rad", args, 1)?;
    Ok(Value::Float(
        number_at(args, 0, "rad")?.as_f64() * std::f64::consts::PI / 180.0,
    ))
}

fn math_exp(args: &[Value]) -> Result<Value, String> {
    expect_arity("exp", args, 1)?;
    Ok(Value::Float(number_at(args, 0, "exp")?.as_f64().exp()))
}

fn math_floor(args: &[Value]) -> Result<Value, String> {
    expect_arity("floor", args, 1)?;
    match number_at(args, 0, "floor")? {
        Number::Int(n) => Ok(Value::Int(n)),
        Number::Float(f) => Ok(Value::Int(f.floor() as i64)),
    }
}

fn math_ceil(args: &[Value]) -> Result<Value, String> {
    expect_arity("ceil", args, 1)?;
    match number_at(args, 0, "ceil")? {
        Number::Int(n) => Ok(Value::Int(n)),
        Number::Float(f) => Ok(Value::Int(f.ceil() as i64)),
    }
}

fn math_fmod(args: &[Value]) -> Result<Value, String> {
    expect_arity("fmod", args, 2)?;
    let a = number_at(args, 0, "fmod")?;
    let b = number_at(args, 1, "fmod")?;
    match (a, b) {
        (Number::Int(x), Number::Int(y)) => {
            if y == 0 {
                return Err("fmod divisor cannot be zero".to_string());
            }
            Ok(Value::Int(x % y))
        }
        _ => {
            let x = a.as_f64();
            let y = b.as_f64();
            if y == 0.0 {
                return Err("fmod divisor cannot be zero".to_string());
            }
            Ok(Value::Float(x % y))
        }
    }
}

fn math_log(args: &[Value]) -> Result<Value, String> {
    if args.len() != 1 && args.len() != 2 {
        return Err(format!("log expects 1 or 2 arguments, got {}", args.len()));
    }
    let x = number_at(args, 0, "log")?.as_f64();
    if x <= 0.0 {
        return Err("log expects a positive value".to_string());
    }
    if args.len() == 1 {
        Ok(Value::Float(x.ln()))
    } else {
        let base = number_at(args, 1, "log")?.as_f64();
        if base <= 0.0 || (base - 1.0).abs() < f64::EPSILON {
            return Err("log base must be positive and not equal to 1".to_string());
        }
        Ok(Value::Float(x.log(base)))
    }
}

fn math_modf(args: &[Value]) -> Result<Value, String> {
    expect_arity("modf", args, 1)?;
    let x = number_at(args, 0, "modf")?.as_f64();
    let int_part = x.trunc();
    let frac_part = x - int_part;
    Ok(Value::Table(Rc::new(RefCell::new(
        crate::value::TableObject::from_array(vec![
            Value::Float(int_part),
            Value::Float(frac_part),
        ]),
    ))))
}

fn math_round(args: &[Value]) -> Result<Value, String> {
    expect_arity("round", args, 1)?;
    match number_at(args, 0, "round")? {
        Number::Int(n) => Ok(Value::Int(n)),
        Number::Float(f) => Ok(Value::Int(f.round() as i64)),
    }
}

fn math_sqrt(args: &[Value]) -> Result<Value, String> {
    expect_arity("sqrt", args, 1)?;
    let x = number_at(args, 0, "sqrt")?.as_f64();
    if x < 0.0 {
        return Err("sqrt expects a non-negative number".to_string());
    }
    Ok(Value::Float(x.sqrt()))
}

fn math_random(args: &[Value]) -> Result<Value, String> {
    match args.len() {
        0 => Ok(Value::Float(random_unit())),
        1 => {
            let n = number_at(args, 0, "random")?;
            let hi = match n {
                Number::Int(i) => i,
                Number::Float(f) => {
                    if f.fract() != 0.0 {
                        return Err("random upper bound must be an integer".to_string());
                    }
                    f as i64
                }
            };
            if hi < 1 {
                return Err("random upper bound must be >= 1".to_string());
            }
            let span = hi as u64;
            Ok(Value::Int((next_u64() % span) as i64 + 1))
        }
        2 => {
            let lo = to_i64(number_at(args, 0, "random")?, "random lower bound")?;
            let hi = to_i64(number_at(args, 1, "random")?, "random upper bound")?;
            if lo > hi {
                return Err("random expects lower bound <= upper bound".to_string());
            }
            let span = (hi as i128 - lo as i128 + 1) as u128;
            let v = (next_u64() as u128) % span;
            Ok(Value::Int(lo + v as i64))
        }
        _ => Err(format!("random expects 0, 1, or 2 arguments, got {}", args.len())),
    }
}

fn math_randomseed(args: &[Value]) -> Result<Value, String> {
    expect_arity("randomseed", args, 1)?;
    let seed = match number_at(args, 0, "randomseed")? {
        Number::Int(i) => i as u64,
        Number::Float(f) => f.to_bits(),
    };
    RNG_STATE.with(|cell| *cell.borrow_mut() = if seed == 0 { 1 } else { seed });
    Ok(Value::Nil)
}

fn math_tointeger(args: &[Value]) -> Result<Value, String> {
    expect_arity("tointeger", args, 1)?;
    let out = match &args[0] {
        Value::Int(i) => Some(*i),
        Value::Float(f) => {
            if f.is_finite() && f.fract() == 0.0 && *f >= i64::MIN as f64 && *f <= i64::MAX as f64
            {
                Some(*f as i64)
            } else {
                None
            }
        }
        _ => None,
    };
    Ok(out.map(Value::Int).unwrap_or(Value::Nil))
}

fn math_type(args: &[Value]) -> Result<Value, String> {
    expect_arity("type", args, 1)?;
    match args[0] {
        Value::Int(_) => Ok(Value::Str(Rc::new("integer".to_string()))),
        Value::Float(_) => Ok(Value::Str(Rc::new("float".to_string()))),
        _ => Ok(Value::Nil),
    }
}

fn math_ult(args: &[Value]) -> Result<Value, String> {
    expect_arity("ult", args, 2)?;
    let a = to_i64(number_at(args, 0, "ult")?, "ult arg #1")? as u64;
    let b = to_i64(number_at(args, 1, "ult")?, "ult arg #2")? as u64;
    Ok(Value::Bool(a < b))
}

fn math_pow(args: &[Value]) -> Result<Value, String> {
    expect_arity("pow", args, 2)?;
    let base = number_at(args, 0, "pow")?.as_f64();
    let exp = number_at(args, 1, "pow")?.as_f64();
    Ok(Value::Float(base.powf(exp)))
}

fn math_clamp(args: &[Value]) -> Result<Value, String> {
    expect_arity("clamp", args, 3)?;
    let value = number_at(args, 0, "clamp")?.as_f64();
    let min = number_at(args, 1, "clamp")?.as_f64();
    let max = number_at(args, 2, "clamp")?.as_f64();
    if min > max {
        return Err("clamp expects min <= max".to_string());
    }
    Ok(Value::Float(value.clamp(min, max)))
}

fn math_sign(args: &[Value]) -> Result<Value, String> {
    expect_arity("sign", args, 1)?;
    let x = number_at(args, 0, "sign")?.as_f64();
    let out = if x > 0.0 {
        1
    } else if x < 0.0 {
        -1
    } else {
        0
    };
    Ok(Value::Int(out))
}

fn to_i64(n: Number, label: &str) -> Result<i64, String> {
    match n {
        Number::Int(i) => Ok(i),
        Number::Float(f) => {
            if f.fract() != 0.0 || !f.is_finite() || f < i64::MIN as f64 || f > i64::MAX as f64 {
                Err(format!("{label} must be an integer"))
            } else {
                Ok(f as i64)
            }
        }
    }
}

//! Math prelude functions and constants.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use std::thread_local;

use crate::env::Environment;
use crate::stdlib::{expect_arity, expect_min_arity};
use crate::value::{ClassObject, Value};

pub fn install(env: &std::rc::Rc<std::cell::RefCell<Environment>>) {
    let mut static_fields = HashMap::new();
    static_fields.insert("abs".to_string(), native("Math.abs", math_abs));
    static_fields.insert("acos".to_string(), native("Math.acos", math_acos));
    static_fields.insert("asin".to_string(), native("Math.asin", math_asin));
    static_fields.insert("atan".to_string(), native("Math.atan", math_atan));
    static_fields.insert("min".to_string(), native("Math.min", math_min));
    static_fields.insert("max".to_string(), native("Math.max", math_max));
    static_fields.insert("cos".to_string(), native("Math.cos", math_cos));
    static_fields.insert("sin".to_string(), native("Math.sin", math_sin));
    static_fields.insert("tan".to_string(), native("Math.tan", math_tan));
    static_fields.insert("deg".to_string(), native("Math.deg", math_deg));
    static_fields.insert("rad".to_string(), native("Math.rad", math_rad));
    static_fields.insert("exp".to_string(), native("Math.exp", math_exp));
    static_fields.insert("floor".to_string(), native("Math.floor", math_floor));
    static_fields.insert("ceil".to_string(), native("Math.ceil", math_ceil));
    static_fields.insert("fmod".to_string(), native("Math.fmod", math_fmod));
    static_fields.insert("log".to_string(), native("Math.log", math_log));
    static_fields.insert("modf".to_string(), native("Math.modf", math_modf));
    static_fields.insert("random".to_string(), native("Math.random", math_random));
    static_fields.insert(
        "randomseed".to_string(),
        native("Math.randomseed", math_randomseed),
    );
    static_fields.insert(
        "tointeger".to_string(),
        native("Math.tointeger", math_tointeger),
    );
    static_fields.insert("type".to_string(), native("Math.type", math_type));
    static_fields.insert("ult".to_string(), native("Math.ult", math_ult));
    static_fields.insert("round".to_string(), native("Math.round", math_round));
    static_fields.insert("sqrt".to_string(), native("Math.sqrt", math_sqrt));
    static_fields.insert("pow".to_string(), native("Math.pow", math_pow));
    static_fields.insert("clamp".to_string(), native("Math.clamp", math_clamp));
    static_fields.insert("sign".to_string(), native("Math.sign", math_sign));
    static_fields.insert("pi".to_string(), Value::Float(std::f64::consts::PI));
    static_fields.insert("huge".to_string(), Value::Float(f64::INFINITY));
    static_fields.insert("maxinteger".to_string(), Value::Int(i64::MAX));
    static_fields.insert("mininteger".to_string(), Value::Int(i64::MIN));
    static_fields.insert("e".to_string(), Value::Float(std::f64::consts::E));

    let class = ClassObject {
        name: "Math".to_string(),
        parent: None,
        field_defs: Vec::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(static_fields),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("Math".to_string(), Value::Class(Rc::new(class)));
}

/// Register native signatures for the typechecker (lazy, via `sigs::lookup`).
pub fn register_sigs() {
    use crate::stdlib::sigs::{register, t_named, t_nullable, t_number};
    let any = || t_named("any");
    let n   = t_number;
    let i   = || t_named("integer");
    let f   = || t_named("float");
    let b   = || t_named("boolean");
    let s   = || t_named("string");

    // `tointeger` / `type` accept anything by design (they return nil for
    // values that can't be coerced / aren't numeric).
    register("Math.tointeger",   vec![any()],               vec![t_nullable(i())]);
    register("Math.type",        vec![any()],               vec![t_nullable(s())]);

    // Definitely-integer returns; require a number in.
    register("Math.floor",       vec![n()],                 vec![i()]);
    register("Math.ceil",        vec![n()],                 vec![i()]);
    register("Math.round",       vec![n()],                 vec![i()]);
    register("Math.maxinteger",  vec![],                    vec![i()]);
    register("Math.mininteger",  vec![],                    vec![i()]);
    register("Math.sign",        vec![n()],                 vec![i()]);

    // Definitely-float returns; require a number in.
    register("Math.sqrt",        vec![n()],                 vec![f()]);
    register("Math.sin",         vec![n()],                 vec![f()]);
    register("Math.cos",         vec![n()],                 vec![f()]);
    register("Math.tan",         vec![n()],                 vec![f()]);
    register("Math.asin",        vec![n()],                 vec![f()]);
    register("Math.acos",        vec![n()],                 vec![f()]);
    // `atan(y)` and `atan(y, x)` are both valid (the 2-arg form is atan2).
    register("Math.atan",        vec![n(), t_nullable(n())], vec![f()]);
    register("Math.exp",         vec![n()],                 vec![f()]);
    // `log(x)` natural log; `log(x, base)` arbitrary base.
    register("Math.log",         vec![n(), t_nullable(n())], vec![f()]);
    register("Math.deg",         vec![n()],                 vec![f()]);
    register("Math.rad",         vec![n()],                 vec![f()]);
    register("Math.huge",        vec![],                    vec![f()]);
    register("Math.pi",          vec![],                    vec![f()]);
    register("Math.e",           vec![],                    vec![f()]);

    // Boolean.
    register("Math.ult",         vec![i(), i()],            vec![b()]);

    // `abs`, `min`, `max`, `pow`, `clamp`, `fmod`, `modf`, `random` can be
    // either integer or float depending on input — left unregistered so the
    // checker stays conservative (`None`) rather than narrowing wrongly.
}

fn native(name: &'static str, func: fn(&[Value]) -> Result<Value, String>) -> Value {
    Value::Native(Rc::new(crate::value::NativeFn { name, func }))
}

#[derive(Clone, Copy)]
enum Number {
    Int(i64),
    Float(f64),
}

thread_local! {
    static RNG_STATE: RefCell<u64> = const { RefCell::new(0x6a09e667f3bcc909) };
}

fn next_u64() -> u64 {
    RNG_STATE.with(|cell| {
        let mut state = cell.borrow_mut();
        let mut x = *state;
        if x == 0 {
            x = 0x9e3779b97f4a7c15;
        }
        // xorshift64*
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        let out = x.wrapping_mul(0x2545f4914f6cdd1d);
        *state = x;
        out
    })
}

fn random_unit() -> f64 {
    // Use top 53 bits for an IEEE754 fraction in [0, 1).
    let bits = next_u64() >> 11;
    (bits as f64) * (1.0 / ((1u64 << 53) as f64))
}

impl Number {
    fn as_f64(self) -> f64 {
        match self {
            Number::Int(n) => n as f64,
            Number::Float(f) => f,
        }
    }
}

fn number_at(args: &[Value], idx: usize, fn_name: &str) -> Result<Number, String> {
    match args.get(idx) {
        Some(Value::Int(n)) => Ok(Number::Int(*n)),
        Some(Value::Float(f)) => Ok(Number::Float(*f)),
        Some(v) => Err(format!(
            "{fn_name} expects numeric arguments; arg #{} is `{}`",
            idx + 1,
            v.type_name()
        )),
        None => Err(format!("{fn_name} missing arg #{}", idx + 1)),
    }
}

fn math_abs(args: &[Value]) -> Result<Value, String> {
    expect_arity("abs", args, 1)?;
    match number_at(args, 0, "abs")? {
        Number::Int(n) => Ok(Value::Int(n.abs())),
        Number::Float(f) => Ok(Value::Float(f.abs())),
    }
}

fn math_acos(args: &[Value]) -> Result<Value, String> {
    expect_arity("acos", args, 1)?;
    Ok(Value::Float(number_at(args, 0, "acos")?.as_f64().acos()))
}

fn math_asin(args: &[Value]) -> Result<Value, String> {
    expect_arity("asin", args, 1)?;
    Ok(Value::Float(number_at(args, 0, "asin")?.as_f64().asin()))
}

fn math_atan(args: &[Value]) -> Result<Value, String> {
    if args.len() != 1 && args.len() != 2 {
        return Err(format!("atan expects 1 or 2 arguments, got {}", args.len()));
    }
    let y = number_at(args, 0, "atan")?.as_f64();
    if args.len() == 1 {
        Ok(Value::Float(y.atan()))
    } else {
        let x = number_at(args, 1, "atan")?.as_f64();
        Ok(Value::Float(y.atan2(x)))
    }
}

fn math_min(args: &[Value]) -> Result<Value, String> {
    expect_min_arity("min", args, 1)?;
    let mut min = number_at(args, 0, "min")?.as_f64();
    for i in 1..args.len() {
        min = min.min(number_at(args, i, "min")?.as_f64());
    }
    Ok(Value::Float(min))
}

fn math_max(args: &[Value]) -> Result<Value, String> {
    expect_min_arity("max", args, 1)?;
    let mut max = number_at(args, 0, "max")?.as_f64();
    for i in 1..args.len() {
        max = max.max(number_at(args, i, "max")?.as_f64());
    }
    Ok(Value::Float(max))
}

fn math_cos(args: &[Value]) -> Result<Value, String> {
    expect_arity("cos", args, 1)?;
    Ok(Value::Float(number_at(args, 0, "cos")?.as_f64().cos()))
}

fn math_sin(args: &[Value]) -> Result<Value, String> {
    expect_arity("sin", args, 1)?;
    Ok(Value::Float(number_at(args, 0, "sin")?.as_f64().sin()))
}

fn math_tan(args: &[Value]) -> Result<Value, String> {
    expect_arity("tan", args, 1)?;
    Ok(Value::Float(number_at(args, 0, "tan")?.as_f64().tan()))
}

fn math_deg(args: &[Value]) -> Result<Value, String> {
    expect_arity("deg", args, 1)?;
    Ok(Value::Float(
        number_at(args, 0, "deg")?.as_f64() * 180.0 / std::f64::consts::PI,
    ))
}

fn math_rad(args: &[Value]) -> Result<Value, String> {
    expect_arity("rad", args, 1)?;
    Ok(Value::Float(
        number_at(args, 0, "rad")?.as_f64() * std::f64::consts::PI / 180.0,
    ))
}

fn math_exp(args: &[Value]) -> Result<Value, String> {
    expect_arity("exp", args, 1)?;
    Ok(Value::Float(number_at(args, 0, "exp")?.as_f64().exp()))
}

fn math_floor(args: &[Value]) -> Result<Value, String> {
    expect_arity("floor", args, 1)?;
    match number_at(args, 0, "floor")? {
        Number::Int(n) => Ok(Value::Int(n)),
        Number::Float(f) => Ok(Value::Int(f.floor() as i64)),
    }
}

fn math_ceil(args: &[Value]) -> Result<Value, String> {
    expect_arity("ceil", args, 1)?;
    match number_at(args, 0, "ceil")? {
        Number::Int(n) => Ok(Value::Int(n)),
        Number::Float(f) => Ok(Value::Int(f.ceil() as i64)),
    }
}

fn math_fmod(args: &[Value]) -> Result<Value, String> {
    expect_arity("fmod", args, 2)?;
    let a = number_at(args, 0, "fmod")?;
    let b = number_at(args, 1, "fmod")?;
    match (a, b) {
        (Number::Int(x), Number::Int(y)) => {
            if y == 0 {
                return Err("fmod divisor cannot be zero".to_string());
            }
            Ok(Value::Int(x % y))
        }
        _ => {
            let x = a.as_f64();
            let y = b.as_f64();
            if y == 0.0 {
                return Err("fmod divisor cannot be zero".to_string());
            }
            Ok(Value::Float(x % y))
        }
    }
}

fn math_log(args: &[Value]) -> Result<Value, String> {
    if args.len() != 1 && args.len() != 2 {
        return Err(format!("log expects 1 or 2 arguments, got {}", args.len()));
    }
    let x = number_at(args, 0, "log")?.as_f64();
    if x <= 0.0 {
        return Err("log expects a positive value".to_string());
    }
    if args.len() == 1 {
        Ok(Value::Float(x.ln()))
    } else {
        let base = number_at(args, 1, "log")?.as_f64();
        if base <= 0.0 || (base - 1.0).abs() < f64::EPSILON {
            return Err("log base must be positive and not equal to 1".to_string());
        }
        Ok(Value::Float(x.log(base)))
    }
}

fn math_modf(args: &[Value]) -> Result<Value, String> {
    expect_arity("modf", args, 1)?;
    let x = number_at(args, 0, "modf")?.as_f64();
    let int_part = x.trunc();
    let frac_part = x - int_part;
    Ok(Value::Table(Rc::new(RefCell::new(
        crate::value::TableObject::from_array(vec![
            Value::Float(int_part),
            Value::Float(frac_part),
        ]),
    ))))
}

fn math_round(args: &[Value]) -> Result<Value, String> {
    expect_arity("round", args, 1)?;
    match number_at(args, 0, "round")? {
        Number::Int(n) => Ok(Value::Int(n)),
        Number::Float(f) => Ok(Value::Int(f.round() as i64)),
    }
}

fn math_sqrt(args: &[Value]) -> Result<Value, String> {
    expect_arity("sqrt", args, 1)?;
    let x = number_at(args, 0, "sqrt")?.as_f64();
    if x < 0.0 {
        return Err("sqrt expects a non-negative number".to_string());
    }
    Ok(Value::Float(x.sqrt()))
}

fn math_random(args: &[Value]) -> Result<Value, String> {
    match args.len() {
        0 => Ok(Value::Float(random_unit())),
        1 => {
            let n = number_at(args, 0, "random")?;
            let hi = match n {
                Number::Int(i) => i,
                Number::Float(f) => {
                    if f.fract() != 0.0 {
                        return Err("random upper bound must be an integer".to_string());
                    }
                    f as i64
                }
            };
            if hi < 1 {
                return Err("random upper bound must be >= 1".to_string());
            }
            let span = hi as u64;
            Ok(Value::Int((next_u64() % span) as i64 + 1))
        }
        2 => {
            let lo = to_i64(number_at(args, 0, "random")?, "random lower bound")?;
            let hi = to_i64(number_at(args, 1, "random")?, "random upper bound")?;
            if lo > hi {
                return Err("random expects lower bound <= upper bound".to_string());
            }
            let span = (hi as i128 - lo as i128 + 1) as u128;
            let v = (next_u64() as u128) % span;
            Ok(Value::Int(lo + v as i64))
        }
        _ => Err(format!("random expects 0, 1, or 2 arguments, got {}", args.len())),
    }
}

fn math_randomseed(args: &[Value]) -> Result<Value, String> {
    expect_arity("randomseed", args, 1)?;
    let seed = match number_at(args, 0, "randomseed")? {
        Number::Int(i) => i as u64,
        Number::Float(f) => f.to_bits(),
    };
    RNG_STATE.with(|cell| *cell.borrow_mut() = if seed == 0 { 1 } else { seed });
    Ok(Value::Nil)
}

fn math_tointeger(args: &[Value]) -> Result<Value, String> {
    expect_arity("tointeger", args, 1)?;
    let out = match &args[0] {
        Value::Int(i) => Some(*i),
        Value::Float(f) => {
            if f.is_finite() && f.fract() == 0.0 && *f >= i64::MIN as f64 && *f <= i64::MAX as f64
            {
                Some(*f as i64)
            } else {
                None
            }
        }
        _ => None,
    };
    Ok(out.map(Value::Int).unwrap_or(Value::Nil))
}

fn math_type(args: &[Value]) -> Result<Value, String> {
    expect_arity("type", args, 1)?;
    match args[0] {
        Value::Int(_) => Ok(Value::Str(Rc::new("integer".to_string()))),
        Value::Float(_) => Ok(Value::Str(Rc::new("float".to_string()))),
        _ => Ok(Value::Nil),
    }
}

fn math_ult(args: &[Value]) -> Result<Value, String> {
    expect_arity("ult", args, 2)?;
    let a = to_i64(number_at(args, 0, "ult")?, "ult arg #1")? as u64;
    let b = to_i64(number_at(args, 1, "ult")?, "ult arg #2")? as u64;
    Ok(Value::Bool(a < b))
}

fn math_pow(args: &[Value]) -> Result<Value, String> {
    expect_arity("pow", args, 2)?;
    let base = number_at(args, 0, "pow")?.as_f64();
    let exp = number_at(args, 1, "pow")?.as_f64();
    Ok(Value::Float(base.powf(exp)))
}

fn math_clamp(args: &[Value]) -> Result<Value, String> {
    expect_arity("clamp", args, 3)?;
    let value = number_at(args, 0, "clamp")?.as_f64();
    let min = number_at(args, 1, "clamp")?.as_f64();
    let max = number_at(args, 2, "clamp")?.as_f64();
    if min > max {
        return Err("clamp expects min <= max".to_string());
    }
    Ok(Value::Float(value.clamp(min, max)))
}

fn math_sign(args: &[Value]) -> Result<Value, String> {
    expect_arity("sign", args, 1)?;
    let x = number_at(args, 0, "sign")?.as_f64();
    let out = if x > 0.0 {
        1
    } else if x < 0.0 {
        -1
    } else {
        0
    };
    Ok(Value::Int(out))
}

fn to_i64(n: Number, label: &str) -> Result<i64, String> {
    match n {
        Number::Int(i) => Ok(i),
        Number::Float(f) => {
            if f.fract() != 0.0 || !f.is_finite() || f < i64::MIN as f64 || f > i64::MAX as f64 {
                Err(format!("{label} must be an integer"))
            } else {
                Ok(f as i64)
            }
        }
    }
}

//! Module loader for `import X from "path"`.
//!
//! Each `.sau` (or `.saule`) file becomes a *module*. Loading a module
//! lexes, parses, type-checks, and runs its top-level statements in a fresh
//! environment seeded with the prelude. The set of names declared with
//! `export` is captured and handed back to whoever requested the import.
//!
//! Results are memoised: importing the same file twice reuses the same
//! [`ModuleExports`] (and so the same `Class` / `Function` `Rc`s) instead of
//! re-executing the file. A `loading` set guards against circular imports.

use std::cell::RefCell;
use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::rc::Rc;

use saule_ast::{Decl, Module, Spanned, Stmt};

use crate::env::Environment;
use crate::error::{ImportedDiagnostic, RuntimeError};
use crate::value::Value;

/// The publicly importable surface of a loaded module.
#[derive(Debug, Default, Clone)]
pub struct ModuleExports {
    pub values: HashMap<String, Value>,
}

/// Shared cache of already-loaded modules plus an in-flight set used to
/// detect circular imports.
#[derive(Debug, Default)]
pub struct ModuleLoader {
    cache: HashMap<PathBuf, ModuleExports>,
    loading: HashSet<PathBuf>,
}

impl ModuleLoader {
    pub fn new() -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Self::default()))
    }
}

/// Resolve a `"path"` literal as it appears in an `import ... from "path"`
/// against the importing file's directory. Tries, in order:
///   1. `<dir>/<path>.sau`
///   2. `<dir>/<path>.saule`
///   3. `<dir>/<path>/init.sau`
///   4. `<dir>/<path>/init.saule`
///   5. `<dir>/<path>` (already has an extension)
///
/// Both `/` and `.` are accepted as path separators inside the literal so
/// `"entities/Player"` and `"entities.Player"` both work.
pub fn resolve_import_path(dir: &Path, raw: &str) -> Option<PathBuf> {
    let normalised = raw.replace('.', "/");
    let base = dir.join(&normalised);

    let candidates = [
        base.with_extension("sau"),
        base.with_extension("saule"),
        base.join("init.sau"),
        base.join("init.saule"),
        base.clone(),
    ];

    for candidate in candidates {
        if candidate.is_file() {
            return std::fs::canonicalize(&candidate).ok().or(Some(candidate));
        }
    }
    None
}

/// Load (or return cached) exports for the module at `abs_path`.
///
/// `loader` must be the same `Rc` that lives on the importing environment
/// — newly created child environments for the imported module borrow it so
/// transitive `import` statements share the same cache.
pub fn load_module(
    abs_path: &Path,
    loader: &Rc<RefCell<ModuleLoader>>,
    import_span: std::ops::Range<usize>,
) -> Result<ModuleExports, RuntimeError> {
    if let Some(hit) = loader.borrow().cache.get(abs_path) {
        return Ok(hit.clone());
    }

    if loader.borrow().loading.contains(abs_path) {
        return Err(RuntimeError::ImportError {
            message: format!(
                "circular import detected at `{}`",
                abs_path.display()
            ),
            span: import_span,
        });
    }
    loader.borrow_mut().loading.insert(abs_path.to_path_buf());

    let result = load_module_inner(abs_path, loader, import_span.clone());

    loader.borrow_mut().loading.remove(abs_path);

    let exports = result?;
    loader
        .borrow_mut()
        .cache
        .insert(abs_path.to_path_buf(), exports.clone());
    Ok(exports)
}

fn load_module_inner(
    abs_path: &Path,
    loader: &Rc<RefCell<ModuleLoader>>,
    import_span: std::ops::Range<usize>,
) -> Result<ModuleExports, RuntimeError> {
    let source = std::fs::read_to_string(abs_path).map_err(|e| RuntimeError::ImportError {
        message: format!("could not read `{}`: {e}", abs_path.display()),
        span: import_span.clone(),
    })?;

    let tokens = saule_lexer::Lexer::new(&source)
        .tokenize()
        .map_err(|e| RuntimeError::ImportError {
            message: format!("lex error in `{}`: {e}", abs_path.display()),
            span: import_span.clone(),
        })?;

    let module = saule_parser::parse(tokens).map_err(|e| RuntimeError::ImportError {
        message: format!("parse error in `{}`: {e}", abs_path.display()),
        span: import_span.clone(),
    })?;

    let errors = crate::typeck::check(&module);
    if let Some(first) = errors.into_iter().next() {
        return Err(RuntimeError::ImportError {
            message: format!("type error in `{}`: {first}", abs_path.display()),
            span: import_span,
        });
    }

    let dir = abs_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let env = Environment::with_prelude_and_context(Some(dir), Some(loader.clone()));

    crate::run_in(&module, &env)?;

    Ok(collect_exports(&module, &env))
}

/// Walk the module's top-level declarations and copy out everything that
/// carries `export`. Anything not exported stays private to the module.
fn collect_exports(module: &Module, env: &Rc<RefCell<Environment>>) -> ModuleExports {
    let mut exports = ModuleExports::default();
    for stmt in &module.stmts {
        if let Stmt::Decl(decl) = &stmt.value {
            if let Some(name) = exported_name(&decl.value) {
                if let Some(value) = env.borrow().get(name) {
                    exports.values.insert(name.to_string(), value);
                }
            }
        }
    }
    exports
}

fn exported_name(decl: &Decl) -> Option<&str> {
    match decl {
        Decl::Function {
            exported: true,
            name,
            ..
        }
        | Decl::Class {
            exported: true,
            name,
            ..
        }
        | Decl::Interface {
            exported: true,
            name,
            ..
        }
        | Decl::Enum {
            exported: true,
            name,
            ..
        } => Some(name),
        _ => None,
    }
}

// Silence unused-import lint when `Spanned` re-export is not needed
// (kept here in case future loader paths need explicit span info).
#[allow(dead_code)]
fn _spanned_marker(_: &Spanned<Stmt>) {}

//! Module loader for `import X from "path"`.
//!
//! Each `.sau` (or `.saule`) file becomes a *module*. Loading a module
//! lexes, parses, type-checks, and runs its top-level statements in a fresh
//! environment seeded with the prelude. The set of names declared with
//! `export` is captured and handed back to whoever requested the import.
//!
//! Results are memoised: importing the same file twice reuses the same
//! [`ModuleExports`] (and so the same `Class` / `Function` `Rc`s) instead of
//! re-executing the file. A `loading` set guards against circular imports.

use std::cell::RefCell;
use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::rc::Rc;

use saule_ast::{Decl, Module, Spanned, Stmt};

use crate::env::Environment;
use crate::error::{ImportedDiagnostic, RuntimeError};
use crate::value::Value;

/// The publicly importable surface of a loaded module.
#[derive(Debug, Default, Clone)]
pub struct ModuleExports {
    pub values: HashMap<String, Value>,
}

/// Shared cache of already-loaded modules plus an in-flight set used to
/// detect circular imports.
#[derive(Debug, Default)]
pub struct ModuleLoader {
    cache: HashMap<PathBuf, ModuleExports>,
    loading: HashSet<PathBuf>,
}

impl ModuleLoader {
    pub fn new() -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(Self::default()))
    }
}

/// Resolve a `"path"` literal as it appears in an `import ... from "path"`
/// against the importing file's directory. Tries, in order:
///   1. `<dir>/<path>.sau`
///   2. `<dir>/<path>.saule`
///   3. `<dir>/<path>/init.sau`
///   4. `<dir>/<path>/init.saule`
///   5. `<dir>/<path>` (already has an extension)
///
/// Both `/` and `.` are accepted as path separators inside the literal so
/// `"entities/Player"` and `"entities.Player"` both work.
pub fn resolve_import_path(dir: &Path, raw: &str) -> Option<PathBuf> {
    let normalised = raw.replace('.', "/");
    let base = dir.join(&normalised);

    let candidates = [
        base.with_extension("sau"),
        base.with_extension("saule"),
        base.join("init.sau"),
        base.join("init.saule"),
        base.clone(),
    ];

    for candidate in candidates {
        if candidate.is_file() {
            return std::fs::canonicalize(&candidate).ok().or(Some(candidate));
        }
    }
    None
}

/// Load (or return cached) exports for the module at `abs_path`.
///
/// `loader` must be the same `Rc` that lives on the importing environment
/// — newly created child environments for the imported module borrow it so
/// transitive `import` statements share the same cache.
pub fn load_module(
    abs_path: &Path,
    loader: &Rc<RefCell<ModuleLoader>>,
    import_span: std::ops::Range<usize>,
) -> Result<ModuleExports, RuntimeError> {
    if let Some(hit) = loader.borrow().cache.get(abs_path) {
        return Ok(hit.clone());
    }

    if loader.borrow().loading.contains(abs_path) {
        return Err(RuntimeError::ImportError {
            message: format!(
                "circular import detected at `{}`",
                abs_path.display()
            ),
            span: import_span,
        });
    }
    loader.borrow_mut().loading.insert(abs_path.to_path_buf());

    let result = load_module_inner(abs_path, loader, import_span.clone());

    loader.borrow_mut().loading.remove(abs_path);

    let exports = result?;
    loader
        .borrow_mut()
        .cache
        .insert(abs_path.to_path_buf(), exports.clone());
    Ok(exports)
}

fn load_module_inner(
    abs_path: &Path,
    loader: &Rc<RefCell<ModuleLoader>>,
    import_span: std::ops::Range<usize>,
) -> Result<ModuleExports, RuntimeError> {
    let source = std::fs::read_to_string(abs_path).map_err(|e| RuntimeError::ImportError {
        message: format!("could not read `{}`: {e}", abs_path.display()),
        span: import_span.clone(),
    })?;

    let file_label = abs_path.display().to_string();
    let wrap = |inner: &dyn miette::Diagnostic| RuntimeError::ImportFailed {
        module_label: file_label.clone(),
        import_span: import_span.clone(),
        inner: Box::new(ImportedDiagnostic::from_inner(
            inner,
            file_label.clone(),
            source.clone(),
        )),
    };

    let tokens = saule_lexer::Lexer::new(&source)
        .tokenize()
        .map_err(|e| wrap(&e))?;

    let module = saule_parser::parse(tokens).map_err(|e| wrap(&e))?;

    let errors = crate::typeck::check(&module);
    if let Some(first) = errors.into_iter().next() {
        return Err(wrap(&first));
    }

    let dir = abs_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let env = Environment::with_prelude_and_context(Some(dir), Some(loader.clone()));

    // Runtime errors from the imported module's top-level: wrap them too,
    // *unless* they're already an ImportFailed (transitive import — keep
    // the original to preserve the deepest source attachment).
    crate::run_in(&module, &env).map_err(|e| match e {
        RuntimeError::ImportFailed { .. } => e,
        other => wrap(&other),
    })?;

    Ok(collect_exports(&module, &env))
}

/// Walk the module's top-level declarations and copy out everything that
/// carries `export`. Anything not exported stays private to the module.
fn collect_exports(module: &Module, env: &Rc<RefCell<Environment>>) -> ModuleExports {
    let mut exports = ModuleExports::default();
    for stmt in &module.stmts {
        if let Stmt::Decl(decl) = &stmt.value {
            if let Some(name) = exported_name(&decl.value) {
                if let Some(value) = env.borrow().get(name) {
                    exports.values.insert(name.to_string(), value);
                }
            }
        }
    }
    exports
}

fn exported_name(decl: &Decl) -> Option<&str> {
    match decl {
        Decl::Function {
            exported: true,
            name,
            ..
        }
        | Decl::Class {
            exported: true,
            name,
            ..
        }
        | Decl::Interface {
            exported: true,
            name,
            ..
        }
        | Decl::Enum {
            exported: true,
            name,
            ..
        } => Some(name),
        _ => None,
    }
}

// Silence unused-import lint when `Spanned` re-export is not needed
// (kept here in case future loader paths need explicit span info).
#[allow(dead_code)]
fn _spanned_marker(_: &Spanned<Stmt>) {}

//! Name resolution + a handful of small structural checks bundled into a
//! single AST walker so we don't traverse the tree N times.
//!
//! Emits:
//!
//! * [`SemanticError::UndefinedName`] — a bare ident that isn't in any
//!   lexical scope, isn't a top-level declaration of this module, isn't
//!   an imported name, and isn't in the prelude.
//! * [`SemanticError::AssignToUndeclared`] — an assignment whose LHS
//!   ident isn't in scope (the runtime previously caught these).
//! * [`SemanticError::SelfOutsideClass`] — `self` referenced outside any
//!   method body.
//! * [`SemanticError::SuperOutsideClass`] — `super.x` or `super(...)` used
//!   outside a method.
//! * [`SemanticError::SuperCallOutsideInit`] — `self.super(...)` outside
//!   `init`.
//! * [`SemanticError::MultipleVariadicParams`] /
//!   [`SemanticError::VariadicNotLast`] — declaration-time variadic shape.
//! * [`SemanticError::PositionalAfterNamed`] — argument-list ordering.
//! * [`SemanticError::ForInArity`] — `for v1, v2, v3 in iter` is invalid.
//!
//! ## Scoping
//!
//! Scopes are a stack of `HashSet<String>`. `Stmt::Local` binds into the
//! top frame. Every `if`/`while`/`repeat`/`for`/`try`/match-arm body
//! pushes its own frame so a `local` declared in a then-branch doesn't
//! leak to the else-branch (Lua-style block scoping).
//!
//! Functions, methods, and lambdas push a frame and reset the
//! enclosing-class / `in_init` flags appropriately. Module-level
//! declarations are pre-collected before the walk so forward references
//! to top-level `fn` / `class` / etc. resolve cleanly.
//!
//! ## Wildcard imports
//!
//! `import * from "..."` introduces names this pass cannot enumerate, so
//! when *any* wildcard import is seen the [`UndefinedName`] /
//! [`AssignToUndeclared`] checks become advisory: we still walk the AST
//! for the other diagnostics, but ident lookups that would otherwise fail
//! are silently accepted. Files without a wildcard import get the full
//! treatment.

use std::collections::HashSet;

use saule_ast::{
    CallArg, ClassMember, Decl, Expr, ImportNames, LambdaBody, MatchBody, Method, Module, Param,
    Pattern, Spanned, Stmt, TableEntry,
};

use crate::error::SemanticError;
use crate::prelude;
use crate::to_source_span;

struct Resolver {
    /// Lexical scope stack. The bottom frame is the module scope (top-level
    /// decls + imported names); subsequent frames cover function/method
    /// bodies and blocks.
    scopes: Vec<HashSet<String>>,
    /// Class context for `self` / `super` validity. `None` at module scope.
    in_class: Option<String>,
    /// Are we currently inside the `init` constructor body of a class?
    in_init: bool,
    /// Walking inside any method body (including `init`). `self` is legal,
    /// `super.x` is legal (when a parent exists; we don't check that here),
    /// `self.super(...)` is only legal when also `in_init`.
    in_method: bool,
    /// True when the module contains `import * from "..."`. Suppresses
    /// undefined-name diagnostics since we can't enumerate the imported
    /// names statically.
    has_wildcard_import: bool,
    errors: Vec<SemanticError>,
}

pub(crate) fn check(module: &Module, errors: &mut Vec<SemanticError>) {
    let mut r = Resolver {
        scopes: vec![collect_module_scope(module)],
        in_class: None,
        in_init: false,
        in_method: false,
        has_wildcard_import: module_has_wildcard_import(module),
        errors: Vec::new(),
    };

    for s in &module.stmts {
        r.stmt(s);
    }

    errors.append(&mut r.errors);
}

fn module_has_wildcard_import(module: &Module) -> bool {
    module.stmts.iter().any(|s| {
        matches!(
            &s.value,
            Stmt::Decl(d) if matches!(&d.value, Decl::Import { names: ImportNames::All, .. })
        )
    })
}

/// Pre-collect every name visible at module scope so forward references
/// (e.g. `fn a() b() end` then `fn b() end`) resolve cleanly.
fn collect_module_scope(module: &Module) -> HashSet<String> {
    let mut scope: HashSet<String> = HashSet::new();
    for s in &module.stmts {
        match &s.value {
            Stmt::Local { name, .. } => {
                scope.insert(name.clone());
            }
            Stmt::LocalMulti { names, .. } => {
                for (n, _) in names {
                    scope.insert(n.clone());
                }
            }
            Stmt::Decl(d) => match &d.value {
                Decl::Function { name, .. }
                | Decl::Class { name, .. }
                | Decl::Interface { name, .. }
                | Decl::Enum { name, .. } => {
                    scope.insert(name.clone());
                }
                Decl::Import { names, .. } => match names {
                    ImportNames::All => {}
                    ImportNames::List(items) => {
                        for (orig, alias) in items {
                            scope.insert(alias.clone().unwrap_or_else(|| orig.clone()));
                        }
                    }
                },
            },
            _ => {}
        }
    }
    scope
}

impl Resolver {
    fn push_scope(&mut self) {
        self.scopes.push(HashSet::new());
    }
    fn pop_scope(&mut self) {
        self.scopes.pop();
    }
    fn declare(&mut self, name: &str) {
        if let Some(top) = self.scopes.last_mut() {
            top.insert(name.to_string());
        }
    }
    fn resolved(&self, name: &str) -> bool {
        if self.has_wildcard_import {
            return true;
        }
        if self.scopes.iter().any(|f| f.contains(name)) {
            return true;
        }
        prelude::contains(name)
    }

    // ── Statements ─────────────────────────────────────────────────────────

    fn stmt(&mut self, stmt: &Spanned<Stmt>) {
        match &stmt.value {
            Stmt::Local { name, value, .. } => {
                if let Some(v) = value {
                    self.expr(v);
                }
                self.declare(name);
            }
            Stmt::LocalMulti { names, values } => {
                for v in values {
                    self.expr(v);
                }
                for (n, _) in names {
                    self.declare(n);
                }
            }
            Stmt::Assign { target, value } => {
                if let Expr::Ident(name) = &target.value
                    && !self.resolved(name)
                {
                    self.errors.push(SemanticError::AssignToUndeclared {
                        name: name.clone(),
                        span: to_source_span(target.span.clone()),
                    });
                } else {
                    // Targets other than plain idents go through `expr`
                    // for member/index resolution.
                    if !matches!(target.value, Expr::Ident(_)) {
                        self.expr(target);
                    }
                }
                self.expr(value);
            }
            Stmt::AssignMulti { targets, values } => {
                for v in values {
                    self.expr(v);
                }
                for t in targets {
                    if let Expr::Ident(name) = &t.value {
                        if !self.resolved(name) {
                            self.errors.push(SemanticError::AssignToUndeclared {
                                name: name.clone(),
                                span: to_source_span(t.span.clone()),
                            });
                        }
                    } else {
                        self.expr(t);
                    }
                }
            }
            Stmt::Expr(e) | Stmt::Throw(e) => self.expr(e),

            Stmt::If { cond, then_block, elseifs, else_block } => {
                self.expr(cond);
                self.push_scope();
                self.block(then_block);
                self.pop_scope();
                for (c, b) in elseifs {
                    self.expr(c);
                    self.push_scope();
                    self.block(b);
                    self.pop_scope();
                }
                if let Some(b) = else_block {
                    self.push_scope();
                    self.block(b);
                    self.pop_scope();
                }
            }
            Stmt::While { cond, body } => {
                self.expr(cond);
                self.push_scope();
                self.block(body);
                self.pop_scope();
            }
            Stmt::Repeat { body, cond } => {
                // Lua-style: `until` cond sees locals declared in body, so
                // walk the cond *before* popping.
                self.push_scope();
                self.block(body);
                self.expr(cond);
                self.pop_scope();
            }
            Stmt::ForNumeric { var, from, to, step, body, .. } => {
                self.expr(from);
                self.expr(to);
                if let Some(s) = step {
                    self.expr(s);
                }
                self.push_scope();
                self.declare(var);
                self.block(body);
                self.pop_scope();
            }
            Stmt::ForIn { vars, iter, body } => {
                if vars.is_empty() || vars.len() > 2 {
                    self.errors.push(SemanticError::ForInArity {
                        found: vars.len(),
                        span: to_source_span(stmt.span.clone()),
                    });
                }
                self.expr(iter);
                self.push_scope();
                for (n, _) in vars {
                    self.declare(n);
                }
                self.block(body);
                self.pop_scope();
            }
            Stmt::Return(values) => {
                for v in values {
                    self.expr(v);
                }
            }
            Stmt::Try { body, catch_var, catch_body, .. } => {
                self.push_scope();
                self.block(body);
                self.pop_scope();
                self.push_scope();
                self.declare(catch_var);
                self.block(catch_body);
                self.pop_scope();
            }
            Stmt::Break | Stmt::Continue => {}

            Stmt::Decl(d) => self.decl(&d.value),
        }
    }

    fn block(&mut self, body: &[Spanned<Stmt>]) {
        for s in body {
            self.stmt(s);
        }
    }

    // ── Declarations ───────────────────────────────────────────────────────

    fn decl(&mut self, decl: &Decl) {
        match decl {
            Decl::Function { params, body, .. } => {
                self.check_variadic_shape(params);
                self.enter_function(params, body);
            }
            Decl::Class { name, members, .. } => {
                let prev_class = self.in_class.replace(name.clone());

                // Inside a class's own methods, every static member is
                // reachable by its bare name (mirrors Lua-style `self` for
                // statics). Collect them once so each method body can be
                // walked with that set visible.
                let static_names: Vec<String> = members
                    .iter()
                    .filter_map(|m| match &m.value {
                        ClassMember::Field { is_static: true, name, .. } => Some(name.clone()),
                        ClassMember::Method(meth) if meth.is_static => Some(meth.name.clone()),
                        _ => None,
                    })
                    .collect();

                for m in members {
                    match &m.value {
                        ClassMember::Method(meth) => {
                            self.method(name, meth, &static_names);
                        }
                        ClassMember::Field { default: Some(d), .. } => self.expr(d),
                        ClassMember::Field { .. } => {}
                    }
                }
                self.in_class = prev_class;
            }
            Decl::Enum { methods, .. } => {
                for meth in methods {
                    self.check_variadic_shape(&meth.params);
                    let prev_method = std::mem::replace(&mut self.in_method, true);
                    self.enter_function(&meth.params, &meth.body);
                    self.in_method = prev_method;
                }
            }
            // Interface declarations carry only signatures; no body to walk.
            // Import declarations don't host expressions.
            Decl::Interface { .. } | Decl::Import { .. } => {}
        }
    }

    fn method(&mut self, class_name: &str, meth: &Method, static_names: &[String]) {
        self.check_variadic_shape(&meth.params);
        let prev_method = std::mem::replace(&mut self.in_method, true);
        let prev_init = std::mem::replace(&mut self.in_init, meth.name == "init" && !meth.is_static);

        // Default-value expressions evaluate in the *outer* scope, so walk
        // them before pushing the body frame.
        for p in &meth.params {
            if let Some(d) = &p.default {
                self.expr(d);
            }
        }

        let prev_class = std::mem::replace(&mut self.in_class, Some(class_name.to_string()));
        self.push_scope();
        // Make the class's static members visible by bare name.
        for n in static_names {
            self.declare(n);
        }
        for p in &meth.params {
            self.declare(&p.name);
        }
        self.block(&meth.body);
        self.pop_scope();
        self.in_class = prev_class;

        self.in_init = prev_init;
        self.in_method = prev_method;
    }

    /// Push a fresh function-body scope, declare every param, walk the
    /// body, pop. Used for top-level `Decl::Function` and enum methods.
    fn enter_function(&mut self, params: &[Param], body: &[Spanned<Stmt>]) {
        // Default-value expressions are evaluated in the *outer* scope, so
        // walk them before pushing the body frame.
        for p in params {
            if let Some(d) = &p.default {
                self.expr(d);
            }
        }
        self.push_scope();
        for p in params {
            self.declare(&p.name);
        }
        self.block(body);
        self.pop_scope();
    }

    fn check_variadic_shape(&mut self, params: &[Param]) {
        let variadic_positions: Vec<usize> =
            params.iter().enumerate().filter(|(_, p)| p.variadic).map(|(i, _)| i).collect();

        if variadic_positions.len() > 1 {
            // Report every extra variadic individually.
            for idx in &variadic_positions[1..] {
                self.errors.push(SemanticError::MultipleVariadicParams {
                    span: to_source_span(params[*idx].span.clone()),
                });
            }
        }

        if let Some(&first_var) = variadic_positions.first()
            && first_var + 1 < params.len()
        {
            let p = &params[first_var];
            self.errors.push(SemanticError::VariadicNotLast {
                name: p.name.clone(),
                span: to_source_span(p.span.clone()),
            });
        }
    }

    // ── Expressions ────────────────────────────────────────────────────────

    fn expr(&mut self, expr: &Spanned<Expr>) {
        let span = expr.span.clone();
        match &expr.value {
            Expr::Ident(name) => {
                if !self.resolved(name) {
                    self.errors.push(SemanticError::UndefinedName {
                        name: name.clone(),
                        span: to_source_span(span),
                    });
                }
            }
            Expr::Self_ => {
                if !self.in_method {
                    self.errors.push(SemanticError::SelfOutsideClass {
                        span: to_source_span(span),
                    });
                }
            }
            Expr::Unary { rhs, .. } => self.expr(rhs),
            Expr::Binary { lhs, rhs, .. } => {
                self.expr(lhs);
                self.expr(rhs);
            }
            Expr::Member { obj, name } => {
                self.check_super_receiver(obj, name, &span);
                self.expr(obj);
            }
            Expr::SafeMember { obj, .. } => self.expr(obj),
            Expr::Index { obj, index } => {
                self.expr(obj);
                self.expr(index);
            }
            Expr::Call { callee, args } => {
                self.check_arg_ordering(args);
                self.check_super_call(callee, &span);
                self.expr(callee);
                for a in args {
                    self.call_arg(a);
                }
            }
            Expr::MethodCall { obj, args, .. } => {
                self.check_arg_ordering(args);
                self.expr(obj);
                for a in args {
                    self.call_arg(a);
                }
            }
            Expr::ForceUnwrap(inner) => self.expr(inner),
            Expr::Table(entries) => {
                for e in entries {
                    match e {
                        TableEntry::Positional(v) => self.expr(v),
                        TableEntry::Field { key, value } => {
                            self.expr(key);
                            self.expr(value);
                        }
                    }
                }
            }
            Expr::Lambda { params, body, .. } => {
                self.check_variadic_shape(params);
                // Default exprs evaluated in outer scope.
                for p in params {
                    if let Some(d) = &p.default {
                        self.expr(d);
                    }
                }
                self.push_scope();
                for p in params {
                    self.declare(&p.name);
                }
                match body {
                    LambdaBody::Expr(e) => self.expr(e),
                    LambdaBody::Block(b) => self.block(b),
                }
                self.pop_scope();
            }
            Expr::Match { scrutinee, arms } => {
                self.expr(scrutinee);
                for arm in arms {
                    self.push_scope();
                    self.bind_pattern(&arm.pattern.value);
                    if let Some(g) = &arm.guard {
                        self.expr(g);
                    }
                    match &arm.body {
                        MatchBody::Expr(e) => self.expr(e),
                        MatchBody::Block(b) => self.block(b),
                    }
                    self.pop_scope();
                }
            }
            // Pure literals — nothing to resolve.
            Expr::Int(_) | Expr::Float(_) | Expr::Bool(_) | Expr::Str(_) | Expr::Nil => {}
        }
    }

    fn call_arg(&mut self, a: &CallArg) {
        match a {
            CallArg::Positional(e) | CallArg::Named { value: e, .. } => self.expr(e),
        }
    }

    fn check_arg_ordering(&mut self, args: &[CallArg]) {
        let mut seen_named = false;
        for a in args {
            match a {
                CallArg::Named { .. } => seen_named = true,
                CallArg::Positional(e) if seen_named => {
                    self.errors.push(SemanticError::PositionalAfterNamed {
                        span: to_source_span(e.span.clone()),
                    });
                    break;
                }
                CallArg::Positional(_) => {}
            }
        }
    }

    /// Catch `super.x` outside a method (otherwise valid super uses are
    /// further validated when paired with a Call in `check_super_call`).
    fn check_super_receiver(
        &mut self,
        obj: &Spanned<Expr>,
        _name: &str,
        span: &std::ops::Range<usize>,
    ) {
        if let Expr::Ident(n) = &obj.value
            && n == "super"
            && !self.in_method
        {
            self.errors.push(SemanticError::SuperOutsideClass {
                span: to_source_span(span.clone()),
            });
        }
    }

    /// `self.super(...)` parses as `Call { callee: Member { obj: Self_, name: "super" }, .. }`.
    /// Only legal inside an `init` body of a subclass — we check the
    /// `in_init` flag here; the "subclass" half is left to the runtime
    /// since this pass doesn't know parent-class info.
    fn check_super_call(&mut self, callee: &Spanned<Expr>, span: &std::ops::Range<usize>) {
        if let Expr::Member { obj, name } = &callee.value
            && name == "super"
            && matches!(obj.value, Expr::Self_)
            && !self.in_init
        {
            self.errors.push(SemanticError::SuperCallOutsideInit {
                span: to_source_span(span.clone()),
            });
        }
    }

    // ── Patterns ───────────────────────────────────────────────────────────

    fn bind_pattern(&mut self, p: &Pattern) {
        match p {
            Pattern::Bind(name) => self.declare(name),
            Pattern::Variant { fields, .. } => {
                for sub in fields {
                    self.bind_pattern(&sub.value);
                }
            }
            Pattern::Tuple(elems) => {
                for sub in elems {
                    self.bind_pattern(&sub.value);
                }
            }
            // Wildcards & literals bind nothing.
            Pattern::Wildcard
            | Pattern::Nil
            | Pattern::Int(_)
            | Pattern::Float(_)
            | Pattern::Bool(_)
            | Pattern::Str(_) => {}
        }
    }
}

//! Name resolution + a handful of small structural checks bundled into a
//! single AST walker so we don't traverse the tree N times.
//!
//! Emits:
//!
//! * [`SemanticError::UndefinedName`] — a bare ident that isn't in any
//!   lexical scope, isn't a top-level declaration of this module, isn't
//!   an imported name, and isn't in the prelude.
//! * [`SemanticError::AssignToUndeclared`] — an assignment whose LHS
//!   ident isn't in scope (the runtime previously caught these).
//! * [`SemanticError::SelfOutsideClass`] — `self` referenced outside any
//!   method body.
//! * [`SemanticError::SuperOutsideClass`] — `super.x` or `super(...)` used
//!   outside a method.
//! * [`SemanticError::SuperCallOutsideInit`] — `self.super(...)` outside
//!   `init`.
//! * [`SemanticError::MultipleVariadicParams`] /
//!   [`SemanticError::VariadicNotLast`] — declaration-time variadic shape.
//! * [`SemanticError::PositionalAfterNamed`] — argument-list ordering.
//! * [`SemanticError::ForInArity`] — `for v1, v2, v3 in iter` is invalid.
//!
//! ## Scoping
//!
//! Scopes are a stack of `HashSet<String>`. `Stmt::Local` binds into the
//! top frame. Every `if`/`while`/`repeat`/`for`/`try`/match-arm body
//! pushes its own frame so a `local` declared in a then-branch doesn't
//! leak to the else-branch (Lua-style block scoping).
//!
//! Functions, methods, and lambdas push a frame and reset the
//! enclosing-class / `in_init` flags appropriately. Module-level
//! declarations are pre-collected before the walk so forward references
//! to top-level `fn` / `class` / etc. resolve cleanly.
//!
//! ## Wildcard imports
//!
//! `import * from "..."` introduces names this pass cannot enumerate, so
//! when *any* wildcard import is seen the [`UndefinedName`] /
//! [`AssignToUndeclared`] checks become advisory: we still walk the AST
//! for the other diagnostics, but ident lookups that would otherwise fail
//! are silently accepted. Files without a wildcard import get the full
//! treatment.

use std::collections::HashSet;

use saule_ast::{
    CallArg, ClassMember, Decl, Expr, ImportNames, LambdaBody, MatchBody, Method, Module, Param,
    Pattern, Spanned, Stmt, TableEntry,
};

use crate::error::SemanticError;
use crate::prelude;
use crate::to_source_span;

struct Resolver {
    /// Lexical scope stack. The bottom frame is the module scope (top-level
    /// decls + imported names); subsequent frames cover function/method
    /// bodies and blocks.
    scopes: Vec<HashSet<String>>,
    /// Class context for `self` / `super` validity. `None` at module scope.
    in_class: Option<String>,
    /// Are we currently inside the `init` constructor body of a class?
    in_init: bool,
    /// Walking inside any method body (including `init`). `self` is legal,
    /// `super.x` is legal (when a parent exists; we don't check that here),
    /// `self.super(...)` is only legal when also `in_init`.
    in_method: bool,
    /// True when the module contains `import * from "..."`. Suppresses
    /// undefined-name diagnostics since we can't enumerate the imported
    /// names statically.
    has_wildcard_import: bool,
    errors: Vec<SemanticError>,
}

pub(crate) fn check(module: &Module, errors: &mut Vec<SemanticError>) {
    let mut r = Resolver {
        scopes: vec![collect_module_scope(module)],
        in_class: None,
        in_init: false,
        in_method: false,
        has_wildcard_import: module_has_wildcard_import(module),
        errors: Vec::new(),
    };

    for s in &module.stmts {
        r.stmt(s);
    }

    errors.append(&mut r.errors);
}

fn module_has_wildcard_import(module: &Module) -> bool {
    module.stmts.iter().any(|s| {
        matches!(
            &s.value,
            Stmt::Decl(d) if matches!(&d.value, Decl::Import { names: ImportNames::All, .. })
        )
    })
}

/// Pre-collect every name visible at module scope so forward references
/// (e.g. `fn a() b() end` then `fn b() end`) resolve cleanly.
fn collect_module_scope(module: &Module) -> HashSet<String> {
    let mut scope: HashSet<String> = HashSet::new();
    for s in &module.stmts {
        match &s.value {
            Stmt::Local { name, .. } => {
                scope.insert(name.clone());
            }
            Stmt::LocalMulti { names, .. } => {
                for (n, _) in names {
                    scope.insert(n.clone());
                }
            }
            Stmt::Decl(d) => match &d.value {
                Decl::Function { name, .. }
                | Decl::Class { name, .. }
                | Decl::Interface { name, .. }
                | Decl::Enum { name, .. } => {
                    scope.insert(name.clone());
                }
                Decl::Import { names, .. } => match names {
                    ImportNames::All => {}
                    ImportNames::List(items) => {
                        for (orig, alias) in items {
                            scope.insert(alias.clone().unwrap_or_else(|| orig.clone()));
                        }
                    }
                },
            },
            _ => {}
        }
    }
    scope
}

impl Resolver {
    fn push_scope(&mut self) {
        self.scopes.push(HashSet::new());
    }
    fn pop_scope(&mut self) {
        self.scopes.pop();
    }
    fn declare(&mut self, name: &str) {
        if let Some(top) = self.scopes.last_mut() {
            top.insert(name.to_string());
        }
    }
    fn resolved(&self, name: &str) -> bool {
        if self.has_wildcard_import {
            return true;
        }
        if self.scopes.iter().any(|f| f.contains(name)) {
            return true;
        }
        prelude::contains(name)
    }

    // ── Statements ─────────────────────────────────────────────────────────

    fn stmt(&mut self, stmt: &Spanned<Stmt>) {
        match &stmt.value {
            Stmt::Local { name, value, .. } => {
                if let Some(v) = value {
                    self.expr(v);
                }
                self.declare(name);
            }
            Stmt::LocalMulti { names, values } => {
                for v in values {
                    self.expr(v);
                }
                for (n, _) in names {
                    self.declare(n);
                }
            }
            Stmt::Assign { target, value } => {
                if let Expr::Ident(name) = &target.value
                    && !self.resolved(name)
                {
                    self.errors.push(SemanticError::AssignToUndeclared {
                        name: name.clone(),
                        span: to_source_span(target.span.clone()),
                    });
                } else {
                    // Targets other than plain idents go through `expr`
                    // for member/index resolution.
                    if !matches!(target.value, Expr::Ident(_)) {
                        self.expr(target);
                    }
                }
                self.expr(value);
            }
            Stmt::AssignMulti { targets, values } => {
                for v in values {
                    self.expr(v);
                }
                for t in targets {
                    if let Expr::Ident(name) = &t.value {
                        if !self.resolved(name) {
                            self.errors.push(SemanticError::AssignToUndeclared {
                                name: name.clone(),
                                span: to_source_span(t.span.clone()),
                            });
                        }
                    } else {
                        self.expr(t);
                    }
                }
            }
            Stmt::Expr(e) | Stmt::Throw(e) => self.expr(e),

            Stmt::If { cond, then_block, elseifs, else_block } => {
                self.expr(cond);
                self.push_scope();
                self.block(then_block);
                self.pop_scope();
                for (c, b) in elseifs {
                    self.expr(c);
                    self.push_scope();
                    self.block(b);
                    self.pop_scope();
                }
                if let Some(b) = else_block {
                    self.push_scope();
                    self.block(b);
                    self.pop_scope();
                }
            }
            Stmt::While { cond, body } => {
                self.expr(cond);
                self.push_scope();
                self.block(body);
                self.pop_scope();
            }
            Stmt::Repeat { body, cond } => {
                // Lua-style: `until` cond sees locals declared in body, so
                // walk the cond *before* popping.
                self.push_scope();
                self.block(body);
                self.expr(cond);
                self.pop_scope();
            }
            Stmt::ForNumeric { var, from, to, step, body, .. } => {
                self.expr(from);
                self.expr(to);
                if let Some(s) = step {
                    self.expr(s);
                }
                self.push_scope();
                self.declare(var);
                self.block(body);
                self.pop_scope();
            }
            Stmt::ForIn { vars, iter, body } => {
                if vars.is_empty() || vars.len() > 2 {
                    self.errors.push(SemanticError::ForInArity {
                        found: vars.len(),
                        span: to_source_span(stmt.span.clone()),
                    });
                }
                self.expr(iter);
                self.push_scope();
                for (n, _) in vars {
                    self.declare(n);
                }
                self.block(body);
                self.pop_scope();
            }
            Stmt::Return(values) => {
                for v in values {
                    self.expr(v);
                }
            }
            Stmt::Try { body, catch_var, catch_body, .. } => {
                self.push_scope();
                self.block(body);
                self.pop_scope();
                self.push_scope();
                self.declare(catch_var);
                self.block(catch_body);
                self.pop_scope();
            }
            Stmt::Break | Stmt::Continue => {}

            Stmt::Decl(d) => self.decl(&d.value),
        }
    }

    fn block(&mut self, body: &[Spanned<Stmt>]) {
        for s in body {
            self.stmt(s);
        }
    }

    // ── Declarations ───────────────────────────────────────────────────────

    fn decl(&mut self, decl: &Decl) {
        match decl {
            Decl::Function { params, body, .. } => {
                self.check_variadic_shape(params);
                self.enter_function(params, body);
            }
            Decl::Class { name, members, .. } => {
                let prev_class = self.in_class.replace(name.clone());

                // Inside a class's own methods, every static member is
                // reachable by its bare name (mirrors Lua-style `self` for
                // statics). Collect them once so each method body can be
                // walked with that set visible.
                let static_names: Vec<String> = members
                    .iter()
                    .filter_map(|m| match &m.value {
                        ClassMember::Field { is_static: true, name, .. } => Some(name.clone()),
                        ClassMember::Method(meth) if meth.is_static => Some(meth.name.clone()),
                        _ => None,
                    })
                    .collect();

                for m in members {
                    match &m.value {
                        ClassMember::Method(meth) => {
                            self.method(name, meth, &static_names);
                        }
                        ClassMember::Field { default: Some(d), .. } => self.expr(d),
                        ClassMember::Field { .. } => {}
                    }
                }
                self.in_class = prev_class;
            }
            Decl::Enum { methods, .. } => {
                for meth in methods {
                    self.check_variadic_shape(&meth.params);
                    let prev_method = std::mem::replace(&mut self.in_method, true);
                    self.enter_function(&meth.params, &meth.body);
                    self.in_method = prev_method;
                }
            }
            // Interface declarations carry only signatures; no body to walk.
            // Import declarations don't host expressions.
            Decl::Interface { .. } | Decl::Import { .. } => {}
        }
    }

    fn method(&mut self, class_name: &str, meth: &Method, static_names: &[String]) {
        self.check_variadic_shape(&meth.params);
        let prev_method = std::mem::replace(&mut self.in_method, true);
        let prev_init = std::mem::replace(&mut self.in_init, meth.name == "init" && !meth.is_static);

        // Default-value expressions evaluate in the *outer* scope, so walk
        // them before pushing the body frame.
        for p in &meth.params {
            if let Some(d) = &p.default {
                self.expr(d);
            }
        }

        let prev_class = std::mem::replace(&mut self.in_class, Some(class_name.to_string()));
        self.push_scope();
        // Make the class's static members visible by bare name.
        for n in static_names {
            self.declare(n);
        }
        for p in &meth.params {
            self.declare(&p.name);
        }
        self.block(&meth.body);
        self.pop_scope();
        self.in_class = prev_class;

        self.in_init = prev_init;
        self.in_method = prev_method;
    }

    /// Push a fresh function-body scope, declare every param, walk the
    /// body, pop. Used for top-level `Decl::Function` and enum methods.
    fn enter_function(&mut self, params: &[Param], body: &[Spanned<Stmt>]) {
        // Default-value expressions are evaluated in the *outer* scope, so
        // walk them before pushing the body frame.
        for p in params {
            if let Some(d) = &p.default {
                self.expr(d);
            }
        }
        self.push_scope();
        for p in params {
            self.declare(&p.name);
        }
        self.block(body);
        self.pop_scope();
    }

    fn check_variadic_shape(&mut self, params: &[Param]) {
        let variadic_positions: Vec<usize> =
            params.iter().enumerate().filter(|(_, p)| p.variadic).map(|(i, _)| i).collect();

        if variadic_positions.len() > 1 {
            // Report every extra variadic individually.
            for idx in &variadic_positions[1..] {
                self.errors.push(SemanticError::MultipleVariadicParams {
                    span: to_source_span(params[*idx].span.clone()),
                });
            }
        }

        if let Some(&first_var) = variadic_positions.first()
            && first_var + 1 < params.len()
        {
            let p = &params[first_var];
            self.errors.push(SemanticError::VariadicNotLast {
                name: p.name.clone(),
                span: to_source_span(p.span.clone()),
            });
        }
    }

    // ── Expressions ────────────────────────────────────────────────────────

    fn expr(&mut self, expr: &Spanned<Expr>) {
        let span = expr.span.clone();
        match &expr.value {
            Expr::Ident(name) => {
                if !self.resolved(name) {
                    self.errors.push(SemanticError::UndefinedName {
                        name: name.clone(),
                        span: to_source_span(span),
                    });
                }
            }
            Expr::Self_ => {
                if !self.in_method {
                    self.errors.push(SemanticError::SelfOutsideClass {
                        span: to_source_span(span),
                    });
                }
            }
            Expr::Unary { rhs, .. } => self.expr(rhs),
            Expr::Binary { lhs, rhs, .. } => {
                self.expr(lhs);
                self.expr(rhs);
            }
            Expr::Member { obj, name } => {
                self.check_super_receiver(obj, name, &span);
                self.expr(obj);
            }
            Expr::SafeMember { obj, .. } => self.expr(obj),
            Expr::Index { obj, index } => {
                self.expr(obj);
                self.expr(index);
            }
            Expr::Call { callee, args } => {
                self.check_arg_ordering(args);
                self.check_super_call(callee, &span);
                self.expr(callee);
                for a in args {
                    self.call_arg(a);
                }
            }
            Expr::MethodCall { obj, args, .. } => {
                self.check_arg_ordering(args);
                self.expr(obj);
                for a in args {
                    self.call_arg(a);
                }
            }
            Expr::ForceUnwrap(inner) => self.expr(inner),
            Expr::Table(entries) => {
                for e in entries {
                    match e {
                        TableEntry::Positional(v) => self.expr(v),
                        TableEntry::Field { key, value } => {
                            self.expr(key);
                            self.expr(value);
                        }
                    }
                }
            }
            Expr::Lambda { params, body, .. } => {
                self.check_variadic_shape(params);
                // Default exprs evaluated in outer scope.
                for p in params {
                    if let Some(d) = &p.default {
                        self.expr(d);
                    }
                }
                self.push_scope();
                for p in params {
                    self.declare(&p.name);
                }
                match body {
                    LambdaBody::Expr(e) => self.expr(e),
                    LambdaBody::Block(b) => self.block(b),
                }
                self.pop_scope();
            }
            Expr::Match { scrutinee, arms } => {
                self.expr(scrutinee);
                for arm in arms {
                    self.push_scope();
                    self.bind_pattern(&arm.pattern.value);
                    if let Some(g) = &arm.guard {
                        self.expr(g);
                    }
                    match &arm.body {
                        MatchBody::Expr(e) => self.expr(e),
                        MatchBody::Block(b) => self.block(b),
                    }
                    self.pop_scope();
                }
            }
            // `when(source):stage1(args):stage2(args)…` — resolve the
            // source like a normal expression, then treat every stage
            // function name as an identifier lookup at its own span so
            // typos surface as `UndefinedName`. Stage args are checked
            // for ordering (positionals before named) just like a regular
            // call.
            Expr::Pipe { source, stages } => {
                self.expr(source);
                for stage in stages {
                    self.check_arg_ordering(&stage.args);
                    self.resolve_ident_use(&stage.name, &stage.span);
                    for a in &stage.args {
                        self.call_arg(a);
                    }
                }
            }
            // Pure literals — nothing to resolve.
            Expr::Int(_) | Expr::Float(_) | Expr::Bool(_) | Expr::Str(_) | Expr::Nil => {}
        }
    }

    fn call_arg(&mut self, a: &CallArg) {
        match a {
            CallArg::Positional(e) | CallArg::Named { value: e, .. } => self.expr(e),
        }
    }

    fn check_arg_ordering(&mut self, args: &[CallArg]) {
        let mut seen_named = false;
        for a in args {
            match a {
                CallArg::Named { .. } => seen_named = true,
                CallArg::Positional(e) if seen_named => {
                    self.errors.push(SemanticError::PositionalAfterNamed {
                        span: to_source_span(e.span.clone()),
                    });
                    break;
                }
                CallArg::Positional(_) => {}
            }
        }
    }

    /// Catch `super.x` outside a method (otherwise valid super uses are
    /// further validated when paired with a Call in `check_super_call`).
    fn check_super_receiver(
        &mut self,
        obj: &Spanned<Expr>,
        _name: &str,
        span: &std::ops::Range<usize>,
    ) {
        if let Expr::Ident(n) = &obj.value
            && n == "super"
            && !self.in_method
        {
            self.errors.push(SemanticError::SuperOutsideClass {
                span: to_source_span(span.clone()),
            });
        }
    }

    /// `self.super(...)` parses as `Call { callee: Member { obj: Self_, name: "super" }, .. }`.
    /// Only legal inside an `init` body of a subclass — we check the
    /// `in_init` flag here; the "subclass" half is left to the runtime
    /// since this pass doesn't know parent-class info.
    fn check_super_call(&mut self, callee: &Spanned<Expr>, span: &std::ops::Range<usize>) {
        if let Expr::Member { obj, name } = &callee.value
            && name == "super"
            && matches!(obj.value, Expr::Self_)
            && !self.in_init
        {
            self.errors.push(SemanticError::SuperCallOutsideInit {
                span: to_source_span(span.clone()),
            });
        }
    }

    // ── Patterns ───────────────────────────────────────────────────────────

    fn bind_pattern(&mut self, p: &Pattern) {
        match p {
            Pattern::Bind(name) => self.declare(name),
            Pattern::Variant { fields, .. } => {
                for sub in fields {
                    self.bind_pattern(&sub.value);
                }
            }
            Pattern::Tuple(elems) => {
                for sub in elems {
                    self.bind_pattern(&sub.value);
                }
            }
            // Wildcards & literals bind nothing.
            Pattern::Wildcard
            | Pattern::Nil
            | Pattern::Int(_)
            | Pattern::Float(_)
            | Pattern::Bool(_)
            | Pattern::Str(_) => {}
        }
    }
}

//! Static signatures for native (Rust-implemented) functions.
//!
//! The runtime's `NativeFn` / `NativeClosure` values carry only a `name` and
//! a callable — no type information. The typechecker can't inspect a Rust
//! closure, so we maintain a side-table mapping qualified names like
//! `"String.byte"` or bare names like `"assert"` to their declared signatures.
//!
//! Each `stdlib::*::install` function registers the signatures of the natives
//! it defines. The typechecker (`crate::expr`) consults [`lookup`] for
//! `Expr::Call` where the callee resolves to a bare ident or a `Class.method`
//! pair, so writing `local n: integer = String.byte("a")` produces the same
//! `NullableToNonNullable` diagnostic as a user-defined function returning
//! `integer?`.
//!
//! ## Embedder responsibility
//!
//! Because this crate doesn't link the stdlib, embedders must install an
//! initializer via [`set_initializer`]. The hook fires lazily on the first
//! [`lookup`] call (per thread) so the runtime's stdlib registration only
//! runs when actually needed. If no initializer is set, [`lookup`] returns
//! `None` and the typechecker conservatively skips the call site.

use std::cell::{Cell, RefCell};
use std::collections::HashMap;

use saule_ast::Type;

/// A native function's static signature.
#[derive(Clone, Debug)]
pub struct NativeSig {
    /// Declared positional parameter types.
    pub params: Vec<Type>,
    /// Type of additional trailing arguments. `Some(T)` makes the call
    /// variadic — every extra positional arg must be a `T`. `None` means
    /// exactly `params.len()` positional args are allowed (callers may also
    /// pass fewer if the missing slots are nullable / `any`).
    pub variadic: Option<Type>,
    /// Declared return types. `len() == 1` for single-return functions;
    /// `len() > 1` for multi-return (surfaced as `Type::Tuple` to callers).
    pub returns: Vec<Type>,
}

thread_local! {
    static SIGS: RefCell<HashMap<String, NativeSig>> = RefCell::new(HashMap::new());
    static INIT_DONE: Cell<bool> = const { Cell::new(false) };
    static INITIALIZER: Cell<Option<fn()>> = const { Cell::new(None) };
}

/// Register `name -> sig`. Overwrites silently — the embedder's initializer
/// is run at most once per thread.
pub fn register(name: &str, params: Vec<Type>, returns: Vec<Type>) {
    SIGS.with(|s| {
        s.borrow_mut().insert(
            name.to_string(),
            NativeSig { params, variadic: None, returns },
        );
    });
}

/// Register a variadic native: any extra trailing positional args must match
/// `variadic`. Use for `printf(fmt, ...)`, `String.char(...integer)`, etc.
pub fn register_v(name: &str, params: Vec<Type>, variadic: Type, returns: Vec<Type>) {
    SIGS.with(|s| {
        s.borrow_mut().insert(
            name.to_string(),
            NativeSig { params, variadic: Some(variadic), returns },
        );
    });
}

/// Install the initializer the embedder wants to run lazily on first
/// [`lookup`]. Typically called once at startup by the interpreter so its
/// stdlib signatures appear in the registry before any type-check pass.
///
/// Calling this after the initializer has already fired has no effect on the
/// current registration but will run the *new* initializer on the next
/// fresh thread.
pub fn set_initializer(f: fn()) {
    INITIALIZER.with(|s| s.set(Some(f)));
}

/// Look up by qualified (`"String.byte"`) or bare (`"assert"`) name.
///
/// Returns `None` when the name isn't registered — the typechecker treats
/// that as "unknown call" and skips signature-based checks rather than
/// emitting a false positive.
pub fn lookup(name: &str) -> Option<NativeSig> {
    ensure_registered();
    SIGS.with(|s| s.borrow().get(name).cloned())
}

fn ensure_registered() {
    if INIT_DONE.with(Cell::get) {
        return;
    }
    INIT_DONE.with(|d| d.set(true));
    if let Some(f) = INITIALIZER.with(Cell::get) {
        f();
    }
}

// ─── Type-builder shorthands for callers ────────────────────────────────────

pub fn t_named(s: &str) -> Type {
    Type::Named(s.to_string())
}

pub fn t_any() -> Type {
    Type::Named("any".to_string())
}

/// Sentinel meaning "either `integer` or `float`". Recognised by
/// `crate::expr::types_compatible`. Use for math/numeric natives.
pub fn t_number() -> Type {
    Type::Named("number".to_string())
}

pub fn t_nullable(inner: Type) -> Type {
    Type::Nullable(Box::new(inner))
}

pub fn t_table(value: Type) -> Type {
    Type::Table { key: None, value: Box::new(value) }
}

pub fn t_table_map(key: Type, value: Type) -> Type {
    Type::Table { key: Some(Box::new(key)), value: Box::new(value) }
}

pub fn t_function(params: Vec<Type>, ret: Type) -> Type {
    Type::Function { params, ret: Box::new(ret) }
}

//! Static signatures for native (Rust-implemented) functions.
//!
//! The runtime's `NativeFn` / `NativeClosure` values carry only a `name` and
//! a callable — no type information. The typechecker can't inspect a Rust
//! closure, so we maintain a side-table mapping qualified names like
//! `"String.byte"` or bare names like `"assert"` to their declared signatures.
//!
//! Each `stdlib::*::install` function registers the signatures of the natives
//! it defines. The typechecker (`crate::expr`) consults [`lookup`] for
//! `Expr::Call` where the callee resolves to a bare ident or a `Class.method`
//! pair, so writing `local n: integer = String.byte("a")` produces the same
//! `NullableToNonNullable` diagnostic as a user-defined function returning
//! `integer?`.
//!
//! ## Embedder responsibility
//!
//! Because this crate doesn't link the stdlib, embedders must install an
//! initializer via [`set_initializer`]. The hook fires lazily on the first
//! [`lookup`] call (per thread) so the runtime's stdlib registration only
//! runs when actually needed. If no initializer is set, [`lookup`] returns
//! `None` and the typechecker conservatively skips the call site.

use std::cell::{Cell, RefCell};
use std::collections::HashMap;
use std::sync::OnceLock;

use saule_ast::Type;

/// A native function's static signature.
#[derive(Clone, Debug)]
pub struct NativeSig {
    /// Declared positional parameter types.
    pub params: Vec<Type>,
    /// Type of additional trailing arguments. `Some(T)` makes the call
    /// variadic — every extra positional arg must be a `T`. `None` means
    /// exactly `params.len()` positional args are allowed (callers may also
    /// pass fewer if the missing slots are nullable / `any`).
    pub variadic: Option<Type>,
    /// Declared return types. `len() == 1` for single-return functions;
    /// `len() > 1` for multi-return (surfaced as `Type::Tuple` to callers).
    pub returns: Vec<Type>,
}

/// Process-global initializer slot. Set once by the embedder.
static INITIALIZER: OnceLock<fn()> = OnceLock::new();

thread_local! {
    static SIGS: RefCell<HashMap<String, NativeSig>> = RefCell::new(HashMap::new());
    static INIT_DONE: Cell<bool> = const { Cell::new(false) };
}

/// Register `name -> sig`. Overwrites silently — the embedder's initializer
/// is run at most once per thread.
pub fn register(name: &str, params: Vec<Type>, returns: Vec<Type>) {
    SIGS.with(|s| {
        s.borrow_mut().insert(
            name.to_string(),
            NativeSig { params, variadic: None, returns },
        );
    });
}

/// Register a variadic native: any extra trailing positional args must match
/// `variadic`. Use for `printf(fmt, ...)`, `String.char(...integer)`, etc.
pub fn register_v(name: &str, params: Vec<Type>, variadic: Type, returns: Vec<Type>) {
    SIGS.with(|s| {
        s.borrow_mut().insert(
            name.to_string(),
            NativeSig { params, variadic: Some(variadic), returns },
        );
