//! Statement & declaration walker. Threads a [`Scope`](super::state::Scope)
//! so we know the static type of every `local` seen on the current path, and
//! so narrowing in `if`/`else` can override types for the duration of a
//! sub-block.

use saule_ast::{ClassMember, Decl, Expr, Param, Spanned, Stmt, Type};

use super::TypeCheckError;
use super::expr::{
    check_assignment_compat, check_boolean_cond, check_element_compat, check_expr,
    check_table_key_compat, infer, is_nullable, narrow_falsy, narrow_truthy, strip_nullable,
    type_to_string,
};
use super::state::{
    Scope, class_implements_iterable, is_interface, is_type_param, pop_generics, push_generics,
    set_current_class, with_classes,
};
use super::to_source_span;

/// Reject `nil` used as a binding type. `nil` is a value (the inhabitant
/// of the unit type), and nullability is expressed with `T?` — so any
/// occurrence of `nil` inside a binding/parameter/field type is a
/// foot-gun the typechecker should call out. Return types are *not*
/// validated here: `fn foo() -> nil` is the conventional "returns
/// nothing" signature.
pub(super) fn reject_nil_in_binding_type(
    ty: &Type,
    span: std::ops::Range<usize>,
    errors: &mut Vec<TypeCheckError>,
) {
    fn walk(ty: &Type) -> bool {
        match ty {
            Type::Named(n) => n == "nil",
            Type::Nullable(inner) => walk(inner),
            Type::Table { key, value } => {
                key.as_deref().map(walk).unwrap_or(false) || walk(value)
            }
            Type::Tuple(items) => items.iter().any(walk),
            Type::Function { params, ret } => {
                params.iter().any(walk) || walk(ret)
            }
        }
    }
    if walk(ty) {
        errors.push(TypeCheckError::NilTypeAnnotation {
            span: to_source_span(span),
        });
    }
}

/// Run [`reject_nil_in_binding_type`] over every parameter's declared type.
fn reject_nil_in_params(params: &[Param], errors: &mut Vec<TypeCheckError>) {
    for p in params {
        reject_nil_in_binding_type(&p.ty, p.span.clone(), errors);
    }
}


pub(super) fn check_stmt(
    stmt: &Spanned<Stmt>,
    scope: &mut Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    match &stmt.value {
        Stmt::Decl(decl) => check_decl(&decl.value, errors),

        Stmt::Local { name, ty, value } => {
            if let Some(t) = ty {
                reject_nil_in_binding_type(t, stmt.span.clone(), errors);
            }
            if let (Some(ty), Some(v)) = (ty, value) {
                check_expr(v, scope, errors);
                check_assignment_compat(ty, v, scope, errors);
                scope.bind(name.clone(), ty.clone());
            } else if let Some(v) = value {
                check_expr(v, scope, errors);
                if let Some(t) = infer(v, scope) {
                    scope.bind(name.clone(), t);
                }
            } else if let Some(ty) = ty {
                // `local x: T` with no initializer is implicitly `nil`.
                // Reject when `T` isn't nullable so the user has to either
                // mark the type `T?` or supply a value up front.
                if !is_nullable(ty) {
                    errors.push(TypeCheckError::NilToNonNullable {
                        ty: type_to_string(ty),
                        span: to_source_span(stmt.span.clone()),
                    });
                }
                scope.bind(name.clone(), ty.clone());
            }
        }

        Stmt::LocalMulti { names, values } => {
            for (_, ty_opt) in names {
                if let Some(t) = ty_opt {
                    reject_nil_in_binding_type(t, stmt.span.clone(), errors);
                }
            }
            for v in values {
                check_expr(v, scope, errors);
            }
            for (i, (name, ty_opt)) in names.iter().enumerate() {
                if let (Some(ty), Some(v)) = (ty_opt, values.get(i)) {
                    check_assignment_compat(ty, v, scope, errors);
                }
                if let Some(ty) = ty_opt {
                    scope.bind(name.clone(), ty.clone());
                } else if let Some(v) = values.get(i)
                    && let Some(t) = infer(v, scope)
                {
                    scope.bind(name.clone(), t);
                }
            }
        }

        Stmt::Assign { target, value } => {
            check_expr(target, scope, errors);
            check_expr(value, scope, errors);
            if let Expr::Ident(n) = &target.value
                && let Some(ty) = scope.lookup(n).cloned()
            {
                check_assignment_compat(&ty, value, scope, errors);
            }
            // `t[k] = v` — enforce the table's static key/value types.
            if let Expr::Index { obj, index } = &target.value
                && let Some(Type::Table { key, value: elem_ty }) = infer(obj, scope)
            {
                let key_ty = key
                    .as_deref()
                    .cloned()
                    .unwrap_or_else(|| Type::Named("integer".into()));
                check_table_key_compat(&key_ty, index, scope, errors);
                check_element_compat(&elem_ty, value, scope, errors);
            }
            // `obj.field = v` — only class instances and class statics support
            // dotted-field assignment. Catches `tbl.foo = ...` on plain
            // tables, where `tbl["foo"] = ...` is the intended form, before
            // it blows up at runtime.
            if let Expr::Member { obj, name } = &target.value {
                check_member_assign_receiver(obj, name, target.span.clone(), scope, errors);
            }
        }

        Stmt::AssignMulti { targets, values } => {
            for t in targets {
                check_expr(t, scope, errors);
            }
            for v in values {
                check_expr(v, scope, errors);
            }
            for (i, target) in targets.iter().enumerate() {
                if let Expr::Ident(n) = &target.value
                    && let (Some(ty), Some(v)) = (scope.lookup(n).cloned(), values.get(i))
                {
                    check_assignment_compat(&ty, v, scope, errors);
                }
            }
        }

        Stmt::Expr(e) => check_expr(e, scope, errors),

        Stmt::If {
            cond,
            then_block,
            elseifs,
            else_block,
        } => {
            check_expr(cond, scope, errors);
            check_boolean_cond("if", cond, scope, errors);

            // Branch the scope so narrowing in the then-block doesn't leak.
            let mut then_scope = scope.clone();
            narrow_truthy(cond, &mut then_scope);
            for s in then_block {
                check_stmt(s, &mut then_scope, errors);
            }

            for (econd, ebody) in elseifs {
                check_expr(econd, scope, errors);
                check_boolean_cond("elseif", econd, scope, errors);
                let mut ei_scope = scope.clone();
                narrow_truthy(econd, &mut ei_scope);
                for s in ebody {
                    check_stmt(s, &mut ei_scope, errors);
                }
            }

            if let Some(block) = else_block {
                let mut else_scope = scope.clone();
                narrow_falsy(cond, &mut else_scope);
                for s in block {
                    check_stmt(s, &mut else_scope, errors);
                }
            }
        }

        Stmt::While { cond, body } | Stmt::Repeat { body, cond } => {
            check_expr(cond, scope, errors);
            check_boolean_cond(
                if matches!(stmt.value, Stmt::While { .. }) {
                    "while"
                } else {
                    "until"
                },
                cond,
                scope,
                errors,
            );
            let mut body_scope = scope.clone();
            narrow_truthy(cond, &mut body_scope);
            for s in body {
                check_stmt(s, &mut body_scope, errors);
            }
        }

        Stmt::ForNumeric {
            var,
            var_ty,
            from,
            to,
            step,
            body,
        } => {
            if let Some(t) = var_ty {
                reject_nil_in_binding_type(t, stmt.span.clone(), errors);
            }
            check_expr(from, scope, errors);
            check_expr(to, scope, errors);
            if let Some(s) = step {
                check_expr(s, scope, errors);
            }
            let mut body_scope = scope.clone();
            let ty = var_ty.clone().unwrap_or(Type::Named("integer".into()));
            body_scope.bind(var.clone(), ty);
            for s in body {
                check_stmt(s, &mut body_scope, errors);
            }
        }

        Stmt::ForIn { vars, iter, body } => {
            for (_, ty_opt) in vars {
                if let Some(t) = ty_opt {
                    reject_nil_in_binding_type(t, stmt.span.clone(), errors);
                }
            }
            check_expr(iter, scope, errors);
            // If the iter expression is a known class instance, it must
            // implement `Iterable` or `Iterable2` (walking the parent chain).
            if let Some(Type::Named(class_name)) = infer(iter, scope)
                && with_classes(|reg| reg.contains_key(&class_name))
                && !class_implements_iterable(&class_name)
            {
                errors.push(TypeCheckError::NotIterable {
                    class: class_name,
                    span: to_source_span(iter.span.clone()),
                });
            }
            let mut body_scope = scope.clone();
            for (name, ty_opt) in vars {
                if let Some(ty) = ty_opt {
                    body_scope.bind(name.clone(), ty.clone());
                }
            }
            for s in body {
                check_stmt(s, &mut body_scope, errors);
            }
        }

        Stmt::Return(values) => {
            for v in values {
                check_expr(v, scope, errors);
            }
        }

        Stmt::Throw(e) => check_expr(e, scope, errors),

        Stmt::Try {
            body,
            catch_var,
            catch_ty,
            catch_body,
        } => {
            reject_nil_in_binding_type(catch_ty, stmt.span.clone(), errors);
            let mut body_scope = scope.clone();
            for s in body {
                check_stmt(s, &mut body_scope, errors);
            }
            let mut catch_scope = scope.clone();
            catch_scope.bind(catch_var.clone(), catch_ty.clone());
            for s in catch_body {
                check_stmt(s, &mut catch_scope, errors);
            }
        }

        Stmt::Break | Stmt::Continue => {}
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Declaration walker.
// ──────────────────────────────────────────────────────────────────────────────

fn check_decl(decl: &Decl, errors: &mut Vec<TypeCheckError>) {
    match decl {
        Decl::Class {
            name: class_name,
            extends,
            implements,
            members,
            ..
        } => {
            // Validate the class hierarchy: every name in `extends` /
            // `implements` must refer to a real class / interface that
            // semantic has already collected into the registry.
            if let Some(parent) = extends
                && !with_classes(|r| r.contains_key(parent))
            {
                // Point the diagnostic at the first member span — class
                // span isn't readily available here; tweaking the AST to
                // carry it is left for a follow-up.
                let span = members
                    .first()
                    .map(|m| m.span.clone())
                    .unwrap_or(0..0);
                errors.push(TypeCheckError::UnknownParentClass {
                    name: class_name.clone(),
                    parent: parent.clone(),
                    span: to_source_span(span),
                });
            }
            for iface in implements {
                if !is_interface(iface) {
                    let span = members
                        .first()
                        .map(|m| m.span.clone())
                        .unwrap_or(0..0);
                    errors.push(TypeCheckError::UnknownInterface {
                        name: class_name.clone(),
                        iface: iface.clone(),
                        span: to_source_span(span),
                    });
                }
            }
            check_class(class_name, members, errors)
        }
        Decl::Function {
            type_params,
            params,
            return_ty,
            body,
            ..
        } => {
            reject_nil_in_params(params, errors);
            let prev_generics = push_generics(type_params);
            let mut scope = Scope::default();
            check_default_params(params, &scope, errors);
            seed_params(&mut scope, params);
            for s in body {
                check_stmt(s, &mut scope, errors);
            }
            if let Some(rt) = return_ty {
                check_returns(body, rt, &scope, errors);
            }
            pop_generics(prev_generics);
        }
        _ => {}
    }
}

pub(super) fn seed_params(scope: &mut Scope, params: &[Param]) {
    for p in params {
        scope.bind(p.name.clone(), p.ty.clone());
    }
}

/// Check each parameter default against the declared parameter type.
fn check_default_params(params: &[Param], scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    for p in params {
        if let Some(d) = &p.default
            && !is_assignment_compatible(&p.ty, d, scope)
        {
            errors.push(TypeCheckError::DefaultParamTypeMismatch {
                param: p.name.clone(),
                ty: type_to_string(&p.ty),
                span: to_source_span(d.span.clone()),
            });
        }
    }
}

/// Walk a function/method body looking for `return v` statements whose first
/// value can be proved incompatible with `return_ty`.
fn check_returns(
    body: &[Spanned<Stmt>],
    return_ty: &Type,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    for s in body {
        walk_returns(&s.value, return_ty, scope, errors);
    }
}

fn walk_returns(
    stmt: &Stmt,
    return_ty: &Type,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    match stmt {
        Stmt::Return(values) => {
            if let Some(v) = values.first()
                && !is_assignment_compatible(return_ty, v, scope)
            {
                errors.push(TypeCheckError::WrongReturnType {
                    ty: type_to_string(return_ty),
                    span: to_source_span(v.span.clone()),
                });
            }
        }
        Stmt::If {
            then_block,
            elseifs,
            else_block,
            ..
        } => {
            for s in then_block {
                walk_returns(&s.value, return_ty, scope, errors);
            }
            for (_, b) in elseifs {
                for s in b {
                    walk_returns(&s.value, return_ty, scope, errors);
                }
            }
            if let Some(b) = else_block {
                for s in b {
                    walk_returns(&s.value, return_ty, scope, errors);
                }
            }
        }
        Stmt::While { body, .. }
        | Stmt::Repeat { body, .. }
        | Stmt::ForNumeric { body, .. }
        | Stmt::ForIn { body, .. } => {
            for s in body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
        }
        Stmt::Try {
            body, catch_body, ..
        } => {
            for s in body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
            for s in catch_body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
        }
        _ => {}
    }
}

/// True when we can *prove* the value is incompatible-free with the target
/// type. Returns true when we can't decide (conservative: don't false-positive).
fn is_assignment_compatible(decl_ty: &Type, value: &Spanned<Expr>, scope: &Scope) -> bool {
    if is_nullable(decl_ty) {
        // Nullable target accepts anything we can express.
        return true;
    }
    if matches!(value.value, Expr::Nil) {
        return false;
    }
    let Some(value_ty) = infer(value, scope) else {
        return true;
    };
    if is_nullable(&value_ty) {
        return false;
    }
    match (decl_ty, &value_ty) {
        (Type::Named(a), Type::Named(b)) => {
            if a == b || a == "any" || b == "any" {
                true
            } else if is_type_param(a) || is_type_param(b) {
                // Generic type parameters in scope match anything.
                true
            } else {
                // Allow numeric literals in either direction only when same name.
                false
            }
        }
        _ => true,
    }
}

fn check_class(
    class_name: &str,
    members: &[Spanned<ClassMember>],
    errors: &mut Vec<TypeCheckError>,
) {
    // Validate field defaults: `local x: string = nil` is an error regardless
    // of whether a constructor exists or the field is static. (Definite
    // assignment of constructor-set fields lives in `saule-semantic`.)
    for m in members {
        if let ClassMember::Field {
            ty,
            default: Some(default_expr),
            ..
        } = &m.value
        {
            let scope = Scope::default();
            check_assignment_compat(ty, default_expr, &scope, errors);
        }
    }


    // Walk every method body with a scope seeded from its parameters,
    // and within `CURRENT_CLASS` set so private-member checks know we're
    // *inside* `class_name`. Also validate default parameters and return types.
    let prev = set_current_class(Some(class_name.to_string()));
    for m in members {
        if let ClassMember::Method(meth) = &m.value {
            let prev_generics = push_generics(&meth.type_params);
            let mut scope = Scope::default();
            // `self` resolves to the class itself in `static fn` and to an
            // instance otherwise. Seed it as the class name so member-existence
            // checks on `self.foo` consult the class registry.
            scope.bind("self".to_string(), Type::Named(class_name.to_string()));
            check_default_params(&meth.params, &scope, errors);
            seed_params(&mut scope, &meth.params);
            for s in &meth.body {
                check_stmt(s, &mut scope, errors);
            }
            if let Some(rt) = &meth.return_ty {
                check_returns(&meth.body, rt, &scope, errors);
            }
            pop_generics(prev_generics);
        }
    }
    set_current_class(prev);
}

/// Verify that `obj.name = ...` is being written to a receiver that
/// actually supports field assignment. Class instances and class statics
/// do; plain tables, primitives, and functions don't.
fn check_member_assign_receiver(
    obj: &Spanned<Expr>,
    name: &str,
    span: std::ops::Range<usize>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    // `self.foo = ...` and `super.foo = ...` are always fine inside a method;
    // the resolver / runtime own that path.
    if matches!(obj.value, Expr::Self_) {
        return;
    }
    // `Class.foo = ...` (static-field assignment) — receiver is a known class.
    if let Expr::Ident(n) = &obj.value
        && with_classes(|reg| reg.contains_key(n))
    {
        return;
    }
    // Otherwise infer the receiver's type. We can only complain when we
    // actually know it; an unknown type silently passes so dynamic `any`
    // code still works.
    let Some(ty) = infer(obj, scope) else { return };
    let stripped = strip_nullable(ty.clone());
    // Lua-style tables let `t.foo = v` mean `t["foo"] = v`, so anything
    // shaped like a table is allowed through. Reject only the truly
    // field-less primitives / functions.
    let bad = match &stripped {
        Type::Named(n) => matches!(
            n.as_str(),
            "integer" | "float" | "number" | "boolean" | "string" | "function"
        ),
        Type::Tuple(_) | Type::Function { .. } => true,
        _ => false,
    };
    if bad {
        errors.push(TypeCheckError::InvalidFieldAssign {
            receiver: type_to_string(&stripped),
            member: name.to_string(),
            span: super::to_source_span(span),
        });
    }
}

//! Statement & declaration walker. Threads a [`Scope`](super::state::Scope)
//! so we know the static type of every `local` seen on the current path, and
//! so narrowing in `if`/`else` can override types for the duration of a
//! sub-block.

use saule_ast::{ClassMember, Decl, Expr, Param, Spanned, Stmt, Type};

use super::TypeCheckError;
use super::expr::{
    check_assignment_compat, check_boolean_cond, check_element_compat, check_expr,
    check_table_key_compat, infer, is_nullable, narrow_falsy, narrow_truthy, strip_nullable,
    type_to_string,
};
use super::state::{
    Scope, class_implements_iterable, is_interface, is_type_param, pop_generics, push_generics,
    set_current_class, with_classes,
};
use super::to_source_span;

/// Reject `nil` used as a binding type. `nil` is a value (the inhabitant
/// of the unit type), and nullability is expressed with `T?` — so any
/// occurrence of `nil` inside a binding/parameter/field type is a
/// foot-gun the typechecker should call out. Return types are *not*
/// validated here: `fn foo() -> nil` is the conventional "returns
/// nothing" signature.
pub(super) fn reject_nil_in_binding_type(
    ty: &Type,
    span: std::ops::Range<usize>,
    errors: &mut Vec<TypeCheckError>,
) {
    fn walk(ty: &Type) -> bool {
        match ty {
            Type::Named(n) => n == "nil",
            Type::Nullable(inner) => walk(inner),
            Type::Table { key, value } => {
                key.as_deref().map(walk).unwrap_or(false) || walk(value)
            }
            Type::Tuple(items) => items.iter().any(walk),
            Type::Function { params, ret } => {
                params.iter().any(walk) || walk(ret)
            }
        }
    }
    if walk(ty) {
        errors.push(TypeCheckError::NilTypeAnnotation {
            span: to_source_span(span),
        });
    }
}

/// Run [`reject_nil_in_binding_type`] over every parameter's declared type.
fn reject_nil_in_params(params: &[Param], errors: &mut Vec<TypeCheckError>) {
    for p in params {
        reject_nil_in_binding_type(&p.ty, p.span.clone(), errors);
    }
}


pub(super) fn check_stmt(
    stmt: &Spanned<Stmt>,
    scope: &mut Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    match &stmt.value {
        Stmt::Decl(decl) => check_decl(&decl.value, errors),

        Stmt::Local { name, ty, value } => {
            if let Some(t) = ty {
                reject_nil_in_binding_type(t, stmt.span.clone(), errors);
            }
            if let (Some(ty), Some(v)) = (ty, value) {
                check_expr(v, scope, errors);
                check_assignment_compat(ty, v, scope, errors);
                scope.bind(name.clone(), ty.clone());
            } else if let Some(v) = value {
                check_expr(v, scope, errors);
                if let Some(t) = infer(v, scope) {
                    scope.bind(name.clone(), t);
                }
            } else if let Some(ty) = ty {
                // `local x: T` with no initializer is implicitly `nil`.
                // Reject when `T` isn't nullable so the user has to either
                // mark the type `T?` or supply a value up front.
                if !is_nullable(ty) {
                    errors.push(TypeCheckError::NilToNonNullable {
                        ty: type_to_string(ty),
                        span: to_source_span(stmt.span.clone()),
                    });
                }
                scope.bind(name.clone(), ty.clone());
            }
        }

        Stmt::LocalMulti { names, values } => {
            for (_, ty_opt) in names {
                if let Some(t) = ty_opt {
                    reject_nil_in_binding_type(t, stmt.span.clone(), errors);
                }
            }
            for v in values {
                check_expr(v, scope, errors);
            }
            for (i, (name, ty_opt)) in names.iter().enumerate() {
                if let (Some(ty), Some(v)) = (ty_opt, values.get(i)) {
                    check_assignment_compat(ty, v, scope, errors);
                }
                if let Some(ty) = ty_opt {
                    scope.bind(name.clone(), ty.clone());
                } else if let Some(v) = values.get(i)
                    && let Some(t) = infer(v, scope)
                {
                    scope.bind(name.clone(), t);
                }
            }
        }

        Stmt::Assign { target, value } => {
            check_expr(target, scope, errors);
            check_expr(value, scope, errors);
            if let Expr::Ident(n) = &target.value
                && let Some(ty) = scope.lookup(n).cloned()
            {
                check_assignment_compat(&ty, value, scope, errors);
            }
            // `t[k] = v` — enforce the table's static key/value types.
            if let Expr::Index { obj, index } = &target.value
                && let Some(Type::Table { key, value: elem_ty }) = infer(obj, scope)
            {
                let key_ty = key
                    .as_deref()
                    .cloned()
                    .unwrap_or_else(|| Type::Named("integer".into()));
                check_table_key_compat(&key_ty, index, scope, errors);
                check_element_compat(&elem_ty, value, scope, errors);
            }
            // `obj.field = v` — only class instances and class statics support
            // dotted-field assignment. Catches `tbl.foo = ...` on plain
            // tables, where `tbl["foo"] = ...` is the intended form, before
            // it blows up at runtime.
            if let Expr::Member { obj, name } = &target.value {
                check_member_assign_receiver(obj, name, target.span.clone(), scope, errors);
            }
        }

        Stmt::AssignMulti { targets, values } => {
            for t in targets {
                check_expr(t, scope, errors);
            }
            for v in values {
                check_expr(v, scope, errors);
            }
            for (i, target) in targets.iter().enumerate() {
                if let Expr::Ident(n) = &target.value
                    && let (Some(ty), Some(v)) = (scope.lookup(n).cloned(), values.get(i))
                {
                    check_assignment_compat(&ty, v, scope, errors);
                }
            }
        }

        Stmt::Expr(e) => check_expr(e, scope, errors),

        Stmt::If {
            cond,
            then_block,
            elseifs,
            else_block,
        } => {
            check_expr(cond, scope, errors);
            check_boolean_cond("if", cond, scope, errors);

            // Branch the scope so narrowing in the then-block doesn't leak.
            let mut then_scope = scope.clone();
            narrow_truthy(cond, &mut then_scope);
            for s in then_block {
                check_stmt(s, &mut then_scope, errors);
            }

            for (econd, ebody) in elseifs {
                check_expr(econd, scope, errors);
                check_boolean_cond("elseif", econd, scope, errors);
                let mut ei_scope = scope.clone();
                narrow_truthy(econd, &mut ei_scope);
                for s in ebody {
                    check_stmt(s, &mut ei_scope, errors);
                }
            }

            if let Some(block) = else_block {
                let mut else_scope = scope.clone();
                narrow_falsy(cond, &mut else_scope);
                for s in block {
                    check_stmt(s, &mut else_scope, errors);
                }
            }
        }

        Stmt::While { cond, body } | Stmt::Repeat { body, cond } => {
            check_expr(cond, scope, errors);
            check_boolean_cond(
                if matches!(stmt.value, Stmt::While { .. }) {
                    "while"
                } else {
                    "until"
                },
                cond,
                scope,
                errors,
            );
            let mut body_scope = scope.clone();
            narrow_truthy(cond, &mut body_scope);
            for s in body {
                check_stmt(s, &mut body_scope, errors);
            }
        }

        Stmt::ForNumeric {
            var,
            var_ty,
            from,
            to,
            step,
            body,
        } => {
            if let Some(t) = var_ty {
                reject_nil_in_binding_type(t, stmt.span.clone(), errors);
            }
            check_expr(from, scope, errors);
            check_expr(to, scope, errors);
            if let Some(s) = step {
                check_expr(s, scope, errors);
            }
            let mut body_scope = scope.clone();
            let ty = var_ty.clone().unwrap_or(Type::Named("integer".into()));
            body_scope.bind(var.clone(), ty);
            for s in body {
                check_stmt(s, &mut body_scope, errors);
            }
        }

        Stmt::ForIn { vars, iter, body } => {
            for (_, ty_opt) in vars {
                if let Some(t) = ty_opt {
                    reject_nil_in_binding_type(t, stmt.span.clone(), errors);
                }
            }
            check_expr(iter, scope, errors);
            // If the iter expression is a known class instance, it must
            // implement `Iterable` or `Iterable2` (walking the parent chain).
            if let Some(Type::Named(class_name)) = infer(iter, scope)
                && with_classes(|reg| reg.contains_key(&class_name))
                && !class_implements_iterable(&class_name)
            {
                errors.push(TypeCheckError::NotIterable {
                    class: class_name,
                    span: to_source_span(iter.span.clone()),
                });
            }
            let mut body_scope = scope.clone();
            for (name, ty_opt) in vars {
                if let Some(ty) = ty_opt {
                    body_scope.bind(name.clone(), ty.clone());
                }
            }
            for s in body {
                check_stmt(s, &mut body_scope, errors);
            }
        }

        Stmt::Return(values) => {
            for v in values {
                check_expr(v, scope, errors);
            }
        }

        Stmt::Throw(e) => check_expr(e, scope, errors),

        Stmt::Try {
            body,
            catch_var,
            catch_ty,
            catch_body,
        } => {
            reject_nil_in_binding_type(catch_ty, stmt.span.clone(), errors);
            let mut body_scope = scope.clone();
            for s in body {
                check_stmt(s, &mut body_scope, errors);
            }
            let mut catch_scope = scope.clone();
            catch_scope.bind(catch_var.clone(), catch_ty.clone());
            for s in catch_body {
                check_stmt(s, &mut catch_scope, errors);
            }
        }

        Stmt::Break | Stmt::Continue => {}
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Declaration walker.
// ──────────────────────────────────────────────────────────────────────────────

fn check_decl(decl: &Decl, errors: &mut Vec<TypeCheckError>) {
    match decl {
        Decl::Class {
            name: class_name,
            extends,
            implements,
            members,
            ..
        } => {
            // Validate the class hierarchy: every name in `extends` /
            // `implements` must refer to a real class / interface that
            // semantic has already collected into the registry.
            if let Some(parent) = extends
                && !with_classes(|r| r.contains_key(parent))
            {
                // Point the diagnostic at the first member span — class
                // span isn't readily available here; tweaking the AST to
                // carry it is left for a follow-up.
                let span = members
                    .first()
                    .map(|m| m.span.clone())
                    .unwrap_or(0..0);
                errors.push(TypeCheckError::UnknownParentClass {
                    name: class_name.clone(),
                    parent: parent.clone(),
                    span: to_source_span(span),
                });
            }
            for iface in implements {
                if !is_interface(iface) {
                    let span = members
                        .first()
                        .map(|m| m.span.clone())
                        .unwrap_or(0..0);
                    errors.push(TypeCheckError::UnknownInterface {
                        name: class_name.clone(),
                        iface: iface.clone(),
                        span: to_source_span(span),
                    });
                }
            }
            check_class(class_name, members, errors)
        }
        Decl::Function {
            type_params,
            params,
            return_ty,
            body,
            ..
        } => {
            reject_nil_in_params(params, errors);
            let prev_generics = push_generics(type_params);
            let mut scope = Scope::default();
            check_default_params(params, &scope, errors);
            seed_params(&mut scope, params);
            for s in body {
                check_stmt(s, &mut scope, errors);
            }
            if let Some(rt) = return_ty {
                check_returns(body, rt, &scope, errors);
            }
            pop_generics(prev_generics);
        }
        _ => {}
    }
}

pub(super) fn seed_params(scope: &mut Scope, params: &[Param]) {
    for p in params {
        scope.bind(p.name.clone(), p.ty.clone());
    }
}

/// Check each parameter default against the declared parameter type.
fn check_default_params(params: &[Param], scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    for p in params {
        if let Some(d) = &p.default
            && !is_assignment_compatible(&p.ty, d, scope)
        {
            errors.push(TypeCheckError::DefaultParamTypeMismatch {
                param: p.name.clone(),
                ty: type_to_string(&p.ty),
                span: to_source_span(d.span.clone()),
            });
        }
    }
}

/// Walk a function/method body looking for `return v` statements whose first
/// value can be proved incompatible with `return_ty`.
fn check_returns(
    body: &[Spanned<Stmt>],
    return_ty: &Type,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    for s in body {
        walk_returns(&s.value, return_ty, scope, errors);
    }
}

fn walk_returns(
    stmt: &Stmt,
    return_ty: &Type,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    match stmt {
        Stmt::Return(values) => {
            if let Some(v) = values.first()
                && !is_assignment_compatible(return_ty, v, scope)
            {
                errors.push(TypeCheckError::WrongReturnType {
                    ty: type_to_string(return_ty),
                    span: to_source_span(v.span.clone()),
                });
            }
        }
        Stmt::If {
            then_block,
            elseifs,
            else_block,
            ..
        } => {
            for s in then_block {
                walk_returns(&s.value, return_ty, scope, errors);
            }
            for (_, b) in elseifs {
                for s in b {
                    walk_returns(&s.value, return_ty, scope, errors);
                }
            }
            if let Some(b) = else_block {
                for s in b {
                    walk_returns(&s.value, return_ty, scope, errors);
                }
            }
        }
        Stmt::While { body, .. }
        | Stmt::Repeat { body, .. }
        | Stmt::ForNumeric { body, .. }
        | Stmt::ForIn { body, .. } => {
            for s in body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
        }
        Stmt::Try {
            body, catch_body, ..
        } => {
            for s in body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
            for s in catch_body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
        }
        _ => {}
    }
}

/// True when we can *prove* the value is incompatible-free with the target
/// type. Returns true when we can't decide (conservative: don't false-positive).
fn is_assignment_compatible(decl_ty: &Type, value: &Spanned<Expr>, scope: &Scope) -> bool {
    if is_nullable(decl_ty) {
        // Nullable target accepts anything we can express.
        return true;
    }
    if matches!(value.value, Expr::Nil) {
        return false;
    }
    let Some(value_ty) = infer(value, scope) else {
        return true;
    };
    if is_nullable(&value_ty) {
        return false;
    }
    match (decl_ty, &value_ty) {
        (Type::Named(a), Type::Named(b)) => {
            if a == b || a == "any" || b == "any" {
                true
            } else if is_type_param(a) || is_type_param(b) {
                // Generic type parameters in scope match anything.
                true
            } else {
                // Allow numeric literals in either direction only when same name.
                false
            }
        }
        _ => true,
    }
}

fn check_class(
    class_name: &str,
    members: &[Spanned<ClassMember>],
    errors: &mut Vec<TypeCheckError>,
) {
    // Validate field defaults: `local x: string = nil` is an error regardless
    // of whether a constructor exists or the field is static. (Definite
    // assignment of constructor-set fields lives in `saule-semantic`.)
    for m in members {
        if let ClassMember::Field {
            ty,
            default,
            ..
        } = &m.value
        {
            reject_nil_in_binding_type(ty, m.span.clone(), errors);
            if let Some(default_expr) = default {
                let scope = Scope::default();
                check_assignment_compat(ty, default_expr, &scope, errors);
            }
        }
    }


    // Walk every method body with a scope seeded from its parameters,
    // and within `CURRENT_CLASS` set so private-member checks know we're
    // *inside* `class_name`. Also validate default parameters and return types.
    let prev = set_current_class(Some(class_name.to_string()));
    for m in members {
        if let ClassMember::Method(meth) = &m.value {
            let prev_generics = push_generics(&meth.type_params);
            let mut scope = Scope::default();
            // `self` resolves to the class itself in `static fn` and to an
            // instance otherwise. Seed it as the class name so member-existence
            // checks on `self.foo` consult the class registry.
            scope.bind("self".to_string(), Type::Named(class_name.to_string()));
            check_default_params(&meth.params, &scope, errors);
            seed_params(&mut scope, &meth.params);
            for s in &meth.body {
                check_stmt(s, &mut scope, errors);
            }
            if let Some(rt) = &meth.return_ty {
                check_returns(&meth.body, rt, &scope, errors);
            }
            pop_generics(prev_generics);
        }
    }
    set_current_class(prev);
}

/// Verify that `obj.name = ...` is being written to a receiver that
/// actually supports field assignment. Class instances and class statics
/// do; plain tables, primitives, and functions don't.
fn check_member_assign_receiver(
    obj: &Spanned<Expr>,
    name: &str,
    span: std::ops::Range<usize>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    // `self.foo = ...` and `super.foo = ...` are always fine inside a method;
    // the resolver / runtime own that path.
    if matches!(obj.value, Expr::Self_) {
        return;
    }
    // `Class.foo = ...` (static-field assignment) — receiver is a known class.
    if let Expr::Ident(n) = &obj.value
        && with_classes(|reg| reg.contains_key(n))
    {
        return;
    }
    // Otherwise infer the receiver's type. We can only complain when we
    // actually know it; an unknown type silently passes so dynamic `any`
    // code still works.
    let Some(ty) = infer(obj, scope) else { return };
    let stripped = strip_nullable(ty.clone());
    // Lua-style tables let `t.foo = v` mean `t["foo"] = v`, so anything
    // shaped like a table is allowed through. Reject only the truly
    // field-less primitives / functions.
    let bad = match &stripped {
        Type::Named(n) => matches!(
            n.as_str(),
            "integer" | "float" | "number" | "boolean" | "string" | "function"
        ),
        Type::Tuple(_) | Type::Function { .. } => true,
        _ => false,
    };
    if bad {
        errors.push(TypeCheckError::InvalidFieldAssign {
            receiver: type_to_string(&stripped),
            member: name.to_string(),
            span: super::to_source_span(span),
        });
    }
}

//! String standard library — exposed as the static class `String`.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use crate::env::Environment;
use crate::stdlib::{expect_arity, expect_min_arity};
use crate::value::{ClassObject, NativeClosure, Value};

pub fn install(env: &Rc<RefCell<Environment>>) {
    let mut static_fields = HashMap::new();
    static_fields.insert("byte".to_string(),   native("String.byte",   str_byte));
    static_fields.insert("char".to_string(),   native("String.char",   str_char));
    static_fields.insert("format".to_string(), native("String.format", str_format));
    static_fields.insert("len".to_string(),    native("String.len",    str_len));
    static_fields.insert("sub".to_string(),    native("String.sub",    str_sub));
    static_fields.insert("rep".to_string(),    native("String.rep",    str_rep));
    static_fields.insert("starts".to_string(), native("String.starts", str_starts));
    static_fields.insert("ends".to_string(),   native("String.ends",   str_ends));
    static_fields.insert("find".to_string(),   native_multi("String.find", str_find));
    static_fields.insert("lower".to_string(),  native("String.lower",  str_lower));
    static_fields.insert("upper".to_string(),  native("String.upper",  str_upper));
    static_fields.insert("iter".to_string(),   native("String.iter",   str_iter));

    let class = ClassObject {
        name: "String".to_string(),
        parent: None,
        field_defs: Vec::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(static_fields),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("String".to_string(), Value::Class(Rc::new(class)));

    // Static signatures consulted by the typechecker.
    use crate::stdlib::sigs::{register, t_named, t_nullable};
    let s   = || t_named("string");
    let i   = || t_named("integer");
    let b   = || t_named("boolean");
    let any = || t_named("any");
    register("String.byte",   vec![s(), t_nullable(i())],         vec![t_nullable(i())]);
    register("String.char",   vec![],                              vec![s()]);
    register("String.format", vec![s()],                           vec![s()]);
    register("String.len",    vec![s()],                           vec![i()]);
    register("String.sub",    vec![s(), i(), t_nullable(i())],     vec![s()]);
    register("String.rep",    vec![s(), i()],                      vec![s()]);
    register("String.starts", vec![s(), s()],                      vec![b()]);
    register("String.ends",   vec![s(), s()],                      vec![b()]);
    register("String.find",   vec![s(), s(), t_nullable(i())],     vec![t_nullable(i()), t_nullable(i())]);
    register("String.lower",  vec![s()],                           vec![s()]);
    register("String.upper",  vec![s()],                           vec![s()]);
    register("String.iter",   vec![s()],                           vec![any()]);  // returns a step closure
}

fn native(name: &'static str, func: fn(&[Value]) -> Result<Value, String>) -> Value {
    Value::Native(Rc::new(crate::value::NativeFn { name, func }))
}

/// Wrap a multi-return native function as a `NativeClosure` so the call
/// site can destructure `local a, b = f(...)`.
fn native_multi(
    name: &'static str,
    func: fn(&[Value]) -> Result<Vec<Value>, String>,
) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name,
        func: Box::new(move |args| func(args)),
    }))
}

// ─── helpers ────────────────────────────────────────────────────────────────

fn expect_string(name: &str, args: &[Value], idx: usize) -> Result<String, String> {
    match args.get(idx) {
        Some(Value::Str(s)) => Ok((**s).clone()),
        Some(other) => Err(format!(
            "{name} expects a string at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

fn expect_int(name: &str, args: &[Value], idx: usize) -> Result<i64, String> {
    match args.get(idx) {
        Some(Value::Int(i)) => Ok(*i),
        Some(other) => Err(format!(
            "{name} expects an integer at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

// Lua-style 1-based index with negative-from-end. Clamps to `[1, len]`. The
// returned value is a 0-based byte offset suitable for slicing the `chars`
// vector (so it's "1-based char index minus 1").
fn resolve_index(i: i64, char_count: usize) -> usize {
    let n = char_count as i64;
    let idx = if i < 0 { n + i + 1 } else { i };
    if idx < 1 {
        0
    } else if idx > n {
        char_count
    } else {
        (idx - 1) as usize
    }
}

// ─── functions ──────────────────────────────────────────────────────────────

fn str_byte(args: &[Value]) -> Result<Value, String> {
    expect_min_arity("String.byte", args, 1)?;
    let s = expect_string("String.byte", args, 0)?;
    let chars: Vec<char> = s.chars().collect();
    let pos: i64 = if args.len() >= 2 {
        expect_int("String.byte", args, 1)?
    } else {
        1
    };
    if pos < 1 || (pos as usize) > chars.len() {
        return Ok(Value::Nil);
    }
    let c = chars[(pos as usize) - 1];
    Ok(Value::Int(c as i64))
}

fn str_char(args: &[Value]) -> Result<Value, String> {
    let mut out = String::with_capacity(args.len());
    for (i, arg) in args.iter().enumerate() {
        let code = match arg {
            Value::Int(n) => *n,
            other => {
                return Err(format!(
                    "String.char expects integer arguments, got `{}` at argument {}",
                    other.type_name(),
                    i + 1
                ));
            }
        };
        let Some(c) = u32::try_from(code).ok().and_then(char::from_u32) else {
            return Err(format!(
                "String.char: code {code} at argument {} is not a valid character",
                i + 1
            ));
        };
        out.push(c);
    }
    Ok(Value::Str(Rc::new(out)))
}

fn str_len(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.len", args, 1)?;
    let s = expect_string("String.len", args, 0)?;
    Ok(Value::Int(s.chars().count() as i64))
}

fn str_sub(args: &[Value]) -> Result<Value, String> {
    expect_min_arity("String.sub", args, 2)?;
    let s = expect_string("String.sub", args, 0)?;
    let chars: Vec<char> = s.chars().collect();
    let i = expect_int("String.sub", args, 1)?;
    let j: i64 = if args.len() >= 3 {
        expect_int("String.sub", args, 2)?
    } else {
        chars.len() as i64
    };

    // Resolve to 0-based [start, end) range with Lua semantics.
    let n = chars.len() as i64;
    let mut start = if i < 0 { (n + i + 1).max(1) } else { i.max(1) };
    let mut end = if j < 0 { n + j + 1 } else { j };
    if end > n {
        end = n;
    }
    if start < 1 {
        start = 1;
    }
    if start > end {
        return Ok(Value::Str(Rc::new(String::new())));
    }
    let out: String = chars[(start as usize - 1)..(end as usize)].iter().collect();
    Ok(Value::Str(Rc::new(out)))
}

fn str_rep(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.rep", args, 2)?;
    let s = expect_string("String.rep", args, 0)?;
    let n = expect_int("String.rep", args, 1)?;
    if n <= 0 {
        return Ok(Value::Str(Rc::new(String::new())));
    }
    Ok(Value::Str(Rc::new(s.repeat(n as usize))))
}

fn str_starts(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.starts", args, 2)?;
    let s = expect_string("String.starts", args, 0)?;
    let prefix = expect_string("String.starts", args, 1)?;
    Ok(Value::Bool(s.starts_with(&prefix)))
}

fn str_ends(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.ends", args, 2)?;
    let s = expect_string("String.ends", args, 0)?;
    let suffix = expect_string("String.ends", args, 1)?;
    Ok(Value::Bool(s.ends_with(&suffix)))
}

fn str_find(args: &[Value]) -> Result<Vec<Value>, String> {
    expect_min_arity("String.find", args, 2)?;
    let s = expect_string("String.find", args, 0)?;
    let pat = expect_string("String.find", args, 1)?;

    // 1-based char start index (Lua-style); default 1. Negative counts back
    // from the end.
    let init: i64 = if args.len() >= 3 {
        expect_int("String.find", args, 2)?
    } else {
        1
    };
    let chars: Vec<char> = s.chars().collect();
    let start = resolve_index(init, chars.len());

    let hay: String = chars[start..].iter().collect();
    let Some(byte_off) = hay.find(&pat) else {
        return Ok(vec![Value::Nil]);
    };
    let char_off_in_hay = hay[..byte_off].chars().count();
    let pat_len = pat.chars().count();
    let s_idx = (start + char_off_in_hay + 1) as i64;
    let e_idx = if pat_len == 0 {
        s_idx - 1
    } else {
        s_idx + pat_len as i64 - 1
    };
    Ok(vec![Value::Int(s_idx), Value::Int(e_idx)])
}

// (placeholder removed)
fn _unused_install_find() {}

fn str_lower(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.lower", args, 1)?;
    let s = expect_string("String.lower", args, 0)?;
    Ok(Value::Str(Rc::new(s.to_lowercase())))
}

fn str_upper(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.upper", args, 1)?;
    let s = expect_string("String.upper", args, 0)?;
    Ok(Value::Str(Rc::new(s.to_uppercase())))
}

// ─── iter: returns a NativeClosure yielding (char, index) per call ──────────

fn str_iter(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.iter", args, 1)?;
    let s = expect_string("String.iter", args, 0)?;
    let chars: Rc<Vec<char>> = Rc::new(s.chars().collect());
    let cursor = Rc::new(RefCell::new(0usize));
    let chars_for_closure = chars.clone();
    Ok(Value::NativeClosure(Rc::new(NativeClosure {
        name: "String.iter#step",
        func: Box::new(move |_args: &[Value]| {
            let mut i = cursor.borrow_mut();
            if *i >= chars_for_closure.len() {
                return Ok(vec![Value::Nil, Value::Nil]);
            }
            let c = chars_for_closure[*i];
            let idx = *i + 1;
            *i += 1;
            Ok(vec![
                Value::Str(Rc::new(c.to_string())),
                Value::Int(idx as i64),
            ])
        }),
    })))
}

// ─── format: minimal printf-style ───────────────────────────────────────────
//
// Supports `%s`, `%d`, `%i`, `%f`, `%x`, `%X`, `%o`, `%c`, `%%`.
// Optional width/precision: `%5d`, `%.2f`, `%-10s`, `%05d`.

fn str_format(args: &[Value]) -> Result<Value, String> {
    Ok(Value::Str(Rc::new(format_args_impl(args)?)))
}

/// Shared formatter used by `String.format` and `printf`. Takes the same
/// argument shape: `args[0]` is the format string, `args[1..]` are the
/// substitutions.
pub(crate) fn format_args_impl(args: &[Value]) -> Result<String, String> {
    expect_min_arity("String.format", args, 1)?;
    let fmt = expect_string("String.format", args, 0)?;
    let mut out = String::with_capacity(fmt.len());
    let mut chars = fmt.chars().peekable();
    let mut arg_idx = 1usize;

    while let Some(ch) = chars.next() {
        if ch != '%' {
            out.push(ch);
            continue;
        }
        // Parse: %[-][0][width][.precision]<spec>
        let mut spec_flags = String::new();
        let mut spec_char: Option<char> = None;
        while let Some(&c) = chars.peek() {
            if matches!(c, '-' | '+' | '0' | ' ' | '#') {
                spec_flags.push(c);
                chars.next();
            } else {
                break;
            }
        }
        let mut width = String::new();
        while let Some(&c) = chars.peek()
            && c.is_ascii_digit()
        {
            width.push(c);
            chars.next();
        }
        let mut precision = String::new();
        if let Some(&'.') = chars.peek() {
            chars.next();
            while let Some(&c) = chars.peek()
                && c.is_ascii_digit()
            {
                precision.push(c);
                chars.next();
            }
        }
        if let Some(&c) = chars.peek() {
            spec_char = Some(c);
            chars.next();
        }
        let Some(spec) = spec_char else {
            return Err("String.format: trailing `%` without format spec".to_string());
        };

        if spec == '%' {
            out.push('%');
            continue;
        }

        let arg = args.get(arg_idx).ok_or_else(|| {
            format!(
                "String.format: not enough arguments for format string (missing arg {arg_idx})"
            )
        })?;
        arg_idx += 1;

        let formatted = format_one(spec, &spec_flags, &width, &precision, arg)?;
        out.push_str(&formatted);
    }
    Ok(out)
}

fn format_one(
    spec: char,
    flags: &str,
    width: &str,
    precision: &str,
    arg: &Value,
) -> Result<String, String> {
    let width: Option<usize> = if width.is_empty() {
        None
    } else {
        width.parse().ok()
    };
    let precision: Option<usize> = if precision.is_empty() {
        None
    } else {
        precision.parse().ok()
    };
    let left_align = flags.contains('-');
    let zero_pad = flags.contains('0') && !left_align;

    let core = match spec {
        's' => {
            let s = match arg {
                Value::Str(s) => (**s).clone(),
                other => other.to_display_string(),
            };
            if let Some(p) = precision {
                s.chars().take(p).collect::<String>()
            } else {
                s
            }
        }
        'd' | 'i' => {
            let n = as_int(arg, spec)?;
            format!("{n}")
        }
        'x' => format!("{:x}", as_int(arg, spec)?),
        'X' => format!("{:X}", as_int(arg, spec)?),
        'o' => format!("{:o}", as_int(arg, spec)?),
        'c' => {
            let n = as_int(arg, spec)?;
            let Some(c) = u32::try_from(n).ok().and_then(char::from_u32) else {
                return Err(format!("String.format `%c`: {n} is not a valid character"));
            };
            c.to_string()
        }
        'f' | 'g' | 'e' => {
            let x = as_float(arg, spec)?;
            match (spec, precision) {
                ('f', Some(p)) => format!("{x:.*}", p),
                ('f', None) => format!("{x:.6}"),
                ('e', Some(p)) => format!("{x:.*e}", p),
                ('e', None) => format!("{x:e}"),
                ('g', Some(_)) | ('g', None) => format!("{x}"),
                _ => unreachable!(),
            }
        }
        other => {
            return Err(format!("String.format: unsupported spec `%{other}`"));
        }
    };

    // Apply width padding.
    let Some(w) = width else { return Ok(core) };
    if core.chars().count() >= w {
        return Ok(core);
    }
    let pad = w - core.chars().count();
    let pad_char = if zero_pad && matches!(spec, 'd' | 'i' | 'x' | 'X' | 'o' | 'f' | 'e' | 'g') {
        '0'
    } else {
        ' '
    };
    Ok(if left_align {
        let mut s = core;
        s.extend(std::iter::repeat_n(pad_char, pad));
        s
    } else {
        let mut s = String::with_capacity(w);
        s.extend(std::iter::repeat_n(pad_char, pad));
        s.push_str(&core);
        s
    })
}

fn as_int(v: &Value, spec: char) -> Result<i64, String> {
    match v {
        Value::Int(i) => Ok(*i),
        Value::Float(f) => Ok(*f as i64),
        other => Err(format!(
            "String.format `%{spec}`: expected integer, got `{}`",
            other.type_name()
        )),
    }
}

fn as_float(v: &Value, spec: char) -> Result<f64, String> {
    match v {
        Value::Int(i) => Ok(*i as f64),
        Value::Float(f) => Ok(*f),
        other => Err(format!(
            "String.format `%{spec}`: expected number, got `{}`",
            other.type_name()
        )),
    }
}

//! String standard library — exposed as the static class `String`.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use crate::env::Environment;
use crate::stdlib::{expect_arity, expect_min_arity};
use crate::value::{ClassObject, NativeClosure, Value};

pub fn install(env: &Rc<RefCell<Environment>>) {
    let mut static_fields = HashMap::new();
    static_fields.insert("byte".to_string(),   native("String.byte",   str_byte));
    static_fields.insert("char".to_string(),   native("String.char",   str_char));
    static_fields.insert("format".to_string(), native("String.format", str_format));
    static_fields.insert("len".to_string(),    native("String.len",    str_len));
    static_fields.insert("sub".to_string(),    native("String.sub",    str_sub));
    static_fields.insert("rep".to_string(),    native("String.rep",    str_rep));
    static_fields.insert("starts".to_string(), native("String.starts", str_starts));
    static_fields.insert("ends".to_string(),   native("String.ends",   str_ends));
    static_fields.insert("find".to_string(),   native_multi("String.find", str_find));
    static_fields.insert("lower".to_string(),  native("String.lower",  str_lower));
    static_fields.insert("upper".to_string(),  native("String.upper",  str_upper));
    static_fields.insert("iter".to_string(),   native("String.iter",   str_iter));

    let class = ClassObject {
        name: "String".to_string(),
        parent: None,
        field_defs: Vec::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(static_fields),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("String".to_string(), Value::Class(Rc::new(class)));
}

/// Register native signatures for the typechecker (lazy, via `sigs::lookup`).
pub fn register_sigs() {
    use crate::stdlib::sigs::{register, t_named, t_nullable};
    let s   = || t_named("string");
    let i   = || t_named("integer");
    let b   = || t_named("boolean");
    let any = || t_named("any");
    register("String.byte",   vec![s(), t_nullable(i())],         vec![t_nullable(i())]);
    register("String.char",   vec![],                              vec![s()]);
    register("String.format", vec![s()],                           vec![s()]);
    register("String.len",    vec![s()],                           vec![i()]);
    register("String.sub",    vec![s(), i(), t_nullable(i())],     vec![s()]);
    register("String.rep",    vec![s(), i()],                      vec![s()]);
    register("String.starts", vec![s(), s()],                      vec![b()]);
    register("String.ends",   vec![s(), s()],                      vec![b()]);
    register("String.find",   vec![s(), s(), t_nullable(i())],     vec![t_nullable(i()), t_nullable(i())]);
    register("String.lower",  vec![s()],                           vec![s()]);
    register("String.upper",  vec![s()],                           vec![s()]);
    register("String.iter",   vec![s()],                           vec![any()]);  // returns a step closure
}

fn native(name: &'static str, func: fn(&[Value]) -> Result<Value, String>) -> Value {
    Value::Native(Rc::new(crate::value::NativeFn { name, func }))
}

/// Wrap a multi-return native function as a `NativeClosure` so the call
/// site can destructure `local a, b = f(...)`.
fn native_multi(
    name: &'static str,
    func: fn(&[Value]) -> Result<Vec<Value>, String>,
) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name,
        func: Box::new(move |args| func(args)),
    }))
}

// ─── helpers ────────────────────────────────────────────────────────────────

fn expect_string(name: &str, args: &[Value], idx: usize) -> Result<String, String> {
    match args.get(idx) {
        Some(Value::Str(s)) => Ok((**s).clone()),
        Some(other) => Err(format!(
            "{name} expects a string at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

fn expect_int(name: &str, args: &[Value], idx: usize) -> Result<i64, String> {
    match args.get(idx) {
        Some(Value::Int(i)) => Ok(*i),
        Some(other) => Err(format!(
            "{name} expects an integer at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

// Lua-style 1-based index with negative-from-end. Clamps to `[1, len]`. The
// returned value is a 0-based byte offset suitable for slicing the `chars`
// vector (so it's "1-based char index minus 1").
fn resolve_index(i: i64, char_count: usize) -> usize {
    let n = char_count as i64;
    let idx = if i < 0 { n + i + 1 } else { i };
    if idx < 1 {
        0
    } else if idx > n {
        char_count
    } else {
        (idx - 1) as usize
    }
}

// ─── functions ──────────────────────────────────────────────────────────────

fn str_byte(args: &[Value]) -> Result<Value, String> {
    expect_min_arity("String.byte", args, 1)?;
    let s = expect_string("String.byte", args, 0)?;
    let chars: Vec<char> = s.chars().collect();
    let pos: i64 = if args.len() >= 2 {
        expect_int("String.byte", args, 1)?
    } else {
        1
    };
    if pos < 1 || (pos as usize) > chars.len() {
        return Ok(Value::Nil);
    }
    let c = chars[(pos as usize) - 1];
    Ok(Value::Int(c as i64))
}

fn str_char(args: &[Value]) -> Result<Value, String> {
    let mut out = String::with_capacity(args.len());
    for (i, arg) in args.iter().enumerate() {
        let code = match arg {
            Value::Int(n) => *n,
            other => {
                return Err(format!(
                    "String.char expects integer arguments, got `{}` at argument {}",
                    other.type_name(),
                    i + 1
                ));
            }
        };
        let Some(c) = u32::try_from(code).ok().and_then(char::from_u32) else {
            return Err(format!(
                "String.char: code {code} at argument {} is not a valid character",
                i + 1
            ));
        };
        out.push(c);
    }
    Ok(Value::Str(Rc::new(out)))
}

fn str_len(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.len", args, 1)?;
    let s = expect_string("String.len", args, 0)?;
    Ok(Value::Int(s.chars().count() as i64))
}

fn str_sub(args: &[Value]) -> Result<Value, String> {
    expect_min_arity("String.sub", args, 2)?;
    let s = expect_string("String.sub", args, 0)?;
    let chars: Vec<char> = s.chars().collect();
    let i = expect_int("String.sub", args, 1)?;
    let j: i64 = if args.len() >= 3 {
        expect_int("String.sub", args, 2)?
    } else {
        chars.len() as i64
    };

    // Resolve to 0-based [start, end) range with Lua semantics.
    let n = chars.len() as i64;
    let mut start = if i < 0 { (n + i + 1).max(1) } else { i.max(1) };
    let mut end = if j < 0 { n + j + 1 } else { j };
    if end > n {
        end = n;
    }
    if start < 1 {
        start = 1;
    }
    if start > end {
        return Ok(Value::Str(Rc::new(String::new())));
    }
    let out: String = chars[(start as usize - 1)..(end as usize)].iter().collect();
    Ok(Value::Str(Rc::new(out)))
}

fn str_rep(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.rep", args, 2)?;
    let s = expect_string("String.rep", args, 0)?;
    let n = expect_int("String.rep", args, 1)?;
    if n <= 0 {
        return Ok(Value::Str(Rc::new(String::new())));
    }
    Ok(Value::Str(Rc::new(s.repeat(n as usize))))
}

fn str_starts(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.starts", args, 2)?;
    let s = expect_string("String.starts", args, 0)?;
    let prefix = expect_string("String.starts", args, 1)?;
    Ok(Value::Bool(s.starts_with(&prefix)))
}

fn str_ends(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.ends", args, 2)?;
    let s = expect_string("String.ends", args, 0)?;
    let suffix = expect_string("String.ends", args, 1)?;
    Ok(Value::Bool(s.ends_with(&suffix)))
}

fn str_find(args: &[Value]) -> Result<Vec<Value>, String> {
    expect_min_arity("String.find", args, 2)?;
    let s = expect_string("String.find", args, 0)?;
    let pat = expect_string("String.find", args, 1)?;

    // 1-based char start index (Lua-style); default 1. Negative counts back
    // from the end.
    let init: i64 = if args.len() >= 3 {
        expect_int("String.find", args, 2)?
    } else {
        1
    };
    let chars: Vec<char> = s.chars().collect();
    let start = resolve_index(init, chars.len());

    let hay: String = chars[start..].iter().collect();
    let Some(byte_off) = hay.find(&pat) else {
        return Ok(vec![Value::Nil]);
    };
    let char_off_in_hay = hay[..byte_off].chars().count();
    let pat_len = pat.chars().count();
    let s_idx = (start + char_off_in_hay + 1) as i64;
    let e_idx = if pat_len == 0 {
        s_idx - 1
    } else {
        s_idx + pat_len as i64 - 1
    };
    Ok(vec![Value::Int(s_idx), Value::Int(e_idx)])
}

// (placeholder removed)
fn _unused_install_find() {}

fn str_lower(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.lower", args, 1)?;
    let s = expect_string("String.lower", args, 0)?;
    Ok(Value::Str(Rc::new(s.to_lowercase())))
}

fn str_upper(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.upper", args, 1)?;
    let s = expect_string("String.upper", args, 0)?;
    Ok(Value::Str(Rc::new(s.to_uppercase())))
}

// ─── iter: returns a NativeClosure yielding (char, index) per call ──────────

fn str_iter(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.iter", args, 1)?;
    let s = expect_string("String.iter", args, 0)?;
    let chars: Rc<Vec<char>> = Rc::new(s.chars().collect());
    let cursor = Rc::new(RefCell::new(0usize));
    let chars_for_closure = chars.clone();
    Ok(Value::NativeClosure(Rc::new(NativeClosure {
        name: "String.iter#step",
        func: Box::new(move |_args: &[Value]| {
            let mut i = cursor.borrow_mut();
            if *i >= chars_for_closure.len() {
                return Ok(vec![Value::Nil, Value::Nil]);
            }
            let c = chars_for_closure[*i];
            let idx = *i + 1;
            *i += 1;
            Ok(vec![
                Value::Str(Rc::new(c.to_string())),
                Value::Int(idx as i64),
            ])
        }),
    })))
}

// ─── format: minimal printf-style ───────────────────────────────────────────
//
// Supports `%s`, `%d`, `%i`, `%f`, `%x`, `%X`, `%o`, `%c`, `%%`.
// Optional width/precision: `%5d`, `%.2f`, `%-10s`, `%05d`.

fn str_format(args: &[Value]) -> Result<Value, String> {
    Ok(Value::Str(Rc::new(format_args_impl(args)?)))
}

/// Shared formatter used by `String.format` and `printf`. Takes the same
/// argument shape: `args[0]` is the format string, `args[1..]` are the
/// substitutions.
pub(crate) fn format_args_impl(args: &[Value]) -> Result<String, String> {
    expect_min_arity("String.format", args, 1)?;
    let fmt = expect_string("String.format", args, 0)?;
    let mut out = String::with_capacity(fmt.len());
    let mut chars = fmt.chars().peekable();
    let mut arg_idx = 1usize;

    while let Some(ch) = chars.next() {
        if ch != '%' {
            out.push(ch);
            continue;
        }
        // Parse: %[-][0][width][.precision]<spec>
        let mut spec_flags = String::new();
        let mut spec_char: Option<char> = None;
        while let Some(&c) = chars.peek() {
            if matches!(c, '-' | '+' | '0' | ' ' | '#') {
                spec_flags.push(c);
                chars.next();
            } else {
                break;
            }
        }
        let mut width = String::new();
        while let Some(&c) = chars.peek()
            && c.is_ascii_digit()
        {
            width.push(c);
            chars.next();
        }
        let mut precision = String::new();
        if let Some(&'.') = chars.peek() {
            chars.next();
            while let Some(&c) = chars.peek()
                && c.is_ascii_digit()
            {
                precision.push(c);
                chars.next();
            }
        }
        if let Some(&c) = chars.peek() {
            spec_char = Some(c);
            chars.next();
        }
        let Some(spec) = spec_char else {
            return Err("String.format: trailing `%` without format spec".to_string());
        };

        if spec == '%' {
            out.push('%');
            continue;
        }

        let arg = args.get(arg_idx).ok_or_else(|| {
            format!(
                "String.format: not enough arguments for format string (missing arg {arg_idx})"
            )
        })?;
        arg_idx += 1;

        let formatted = format_one(spec, &spec_flags, &width, &precision, arg)?;
        out.push_str(&formatted);
    }
    Ok(out)
}

fn format_one(
    spec: char,
    flags: &str,
    width: &str,
    precision: &str,
    arg: &Value,
) -> Result<String, String> {
    let width: Option<usize> = if width.is_empty() {
        None
    } else {
        width.parse().ok()
    };
    let precision: Option<usize> = if precision.is_empty() {
        None
    } else {
        precision.parse().ok()
    };
    let left_align = flags.contains('-');
    let zero_pad = flags.contains('0') && !left_align;

    let core = match spec {
        's' => {
            let s = match arg {
                Value::Str(s) => (**s).clone(),
                other => other.to_display_string(),
            };
            if let Some(p) = precision {
                s.chars().take(p).collect::<String>()
            } else {
                s
            }
        }
        'd' | 'i' => {
            let n = as_int(arg, spec)?;
            format!("{n}")
        }
        'x' => format!("{:x}", as_int(arg, spec)?),
        'X' => format!("{:X}", as_int(arg, spec)?),
        'o' => format!("{:o}", as_int(arg, spec)?),
        'c' => {
            let n = as_int(arg, spec)?;
            let Some(c) = u32::try_from(n).ok().and_then(char::from_u32) else {
                return Err(format!("String.format `%c`: {n} is not a valid character"));
            };
            c.to_string()
        }
        'f' | 'g' | 'e' => {
            let x = as_float(arg, spec)?;
            match (spec, precision) {
                ('f', Some(p)) => format!("{x:.*}", p),
                ('f', None) => format!("{x:.6}"),
                ('e', Some(p)) => format!("{x:.*e}", p),
                ('e', None) => format!("{x:e}"),
                ('g', Some(_)) | ('g', None) => format!("{x}"),
                _ => unreachable!(),
            }
        }
        other => {
            return Err(format!("String.format: unsupported spec `%{other}`"));
        }
    };

    // Apply width padding.
    let Some(w) = width else { return Ok(core) };
    if core.chars().count() >= w {
        return Ok(core);
    }
    let pad = w - core.chars().count();
    let pad_char = if zero_pad && matches!(spec, 'd' | 'i' | 'x' | 'X' | 'o' | 'f' | 'e' | 'g') {
        '0'
    } else {
        ' '
    };
    Ok(if left_align {
        let mut s = core;
        s.extend(std::iter::repeat_n(pad_char, pad));
        s
    } else {
        let mut s = String::with_capacity(w);
        s.extend(std::iter::repeat_n(pad_char, pad));
        s.push_str(&core);
        s
    })
}

fn as_int(v: &Value, spec: char) -> Result<i64, String> {
    match v {
        Value::Int(i) => Ok(*i),
        Value::Float(f) => Ok(*f as i64),
        other => Err(format!(
            "String.format `%{spec}`: expected integer, got `{}`",
            other.type_name()
        )),
    }
}

fn as_float(v: &Value, spec: char) -> Result<f64, String> {
    match v {
        Value::Int(i) => Ok(*i as f64),
        Value::Float(f) => Ok(*f),
        other => Err(format!(
            "String.format `%{spec}`: expected number, got `{}`",
            other.type_name()
        )),
    }
}

//! Static checks performed between parsing and evaluation.
//!
//! Two flavours of checks live here:
//!
//! 1. **Field initialization** — every non-nullable instance field of a class
//!    with a constructor must be assigned `self.field = ...` somewhere inside
//!    that constructor's body. Fields with defaults are exempt; nullable
//!    fields (`name: string?`) are exempt by design.
//!
//! 2. **Null safety** — values whose static type is nullable cannot be
//!    silently assigned to non-nullable bindings, and members cannot be read
//!    off a nullable receiver without `?.` / `!` / a prior nil-guard. A
//!    lightweight flow-narrowing pass treats `if x != nil then ... end` as
//!    proving `x` is non-nullable inside the then-block (and symmetrically
//!    for `if x == nil ... else ...`).
//!
//! The expression type inference here is intentionally partial: when the
//! checker can't prove a type (e.g. calls, member reads on unknown classes),
//! it returns `None` and conservatively skips the check rather than producing
//! a false positive.

use std::collections::{HashMap, HashSet};
use std::ops::Range;

use miette::Diagnostic;
use saule_ast::{
    BinOp, CallArg, ClassMember, Decl, EnumVariant, Expr, LambdaBody, MatchArm, MatchBody, Method,
    Module, Param, Pattern, Spanned, Stmt, Type,
};
use thiserror::Error;

/// One diagnostic produced by [`check`]. Carries a `miette` source span so
/// the CLI can render it with the offending snippet underlined.
#[derive(Debug, Error, Diagnostic)]
pub enum TypeCheckError {
    #[error("field `{field}` of class `{class}` is never initialized")]
    #[diagnostic(help(
        "assign `self.{field} = ...` in `init`, give the field a default value, or mark it nullable with `?`"
    ))]
    FieldNotInitialized {
        class: String,
        field: String,
        #[label("declared here")]
        span: miette::SourceSpan,
    },

    #[error("cannot assign `nil` to non-nullable type `{ty}`")]
    #[diagnostic(help(
        "mark the type nullable with `?` (e.g. `{ty}?`) or initialize it with a non-nil value"
    ))]
    NilToNonNullable {
        ty: String,
        #[label("`nil` not allowed here")]
        span: miette::SourceSpan,
    },

    #[error("cannot assign a nullable value of type `{from}` to non-nullable type `{to}`")]
    #[diagnostic(help(
        "guard with `if x != nil then ... end`, use `??` to provide a fallback, or force-unwrap with `!`"
    ))]
    NullableToNonNullable {
        from: String,
        to: String,
        #[label("this expression may be `nil`")]
        span: miette::SourceSpan,
    },

    #[error("cannot access `{member}` on nullable type `{ty}`")]
    #[diagnostic(help(
        "use `?.` for safe access, `!` to force-unwrap, or guard with `if x != nil then ... end`"
    ))]
    NullableMemberAccess {
        ty: String,
        member: String,
        #[label("receiver may be `nil`")]
        span: miette::SourceSpan,
    },

    #[error("default value for parameter `{param}` is incompatible with declared type `{ty}`")]
    #[diagnostic(help(
        "the default expression must produce a value of type `{ty}`"
    ))]
    DefaultParamTypeMismatch {
        param: String,
        ty: String,
        #[label("default here")]
        span: miette::SourceSpan,
    },

    #[error("return value is incompatible with declared return type `{ty}`")]
    #[diagnostic(help("this function must return a `{ty}`"))]
    WrongReturnType {
        ty: String,
        #[label("returned here")]
        span: miette::SourceSpan,
    },

    #[error("cannot access private member `{member}` of class `{class}` from outside the class")]
    #[diagnostic(help(
        "`local` fields and methods are only accessible from within `{class}`"
    ))]
    PrivateMemberAccess {
        class: String,
        member: String,
        #[label("private")]
        span: miette::SourceSpan,
    },

    #[error("table value of type `{found}` is incompatible with declared element type `{expected}`")]
    #[diagnostic(help(
        "every value stored in this table must be a `{expected}`"
    ))]
    TableElementTypeMismatch {
        expected: String,
        found: String,
        #[label("wrong value type")]
        span: miette::SourceSpan,
    },

    #[error("table key of type `{found}` is incompatible with declared key type `{expected}`")]
    #[diagnostic(help(
        "this table is declared with key type `{expected}` — pass an index of that type"
    ))]
    TableKeyTypeMismatch {
        expected: String,
        found: String,
        #[label("wrong key type")]
        span: miette::SourceSpan,
    },

    #[error("cannot initialise `table<{key}, {value}>` with an array-style literal")]
    #[diagnostic(help(
        "array-style `{{ ... }}` literals can only fill `table<T>` (integer-keyed); start from `{{}}` and assign by key instead"
    ))]
    TableArrayLiteralForMap {
        key: String,
        value: String,
        #[label("array literal not allowed for a map-typed table")]
        span: miette::SourceSpan,
    },

    #[error("cannot iterate over a `{class}` — it does not implement `Iterable` or `Iterable2`")]
    #[diagnostic(help(
        "add `implements Iterable<T>` (or `Iterable2<K, V>`) to `{class}` and define `fn iter() -> fn(): T?` returning a step closure"
    ))]
    NotIterable {
        class: String,
        #[label("class is not iterable")]
        span: miette::SourceSpan,
    },

    #[error("argument {arg} of `{callee}` expects `{expected}`, got `{found}`")]
    #[diagnostic(help(
        "pass a value of type `{expected}` here — check the signature of `{callee}`"
    ))]
    NativeArgTypeMismatch {
        callee: String,
        arg: usize,
        expected: String,
        found: String,
        #[label("wrong argument type")]
        span: miette::SourceSpan,
    },

    #[error("`{callee}` expects {expected} argument(s), got {found}")]
    #[diagnostic(help("check the signature of `{callee}`"))]
    NativeArity {
        callee: String,
        expected: usize,
        found: usize,
        #[label("wrong number of arguments")]
        span: miette::SourceSpan,
    },

    #[error("`{construct}` condition must be a `boolean`, got `{found}`")]
    #[diagnostic(help(
        "compare with `==`, `!=`, `<`, `>` etc., or use `?? false` / `!= nil` to coerce a nullable to a `boolean`"
    ))]
    NonBooleanCondition {
        construct: &'static str,
        found: String,
        #[label("not a boolean")]
        span: miette::SourceSpan,
    },

    #[error("non-exhaustive `match`: {reason}")]
    #[diagnostic(help(
        "add a wildcard arm `case _ then ...` or cover the remaining cases explicitly"
    ))]
    MatchNonExhaustive {
        reason: String,
        #[label("not all cases covered")]
        span: miette::SourceSpan,
    },

    #[error("`match` arms produce incompatible types: `{expected}` vs `{found}`")]
    #[diagnostic(help("every arm of a `match` expression must evaluate to the same type"))]
    MatchArmTypeMismatch {
        expected: String,
        found: String,
        #[label("arms disagree on result type")]
        span: miette::SourceSpan,
    },

    #[error("pattern of type `{found}` cannot match scrutinee of type `{expected}`")]
    #[diagnostic(help("change the pattern to match the scrutinee's type"))]
    MatchPatternTypeMismatch {
        expected: String,
        found: String,
        #[label("incompatible pattern")]
        span: miette::SourceSpan,
    },

    #[error("enum `{enum_name}` has no variant `{variant}`")]
    #[diagnostic(help("check the spelling of the variant or add it to the enum"))]
    MatchUnknownVariant {
        enum_name: String,
        variant: String,
        #[label("unknown variant")]
        span: miette::SourceSpan,
    },

    #[error("variant `{variant}` expects {expected} field(s), got {found}")]
    #[diagnostic(help("supply a sub-pattern for every payload field of the variant"))]
    MatchVariantArityMismatch {
        variant: String,
        expected: usize,
        found: usize,
        #[label("wrong number of sub-patterns")]
        span: miette::SourceSpan,
    },
}

fn to_source_span(r: Range<usize>) -> miette::SourceSpan {
    (r.start, r.end.saturating_sub(r.start)).into()
}

// ──────────────────────────────────────────────────────────────────────────────
// Scope: tracks the static types of `local` bindings in lexical scope.
// ──────────────────────────────────────────────────────────────────────────────

#[derive(Default, Clone)]
struct Scope {
    vars: HashMap<String, Type>,
}

impl Scope {
    fn lookup(&self, name: &str) -> Option<&Type> {
        self.vars.get(name)
    }

    fn bind(&mut self, name: String, ty: Type) {
        self.vars.insert(name, ty);
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Public entry point.
// ──────────────────────────────────────────────────────────────────────────────

/// Class info collected by a pre-pass so member-access checks can consult
/// member visibility, parent classes, etc.
#[derive(Default, Clone)]
struct ClassInfo {
    parent: Option<String>,
    /// Interfaces declared on the class (`class C implements A, B`).
    implements: Vec<String>,
    /// member name -> is_private
    members: HashMap<String, bool>,
}

type ClassRegistry = HashMap<String, ClassInfo>;
type InterfaceRegistry = HashMap<String, Vec<String>>;

/// Enum info: variant name -> payload arity (0 for `Bare` / `Valued`,
/// N for `Tuple { fields: [...; N] }`).
#[derive(Default, Clone)]
struct EnumInfo {
    variants: HashMap<String, usize>,
}
type EnumRegistry = HashMap<String, EnumInfo>;

thread_local! {
    static CLASSES: std::cell::RefCell<ClassRegistry> = std::cell::RefCell::new(HashMap::new());
    static INTERFACES: std::cell::RefCell<InterfaceRegistry> = std::cell::RefCell::new(HashMap::new());
    static ENUMS: std::cell::RefCell<EnumRegistry> = std::cell::RefCell::new(HashMap::new());
    static CURRENT_CLASS: std::cell::RefCell<Option<String>> = const { std::cell::RefCell::new(None) };

    /// Generic type-parameter names in scope for the function/method body
    /// currently being checked. Treated as `any`-equivalent so that
    /// `table<T>`, `T?`, and bare `T` accept any concrete instantiation.
    static GENERICS: std::cell::RefCell<std::collections::HashSet<String>> =
        std::cell::RefCell::new(std::collections::HashSet::new());
}

fn with_classes<R>(f: impl FnOnce(&ClassRegistry) -> R) -> R {
    CLASSES.with(|c| f(&c.borrow()))
}

fn with_interfaces<R>(f: impl FnOnce(&InterfaceRegistry) -> R) -> R {
    INTERFACES.with(|c| f(&c.borrow()))
}

fn with_enums<R>(f: impl FnOnce(&EnumRegistry) -> R) -> R {
    ENUMS.with(|c| f(&c.borrow()))
}

/// Is `iface` a known interface name?
fn is_interface(name: &str) -> bool {
    with_interfaces(|r| r.contains_key(name))
}

/// Does `iface` extend `target` (transitively, including itself)?
fn interface_extends(iface: &str, target: &str) -> bool {
    if iface == target {
        return true;
    }
    with_interfaces(|r| {
        let mut stack: Vec<String> = vec![iface.to_string()];
        let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
        while let Some(cur) = stack.pop() {
            if !seen.insert(cur.clone()) {
                continue;
            }
            if cur == target {
                return true;
            }
            if let Some(parents) = r.get(&cur) {
                for p in parents {
                    stack.push(p.clone());
                }
            }
        }
        false
    })
}

/// Does class `class` (or any ancestor) implement interface `target`
/// (directly or via interface composition)?
fn class_implements(class: &str, target: &str) -> bool {
    with_classes(|reg| {
        let mut cur = Some(class.to_string());
        while let Some(name) = cur {
            let Some(info) = reg.get(&name) else {
                return false;
            };
            for i in &info.implements {
                if interface_extends(i, target) {
                    return true;
                }
            }
            cur = info.parent.clone();
        }
        false
    })
}

/// `got` is a subtype of `expected` when:
/// - they're equal, OR
/// - `expected` is an interface and `got` is a class implementing it
///   (directly or via a parent), OR
/// - both are interfaces and `got` extends `expected`, OR
/// - `got` is a class that extends `expected` (class inheritance).
fn is_subtype_named(got: &str, expected: &str) -> bool {
    if got == expected {
        return true;
    }
    // Class → interface
    if is_interface(expected) && class_implements(got, expected) {
        return true;
    }
    // Interface → interface
    if is_interface(got) && is_interface(expected) && interface_extends(got, expected) {
        return true;
    }
    // Class → ancestor class
    with_classes(|reg| {
        let mut cur = reg.get(got).and_then(|i| i.parent.clone());
        while let Some(name) = cur {
            if name == expected {
                return true;
            }
            cur = reg.get(&name).and_then(|i| i.parent.clone());
        }
        false
    })
}

fn current_class() -> Option<String> {
    CURRENT_CLASS.with(|c| c.borrow().clone())
}

fn set_current_class(name: Option<String>) -> Option<String> {
    CURRENT_CLASS.with(|c| std::mem::replace(&mut *c.borrow_mut(), name))
}

/// Add `params` to the in-scope generic set. Returns the names actually
/// inserted so the matching [`pop_generics`] can remove just those (and
/// preserve any outer generics that share a name).
fn push_generics(params: &[String]) -> Vec<String> {
    let mut added = Vec::new();
    GENERICS.with(|g| {
        let mut set = g.borrow_mut();
        for p in params {
            if set.insert(p.clone()) {
                added.push(p.clone());
            }
        }
    });
    added
}

fn pop_generics(added: Vec<String>) {
    GENERICS.with(|g| {
        let mut set = g.borrow_mut();
        for p in added {
            set.remove(&p);
        }
    });
}

/// True if `name` names a type parameter in scope for the current body.
fn is_type_param(name: &str) -> bool {
    GENERICS.with(|g| g.borrow().contains(name))
}

/// Look up `member` on `class` (walking the parent chain). Returns
/// `Some((owning_class, is_private))` if found.
fn lookup_member(class: &str, member: &str) -> Option<(String, bool)> {
    with_classes(|reg| {
        let mut cur = Some(class.to_string());
        while let Some(name) = cur {
            if let Some(info) = reg.get(&name) {
                if let Some(&priv_) = info.members.get(member) {
                    return Some((name, priv_));
                }
                cur = info.parent.clone();
            } else {
                return None;
            }
        }
        None
    })
}

/// Does the class (or any ancestor) declare it implements `Iterable` or
/// `Iterable2`? Used by the `for ... in` static check.
fn class_implements_iterable(class: &str) -> bool {
    class_implements(class, "Iterable") || class_implements(class, "Iterable2")
}

fn build_registry(module: &Module) -> (ClassRegistry, InterfaceRegistry, EnumRegistry) {
    let mut reg = ClassRegistry::new();
    let mut ifaces = InterfaceRegistry::new();
    let mut enums = EnumRegistry::new();
    for stmt in &module.stmts {
        if let Stmt::Decl(d) = &stmt.value {
            match &d.value {
                Decl::Class {
                    name,
                    extends,
                    implements,
                    members,
                    ..
                } => {
                    let mut info = ClassInfo {
                        parent: extends.clone(),
                        implements: implements.clone(),
                        members: HashMap::new(),
                    };
                    for m in members {
                        match &m.value {
                            ClassMember::Field {
                                name, is_private, ..
                            } => {
                                info.members.insert(name.clone(), *is_private);
                            }
                            ClassMember::Method(meth) => {
                                info.members.insert(meth.name.clone(), meth.is_private);
                            }
                        }
                    }
                    reg.insert(name.clone(), info);
                }
                Decl::Interface { name, extends, .. } => {
                    ifaces.insert(name.clone(), extends.clone());
                }
                Decl::Enum { name, variants, .. } => {
                    let mut info = EnumInfo::default();
                    for v in variants {
                        let (vname, arity) = match &v.value {
                            EnumVariant::Bare(n) => (n.clone(), 0),
                            EnumVariant::Valued(n, _) => (n.clone(), 0),
                            EnumVariant::Tuple { name, fields } => (name.clone(), fields.len()),
                        };
                        info.variants.insert(vname, arity);
                    }
                    enums.insert(name.clone(), info);
                }
                _ => {}
            }
        }
    }
    // Pre-register the builtin iterable interfaces so class-implements checks
    // see them even without explicit declarations in user code.
    ifaces.entry("Iterable".into()).or_default();
    ifaces.entry("Iterable2".into()).or_default();
    (reg, ifaces, enums)
}

/// Run the static checks on a parsed module. Returns *all* errors found so
/// the user sees everything in one pass.
pub fn check(module: &Module) -> Vec<TypeCheckError> {
    let (reg, ifaces, enums) = build_registry(module);
    CLASSES.with(|c| *c.borrow_mut() = reg);
    INTERFACES.with(|c| *c.borrow_mut() = ifaces);
    ENUMS.with(|c| *c.borrow_mut() = enums);
    let _restore = set_current_class(None);
    let mut errors = Vec::new();
    let mut scope = Scope::default();
    for stmt in &module.stmts {
        check_stmt(&stmt.value, &mut scope, &mut errors);
    }
    CLASSES.with(|c| c.borrow_mut().clear());
    INTERFACES.with(|c| c.borrow_mut().clear());
    ENUMS.with(|c| c.borrow_mut().clear());
    errors
}

// ──────────────────────────────────────────────────────────────────────────────
// Statement walker. Threads a `Scope` so we know the static type of every
// `local` we've seen on the current path, and so narrowing in `if`/`else` can
// override types for the duration of a sub-block.
// ──────────────────────────────────────────────────────────────────────────────

fn check_stmt(stmt: &Stmt, scope: &mut Scope, errors: &mut Vec<TypeCheckError>) {
    match stmt {
        Stmt::Decl(decl) => check_decl(&decl.value, errors),

        Stmt::Local { name, ty, value } => {
            if let (Some(ty), Some(v)) = (ty, value) {
                check_expr(v, scope, errors);
                check_assignment_compat(ty, v, scope, errors);
                scope.bind(name.clone(), ty.clone());
            } else if let Some(v) = value {
                check_expr(v, scope, errors);
                if let Some(t) = infer(v, scope) {
                    scope.bind(name.clone(), t);
                }
            } else if let Some(ty) = ty {
                scope.bind(name.clone(), ty.clone());
            }
        }

        Stmt::LocalMulti { names, values } => {
            for v in values {
                check_expr(v, scope, errors);
            }
            for (i, (name, ty_opt)) in names.iter().enumerate() {
                if let (Some(ty), Some(v)) = (ty_opt, values.get(i)) {
                    check_assignment_compat(ty, v, scope, errors);
                }
                if let Some(ty) = ty_opt {
                    scope.bind(name.clone(), ty.clone());
                } else if let Some(v) = values.get(i)
                    && let Some(t) = infer(v, scope)
                {
                    scope.bind(name.clone(), t);
                }
            }
        }

        Stmt::Assign { target, value } => {
            check_expr(target, scope, errors);
            check_expr(value, scope, errors);
            if let Expr::Ident(n) = &target.value
                && let Some(ty) = scope.lookup(n).cloned()
            {
                check_assignment_compat(&ty, value, scope, errors);
            }
            // `t[k] = v` — enforce the table's static key/value types.
            if let Expr::Index { obj, index } = &target.value
                && let Some(Type::Table { key, value: elem_ty }) = infer(obj, scope)
            {
                let key_ty = key
                    .as_deref()
                    .cloned()
                    .unwrap_or_else(|| Type::Named("integer".into()));
                check_table_key_compat(&key_ty, index, scope, errors);
                check_element_compat(&elem_ty, value, scope, errors);
            }
        }

        Stmt::AssignMulti { targets, values } => {
            for t in targets {
                check_expr(t, scope, errors);
            }
            for v in values {
                check_expr(v, scope, errors);
            }
            for (i, target) in targets.iter().enumerate() {
                if let Expr::Ident(n) = &target.value
                    && let (Some(ty), Some(v)) = (scope.lookup(n).cloned(), values.get(i))
                {
                    check_assignment_compat(&ty, v, scope, errors);
                }
            }
        }

        Stmt::Expr(e) => check_expr(e, scope, errors),

        Stmt::If {
            cond,
            then_block,
            elseifs,
            else_block,
        } => {
            check_expr(cond, scope, errors);
            check_boolean_cond("if", cond, scope, errors);

            // Branch the scope so narrowing in the then-block doesn't leak.
            let mut then_scope = scope.clone();
            narrow_truthy(cond, &mut then_scope);
            for s in then_block {
                check_stmt(&s.value, &mut then_scope, errors);
            }

            for (econd, ebody) in elseifs {
                check_expr(econd, scope, errors);
                check_boolean_cond("elseif", econd, scope, errors);
                let mut ei_scope = scope.clone();
                narrow_truthy(econd, &mut ei_scope);
                for s in ebody {
                    check_stmt(&s.value, &mut ei_scope, errors);
                }
            }

            if let Some(block) = else_block {
                let mut else_scope = scope.clone();
                narrow_falsy(cond, &mut else_scope);
                for s in block {
                    check_stmt(&s.value, &mut else_scope, errors);
                }
            }
        }

        Stmt::While { cond, body } | Stmt::Repeat { body, cond } => {
            check_expr(cond, scope, errors);
            check_boolean_cond(
                if matches!(stmt, Stmt::While { .. }) { "while" } else { "until" },
                cond,
                scope,
                errors,
            );
            let mut body_scope = scope.clone();
            narrow_truthy(cond, &mut body_scope);
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
        }

        Stmt::ForNumeric {
            var,
            var_ty,
            from,
            to,
            step,
            body,
        } => {
            check_expr(from, scope, errors);
            check_expr(to, scope, errors);
            if let Some(s) = step {
                check_expr(s, scope, errors);
            }
            let mut body_scope = scope.clone();
            let ty = var_ty.clone().unwrap_or(Type::Named("integer".into()));
            body_scope.bind(var.clone(), ty);
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
        }

        Stmt::ForIn { vars, iter, body } => {
            check_expr(iter, scope, errors);
            // If the iter expression is a known class instance, it must
            // implement `Iterable` or `Iterable2` (walking the parent chain).
            if let Some(Type::Named(class_name)) = infer(iter, scope)
                && with_classes(|reg| reg.contains_key(&class_name))
                && !class_implements_iterable(&class_name)
            {
                errors.push(TypeCheckError::NotIterable {
                    class: class_name,
                    span: to_source_span(iter.span.clone()),
                });
            }
            let mut body_scope = scope.clone();
            for (name, ty_opt) in vars {
                if let Some(ty) = ty_opt {
                    body_scope.bind(name.clone(), ty.clone());
                }
            }
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
        }

        Stmt::Return(values) => {
            for v in values {
                check_expr(v, scope, errors);
            }
        }

        Stmt::Throw(e) => check_expr(e, scope, errors),

        Stmt::Try {
            body,
            catch_var,
            catch_ty,
            catch_body,
        } => {
            let mut body_scope = scope.clone();
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
            let mut catch_scope = scope.clone();
            catch_scope.bind(catch_var.clone(), catch_ty.clone());
            for s in catch_body {
                check_stmt(&s.value, &mut catch_scope, errors);
            }
        }

        Stmt::Break | Stmt::Continue => {}
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Declaration walker.
// ──────────────────────────────────────────────────────────────────────────────

fn check_decl(decl: &Decl, errors: &mut Vec<TypeCheckError>) {
    match decl {
        Decl::Class {
            name: class_name,
            members,
            ..
        } => check_class(class_name, members, errors),
        Decl::Function {
            type_params,
            params,
            return_ty,
            body,
            ..
        } => {
            let prev_generics = push_generics(type_params);
            let mut scope = Scope::default();
            check_default_params(params, &scope, errors);
            seed_params(&mut scope, params);
            for s in body {
                check_stmt(&s.value, &mut scope, errors);
            }
            if let Some(rt) = return_ty {
                check_returns(body, rt, &scope, errors);
            }
            pop_generics(prev_generics);
        }
        _ => {}
    }
}

fn seed_params(scope: &mut Scope, params: &[Param]) {
    for p in params {
        scope.bind(p.name.clone(), p.ty.clone());
    }
}

/// Check each parameter default against the declared parameter type.
fn check_default_params(params: &[Param], scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    for p in params {
        if let Some(d) = &p.default
            && !is_assignment_compatible(&p.ty, d, scope)
        {
            errors.push(TypeCheckError::DefaultParamTypeMismatch {
                param: p.name.clone(),
                ty: type_to_string(&p.ty),
                span: to_source_span(d.span.clone()),
            });
        }
    }
}

/// Walk a function/method body looking for `return v` statements whose first
/// value can be proved incompatible with `return_ty`.
fn check_returns(
    body: &[Spanned<Stmt>],
    return_ty: &Type,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    for s in body {
        walk_returns(&s.value, return_ty, scope, errors);
    }
}

fn walk_returns(
    stmt: &Stmt,
    return_ty: &Type,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    match stmt {
        Stmt::Return(values) => {
            if let Some(v) = values.first()
                && !is_assignment_compatible(return_ty, v, scope)
            {
                errors.push(TypeCheckError::WrongReturnType {
                    ty: type_to_string(return_ty),
                    span: to_source_span(v.span.clone()),
                });
            }
        }
        Stmt::If {
            then_block,
            elseifs,
            else_block,
            ..
        } => {
            for s in then_block {
                walk_returns(&s.value, return_ty, scope, errors);
            }
            for (_, b) in elseifs {
                for s in b {
                    walk_returns(&s.value, return_ty, scope, errors);
                }
            }
            if let Some(b) = else_block {
                for s in b {
                    walk_returns(&s.value, return_ty, scope, errors);
                }
            }
        }
        Stmt::While { body, .. }
        | Stmt::Repeat { body, .. }
        | Stmt::ForNumeric { body, .. }
        | Stmt::ForIn { body, .. } => {
            for s in body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
        }
        Stmt::Try {
            body, catch_body, ..
        } => {
            for s in body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
            for s in catch_body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
        }
        _ => {}
    }
}

/// True when we can *prove* the value is incompatible-free with the target
/// type. Returns true when we can't decide (conservative: don't false-positive).
fn is_assignment_compatible(decl_ty: &Type, value: &Spanned<Expr>, scope: &Scope) -> bool {
    if is_nullable(decl_ty) {
        // Nullable target accepts anything we can express.
        return true;
    }
    if matches!(value.value, Expr::Nil) {
        return false;
    }
    let Some(value_ty) = infer(value, scope) else {
        return true;
    };
    if is_nullable(&value_ty) {
        return false;
    }
    match (decl_ty, &value_ty) {
        (Type::Named(a), Type::Named(b)) => {
            if a == b || a == "any" || b == "any" {
                true
            } else if is_type_param(a) || is_type_param(b) {
                // Generic type parameters in scope match anything.
                true
            } else {
                // Allow numeric literals in either direction only when same name.
                false
            }
        }
        _ => true,
    }
}

fn check_class(
    class_name: &str,
    members: &[Spanned<ClassMember>],
    errors: &mut Vec<TypeCheckError>,
) {
    // Locate the constructor body: the non-static `fn init` method.
    let mut ctor_body: Option<&Vec<Spanned<Stmt>>> = None;
    for m in members {
        match &m.value {
            ClassMember::Method(Method {
                name,
                is_static: false,
                body,
                ..
            }) if name == "init" => {
                ctor_body = Some(body);
            }
            _ => {}
        }
    }

    // Validate field defaults: `local x: string = nil` is an error regardless
    // of whether a constructor exists or the field is static.
    for m in members {
        if let ClassMember::Field {
            ty,
            default: Some(default_expr),
            ..
        } = &m.value
        {
            let scope = Scope::default();
            check_assignment_compat(ty, default_expr, &scope, errors);
        }
    }

    if let Some(body) = ctor_body {
        let mut assigned: Vec<String> = Vec::new();
        for s in body {
            collect_self_assignments(&s.value, &mut assigned);
        }
        for m in members {
            if let ClassMember::Field {
                is_static: false,
                name,
                ty,
                default,
                ..
            } = &m.value
            {
                if default.is_some() || is_nullable(ty) {
                    continue;
                }
                if !assigned.iter().any(|a| a == name) {
                    errors.push(TypeCheckError::FieldNotInitialized {
                        class: class_name.to_string(),
                        field: name.clone(),
                        span: to_source_span(m.span.clone()),
                    });
                }
            }
        }
    }

    // Walk every method body with a scope seeded from its parameters,
    // and within `CURRENT_CLASS` set so private-member checks know we're
    // *inside* `class_name`. Also validate default parameters and return types.
    let prev = set_current_class(Some(class_name.to_string()));
    for m in members {
        if let ClassMember::Method(meth) = &m.value {
            let prev_generics = push_generics(&meth.type_params);
            let mut scope = Scope::default();
            // `self` resolves to the class itself in `static fn` and to an
            // instance otherwise. Seed it as the class name so member-existence
            // checks on `self.foo` consult the class registry.
            scope.bind("self".to_string(), Type::Named(class_name.to_string()));
            check_default_params(&meth.params, &scope, errors);
            seed_params(&mut scope, &meth.params);
            for s in &meth.body {
                check_stmt(&s.value, &mut scope, errors);
            }
            if let Some(rt) = &meth.return_ty {
                check_returns(&meth.body, rt, &scope, errors);
            }
            pop_generics(prev_generics);
        }
    }
    set_current_class(prev);
}

// ──────────────────────────────────────────────────────────────────────────────
// Expression checker — walks expressions looking for `obj.member` /
// `obj.method(...)` where `obj` has a statically-known nullable type.
// ──────────────────────────────────────────────────────────────────────────────

fn check_expr(expr: &Spanned<Expr>, scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    match &expr.value {
        Expr::Member { obj, name } => {
            check_expr(obj, scope, errors);
            report_if_nullable_receiver(obj, name, scope, errors);
            report_if_private(obj, name, scope, errors);
        }
        Expr::MethodCall { obj, method, args } => {
            check_expr(obj, scope, errors);
            report_if_nullable_receiver(obj, method, scope, errors);
            report_if_private(obj, method, scope, errors);
            for a in args {
                check_arg(a, scope, errors);
            }
        }
        Expr::Call { callee, args } => {
            // `obj.method(args)` is parsed as Call(Member { obj, name }, args)
            // — same nullable-receiver rule applies.
            if let Expr::Member { obj, name } = &callee.value {
                check_expr(obj, scope, errors);
                report_if_nullable_receiver(obj, name, scope, errors);
                report_if_private(obj, name, scope, errors);
            } else {
                check_expr(callee, scope, errors);
            }
            for a in args {
                check_arg(a, scope, errors);
            }
            // If the callee resolves to a known native signature, check the
            // argument types positionally. Named arguments are skipped (those
            // aren't supported on natives anyway, and they error at runtime).
            if let Some(qname) = native_callee_name(callee)
                && let Some(sig) = crate::stdlib::sigs::lookup(&qname)
            {
                check_native_args(&qname, &sig, args, scope, errors, expr.span.clone());
            }
        }
        Expr::SafeMember { obj, .. } => check_expr(obj, scope, errors),
        Expr::Index { obj, index } => {
            check_expr(obj, scope, errors);
            check_expr(index, scope, errors);
        }
        Expr::Unary { rhs, .. } => check_expr(rhs, scope, errors),
        Expr::Binary { lhs, rhs, .. } => {
            check_expr(lhs, scope, errors);
            check_expr(rhs, scope, errors);
        }
        Expr::ForceUnwrap(inner) => check_expr(inner, scope, errors),
        Expr::Table(items) => {
            for e in items {
                check_expr(e, scope, errors);
            }
        }
        Expr::Lambda { params, body, .. } => {
            let mut lscope = scope.clone();
            seed_params(&mut lscope, params);
            match body {
                LambdaBody::Expr(e) => check_expr(e, &lscope, errors),
                LambdaBody::Block(stmts) => {
                    for s in stmts {
                        check_stmt(&s.value, &mut lscope, errors);
                    }
                }
            }
        }
        _ => {}
    }
}

fn check_arg(arg: &CallArg, scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    match arg {
        CallArg::Positional(e) | CallArg::Named { value: e, .. } => check_expr(e, scope, errors),
    }
}

/// Check positional arguments of a native call against the registered
/// signature. Skips named arguments (natives don't support them; the runtime
/// will surface that as an error).
///
/// Heuristics intentionally lenient:
///   * `any` and `T?` parameters accept anything (incl. nil) — they're the
///     "I'll figure it out" slots.
///   * Variadic / over-supplied calls aren't penalised when the declared
///     param list runs out — many natives accept `...rest` (variadic) which
///     isn't expressed in the sig yet.
///   * If `infer` can't produce a type for the argument, we skip silently.
fn check_native_args(
    callee: &str,
    sig: &crate::stdlib::sigs::NativeSig,
    args: &[CallArg],
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
    call_span: std::ops::Range<usize>,
) {
    // Count required positional params (every param up to the first
    // nullable / `any` is required — nullable+`any` slots are optional).
    let required: usize = sig
        .params
        .iter()
        .take_while(|p| !is_nullable(p) && !is_any(p))
        .count();
    let positional: Vec<&CallArg> = args.iter().filter(|a| matches!(a, CallArg::Positional(_))).collect();
    if positional.len() < required {
        errors.push(TypeCheckError::NativeArity {
            callee: callee.to_string(),
            expected: required,
            found: positional.len(),
            span: to_source_span(call_span.clone()),
        });
        return;
    }

    // Reject extras when the native is not variadic. Don't bail though —
    // continue checking the known positions for type mismatches.
    if sig.variadic.is_none() && positional.len() > sig.params.len() {
        errors.push(TypeCheckError::NativeArity {
            callee: callee.to_string(),
            expected: sig.params.len(),
            found: positional.len(),
            span: to_source_span(call_span),
        });
    }

    for (i, arg) in args.iter().enumerate() {
        // Pick the expected type for slot `i`:
        //   - within declared params: use `params[i]`
        //   - past the end: use the variadic element type (or stop if absent)
        let expected = match sig.params.get(i) {
            Some(t) => t,
            None => match &sig.variadic {
                Some(t) => t,
                None => break,
            },
        };
        let value_expr = match arg {
            CallArg::Positional(e) => e,
            CallArg::Named { .. } => continue,
        };
        if is_any(expected) {
            continue;
        }
        let Some(found_ty) = infer(value_expr, scope) else {
            continue;
        };
        if !types_compatible(expected, &found_ty) {
            errors.push(TypeCheckError::NativeArgTypeMismatch {
                callee: callee.to_string(),
                arg: i + 1,
                expected: type_to_string(expected),
                found: type_to_string(&found_ty),
                span: to_source_span(value_expr.span.clone()),
            });
        }
    }
}

fn is_any(t: &Type) -> bool {
    matches!(t, Type::Named(n) if n == "any")
}

fn report_if_nullable_receiver(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(ty) = infer(obj, scope)
        && is_nullable(&ty)
    {
        errors.push(TypeCheckError::NullableMemberAccess {
            ty: type_to_string(&ty),
            member: member.to_string(),
            span: to_source_span(obj.span.clone()),
        });
    }
}

/// Reject access to `local` (private) members from outside the owning class.
/// `self.foo` is allowed only when the *owning* class of `foo` is the class
/// currently being checked — a private field inherited from a parent is
/// **not** visible to the child.
fn report_if_private(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    // Resolve the class name we're reading the member off:
    //   * `self.member` → the current class (lookup walks the parent chain).
    //   * `obj.member` where `obj` is an *instance* → infer the receiver type.
    //   * `Class.member` where the receiver is the class itself
    //     (e.g. `Bank.secret`) → use the ident directly.
    let class_name = match &obj.value {
        Expr::Self_ => match current_class() {
            Some(n) => n,
            None => return,
        },
        Expr::Ident(n) if with_classes(|reg| reg.contains_key(n)) => n.clone(),
        _ => match infer(obj, scope) {
            Some(ty) => match strip_nullable(ty) {
                Type::Named(n) => n,
                _ => return,
            },
            None => return,
        },
    };
    let Some((owning, is_private)) = lookup_member(&class_name, member) else {
        return;
    };
    if is_private && current_class().as_deref() != Some(owning.as_str()) {
        errors.push(TypeCheckError::PrivateMemberAccess {
            class: owning,
            member: member.to_string(),
            span: to_source_span(obj.span.end..obj.span.end + member.len() + 1),
        });
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Assignment compatibility — only flags the cases we can prove are wrong.
// ──────────────────────────────────────────────────────────────────────────────

fn check_assignment_compat(
    decl_ty: &Type,
    value: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if is_nullable(decl_ty) {
        return;
    }
    if matches!(value.value, Expr::Nil) {
        errors.push(TypeCheckError::NilToNonNullable {
            ty: type_to_string(decl_ty),
            span: to_source_span(value.span.clone()),
        });
        return;
    }

    // Table-aware checks for array-style literals assigned to a typed table.
    if let (Type::Table { key, value: elem_ty }, Expr::Table(items)) = (decl_ty, &value.value) {
        // `{a, b, c}` literal cannot fill a map-typed table whose key is not
        // integer-compatible.
        if let Some(k) = key
            && !is_integer_like(k)
            && !items.is_empty()
        {
            errors.push(TypeCheckError::TableArrayLiteralForMap {
                key: type_to_string(k),
                value: type_to_string(elem_ty),
                span: to_source_span(value.span.clone()),
            });
            return;
        }
        // Each element must match the declared value type.
        for item in items {
            check_element_compat(elem_ty, item, scope, errors);
        }
        return;
    }

    if let Some(value_ty) = infer(value, scope)
        && is_nullable(&value_ty)
    {
        errors.push(TypeCheckError::NullableToNonNullable {
            from: type_to_string(&value_ty),
            to: type_to_string(decl_ty),
            span: to_source_span(value.span.clone()),
        });
    }
}

/// Index key must match the table's declared key type.
fn check_table_key_compat(
    expected: &Type,
    index: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(idx_ty) = infer(index, scope)
        && !types_compatible(expected, &idx_ty)
    {
        errors.push(TypeCheckError::TableKeyTypeMismatch {
            expected: type_to_string(expected),
            found: type_to_string(&idx_ty),
            span: to_source_span(index.span.clone()),
        });
    }
}

/// True for `integer` and `any` — the key types that an array-style literal
/// can satisfy.
fn is_integer_like(ty: &Type) -> bool {
    matches!(ty, Type::Named(n) if n == "integer" || n == "any")
}

/// Element-of-table compatibility — accepts literals/`Ident`s whose inferred
/// type matches, and stays quiet otherwise (conservative).
fn check_element_compat(
    expected: &Type,
    value: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(value_ty) = infer(value, scope)
        && !types_compatible(expected, &value_ty)
    {
        errors.push(TypeCheckError::TableElementTypeMismatch {
            expected: type_to_string(expected),
            found: type_to_string(&value_ty),
            span: to_source_span(value.span.clone()),
        });
    }
}

/// Conservative type compatibility — names match (or either is `any`), or
/// `value_ty` is `Nullable` of a compatible inner, etc.
fn types_compatible(expected: &Type, value_ty: &Type) -> bool {
    match (expected, value_ty) {
        // Same-name primitives, plus `any` on either side, plus `nil` on the
        // value side (nil is universally assignable; nullable-rejection is
        // handled separately by `NullableToNonNullable`).
        (Type::Named(a), Type::Named(b)) => {
            if a == b || a == "any" || b == "any" || b == "nil" {
                return true;
            }
            // Generic type parameters in scope match anything — they're
            // effectively `any` from the body's point of view.
            if is_type_param(a) || is_type_param(b) {
                return true;
            }
            // `number` is the sentinel used in native sigs to mean
            // "integer or float" — accept either.
            if a == "number" && (b == "integer" || b == "float" || b == "number") {
                return true;
            }
            // Class/interface subtyping: a value of type `b` is assignable to
            // a slot of type `a` if `b` is a subtype of `a` (class implements
            // interface, class extends class, interface extends interface).
            if is_subtype_named(b, a) {
                return true;
            }
            false
        }
        // `table<any>` (or `table<any, any>`) matches any table — used by
        // native sigs like `pairs(t)` / `Table.insert(t, ...)` to mean
        // "any table".
        (
            Type::Table { key: ek, value: ev },
            Type::Table { key: vk, value: vv },
        ) => {
            let key_ok = match (ek, vk) {
                (None, None) => true,
                (Some(a), Some(b)) => types_compatible(a, b),
                // Cross-shape (`table<T>` vs `table<K, V>`) only when one
                // side is the `any` wildcard.
                _ => is_any(ev),
            };
            key_ok && (is_any(ev) || types_compatible(ev, vv))
        }
        // Expected table, but value is the bare type-name `table`, `any` or
        // `nil` — accept (caller has erased the element type, or it's nil).
        (Type::Table { .. }, Type::Named(n)) if n == "table" || n == "any" || n == "nil" => true,
        // Expected `any` / `table` / `nil` named slot, value is a table —
        // accept (we widen to the named slot).
        (Type::Named(n), Type::Table { .. }) if n == "table" || n == "any" => true,
        (Type::Nullable(a), b) => types_compatible(a, b),
        (a, Type::Nullable(b)) => types_compatible(a, b),
        // Function / Tuple shapes — only equal-shape is strictly compatible,
        // but the checker doesn't track those precisely yet. Accept rather
        // than emit false positives.
        (Type::Function { .. }, Type::Function { .. }) => true,
        (Type::Tuple(_), Type::Tuple(_)) => true,
        // Different kinds (e.g. table vs integer) — reject.
        _ => false,
    }
}

/// Reject `if`/`while`/`until` conditions that the type system can prove are
/// not `boolean`. Conservative: when `infer` can't determine a type, we skip
/// silently so calls and dynamic expressions keep working.
fn check_boolean_cond(
    construct: &'static str,
    cond: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let Some(ty) = infer(cond, scope) else {
        return;
    };
    let is_bool = matches!(&ty, Type::Named(n) if n == "boolean" || n == "any");
    if !is_bool {
        errors.push(TypeCheckError::NonBooleanCondition {
            construct,
            found: type_to_string(&ty),
            span: to_source_span(cond.span.clone()),
        });
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Lightweight type inference.
//
// Returns `Some(ty)` only when we can prove the type. Anything we can't see
// through (calls, member reads on unknown classes, indexing) returns `None`,
// and callers treat that as "don't know, don't complain".
// ──────────────────────────────────────────────────────────────────────────────

fn infer(expr: &Spanned<Expr>, scope: &Scope) -> Option<Type> {
    match &expr.value {
        Expr::Nil => Some(Type::Named("nil".into())),
        Expr::Int(_) => Some(Type::Named("integer".into())),
        Expr::Float(_) => Some(Type::Named("float".into())),
        Expr::Bool(_) => Some(Type::Named("boolean".into())),
        Expr::Str(_) => Some(Type::Named("string".into())),
        Expr::Ident(n) => scope.lookup(n).cloned(),
        Expr::SafeMember { .. } => Some(Type::Nullable(Box::new(Type::Named("any".into())))),
        Expr::ForceUnwrap(inner) => match infer(inner, scope)? {
            Type::Nullable(t) => Some(*t),
            other => Some(other),
        },
        Expr::Binary { op, lhs, rhs } => match op {
            BinOp::Coalesce => {
                // `lhs ?? rhs`: result is non-nullable iff `rhs` is non-nullable.
                match (infer(lhs, scope), infer(rhs, scope)) {
                    (Some(lt), Some(rt)) => {
                        let base = strip_nullable(lt);
                        if is_nullable(&rt) {
                            Some(Type::Nullable(Box::new(base)))
                        } else {
                            Some(base)
                        }
                    }
                    _ => None,
                }
            }
            BinOp::Eq | BinOp::NotEq | BinOp::Lt | BinOp::LtEq | BinOp::Gt | BinOp::GtEq => {
                Some(Type::Named("boolean".into()))
            }
            BinOp::And | BinOp::Or => None,
            BinOp::Concat => Some(Type::Named("string".into())),
            BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod => {
                infer(lhs, scope).or_else(|| infer(rhs, scope))
            }
        },
        // `Foo(args)` where `Foo` is a known class → produces a `Foo`.
        // Otherwise, look up the qualified callee name in the native signature
        // table (e.g. `String.byte`, `Math.tointeger`, `assert`).
        Expr::Call { callee, .. } => {
            if let Expr::Ident(n) = &callee.value
                && with_classes(|reg| reg.contains_key(n))
            {
                Some(Type::Named(n.clone()))
            } else if let Some(qname) = native_callee_name(callee)
                && let Some(sig) = crate::stdlib::sigs::lookup(&qname)
            {
                first_or_tuple(sig.returns)
            } else {
                None
            }
        }
        _ => None,
    }
}

fn strip_nullable(ty: Type) -> Type {
    match ty {
        Type::Nullable(t) => *t,
        other => other,
    }
}

/// Build a qualified callee name suitable for `stdlib::sigs::lookup`:
/// `assert` or `String.byte`.
fn native_callee_name(callee: &Spanned<Expr>) -> Option<String> {
    match &callee.value {
        Expr::Ident(n) => Some(n.clone()),
        Expr::Member { obj, name } => {
            if let Expr::Ident(class) = &obj.value {
                Some(format!("{class}.{name}"))
            } else {
                None
            }
        }
        _ => None,
    }
}

/// Collapse a returns-list into a single inferred type: single returns stay
/// as-is, multi-returns become a `Type::Tuple`.
fn first_or_tuple(returns: Vec<Type>) -> Option<Type> {
    match returns.len() {
        0 => None,
        1 => returns.into_iter().next(),
        _ => Some(Type::Tuple(returns)),
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Flow narrowing.
//
// `narrow_truthy(cond, scope)` — apply the assumptions that hold when `cond`
// is true. Today: `x != nil` and `nil != x` strip `Nullable` off `x`. `and`
// chains compose.
//
// `narrow_falsy(cond, scope)` — apply the assumptions when `cond` is false.
// Used by the else-branch: `if x == nil then ... else ... end` narrows `x`
// in the else.
// ──────────────────────────────────────────────────────────────────────────────

fn narrow_truthy(cond: &Spanned<Expr>, scope: &mut Scope) {
    match &cond.value {
        Expr::Binary {
            op: BinOp::NotEq,
            lhs,
            rhs,
        } => {
            if let Some(name) = pick_ident_compared_to_nil(lhs, rhs)
                && let Some(Type::Nullable(t)) = scope.lookup(name).cloned()
            {
                scope.bind(name.to_string(), *t);
            }
        }
        Expr::Binary {
            op: BinOp::And,
            lhs,
            rhs,
        } => {
            narrow_truthy(lhs, scope);
            narrow_truthy(rhs, scope);
        }
        _ => {}
    }
}

fn narrow_falsy(cond: &Spanned<Expr>, scope: &mut Scope) {
    if let Expr::Binary {
        op: BinOp::Eq,
        lhs,
        rhs,
    } = &cond.value
        && let Some(name) = pick_ident_compared_to_nil(lhs, rhs)
        && let Some(Type::Nullable(t)) = scope.lookup(name).cloned()
    {
        scope.bind(name.to_string(), *t);
    }
}

/// If `lhs` / `rhs` is `(Ident(x), Nil)` in either order, return `Some(x)`.
fn pick_ident_compared_to_nil<'a>(
    lhs: &'a Spanned<Expr>,
    rhs: &'a Spanned<Expr>,
) -> Option<&'a str> {
    match (&lhs.value, &rhs.value) {
        (Expr::Ident(n), Expr::Nil) => Some(n),
        (Expr::Nil, Expr::Ident(n)) => Some(n),
        _ => None,
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Misc helpers.
// ──────────────────────────────────────────────────────────────────────────────

fn type_to_string(ty: &Type) -> String {
    match ty {
        Type::Named(n) => n.clone(),
        Type::Nullable(inner) => format!("{}?", type_to_string(inner)),
        Type::Table { key: None, value } => format!("table<{}>", type_to_string(value)),
        Type::Table {
            key: Some(k),
            value,
        } => format!("table<{}, {}>", type_to_string(k), type_to_string(value)),
        other => format!("{:?}", other),
    }
}

fn is_nullable(ty: &Type) -> bool {
    match ty {
        Type::Nullable(_) => true,
        Type::Named(n) => n == "nil",
        _ => false,
    }
}

/// Walk a statement collecting every `self.NAME` that appears on the LHS of
/// an `=`. Recurses through control-flow statements so an assignment inside
/// an `if` still counts.
fn collect_self_assignments(stmt: &Stmt, out: &mut Vec<String>) {
    match stmt {
        Stmt::Assign { target, .. } => {
            if let Expr::Member { obj, name } = &target.value
                && matches!(obj.value, Expr::Self_)
                && !out.iter().any(|n| n == name)
            {
                out.push(name.clone());
            }
        }
        Stmt::AssignMulti { targets, .. } => {
            for target in targets {
                if let Expr::Member { obj, name } = &target.value
                    && matches!(obj.value, Expr::Self_)
                    && !out.iter().any(|n| n == name)
                {
                    out.push(name.clone());
                }
            }
        }
        Stmt::If {
            then_block,
            elseifs,
            else_block,
            ..
        } => {
            for s in then_block {
                collect_self_assignments(&s.value, out);
            }
            for (_, block) in elseifs {
                for s in block {
                    collect_self_assignments(&s.value, out);
                }
            }
            if let Some(block) = else_block {
                for s in block {
                    collect_self_assignments(&s.value, out);
                }
            }
        }
        Stmt::While { body, .. }
        | Stmt::Repeat { body, .. }
        | Stmt::ForNumeric { body, .. }
        | Stmt::ForIn { body, .. } => {
            for s in body {
                collect_self_assignments(&s.value, out);
            }
        }
        Stmt::Try {
            body, catch_body, ..
        } => {
            for s in body {
                collect_self_assignments(&s.value, out);
            }
            for s in catch_body {
                collect_self_assignments(&s.value, out);
            }
        }
        _ => {}
    }
}

//! Static checks performed between parsing and evaluation.
//!
//! Two flavours of checks live here:
//!
//! 1. **Field initialization** — every non-nullable instance field of a class
//!    with a constructor must be assigned `self.field = ...` somewhere inside
//!    that constructor's body. Fields with defaults are exempt; nullable
//!    fields (`name: string?`) are exempt by design.
//!
//! 2. **Null safety** — values whose static type is nullable cannot be
//!    silently assigned to non-nullable bindings, and members cannot be read
//!    off a nullable receiver without `?.` / `!` / a prior nil-guard. A
//!    lightweight flow-narrowing pass treats `if x != nil then ... end` as
//!    proving `x` is non-nullable inside the then-block (and symmetrically
//!    for `if x == nil ... else ...`).
//!
//! The expression type inference here is intentionally partial: when the
//! checker can't prove a type (e.g. calls, member reads on unknown classes),
//! it returns `None` and conservatively skips the check rather than producing
//! a false positive.

use std::collections::{HashMap, HashSet};
use std::ops::Range;

use miette::Diagnostic;
use saule_ast::{
    BinOp, CallArg, ClassMember, Decl, EnumVariant, Expr, LambdaBody, MatchArm, MatchBody, Method,
    Module, Param, Pattern, Spanned, Stmt, Type,
};
use thiserror::Error;

/// One diagnostic produced by [`check`]. Carries a `miette` source span so
/// the CLI can render it with the offending snippet underlined.
#[derive(Debug, Error, Diagnostic)]
pub enum TypeCheckError {
    #[error("field `{field}` of class `{class}` is never initialized")]
    #[diagnostic(help(
        "assign `self.{field} = ...` in `init`, give the field a default value, or mark it nullable with `?`"
    ))]
    FieldNotInitialized {
        class: String,
        field: String,
        #[label("declared here")]
        span: miette::SourceSpan,
    },

    #[error("cannot assign `nil` to non-nullable type `{ty}`")]
    #[diagnostic(help(
        "mark the type nullable with `?` (e.g. `{ty}?`) or initialize it with a non-nil value"
    ))]
    NilToNonNullable {
        ty: String,
        #[label("`nil` not allowed here")]
        span: miette::SourceSpan,
    },

    #[error("cannot assign a nullable value of type `{from}` to non-nullable type `{to}`")]
    #[diagnostic(help(
        "guard with `if x != nil then ... end`, use `??` to provide a fallback, or force-unwrap with `!`"
    ))]
    NullableToNonNullable {
        from: String,
        to: String,
        #[label("this expression may be `nil`")]
        span: miette::SourceSpan,
    },

    #[error("cannot access `{member}` on nullable type `{ty}`")]
    #[diagnostic(help(
        "use `?.` for safe access, `!` to force-unwrap, or guard with `if x != nil then ... end`"
    ))]
    NullableMemberAccess {
        ty: String,
        member: String,
        #[label("receiver may be `nil`")]
        span: miette::SourceSpan,
    },

    #[error("default value for parameter `{param}` is incompatible with declared type `{ty}`")]
    #[diagnostic(help(
        "the default expression must produce a value of type `{ty}`"
    ))]
    DefaultParamTypeMismatch {
        param: String,
        ty: String,
        #[label("default here")]
        span: miette::SourceSpan,
    },

    #[error("return value is incompatible with declared return type `{ty}`")]
    #[diagnostic(help("this function must return a `{ty}`"))]
    WrongReturnType {
        ty: String,
        #[label("returned here")]
        span: miette::SourceSpan,
    },

    #[error("cannot access private member `{member}` of class `{class}` from outside the class")]
    #[diagnostic(help(
        "`local` fields and methods are only accessible from within `{class}`"
    ))]
    PrivateMemberAccess {
        class: String,
        member: String,
        #[label("private")]
        span: miette::SourceSpan,
    },

    #[error("table value of type `{found}` is incompatible with declared element type `{expected}`")]
    #[diagnostic(help(
        "every value stored in this table must be a `{expected}`"
    ))]
    TableElementTypeMismatch {
        expected: String,
        found: String,
        #[label("wrong value type")]
        span: miette::SourceSpan,
    },

    #[error("table key of type `{found}` is incompatible with declared key type `{expected}`")]
    #[diagnostic(help(
        "this table is declared with key type `{expected}` — pass an index of that type"
    ))]
    TableKeyTypeMismatch {
        expected: String,
        found: String,
        #[label("wrong key type")]
        span: miette::SourceSpan,
    },

    #[error("cannot initialise `table<{key}, {value}>` with an array-style literal")]
    #[diagnostic(help(
        "array-style `{{ ... }}` literals can only fill `table<T>` (integer-keyed); start from `{{}}` and assign by key instead"
    ))]
    TableArrayLiteralForMap {
        key: String,
        value: String,
        #[label("array literal not allowed for a map-typed table")]
        span: miette::SourceSpan,
    },

    #[error("cannot iterate over a `{class}` — it does not implement `Iterable` or `Iterable2`")]
    #[diagnostic(help(
        "add `implements Iterable<T>` (or `Iterable2<K, V>`) to `{class}` and define `fn iter() -> fn(): T?` returning a step closure"
    ))]
    NotIterable {
        class: String,
        #[label("class is not iterable")]
        span: miette::SourceSpan,
    },

    #[error("argument {arg} of `{callee}` expects `{expected}`, got `{found}`")]
    #[diagnostic(help(
        "pass a value of type `{expected}` here — check the signature of `{callee}`"
    ))]
    NativeArgTypeMismatch {
        callee: String,
        arg: usize,
        expected: String,
        found: String,
        #[label("wrong argument type")]
        span: miette::SourceSpan,
    },

    #[error("`{callee}` expects {expected} argument(s), got {found}")]
    #[diagnostic(help("check the signature of `{callee}`"))]
    NativeArity {
        callee: String,
        expected: usize,
        found: usize,
        #[label("wrong number of arguments")]
        span: miette::SourceSpan,
    },

    #[error("`{construct}` condition must be a `boolean`, got `{found}`")]
    #[diagnostic(help(
        "compare with `==`, `!=`, `<`, `>` etc., or use `?? false` / `!= nil` to coerce a nullable to a `boolean`"
    ))]
    NonBooleanCondition {
        construct: &'static str,
        found: String,
        #[label("not a boolean")]
        span: miette::SourceSpan,
    },

    #[error("non-exhaustive `match`: {reason}")]
    #[diagnostic(help(
        "add a wildcard arm `case _ then ...` or cover the remaining cases explicitly"
    ))]
    MatchNonExhaustive {
        reason: String,
        #[label("not all cases covered")]
        span: miette::SourceSpan,
    },

    #[error("`match` arms produce incompatible types: `{expected}` vs `{found}`")]
    #[diagnostic(help("every arm of a `match` expression must evaluate to the same type"))]
    MatchArmTypeMismatch {
        expected: String,
        found: String,
        #[label("arms disagree on result type")]
        span: miette::SourceSpan,
    },

    #[error("pattern of type `{found}` cannot match scrutinee of type `{expected}`")]
    #[diagnostic(help("change the pattern to match the scrutinee's type"))]
    MatchPatternTypeMismatch {
        expected: String,
        found: String,
        #[label("incompatible pattern")]
        span: miette::SourceSpan,
    },

    #[error("enum `{enum_name}` has no variant `{variant}`")]
    #[diagnostic(help("check the spelling of the variant or add it to the enum"))]
    MatchUnknownVariant {
        enum_name: String,
        variant: String,
        #[label("unknown variant")]
        span: miette::SourceSpan,
    },

    #[error("variant `{variant}` expects {expected} field(s), got {found}")]
    #[diagnostic(help("supply a sub-pattern for every payload field of the variant"))]
    MatchVariantArityMismatch {
        variant: String,
        expected: usize,
        found: usize,
        #[label("wrong number of sub-patterns")]
        span: miette::SourceSpan,
    },
}

fn to_source_span(r: Range<usize>) -> miette::SourceSpan {
    (r.start, r.end.saturating_sub(r.start)).into()
}

// ──────────────────────────────────────────────────────────────────────────────
// Scope: tracks the static types of `local` bindings in lexical scope.
// ──────────────────────────────────────────────────────────────────────────────

#[derive(Default, Clone)]
struct Scope {
    vars: HashMap<String, Type>,
}

impl Scope {
    fn lookup(&self, name: &str) -> Option<&Type> {
        self.vars.get(name)
    }

    fn bind(&mut self, name: String, ty: Type) {
        self.vars.insert(name, ty);
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Public entry point.
// ──────────────────────────────────────────────────────────────────────────────

/// Class info collected by a pre-pass so member-access checks can consult
/// member visibility, parent classes, etc.
#[derive(Default, Clone)]
struct ClassInfo {
    parent: Option<String>,
    /// Interfaces declared on the class (`class C implements A, B`).
    implements: Vec<String>,
    /// member name -> is_private
    members: HashMap<String, bool>,
}

type ClassRegistry = HashMap<String, ClassInfo>;
type InterfaceRegistry = HashMap<String, Vec<String>>;

/// Enum info: variant name -> payload arity (0 for `Bare` / `Valued`,
/// N for `Tuple { fields: [...; N] }`).
#[derive(Default, Clone)]
struct EnumInfo {
    variants: HashMap<String, usize>,
}
type EnumRegistry = HashMap<String, EnumInfo>;

thread_local! {
    static CLASSES: std::cell::RefCell<ClassRegistry> = std::cell::RefCell::new(HashMap::new());
    static INTERFACES: std::cell::RefCell<InterfaceRegistry> = std::cell::RefCell::new(HashMap::new());
    static ENUMS: std::cell::RefCell<EnumRegistry> = std::cell::RefCell::new(HashMap::new());
    static CURRENT_CLASS: std::cell::RefCell<Option<String>> = const { std::cell::RefCell::new(None) };

    /// Generic type-parameter names in scope for the function/method body
    /// currently being checked. Treated as `any`-equivalent so that
    /// `table<T>`, `T?`, and bare `T` accept any concrete instantiation.
    static GENERICS: std::cell::RefCell<std::collections::HashSet<String>> =
        std::cell::RefCell::new(std::collections::HashSet::new());
}

fn with_classes<R>(f: impl FnOnce(&ClassRegistry) -> R) -> R {
    CLASSES.with(|c| f(&c.borrow()))
}

fn with_interfaces<R>(f: impl FnOnce(&InterfaceRegistry) -> R) -> R {
    INTERFACES.with(|c| f(&c.borrow()))
}

fn with_enums<R>(f: impl FnOnce(&EnumRegistry) -> R) -> R {
    ENUMS.with(|c| f(&c.borrow()))
}

/// Is `iface` a known interface name?
fn is_interface(name: &str) -> bool {
    with_interfaces(|r| r.contains_key(name))
}

/// Does `iface` extend `target` (transitively, including itself)?
fn interface_extends(iface: &str, target: &str) -> bool {
    if iface == target {
        return true;
    }
    with_interfaces(|r| {
        let mut stack: Vec<String> = vec![iface.to_string()];
        let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
        while let Some(cur) = stack.pop() {
            if !seen.insert(cur.clone()) {
                continue;
            }
            if cur == target {
                return true;
            }
            if let Some(parents) = r.get(&cur) {
                for p in parents {
                    stack.push(p.clone());
                }
            }
        }
        false
    })
}

/// Does class `class` (or any ancestor) implement interface `target`
/// (directly or via interface composition)?
fn class_implements(class: &str, target: &str) -> bool {
    with_classes(|reg| {
        let mut cur = Some(class.to_string());
        while let Some(name) = cur {
            let Some(info) = reg.get(&name) else {
                return false;
            };
            for i in &info.implements {
                if interface_extends(i, target) {
                    return true;
                }
            }
            cur = info.parent.clone();
        }
        false
    })
}

/// `got` is a subtype of `expected` when:
/// - they're equal, OR
/// - `expected` is an interface and `got` is a class implementing it
///   (directly or via a parent), OR
/// - both are interfaces and `got` extends `expected`, OR
/// - `got` is a class that extends `expected` (class inheritance).
fn is_subtype_named(got: &str, expected: &str) -> bool {
    if got == expected {
        return true;
    }
    // Class → interface
    if is_interface(expected) && class_implements(got, expected) {
        return true;
    }
    // Interface → interface
    if is_interface(got) && is_interface(expected) && interface_extends(got, expected) {
        return true;
    }
    // Class → ancestor class
    with_classes(|reg| {
        let mut cur = reg.get(got).and_then(|i| i.parent.clone());
        while let Some(name) = cur {
            if name == expected {
                return true;
            }
            cur = reg.get(&name).and_then(|i| i.parent.clone());
        }
        false
    })
}

fn current_class() -> Option<String> {
    CURRENT_CLASS.with(|c| c.borrow().clone())
}

fn set_current_class(name: Option<String>) -> Option<String> {
    CURRENT_CLASS.with(|c| std::mem::replace(&mut *c.borrow_mut(), name))
}

/// Add `params` to the in-scope generic set. Returns the names actually
/// inserted so the matching [`pop_generics`] can remove just those (and
/// preserve any outer generics that share a name).
fn push_generics(params: &[String]) -> Vec<String> {
    let mut added = Vec::new();
    GENERICS.with(|g| {
        let mut set = g.borrow_mut();
        for p in params {
            if set.insert(p.clone()) {
                added.push(p.clone());
            }
        }
    });
    added
}

fn pop_generics(added: Vec<String>) {
    GENERICS.with(|g| {
        let mut set = g.borrow_mut();
        for p in added {
            set.remove(&p);
        }
    });
}

/// True if `name` names a type parameter in scope for the current body.
fn is_type_param(name: &str) -> bool {
    GENERICS.with(|g| g.borrow().contains(name))
}

/// Look up `member` on `class` (walking the parent chain). Returns
/// `Some((owning_class, is_private))` if found.
fn lookup_member(class: &str, member: &str) -> Option<(String, bool)> {
    with_classes(|reg| {
        let mut cur = Some(class.to_string());
        while let Some(name) = cur {
            if let Some(info) = reg.get(&name) {
                if let Some(&priv_) = info.members.get(member) {
                    return Some((name, priv_));
                }
                cur = info.parent.clone();
            } else {
                return None;
            }
        }
        None
    })
}

/// Does the class (or any ancestor) declare it implements `Iterable` or
/// `Iterable2`? Used by the `for ... in` static check.
fn class_implements_iterable(class: &str) -> bool {
    class_implements(class, "Iterable") || class_implements(class, "Iterable2")
}

fn build_registry(module: &Module) -> (ClassRegistry, InterfaceRegistry, EnumRegistry) {
    let mut reg = ClassRegistry::new();
    let mut ifaces = InterfaceRegistry::new();
    let mut enums = EnumRegistry::new();
    for stmt in &module.stmts {
        if let Stmt::Decl(d) = &stmt.value {
            match &d.value {
                Decl::Class {
                    name,
                    extends,
                    implements,
                    members,
                    ..
                } => {
                    let mut info = ClassInfo {
                        parent: extends.clone(),
                        implements: implements.clone(),
                        members: HashMap::new(),
                    };
                    for m in members {
                        match &m.value {
                            ClassMember::Field {
                                name, is_private, ..
                            } => {
                                info.members.insert(name.clone(), *is_private);
                            }
                            ClassMember::Method(meth) => {
                                info.members.insert(meth.name.clone(), meth.is_private);
                            }
                        }
                    }
                    reg.insert(name.clone(), info);
                }
                Decl::Interface { name, extends, .. } => {
                    ifaces.insert(name.clone(), extends.clone());
                }
                Decl::Enum { name, variants, .. } => {
                    let mut info = EnumInfo::default();
                    for v in variants {
                        let (vname, arity) = match &v.value {
                            EnumVariant::Bare(n) => (n.clone(), 0),
                            EnumVariant::Valued(n, _) => (n.clone(), 0),
                            EnumVariant::Tuple { name, fields } => (name.clone(), fields.len()),
                        };
                        info.variants.insert(vname, arity);
                    }
                    enums.insert(name.clone(), info);
                }
                _ => {}
            }
        }
    }
    // Pre-register the builtin iterable interfaces so class-implements checks
    // see them even without explicit declarations in user code.
    ifaces.entry("Iterable".into()).or_default();
    ifaces.entry("Iterable2".into()).or_default();
    (reg, ifaces, enums)
}

/// Run the static checks on a parsed module. Returns *all* errors found so
/// the user sees everything in one pass.
pub fn check(module: &Module) -> Vec<TypeCheckError> {
    let (reg, ifaces, enums) = build_registry(module);
    CLASSES.with(|c| *c.borrow_mut() = reg);
    INTERFACES.with(|c| *c.borrow_mut() = ifaces);
    ENUMS.with(|c| *c.borrow_mut() = enums);
    let _restore = set_current_class(None);
    let mut errors = Vec::new();
    let mut scope = Scope::default();
    for stmt in &module.stmts {
        check_stmt(&stmt.value, &mut scope, &mut errors);
    }
    CLASSES.with(|c| c.borrow_mut().clear());
    INTERFACES.with(|c| c.borrow_mut().clear());
    ENUMS.with(|c| c.borrow_mut().clear());
    errors
}

// ──────────────────────────────────────────────────────────────────────────────
// Statement walker. Threads a `Scope` so we know the static type of every
// `local` we've seen on the current path, and so narrowing in `if`/`else` can
// override types for the duration of a sub-block.
// ──────────────────────────────────────────────────────────────────────────────

fn check_stmt(stmt: &Stmt, scope: &mut Scope, errors: &mut Vec<TypeCheckError>) {
    match stmt {
        Stmt::Decl(decl) => check_decl(&decl.value, errors),

        Stmt::Local { name, ty, value } => {
            if let (Some(ty), Some(v)) = (ty, value) {
                check_expr(v, scope, errors);
                check_assignment_compat(ty, v, scope, errors);
                scope.bind(name.clone(), ty.clone());
            } else if let Some(v) = value {
                check_expr(v, scope, errors);
                if let Some(t) = infer(v, scope) {
                    scope.bind(name.clone(), t);
                }
            } else if let Some(ty) = ty {
                scope.bind(name.clone(), ty.clone());
            }
        }

        Stmt::LocalMulti { names, values } => {
            for v in values {
                check_expr(v, scope, errors);
            }
            for (i, (name, ty_opt)) in names.iter().enumerate() {
                if let (Some(ty), Some(v)) = (ty_opt, values.get(i)) {
                    check_assignment_compat(ty, v, scope, errors);
                }
                if let Some(ty) = ty_opt {
                    scope.bind(name.clone(), ty.clone());
                } else if let Some(v) = values.get(i)
                    && let Some(t) = infer(v, scope)
                {
                    scope.bind(name.clone(), t);
                }
            }
        }

        Stmt::Assign { target, value } => {
            check_expr(target, scope, errors);
            check_expr(value, scope, errors);
            if let Expr::Ident(n) = &target.value
                && let Some(ty) = scope.lookup(n).cloned()
            {
                check_assignment_compat(&ty, value, scope, errors);
            }
            // `t[k] = v` — enforce the table's static key/value types.
            if let Expr::Index { obj, index } = &target.value
                && let Some(Type::Table { key, value: elem_ty }) = infer(obj, scope)
            {
                let key_ty = key
                    .as_deref()
                    .cloned()
                    .unwrap_or_else(|| Type::Named("integer".into()));
                check_table_key_compat(&key_ty, index, scope, errors);
                check_element_compat(&elem_ty, value, scope, errors);
            }
        }

        Stmt::AssignMulti { targets, values } => {
            for t in targets {
                check_expr(t, scope, errors);
            }
            for v in values {
                check_expr(v, scope, errors);
            }
            for (i, target) in targets.iter().enumerate() {
                if let Expr::Ident(n) = &target.value
                    && let (Some(ty), Some(v)) = (scope.lookup(n).cloned(), values.get(i))
                {
                    check_assignment_compat(&ty, v, scope, errors);
                }
            }
        }

        Stmt::Expr(e) => check_expr(e, scope, errors),

        Stmt::If {
            cond,
            then_block,
            elseifs,
            else_block,
        } => {
            check_expr(cond, scope, errors);
            check_boolean_cond("if", cond, scope, errors);

            // Branch the scope so narrowing in the then-block doesn't leak.
            let mut then_scope = scope.clone();
            narrow_truthy(cond, &mut then_scope);
            for s in then_block {
                check_stmt(&s.value, &mut then_scope, errors);
            }

            for (econd, ebody) in elseifs {
                check_expr(econd, scope, errors);
                check_boolean_cond("elseif", econd, scope, errors);
                let mut ei_scope = scope.clone();
                narrow_truthy(econd, &mut ei_scope);
                for s in ebody {
                    check_stmt(&s.value, &mut ei_scope, errors);
                }
            }

            if let Some(block) = else_block {
                let mut else_scope = scope.clone();
                narrow_falsy(cond, &mut else_scope);
                for s in block {
                    check_stmt(&s.value, &mut else_scope, errors);
                }
            }
        }

        Stmt::While { cond, body } | Stmt::Repeat { body, cond } => {
            check_expr(cond, scope, errors);
            check_boolean_cond(
                if matches!(stmt, Stmt::While { .. }) { "while" } else { "until" },
                cond,
                scope,
                errors,
            );
            let mut body_scope = scope.clone();
            narrow_truthy(cond, &mut body_scope);
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
        }

        Stmt::ForNumeric {
            var,
            var_ty,
            from,
            to,
            step,
            body,
        } => {
            check_expr(from, scope, errors);
            check_expr(to, scope, errors);
            if let Some(s) = step {
                check_expr(s, scope, errors);
            }
            let mut body_scope = scope.clone();
            let ty = var_ty.clone().unwrap_or(Type::Named("integer".into()));
            body_scope.bind(var.clone(), ty);
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
        }

        Stmt::ForIn { vars, iter, body } => {
            check_expr(iter, scope, errors);
            // If the iter expression is a known class instance, it must
            // implement `Iterable` or `Iterable2` (walking the parent chain).
            if let Some(Type::Named(class_name)) = infer(iter, scope)
                && with_classes(|reg| reg.contains_key(&class_name))
                && !class_implements_iterable(&class_name)
            {
                errors.push(TypeCheckError::NotIterable {
                    class: class_name,
                    span: to_source_span(iter.span.clone()),
                });
            }
            let mut body_scope = scope.clone();
            for (name, ty_opt) in vars {
                if let Some(ty) = ty_opt {
                    body_scope.bind(name.clone(), ty.clone());
                }
            }
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
        }

        Stmt::Return(values) => {
            for v in values {
                check_expr(v, scope, errors);
            }
        }

        Stmt::Throw(e) => check_expr(e, scope, errors),

        Stmt::Try {
            body,
            catch_var,
            catch_ty,
            catch_body,
        } => {
            let mut body_scope = scope.clone();
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
            let mut catch_scope = scope.clone();
            catch_scope.bind(catch_var.clone(), catch_ty.clone());
            for s in catch_body {
                check_stmt(&s.value, &mut catch_scope, errors);
            }
        }

        Stmt::Break | Stmt::Continue => {}
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Declaration walker.
// ──────────────────────────────────────────────────────────────────────────────

fn check_decl(decl: &Decl, errors: &mut Vec<TypeCheckError>) {
    match decl {
        Decl::Class {
            name: class_name,
            members,
            ..
        } => check_class(class_name, members, errors),
        Decl::Function {
            type_params,
            params,
            return_ty,
            body,
            ..
        } => {
            let prev_generics = push_generics(type_params);
            let mut scope = Scope::default();
            check_default_params(params, &scope, errors);
            seed_params(&mut scope, params);
            for s in body {
                check_stmt(&s.value, &mut scope, errors);
            }
            if let Some(rt) = return_ty {
                check_returns(body, rt, &scope, errors);
            }
            pop_generics(prev_generics);
        }
        _ => {}
    }
}

fn seed_params(scope: &mut Scope, params: &[Param]) {
    for p in params {
        scope.bind(p.name.clone(), p.ty.clone());
    }
}

/// Check each parameter default against the declared parameter type.
fn check_default_params(params: &[Param], scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    for p in params {
        if let Some(d) = &p.default
            && !is_assignment_compatible(&p.ty, d, scope)
        {
            errors.push(TypeCheckError::DefaultParamTypeMismatch {
                param: p.name.clone(),
                ty: type_to_string(&p.ty),
                span: to_source_span(d.span.clone()),
            });
        }
    }
}

/// Walk a function/method body looking for `return v` statements whose first
/// value can be proved incompatible with `return_ty`.
fn check_returns(
    body: &[Spanned<Stmt>],
    return_ty: &Type,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    for s in body {
        walk_returns(&s.value, return_ty, scope, errors);
    }
}

fn walk_returns(
    stmt: &Stmt,
    return_ty: &Type,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    match stmt {
        Stmt::Return(values) => {
            if let Some(v) = values.first()
                && !is_assignment_compatible(return_ty, v, scope)
            {
                errors.push(TypeCheckError::WrongReturnType {
                    ty: type_to_string(return_ty),
                    span: to_source_span(v.span.clone()),
                });
            }
        }
        Stmt::If {
            then_block,
            elseifs,
            else_block,
            ..
        } => {
            for s in then_block {
                walk_returns(&s.value, return_ty, scope, errors);
            }
            for (_, b) in elseifs {
                for s in b {
                    walk_returns(&s.value, return_ty, scope, errors);
                }
            }
            if let Some(b) = else_block {
                for s in b {
                    walk_returns(&s.value, return_ty, scope, errors);
                }
            }
        }
        Stmt::While { body, .. }
        | Stmt::Repeat { body, .. }
        | Stmt::ForNumeric { body, .. }
        | Stmt::ForIn { body, .. } => {
            for s in body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
        }
        Stmt::Try {
            body, catch_body, ..
        } => {
            for s in body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
            for s in catch_body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
        }
        _ => {}
    }
}

/// True when we can *prove* the value is incompatible-free with the target
/// type. Returns true when we can't decide (conservative: don't false-positive).
fn is_assignment_compatible(decl_ty: &Type, value: &Spanned<Expr>, scope: &Scope) -> bool {
    if is_nullable(decl_ty) {
        // Nullable target accepts anything we can express.
        return true;
    }
    if matches!(value.value, Expr::Nil) {
        return false;
    }
    let Some(value_ty) = infer(value, scope) else {
        return true;
    };
    if is_nullable(&value_ty) {
        return false;
    }
    match (decl_ty, &value_ty) {
        (Type::Named(a), Type::Named(b)) => {
            if a == b || a == "any" || b == "any" {
                true
            } else if is_type_param(a) || is_type_param(b) {
                // Generic type parameters in scope match anything.
                true
            } else {
                // Allow numeric literals in either direction only when same name.
                false
            }
        }
        _ => true,
    }
}

fn check_class(
    class_name: &str,
    members: &[Spanned<ClassMember>],
    errors: &mut Vec<TypeCheckError>,
) {
    // Locate the constructor body: the non-static `fn init` method.
    let mut ctor_body: Option<&Vec<Spanned<Stmt>>> = None;
    for m in members {
        match &m.value {
            ClassMember::Method(Method {
                name,
                is_static: false,
                body,
                ..
            }) if name == "init" => {
                ctor_body = Some(body);
            }
            _ => {}
        }
    }

    // Validate field defaults: `local x: string = nil` is an error regardless
    // of whether a constructor exists or the field is static.
    for m in members {
        if let ClassMember::Field {
            ty,
            default: Some(default_expr),
            ..
        } = &m.value
        {
            let scope = Scope::default();
            check_assignment_compat(ty, default_expr, &scope, errors);
        }
    }

    if let Some(body) = ctor_body {
        let mut assigned: Vec<String> = Vec::new();
        for s in body {
            collect_self_assignments(&s.value, &mut assigned);
        }
        for m in members {
            if let ClassMember::Field {
                is_static: false,
                name,
                ty,
                default,
                ..
            } = &m.value
            {
                if default.is_some() || is_nullable(ty) {
                    continue;
                }
                if !assigned.iter().any(|a| a == name) {
                    errors.push(TypeCheckError::FieldNotInitialized {
                        class: class_name.to_string(),
                        field: name.clone(),
                        span: to_source_span(m.span.clone()),
                    });
                }
            }
        }
    }

    // Walk every method body with a scope seeded from its parameters,
    // and within `CURRENT_CLASS` set so private-member checks know we're
    // *inside* `class_name`. Also validate default parameters and return types.
    let prev = set_current_class(Some(class_name.to_string()));
    for m in members {
        if let ClassMember::Method(meth) = &m.value {
            let prev_generics = push_generics(&meth.type_params);
            let mut scope = Scope::default();
            // `self` resolves to the class itself in `static fn` and to an
            // instance otherwise. Seed it as the class name so member-existence
            // checks on `self.foo` consult the class registry.
            scope.bind("self".to_string(), Type::Named(class_name.to_string()));
            check_default_params(&meth.params, &scope, errors);
            seed_params(&mut scope, &meth.params);
            for s in &meth.body {
                check_stmt(&s.value, &mut scope, errors);
            }
            if let Some(rt) = &meth.return_ty {
                check_returns(&meth.body, rt, &scope, errors);
            }
            pop_generics(prev_generics);
        }
    }
    set_current_class(prev);
}

// ──────────────────────────────────────────────────────────────────────────────
// Expression checker — walks expressions looking for `obj.member` /
// `obj.method(...)` where `obj` has a statically-known nullable type.
// ──────────────────────────────────────────────────────────────────────────────

fn check_expr(expr: &Spanned<Expr>, scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    match &expr.value {
        Expr::Member { obj, name } => {
            check_expr(obj, scope, errors);
            report_if_nullable_receiver(obj, name, scope, errors);
            report_if_private(obj, name, scope, errors);
        }
        Expr::MethodCall { obj, method, args } => {
            check_expr(obj, scope, errors);
            report_if_nullable_receiver(obj, method, scope, errors);
            report_if_private(obj, method, scope, errors);
            for a in args {
                check_arg(a, scope, errors);
            }
        }
        Expr::Call { callee, args } => {
            // `obj.method(args)` is parsed as Call(Member { obj, name }, args)
            // — same nullable-receiver rule applies.
            if let Expr::Member { obj, name } = &callee.value {
                check_expr(obj, scope, errors);
                report_if_nullable_receiver(obj, name, scope, errors);
                report_if_private(obj, name, scope, errors);
            } else {
                check_expr(callee, scope, errors);
            }
            for a in args {
                check_arg(a, scope, errors);
            }
            // If the callee resolves to a known native signature, check the
            // argument types positionally. Named arguments are skipped (those
            // aren't supported on natives anyway, and they error at runtime).
            if let Some(qname) = native_callee_name(callee)
                && let Some(sig) = crate::stdlib::sigs::lookup(&qname)
            {
                check_native_args(&qname, &sig, args, scope, errors, expr.span.clone());
            }
        }
        Expr::SafeMember { obj, .. } => check_expr(obj, scope, errors),
        Expr::Index { obj, index } => {
            check_expr(obj, scope, errors);
            check_expr(index, scope, errors);
        }
        Expr::Unary { rhs, .. } => check_expr(rhs, scope, errors),
        Expr::Binary { lhs, rhs, .. } => {
            check_expr(lhs, scope, errors);
            check_expr(rhs, scope, errors);
        }
        Expr::ForceUnwrap(inner) => check_expr(inner, scope, errors),
        Expr::Table(items) => {
            for e in items {
                check_expr(e, scope, errors);
            }
        }
        Expr::Lambda { params, body, .. } => {
            let mut lscope = scope.clone();
            seed_params(&mut lscope, params);
            match body {
                LambdaBody::Expr(e) => check_expr(e, &lscope, errors),
                LambdaBody::Block(stmts) => {
                    for s in stmts {
                        check_stmt(&s.value, &mut lscope, errors);
                    }
                }
            }
        }
        Expr::Match { scrutinee, arms } => {
            check_match(expr, scrutinee, arms, scope, errors);
        }
        _ => {}
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// `match` expression checks: pattern/scrutinee compat, exhaustiveness,
// arm-body type unification. Pattern-bound variables are added to a per-arm
// scope so guards and bodies can reference them.
// ──────────────────────────────────────────────────────────────────────────────

fn check_match(
    match_expr: &Spanned<Expr>,
    scrutinee: &Spanned<Expr>,
    arms: &[MatchArm],
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    check_expr(scrutinee, scope, errors);
    let scrut_ty = infer(scrutinee, scope);

    // Determine which enum (if any) drives exhaustiveness — prefer the
    // scrutinee's static type; fall back to the enum referenced by any
    // `Variant` pattern in the arms.
    let scrut_enum_name = match &scrut_ty {
        Some(ty) => match strip_nullable(ty.clone()) {
            Type::Named(n) if with_enums(|e| e.contains_key(&n)) => Some(n),
            _ => None,
        },
        None => None,
    };
    let pattern_enum_name = arms.iter().find_map(|a| match &a.pattern.value {
        Pattern::Variant { enum_name, .. } if with_enums(|e| e.contains_key(enum_name)) => {
            Some(enum_name.clone())
        }
        _ => None,
    });
    let active_enum = scrut_enum_name.clone().or(pattern_enum_name);

    let mut covered_variants: HashSet<String> = HashSet::new();
    let mut has_fallback = false;
    let mut covered_true = false;
    let mut covered_false = false;
    let mut arm_types: Vec<Option<Type>> = Vec::new();
    let arm_bind_ty = scrut_ty.as_ref().map(|t| strip_nullable(t.clone()));

    for arm in arms {
        check_pattern(&arm.pattern, &scrut_ty, errors);

        let mut arm_scope = scope.clone();
        bind_pattern(&arm.pattern.value, arm_bind_ty.as_ref(), &mut arm_scope);

        if let Some(g) = &arm.guard {
            check_expr(g, &arm_scope, errors);
            check_boolean_cond("when", g, &arm_scope, errors);
        }

        let body_ty = match &arm.body {
            MatchBody::Expr(e) => {
                check_expr(e, &arm_scope, errors);
                infer(e, &arm_scope)
            }
            MatchBody::Block(stmts) => {
                let mut bs = arm_scope.clone();
                for s in stmts {
                    check_stmt(&s.value, &mut bs, errors);
                }
                None
            }
        };
        arm_types.push(body_ty);

        // Only unguarded arms contribute to exhaustiveness.
        if arm.guard.is_none() {
            match &arm.pattern.value {
                Pattern::Wildcard | Pattern::Bind(_) => has_fallback = true,
                Pattern::Tuple(fields)
                    if fields
                        .iter()
                        .all(|p| matches!(p.value, Pattern::Wildcard | Pattern::Bind(_))) =>
                {
                    has_fallback = true;
                }
                Pattern::Variant { enum_name, variant, .. } => {
                    if let Some(en) = &active_enum
                        && en == enum_name
                    {
                        covered_variants.insert(variant.clone());
                    }
                }
                Pattern::Bool(true) => covered_true = true,
                Pattern::Bool(false) => covered_false = true,
                _ => {}
            }
        }
    }

    // Exhaustiveness.
    let (exhaustive, missing_variants): (bool, Vec<String>) = if has_fallback {
        (true, vec![])
    } else if let Some(en) = &active_enum {
        with_enums(|e| {
            if let Some(info) = e.get(en) {
                let missing: Vec<String> = info
                    .variants
                    .keys()
                    .filter(|v| !covered_variants.contains(*v))
                    .cloned()
                    .collect();
                (missing.is_empty(), missing)
            } else {
                (false, vec![])
            }
        })
    } else if matches!(&scrut_ty, Some(Type::Named(n)) if n == "boolean") {
        (covered_true && covered_false, vec![])
    } else {
        (false, vec![])
    };

    if !exhaustive {
        let reason = if let Some(en) = &active_enum {
            if missing_variants.is_empty() {
                format!("enum `{en}` is not fully covered")
            } else {
                format!(
                    "missing variant(s) of `{en}`: {}",
                    missing_variants.join(", ")
                )
            }
        } else if matches!(&scrut_ty, Some(Type::Named(n)) if n == "boolean") {
            "boolean match must cover both `true` and `false`".to_string()
        } else {
            "no unguarded wildcard / binding arm".to_string()
        };
        errors.push(TypeCheckError::MatchNonExhaustive {
            reason,
            span: to_source_span(match_expr.span.clone()),
        });
    }

    // Arm body type unification — flag the first pair that don't agree.
    let mut first_ty: Option<Type> = None;
    for ty_opt in &arm_types {
        if let Some(t) = ty_opt {
            if let Some(first) = &first_ty {
                if !types_compatible(first, t) && !types_compatible(t, first) {
                    errors.push(TypeCheckError::MatchArmTypeMismatch {
                        expected: type_to_string(first),
                        found: type_to_string(t),
                        span: to_source_span(match_expr.span.clone()),
                    });
                    break;
                }
            } else {
                first_ty = Some(t.clone());
            }
        }
    }
}

fn check_pattern(
    pat: &Spanned<Pattern>,
    scrut_ty: &Option<Type>,
    errors: &mut Vec<TypeCheckError>,
) {
    match &pat.value {
        Pattern::Wildcard | Pattern::Bind(_) | Pattern::Nil => {}
        Pattern::Int(_) => check_pattern_literal_compat(scrut_ty, "integer", &pat.span, errors),
        Pattern::Float(_) => check_pattern_literal_compat(scrut_ty, "float", &pat.span, errors),
        Pattern::Bool(_) => check_pattern_literal_compat(scrut_ty, "boolean", &pat.span, errors),
        Pattern::Str(_) => check_pattern_literal_compat(scrut_ty, "string", &pat.span, errors),
        Pattern::Variant {
            enum_name,
            variant,
            fields,
        } => {
            let mut known_enum = false;
            with_enums(|e| {
                if let Some(info) = e.get(enum_name) {
                    known_enum = true;
                    if let Some(&arity) = info.variants.get(variant) {
                        if fields.len() != arity {
                            errors.push(TypeCheckError::MatchVariantArityMismatch {
                                variant: format!("{enum_name}.{variant}"),
                                expected: arity,
                                found: fields.len(),
                                span: to_source_span(pat.span.clone()),
                            });
                        }
                    } else {
                        errors.push(TypeCheckError::MatchUnknownVariant {
                            enum_name: enum_name.clone(),
                            variant: variant.clone(),
                            span: to_source_span(pat.span.clone()),
                        });
                    }
                }
            });
            let _ = known_enum;
            for f in fields {
                check_pattern(f, &None, errors);
            }
        }
        Pattern::Tuple(fields) => {
            for f in fields {
                check_pattern(f, &None, errors);
            }
        }
    }
}

fn check_pattern_literal_compat(
    scrut_ty: &Option<Type>,
    pat_ty_name: &str,
    span: &Range<usize>,
    errors: &mut Vec<TypeCheckError>,
) {
    let Some(ty) = scrut_ty else {
        return;
    };
    let stripped = strip_nullable(ty.clone());
    if let Type::Named(n) = &stripped {
        if n == "any" || n == pat_ty_name || is_type_param(n) {
            return;
        }
        // `number` accepts integer/float literals.
        if n == "number" && (pat_ty_name == "integer" || pat_ty_name == "float") {
            return;
        }
        errors.push(TypeCheckError::MatchPatternTypeMismatch {
            expected: n.clone(),
            found: pat_ty_name.to_string(),
            span: to_source_span(span.clone()),
        });
    }
}

/// Bind the variables introduced by a pattern into `scope`. Best-effort
/// typing: scrutinee-typed for top-level binds, `any` for sub-patterns whose
/// type we can't easily derive.
fn bind_pattern(pat: &Pattern, scrut_ty: Option<&Type>, scope: &mut Scope) {
    match pat {
        Pattern::Bind(name) => {
            let ty = scrut_ty.cloned().unwrap_or(Type::Named("any".into()));
            scope.bind(name.clone(), ty);
        }
        Pattern::Variant { fields, .. } => {
            for f in fields {
                bind_pattern(&f.value, None, scope);
            }
        }
        Pattern::Tuple(fields) => {
            for f in fields {
                bind_pattern(&f.value, None, scope);
            }
        }
        _ => {}
    }
}

fn check_arg(arg: &CallArg, scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    match arg {
        CallArg::Positional(e) | CallArg::Named { value: e, .. } => check_expr(e, scope, errors),
    }
}

/// Check positional arguments of a native call against the registered
/// signature. Skips named arguments (natives don't support them; the runtime
/// will surface that as an error).
///
/// Heuristics intentionally lenient:
///   * `any` and `T?` parameters accept anything (incl. nil) — they're the
///     "I'll figure it out" slots.
///   * Variadic / over-supplied calls aren't penalised when the declared
///     param list runs out — many natives accept `...rest` (variadic) which
///     isn't expressed in the sig yet.
///   * If `infer` can't produce a type for the argument, we skip silently.
fn check_native_args(
    callee: &str,
    sig: &crate::stdlib::sigs::NativeSig,
    args: &[CallArg],
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
    call_span: std::ops::Range<usize>,
) {
    // Count required positional params (every param up to the first
    // nullable / `any` is required — nullable+`any` slots are optional).
    let required: usize = sig
        .params
        .iter()
        .take_while(|p| !is_nullable(p) && !is_any(p))
        .count();
    let positional: Vec<&CallArg> = args.iter().filter(|a| matches!(a, CallArg::Positional(_))).collect();
    if positional.len() < required {
        errors.push(TypeCheckError::NativeArity {
            callee: callee.to_string(),
            expected: required,
            found: positional.len(),
            span: to_source_span(call_span.clone()),
        });
        return;
    }

    // Reject extras when the native is not variadic. Don't bail though —
    // continue checking the known positions for type mismatches.
    if sig.variadic.is_none() && positional.len() > sig.params.len() {
        errors.push(TypeCheckError::NativeArity {
            callee: callee.to_string(),
            expected: sig.params.len(),
            found: positional.len(),
            span: to_source_span(call_span),
        });
    }

    for (i, arg) in args.iter().enumerate() {
        // Pick the expected type for slot `i`:
        //   - within declared params: use `params[i]`
        //   - past the end: use the variadic element type (or stop if absent)
        let expected = match sig.params.get(i) {
            Some(t) => t,
            None => match &sig.variadic {
                Some(t) => t,
                None => break,
            },
        };
        let value_expr = match arg {
            CallArg::Positional(e) => e,
            CallArg::Named { .. } => continue,
        };
        if is_any(expected) {
            continue;
        }
        let Some(found_ty) = infer(value_expr, scope) else {
            continue;
        };
        if !types_compatible(expected, &found_ty) {
            errors.push(TypeCheckError::NativeArgTypeMismatch {
                callee: callee.to_string(),
                arg: i + 1,
                expected: type_to_string(expected),
                found: type_to_string(&found_ty),
                span: to_source_span(value_expr.span.clone()),
            });
        }
    }
}

fn is_any(t: &Type) -> bool {
    matches!(t, Type::Named(n) if n == "any")
}

fn report_if_nullable_receiver(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(ty) = infer(obj, scope)
        && is_nullable(&ty)
    {
        errors.push(TypeCheckError::NullableMemberAccess {
            ty: type_to_string(&ty),
            member: member.to_string(),
            span: to_source_span(obj.span.clone()),
        });
    }
}

/// Reject access to `local` (private) members from outside the owning class.
/// `self.foo` is allowed only when the *owning* class of `foo` is the class
/// currently being checked — a private field inherited from a parent is
/// **not** visible to the child.
fn report_if_private(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    // Resolve the class name we're reading the member off:
    //   * `self.member` → the current class (lookup walks the parent chain).
    //   * `obj.member` where `obj` is an *instance* → infer the receiver type.
    //   * `Class.member` where the receiver is the class itself
    //     (e.g. `Bank.secret`) → use the ident directly.
    let class_name = match &obj.value {
        Expr::Self_ => match current_class() {
            Some(n) => n,
            None => return,
        },
        Expr::Ident(n) if with_classes(|reg| reg.contains_key(n)) => n.clone(),
        _ => match infer(obj, scope) {
            Some(ty) => match strip_nullable(ty) {
                Type::Named(n) => n,
                _ => return,
            },
            None => return,
        },
    };
    let Some((owning, is_private)) = lookup_member(&class_name, member) else {
        return;
    };
    if is_private && current_class().as_deref() != Some(owning.as_str()) {
        errors.push(TypeCheckError::PrivateMemberAccess {
            class: owning,
            member: member.to_string(),
            span: to_source_span(obj.span.end..obj.span.end + member.len() + 1),
        });
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Assignment compatibility — only flags the cases we can prove are wrong.
// ──────────────────────────────────────────────────────────────────────────────

fn check_assignment_compat(
    decl_ty: &Type,
    value: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if is_nullable(decl_ty) {
        return;
    }
    if matches!(value.value, Expr::Nil) {
        errors.push(TypeCheckError::NilToNonNullable {
            ty: type_to_string(decl_ty),
            span: to_source_span(value.span.clone()),
        });
        return;
    }

    // Table-aware checks for array-style literals assigned to a typed table.
    if let (Type::Table { key, value: elem_ty }, Expr::Table(items)) = (decl_ty, &value.value) {
        // `{a, b, c}` literal cannot fill a map-typed table whose key is not
        // integer-compatible.
        if let Some(k) = key
            && !is_integer_like(k)
            && !items.is_empty()
        {
            errors.push(TypeCheckError::TableArrayLiteralForMap {
                key: type_to_string(k),
                value: type_to_string(elem_ty),
                span: to_source_span(value.span.clone()),
            });
            return;
        }
        // Each element must match the declared value type.
        for item in items {
            check_element_compat(elem_ty, item, scope, errors);
        }
        return;
    }

    if let Some(value_ty) = infer(value, scope)
        && is_nullable(&value_ty)
    {
        errors.push(TypeCheckError::NullableToNonNullable {
            from: type_to_string(&value_ty),
            to: type_to_string(decl_ty),
            span: to_source_span(value.span.clone()),
        });
    }
}

/// Index key must match the table's declared key type.
fn check_table_key_compat(
    expected: &Type,
    index: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(idx_ty) = infer(index, scope)
        && !types_compatible(expected, &idx_ty)
    {
        errors.push(TypeCheckError::TableKeyTypeMismatch {
            expected: type_to_string(expected),
            found: type_to_string(&idx_ty),
            span: to_source_span(index.span.clone()),
        });
    }
}

/// True for `integer` and `any` — the key types that an array-style literal
/// can satisfy.
fn is_integer_like(ty: &Type) -> bool {
    matches!(ty, Type::Named(n) if n == "integer" || n == "any")
}

/// Element-of-table compatibility — accepts literals/`Ident`s whose inferred
/// type matches, and stays quiet otherwise (conservative).
fn check_element_compat(
    expected: &Type,
    value: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(value_ty) = infer(value, scope)
        && !types_compatible(expected, &value_ty)
    {
        errors.push(TypeCheckError::TableElementTypeMismatch {
            expected: type_to_string(expected),
            found: type_to_string(&value_ty),
            span: to_source_span(value.span.clone()),
        });
    }
}

/// Conservative type compatibility — names match (or either is `any`), or
/// `value_ty` is `Nullable` of a compatible inner, etc.
fn types_compatible(expected: &Type, value_ty: &Type) -> bool {
    match (expected, value_ty) {
        // Same-name primitives, plus `any` on either side, plus `nil` on the
        // value side (nil is universally assignable; nullable-rejection is
        // handled separately by `NullableToNonNullable`).
        (Type::Named(a), Type::Named(b)) => {
            if a == b || a == "any" || b == "any" || b == "nil" {
                return true;
            }
            // Generic type parameters in scope match anything — they're
            // effectively `any` from the body's point of view.
            if is_type_param(a) || is_type_param(b) {
                return true;
            }
            // `number` is the sentinel used in native sigs to mean
            // "integer or float" — accept either.
            if a == "number" && (b == "integer" || b == "float" || b == "number") {
                return true;
            }
            // Class/interface subtyping: a value of type `b` is assignable to
            // a slot of type `a` if `b` is a subtype of `a` (class implements
            // interface, class extends class, interface extends interface).
            if is_subtype_named(b, a) {
                return true;
            }
            false
        }
        // `table<any>` (or `table<any, any>`) matches any table — used by
        // native sigs like `pairs(t)` / `Table.insert(t, ...)` to mean
        // "any table".
        (
            Type::Table { key: ek, value: ev },
            Type::Table { key: vk, value: vv },
        ) => {
            let key_ok = match (ek, vk) {
                (None, None) => true,
                (Some(a), Some(b)) => types_compatible(a, b),
                // Cross-shape (`table<T>` vs `table<K, V>`) only when one
                // side is the `any` wildcard.
                _ => is_any(ev),
            };
            key_ok && (is_any(ev) || types_compatible(ev, vv))
        }
        // Expected table, but value is the bare type-name `table`, `any` or
        // `nil` — accept (caller has erased the element type, or it's nil).
        (Type::Table { .. }, Type::Named(n)) if n == "table" || n == "any" || n == "nil" => true,
        // Expected `any` / `table` / `nil` named slot, value is a table —
        // accept (we widen to the named slot).
        (Type::Named(n), Type::Table { .. }) if n == "table" || n == "any" => true,
        (Type::Nullable(a), b) => types_compatible(a, b),
        (a, Type::Nullable(b)) => types_compatible(a, b),
        // Function / Tuple shapes — only equal-shape is strictly compatible,
        // but the checker doesn't track those precisely yet. Accept rather
        // than emit false positives.
        (Type::Function { .. }, Type::Function { .. }) => true,
        (Type::Tuple(_), Type::Tuple(_)) => true,
        // Different kinds (e.g. table vs integer) — reject.
        _ => false,
    }
}

/// Reject `if`/`while`/`until` conditions that the type system can prove are
/// not `boolean`. Conservative: when `infer` can't determine a type, we skip
/// silently so calls and dynamic expressions keep working.
fn check_boolean_cond(
    construct: &'static str,
    cond: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    let Some(ty) = infer(cond, scope) else {
        return;
    };
    let is_bool = matches!(&ty, Type::Named(n) if n == "boolean" || n == "any");
    if !is_bool {
        errors.push(TypeCheckError::NonBooleanCondition {
            construct,
            found: type_to_string(&ty),
            span: to_source_span(cond.span.clone()),
        });
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Lightweight type inference.
//
// Returns `Some(ty)` only when we can prove the type. Anything we can't see
// through (calls, member reads on unknown classes, indexing) returns `None`,
// and callers treat that as "don't know, don't complain".
// ──────────────────────────────────────────────────────────────────────────────

fn infer(expr: &Spanned<Expr>, scope: &Scope) -> Option<Type> {
    match &expr.value {
        Expr::Nil => Some(Type::Named("nil".into())),
        Expr::Int(_) => Some(Type::Named("integer".into())),
        Expr::Float(_) => Some(Type::Named("float".into())),
        Expr::Bool(_) => Some(Type::Named("boolean".into())),
        Expr::Str(_) => Some(Type::Named("string".into())),
        Expr::Ident(n) => scope.lookup(n).cloned(),
        Expr::SafeMember { .. } => Some(Type::Nullable(Box::new(Type::Named("any".into())))),
        Expr::ForceUnwrap(inner) => match infer(inner, scope)? {
            Type::Nullable(t) => Some(*t),
            other => Some(other),
        },
        Expr::Binary { op, lhs, rhs } => match op {
            BinOp::Coalesce => {
                // `lhs ?? rhs`: result is non-nullable iff `rhs` is non-nullable.
                match (infer(lhs, scope), infer(rhs, scope)) {
                    (Some(lt), Some(rt)) => {
                        let base = strip_nullable(lt);
                        if is_nullable(&rt) {
                            Some(Type::Nullable(Box::new(base)))
                        } else {
                            Some(base)
                        }
                    }
                    _ => None,
                }
            }
            BinOp::Eq | BinOp::NotEq | BinOp::Lt | BinOp::LtEq | BinOp::Gt | BinOp::GtEq => {
                Some(Type::Named("boolean".into()))
            }
            BinOp::And | BinOp::Or => None,
            BinOp::Concat => Some(Type::Named("string".into())),
            BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod => {
                infer(lhs, scope).or_else(|| infer(rhs, scope))
            }
        },
        // `Foo(args)` where `Foo` is a known class → produces a `Foo`.
        // Otherwise, look up the qualified callee name in the native signature
        // table (e.g. `String.byte`, `Math.tointeger`, `assert`).
        Expr::Call { callee, .. } => {
            if let Expr::Ident(n) = &callee.value
                && with_classes(|reg| reg.contains_key(n))
            {
                Some(Type::Named(n.clone()))
            } else if let Some(qname) = native_callee_name(callee)
                && let Some(sig) = crate::stdlib::sigs::lookup(&qname)
            {
                first_or_tuple(sig.returns)
            } else {
                None
            }
        }
        _ => None,
    }
}

fn strip_nullable(ty: Type) -> Type {
    match ty {
        Type::Nullable(t) => *t,
        other => other,
    }
}

/// Build a qualified callee name suitable for `stdlib::sigs::lookup`:
/// `assert` or `String.byte`.
fn native_callee_name(callee: &Spanned<Expr>) -> Option<String> {
    match &callee.value {
        Expr::Ident(n) => Some(n.clone()),
        Expr::Member { obj, name } => {
            if let Expr::Ident(class) = &obj.value {
                Some(format!("{class}.{name}"))
            } else {
                None
            }
        }
        _ => None,
    }
}

/// Collapse a returns-list into a single inferred type: single returns stay
/// as-is, multi-returns become a `Type::Tuple`.
fn first_or_tuple(returns: Vec<Type>) -> Option<Type> {
    match returns.len() {
        0 => None,
        1 => returns.into_iter().next(),
        _ => Some(Type::Tuple(returns)),
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Flow narrowing.
//
// `narrow_truthy(cond, scope)` — apply the assumptions that hold when `cond`
// is true. Today: `x != nil` and `nil != x` strip `Nullable` off `x`. `and`
// chains compose.
//
// `narrow_falsy(cond, scope)` — apply the assumptions when `cond` is false.
// Used by the else-branch: `if x == nil then ... else ... end` narrows `x`
// in the else.
// ──────────────────────────────────────────────────────────────────────────────

fn narrow_truthy(cond: &Spanned<Expr>, scope: &mut Scope) {
    match &cond.value {
        Expr::Binary {
            op: BinOp::NotEq,
            lhs,
            rhs,
        } => {
            if let Some(name) = pick_ident_compared_to_nil(lhs, rhs)
                && let Some(Type::Nullable(t)) = scope.lookup(name).cloned()
            {
                scope.bind(name.to_string(), *t);
            }
        }
        Expr::Binary {
            op: BinOp::And,
            lhs,
            rhs,
        } => {
            narrow_truthy(lhs, scope);
            narrow_truthy(rhs, scope);
        }
        _ => {}
    }
}

fn narrow_falsy(cond: &Spanned<Expr>, scope: &mut Scope) {
    if let Expr::Binary {
        op: BinOp::Eq,
        lhs,
        rhs,
    } = &cond.value
        && let Some(name) = pick_ident_compared_to_nil(lhs, rhs)
        && let Some(Type::Nullable(t)) = scope.lookup(name).cloned()
    {
        scope.bind(name.to_string(), *t);
    }
}

/// If `lhs` / `rhs` is `(Ident(x), Nil)` in either order, return `Some(x)`.
fn pick_ident_compared_to_nil<'a>(
    lhs: &'a Spanned<Expr>,
    rhs: &'a Spanned<Expr>,
) -> Option<&'a str> {
    match (&lhs.value, &rhs.value) {
        (Expr::Ident(n), Expr::Nil) => Some(n),
        (Expr::Nil, Expr::Ident(n)) => Some(n),
        _ => None,
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Misc helpers.
// ──────────────────────────────────────────────────────────────────────────────

fn type_to_string(ty: &Type) -> String {
    match ty {
        Type::Named(n) => n.clone(),
        Type::Nullable(inner) => format!("{}?", type_to_string(inner)),
        Type::Table { key: None, value } => format!("table<{}>", type_to_string(value)),
        Type::Table {
            key: Some(k),
            value,
        } => format!("table<{}, {}>", type_to_string(k), type_to_string(value)),
        other => format!("{:?}", other),
    }
}

fn is_nullable(ty: &Type) -> bool {
    match ty {
        Type::Nullable(_) => true,
        Type::Named(n) => n == "nil",
        _ => false,
    }
}

/// Walk a statement collecting every `self.NAME` that appears on the LHS of
/// an `=`. Recurses through control-flow statements so an assignment inside
/// an `if` still counts.
fn collect_self_assignments(stmt: &Stmt, out: &mut Vec<String>) {
    match stmt {
        Stmt::Assign { target, .. } => {
            if let Expr::Member { obj, name } = &target.value
                && matches!(obj.value, Expr::Self_)
                && !out.iter().any(|n| n == name)
            {
                out.push(name.clone());
            }
        }
        Stmt::AssignMulti { targets, .. } => {
            for target in targets {
                if let Expr::Member { obj, name } = &target.value
                    && matches!(obj.value, Expr::Self_)
                    && !out.iter().any(|n| n == name)
                {
                    out.push(name.clone());
                }
            }
        }
        Stmt::If {
            then_block,
            elseifs,
            else_block,
            ..
        } => {
            for s in then_block {
                collect_self_assignments(&s.value, out);
            }
            for (_, block) in elseifs {
                for s in block {
                    collect_self_assignments(&s.value, out);
                }
            }
            if let Some(block) = else_block {
                for s in block {
                    collect_self_assignments(&s.value, out);
                }
            }
        }
        Stmt::While { body, .. }
        | Stmt::Repeat { body, .. }
        | Stmt::ForNumeric { body, .. }
        | Stmt::ForIn { body, .. } => {
            for s in body {
                collect_self_assignments(&s.value, out);
            }
        }
        Stmt::Try {
            body, catch_body, ..
        } => {
            for s in body {
                collect_self_assignments(&s.value, out);
            }
            for s in catch_body {
                collect_self_assignments(&s.value, out);
            }
        }
        _ => {}
    }
}

//! Type parsing: nullable suffix, table<T>/table<K,V>, generic param/arg
//! lists, function types.

use saule_ast::Type;
use saule_lexer::Token;

use crate::Parser;
use crate::error::ParseError;

impl Parser {
    // ─────────────────────────────────────────────────────────────────────────
    // Types
    // ─────────────────────────────────────────────────────────────────────────

    /// Optional return type after a `)` in a function/method/lambda signature.
    /// Only `-> T` is accepted; the legacy `: T` form has been removed.
    pub(crate) fn parse_return_type_opt(&mut self) -> Result<Option<Type>, ParseError> {
        if self.eat(&Token::Arrow) {
            Ok(Some(self.parse_type()?))
        } else {
            Ok(None)
        }
    }

    pub(crate) fn parse_type(&mut self) -> Result<Type, ParseError> {
        let mut ty = self.parse_base_type()?;
        // Trailing `?` makes the type nullable. Allow chaining (`T??` though rare).
        while self.check(&Token::Question) {
            self.advance();
            ty = Type::Nullable(Box::new(ty));
        }
        Ok(ty)
    }

    pub(crate) fn parse_base_type(&mut self) -> Result<Type, ParseError> {
        let tok = self.peek().clone();
        match tok.value {
            Token::LParen => {
                self.advance();
                let mut items = Vec::new();
                if !self.check(&Token::RParen) {
                    items.push(self.parse_type()?);
                    while self.eat(&Token::Comma) {
                        items.push(self.parse_type()?);
                    }
                }
                self.expect(&Token::RParen, "`)` to close tuple type")?;
                if items.len() == 1 {
                    Ok(items.into_iter().next().expect("one tuple item"))
                } else {
                    Ok(Type::Tuple(items))
                }
            }
            Token::Identifier(name) => {
                self.advance();
                // `table<T>` (array) and `table<K, V>` (hashmap) are first-class
                // forms in the type system. Other identifiers may carry generic
                // arguments which we still accept-and-discard for forward-compat.
                if name == "table" && self.check(&Token::Lt) {
                    self.expect(&Token::Lt, "`<`")?;
                    let first = self.parse_type()?;
                    let (key, value) = if self.eat(&Token::Comma) {
                        let v = self.parse_type()?;
                        (Some(Box::new(first)), Box::new(v))
                    } else {
                        (None, Box::new(first))
                    };
                    self.expect(&Token::Gt, "`>` to close `table<...>`")?;
                    return Ok(Type::Table { key, value });
                }
                // Drop any generic argument list `<T, U>` — generics aren't
                // implemented yet but appear in the README; we accept and
                // ignore them so real programs parse.
                if self.check(&Token::Lt) {
                    self.skip_generic_args()?;
                }
                Ok(Type::Named(name))
            }
            // `nil` is a keyword token but also a legal return type ("void").
            Token::Nil => {
                self.advance();
                Ok(Type::Named("nil".to_string()))
            }
            Token::Fn => {
                self.advance();
                self.expect(&Token::LParen, "`(` in function type")?;
                let mut params = Vec::new();
                if !self.check(&Token::RParen) {
                    params.push(self.parse_type()?);
                    while self.eat(&Token::Comma) {
                        params.push(self.parse_type()?);
                    }
                }
                self.expect(&Token::RParen, "`)` in function type")?;
                if !(self.eat(&Token::Arrow) || self.eat(&Token::Colon)) {
                    return Err(ParseError::Expected {
                        expected: "`->` or `:` before return type",
                        span: self.peek().span.clone(),
                    });
                }
                let ret = self.parse_type()?;
                Ok(Type::Function {
                    params,
                    ret: Box::new(ret),
                })
            }
            _ => Err(ParseError::Expected {
                expected: "a type",
                span: tok.span,
            }),
        }
    }

    /// Consumes a `<T, U, ...>` generic argument list, discarding the types.
    /// We assume `<` is currently the next token.
    pub(crate) fn skip_generic_args(&mut self) -> Result<(), ParseError> {
        self.expect(&Token::Lt, "`<`")?;
        let _ = self.parse_type()?;
        while self.eat(&Token::Comma) {
            let _ = self.parse_type()?;
        }
        self.expect(&Token::Gt, "`>` to close generic arguments")?;
        Ok(())
    }

    /// Consumes a `<T, U, ...>` *parameter* list on a function or method
    /// declaration and returns the type-parameter names. Unlike
    /// [`skip_generic_args`], every entry must be a bare identifier.
    pub(crate) fn parse_generic_params(&mut self) -> Result<Vec<String>, ParseError> {
        self.expect(&Token::Lt, "`<`")?;
        let mut params = Vec::new();
        let (first, _) = self.expect_ident("generic parameter name")?;
        params.push(first);
        while self.eat(&Token::Comma) {
            let (n, _) = self.expect_ident("generic parameter name")?;
            params.push(n);
        }
        self.expect(&Token::Gt, "`>` to close generic parameters")?;
        Ok(params)
    }

    /// Try to consume a generic-call instantiation `<T, U, ...>` immediately
    /// followed by `(`. Returns `true` if the consumption succeeded; restores
    /// the cursor and returns `false` otherwise (so the `<` can be parsed as
    /// a less-than operator instead). Used at call sites like
    /// `filter<integer>(nums, ...)`.
    pub(crate) fn try_eat_generic_call_args(&mut self) -> bool {
        let saved = self.pos;
        if !self.check(&Token::Lt) {
            return false;
        }
        // Try to consume a `<` ... `>` window where every entry parses as a
        // type. If the window doesn't end in `>(`, restore.
        self.advance(); // `<`
        if self.parse_type().is_err() {
            self.pos = saved;
            return false;
        }
        while self.eat(&Token::Comma) {
            if self.parse_type().is_err() {
                self.pos = saved;
                return false;
            }
        }
        if !self.eat(&Token::Gt) {
            self.pos = saved;
            return false;
        }
        if !self.check(&Token::LParen) {
            self.pos = saved;
            return false;
        }
        true
    }
}

//! Type parsing: nullable suffix, table<T>/table<K,V>, generic param/arg
//! lists, function types.

use saule_ast::Type;
use saule_lexer::Token;

use crate::Parser;
use crate::error::ParseError;

impl Parser {
    // ─────────────────────────────────────────────────────────────────────────
    // Types
    // ─────────────────────────────────────────────────────────────────────────

    /// Optional return type after a `)` in a function/method/lambda signature.
    /// Only `-> T` is accepted; the legacy `: T` form has been removed.
    pub(crate) fn parse_return_type_opt(&mut self) -> Result<Option<Type>, ParseError> {
        if self.eat(&Token::Arrow) {
            Ok(Some(self.parse_type()?))
        } else {
            Ok(None)
        }
    }

    pub(crate) fn parse_type(&mut self) -> Result<Type, ParseError> {
        let mut ty = self.parse_base_type()?;
        // Trailing `?` makes the type nullable. Allow chaining (`T??` though rare).
        while self.check(&Token::Question) {
            self.advance();
            ty = Type::Nullable(Box::new(ty));
        }
        Ok(ty)
    }

    pub(crate) fn parse_base_type(&mut self) -> Result<Type, ParseError> {
        let tok = self.peek().clone();
        match tok.value {
            Token::LParen => {
                self.advance();
                let mut items = Vec::new();
                if !self.check(&Token::RParen) {
                    items.push(self.parse_type()?);
                    while self.eat(&Token::Comma) {
                        items.push(self.parse_type()?);
                    }
                }
                self.expect(&Token::RParen, "`)` to close tuple type")?;
                if items.len() == 1 {
                    Ok(items.into_iter().next().expect("one tuple item"))
                } else {
                    Ok(Type::Tuple(items))
                }
            }
            Token::Identifier(name) => {
                self.advance();
                // `table<T>` (array) and `table<K, V>` (hashmap) are first-class
                // forms in the type system. Other identifiers may carry generic
                // arguments which we still accept-and-discard for forward-compat.
                if name == "table" && self.check(&Token::Lt) {
                    self.expect(&Token::Lt, "`<`")?;
                    let first = self.parse_type()?;
                    let (key, value) = if self.eat(&Token::Comma) {
                        let v = self.parse_type()?;
                        (Some(Box::new(first)), Box::new(v))
                    } else {
                        (None, Box::new(first))
                    };
                    self.expect(&Token::Gt, "`>` to close `table<...>`")?;
                    return Ok(Type::Table { key, value });
                }
                // Drop any generic argument list `<T, U>` — generics aren't
                // implemented yet but appear in the README; we accept and
                // ignore them so real programs parse.
                if self.check(&Token::Lt) {
                    self.skip_generic_args()?;
                }
                Ok(Type::Named(name))
            }
            // `nil` is a keyword token but also a legal return type ("void").
            Token::Nil => {
                self.advance();
                Ok(Type::Named("nil".to_string()))
            }
            Token::Fn => {
                self.advance();
                self.expect(&Token::LParen, "`(` in function type")?;
                let mut params = Vec::new();
                if !self.check(&Token::RParen) {
                    params.push(self.parse_type()?);
                    while self.eat(&Token::Comma) {
                        params.push(self.parse_type()?);
                    }
                }
                self.expect(&Token::RParen, "`)` in function type")?;
                if !self.eat(&Token::Arrow) {
                    return Err(ParseError::Expected {
                        expected: "`->` before return type",
                        span: self.peek().span.clone(),
                    });
                }
                let ret = self.parse_type()?;
                Ok(Type::Function {
                    params,
                    ret: Box::new(ret),
                })
            }
            _ => Err(ParseError::Expected {
                expected: "a type",
                span: tok.span,
            }),
        }
    }

    /// Consumes a `<T, U, ...>` generic argument list, discarding the types.
    /// We assume `<` is currently the next token.
    pub(crate) fn skip_generic_args(&mut self) -> Result<(), ParseError> {
        self.expect(&Token::Lt, "`<`")?;
        let _ = self.parse_type()?;
        while self.eat(&Token::Comma) {
            let _ = self.parse_type()?;
        }
        self.expect(&Token::Gt, "`>` to close generic arguments")?;
        Ok(())
    }

    /// Consumes a `<T, U, ...>` *parameter* list on a function or method
    /// declaration and returns the type-parameter names. Unlike
    /// [`skip_generic_args`], every entry must be a bare identifier.
    pub(crate) fn parse_generic_params(&mut self) -> Result<Vec<String>, ParseError> {
        self.expect(&Token::Lt, "`<`")?;
        let mut params = Vec::new();
        let (first, _) = self.expect_ident("generic parameter name")?;
        params.push(first);
        while self.eat(&Token::Comma) {
            let (n, _) = self.expect_ident("generic parameter name")?;
            params.push(n);
        }
        self.expect(&Token::Gt, "`>` to close generic parameters")?;
        Ok(params)
    }

    /// Try to consume a generic-call instantiation `<T, U, ...>` immediately
    /// followed by `(`. Returns `true` if the consumption succeeded; restores
    /// the cursor and returns `false` otherwise (so the `<` can be parsed as
    /// a less-than operator instead). Used at call sites like
    /// `filter<integer>(nums, ...)`.
    pub(crate) fn try_eat_generic_call_args(&mut self) -> bool {
        let saved = self.pos;
        if !self.check(&Token::Lt) {
            return false;
        }
        // Try to consume a `<` ... `>` window where every entry parses as a
        // type. If the window doesn't end in `>(`, restore.
        self.advance(); // `<`
        if self.parse_type().is_err() {
            self.pos = saved;
            return false;
        }
        while self.eat(&Token::Comma) {
            if self.parse_type().is_err() {
                self.pos = saved;
                return false;
            }
        }
        if !self.eat(&Token::Gt) {
            self.pos = saved;
            return false;
        }
        if !self.check(&Token::LParen) {
            self.pos = saved;
            return false;
        }
        true
    }
}

//! Runtime values for the Saule interpreter.
//!
//! When adding a new variant, remember to extend [`Value::type_name`],
//! [`Value::is_truthy`], [`Value::to_display_string`], and the `PartialEq`
//! impl below.

use std::cell::RefCell;
use std::collections::HashMap;
use std::fmt;
use std::rc::Rc;

use saule_ast::{Expr, Param, Spanned, Stmt};

use crate::env::Environment;

/// A Saule runtime value.
#[derive(Debug, Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    /// Interned via `Rc` so cloning a value is cheap.
    Str(Rc<String>),
    /// Hybrid table storage: a dense array part plus a hashmap part. `table<T>`
    /// uses only the array; `table<K, V>` uses the map (and may also use the
    /// array when keys happen to be positive integers). Shared by reference so
    /// aliasing behaves like Lua tables.
    Table(Rc<RefCell<TableObject>>),
    /// Built-in function written in Rust (e.g. `print`).
    Native(Rc<NativeFn>),
    /// Built-in function with captured Rust state (e.g. iterators). Same call
    /// shape as `Native` but stateful and may return multiple values.
    NativeClosure(Rc<NativeClosure>),
    /// User-defined function or lambda. The `Rc` makes cloning cheap and
    /// gives recursive closures something stable to point at.
    Function(Rc<FunctionObject>),
    /// A class declaration — carries its statics, instance template, and
    /// optional parent. Compared by identity.
    Class(Rc<ClassObject>),
    /// An instance produced by `new ClassName(args)`. Fields are mutable
    /// behind a `RefCell`; identity is the `Rc` pointer.
    Instance(Rc<RefCell<InstanceObject>>),
    /// An enum variant: carries the enum name, variant name, and optional
    /// value. Compared by identity so each access to `Status.Alive` returns
    /// the same `Rc` pointer.
    EnumVariant(Rc<EnumVariantObject>),
    /// An enum declaration — carries its variants and methods.
    Enum(Rc<EnumObject>),
    /// An interface declaration — carries method signatures.
    Interface(Rc<InterfaceObject>),
    /// An open (or closed) file handle returned by `Io.open` and the
    /// `Io.stdin`/`stdout`/`stderr` statics. Methods are dispatched via a
    /// static table inside `stdlib::io`.
    File(Rc<RefCell<FileHandle>>),
}

/// Backing storage for a `Value::File`. Variants split read- and write-side
/// state so we can buffer line reads via `BufReader` while leaving writes
/// unbuffered (the caller can call `:flush` explicitly when needed).
pub enum FileHandle {
    Stdin(std::io::BufReader<std::io::Stdin>),
    Stdout,
    Stderr,
    Open {
        path: String,
        reader: Option<std::io::BufReader<std::fs::File>>,
        writer: Option<std::fs::File>,
    },
    Closed,
}

impl fmt::Debug for FileHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            FileHandle::Stdin(_) => write!(f, "<file stdin>"),
            FileHandle::Stdout => write!(f, "<file stdout>"),
            FileHandle::Stderr => write!(f, "<file stderr>"),
            FileHandle::Open { path, .. } => write!(f, "<file {path}>"),
            FileHandle::Closed => write!(f, "<closed file>"),
        }
    }
}

#[derive(Debug)]
pub struct EnumVariantObject {
    pub enum_name: String,
    pub variant_name: String,
    pub value: Option<Value>,
    /// Reference to the enum so we can access methods. Stored in RefCell to
    /// allow updating after enum creation (breaking the circular reference issue).
    pub enum_obj: std::cell::RefCell<Option<Rc<EnumObject>>>,
}

#[derive(Debug)]
pub struct EnumObject {
    pub name: String,
    /// Enum variants, keyed by name. Each variant is cached so identity is stable.
    pub variants: HashMap<String, Rc<EnumVariantObject>>,
    /// Methods defined on the enum, keyed by name.
    pub methods: HashMap<String, Rc<FunctionObject>>,
}

/// Rust-implemented function exposed to Saule.
///
/// The function returns `Result<Value, String>` where the error string is
/// surfaced as a `RuntimeError::TypeError` at the call site.
pub struct NativeFn {
    pub name: &'static str,
    pub func: fn(&[Value]) -> Result<Value, String>,
}

impl fmt::Debug for NativeFn {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "<native fn {}>", self.name)
    }
}

/// Stateful Rust-implemented function. The closure may capture arbitrary
/// Rust state (e.g. an iterator's cursor) and may return multiple values.
pub struct NativeClosure {
    pub name: &'static str,
    pub func: Box<dyn Fn(&[Value]) -> Result<Vec<Value>, String>>,
}

impl fmt::Debug for NativeClosure {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "<native closure {}>", self.name)
    }
}

/// A user-defined function carrying its body and lexical closure.
#[derive(Debug)]
pub struct FunctionObject {
    /// `Some(name)` for named declarations, `None` for lambdas.
    pub name: Option<String>,
    pub params: Vec<Param>,
    pub body: FunctionBody,
    /// The environment that was in scope when the function was created.
    /// Captured by reference so inner functions see live bindings.
    pub closure: Rc<RefCell<Environment>>,
    /// `Some(class)` when this function is a method (static or instance) of
    /// a class. Set after class construction via [`set_owner_class`]. The
    /// call sites consult this to re-inject the owning class's statics into
    /// the call scope, so a static method can reach sibling statics by their
    /// bare names even when invoked as a plain `Value::Function`.
    pub owner_class: RefCell<Option<std::rc::Weak<ClassObject>>>,
}

impl FunctionObject {
    /// Attach this function to its owning class. No-op when called more than
    /// once; the first owner wins.
    pub fn set_owner_class(&self, class: &Rc<ClassObject>) {
        let mut slot = self.owner_class.borrow_mut();
        if slot.is_none() {
            *slot = Some(Rc::downgrade(class));
        }
    }

    /// Resolve the owning class, if any. Returns `None` once the class has
    /// been dropped (which shouldn't happen in practice because the class
    /// outlives its methods).
    pub fn resolved_owner(&self) -> Option<Rc<ClassObject>> {
        self.owner_class.borrow().as_ref().and_then(|w| w.upgrade())
    }
}

/// Function bodies come in two shapes:
///   * a block of statements (named `fn` decls, block-body lambdas),
///   * a single expression (arrow-style lambdas like `(x) => x + 1`).
#[derive(Debug, Clone)]
pub enum FunctionBody {
    Block(Vec<Spanned<Stmt>>),
    Expr(Box<Spanned<saule_ast::Expr>>),
}

/// Runtime representation of a `class` declaration.
///
/// Instance fields live on the [`InstanceObject`]; statics live here (behind
/// a `RefCell` because they can be reassigned). Methods are stored as
/// already-constructed [`FunctionObject`]s capturing the module-level
/// environment so they can refer to other top-level names (including the
/// class itself for static calls).
#[derive(Debug)]
pub struct ClassObject {
    pub name: String,
    pub parent: Option<Rc<ClassObject>>,
    /// Instance-field templates evaluated on construction.
    pub field_defs: Vec<FieldDef>,
    /// Instance methods, keyed by name. First parameter is the user-written
    /// `self`, so calling `obj:method(a)` is the same as `method(obj, a)`.
    pub methods: HashMap<String, Rc<FunctionObject>>,
    /// Static fields. Mutable through `ClassName.field = …`.
    pub static_fields: RefCell<HashMap<String, Value>>,
    /// Static methods (no implicit `self`).
    pub static_methods: HashMap<String, Rc<FunctionObject>>,
    /// `constructor(args) … end`. None means the class has no explicit
    /// constructor — `new` still produces a valid instance.
    pub constructor: Option<Rc<FunctionObject>>,
}

#[derive(Debug, Clone)]
pub struct FieldDef {
    pub name: String,
    /// Evaluated in the constructor scope each time an instance is built.
    pub default: Option<Spanned<Expr>>,
}

#[derive(Debug)]
pub struct InstanceObject {
    pub class: Rc<ClassObject>,
    pub fields: HashMap<String, Value>,
}

impl ClassObject {
    /// Walk the inheritance chain for a method.
    pub fn lookup_method(self: &Rc<Self>, name: &str) -> Option<Rc<FunctionObject>> {
        if let Some(m) = self.methods.get(name) {
            return Some(m.clone());
        }
        self.parent.as_ref().and_then(|p| p.lookup_method(name))
    }

    /// Walk the inheritance chain for a static method.
    pub fn lookup_static_method(self: &Rc<Self>, name: &str) -> Option<Rc<FunctionObject>> {
        if let Some(m) = self.static_methods.get(name) {
            return Some(m.clone());
        }
        self.parent
            .as_ref()
            .and_then(|p| p.lookup_static_method(name))
    }

    /// Walk the inheritance chain for a static field.
    pub fn lookup_static_field(self: &Rc<Self>, name: &str) -> Option<Value> {
        if let Some(v) = self.static_fields.borrow().get(name) {
            return Some(v.clone());
        }
        self.parent
            .as_ref()
            .and_then(|p| p.lookup_static_field(name))
    }
}

impl Value {
    /// Human-readable type name for error messages — matches the names used
    /// in the README's type system.
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "boolean",
            Value::Int(_) => "integer",
            Value::Float(_) => "float",
            Value::Str(_) => "string",
            Value::Table(_) => "table",
            Value::Native(_) | Value::NativeClosure(_) | Value::Function(_) => "function",
            Value::Class(_) => "class",
            Value::Instance(_) => "instance",
            Value::EnumVariant(_) => "enum",
            Value::Enum(_) => "enum",
            Value::Interface(_) => "interface",
            Value::File(_) => "file",
        }
    }

    /// Lua-style truthiness: only `nil` and `false` are falsy.
    pub fn is_truthy(&self) -> bool {
        !matches!(self, Value::Nil | Value::Bool(false))
    }

    /// Format used by `print` and the `..` operator.
    pub fn to_display_string(&self) -> String {
        match self {
            Value::Nil => "nil".into(),
            Value::Bool(b) => b.to_string(),
            Value::Int(n) => n.to_string(),
            Value::Float(f) => {
                // Always show a decimal point so floats are visually distinct
                // from ints, matching the README's display style.
                if f.fract() == 0.0 && f.is_finite() {
                    format!("{f:.1}")
                } else {
                    f.to_string()
                }
            }
            Value::Str(s) => (**s).clone(),
            Value::Table(items) => {
                let t = items.borrow();
                let array_parts = t.array.iter().map(Value::to_display_string);
                let map_parts = t
                    .map
                    .iter()
                    .map(|(k, v)| format!("{}={}", k.display(), v.to_display_string()));
                let parts: Vec<String> = array_parts.chain(map_parts).collect();
                format!("{{{}}}", parts.join(", "))
            }
            Value::EnumVariant(ev) => {
                format!("{}.{}", ev.enum_name, ev.variant_name)
            }
            Value::Enum(e) => format!("<enum {}>", e.name),
            Value::Interface(iface) => format!("<interface {}>", iface.name),
            Value::Native(nf) => format!("<native fn {}>", nf.name),
            Value::NativeClosure(nc) => format!("<native fn {}>", nc.name),
            Value::Function(f) => match &f.name {
                Some(n) => format!("<fn {n}>"),
                None => "<lambda>".into(),
            },
            Value::Class(c) => format!("<class {}>", c.name),
            Value::Instance(i) => format!("<instance of {}>", i.borrow().class.name),
            Value::File(h) => format!("{:?}", h.borrow()),
        }
    }
}

// Equality is used by tests and by the `==` / `~=` operators. Functions
// (native or user-defined) compare by identity.
impl PartialEq for Value {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Table(a), Value::Table(b)) => Rc::ptr_eq(a, b),
            (Value::Native(a), Value::Native(b)) => Rc::ptr_eq(a, b),
            (Value::NativeClosure(a), Value::NativeClosure(b)) => Rc::ptr_eq(a, b),
            (Value::Function(a), Value::Function(b)) => Rc::ptr_eq(a, b),
            (Value::Class(a), Value::Class(b)) => Rc::ptr_eq(a, b),
            (Value::Instance(a), Value::Instance(b)) => Rc::ptr_eq(a, b),
            (Value::EnumVariant(a), Value::EnumVariant(b)) => Rc::ptr_eq(a, b),
            (Value::Enum(a), Value::Enum(b)) => Rc::ptr_eq(a, b),
            (Value::Interface(a), Value::Interface(b)) => Rc::ptr_eq(a, b),
            (Value::File(a), Value::File(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
}

/// Runtime representation of an `interface` declaration.
///
/// Carries the interface's method signatures. Used for compile-time and
/// runtime verification that implementing classes have the required methods.
#[derive(Debug)]
pub struct InterfaceObject {
    pub name: String,
    /// Parent interfaces (for interface extension).
    pub extends: Vec<String>,
    /// Method signatures required by this interface.
    /// Key is method name, value is (param_count, has_return_type).
    pub methods: HashMap<String, (usize, bool)>,
}

// ──────────────────────────────────────────────────────────────────────────────
// Tables — hybrid array + map storage.
//
// The static type system decides how a table is *typed* (`table<T>` array or
// `table<K, V>` map). At runtime there is a single representation so a table
// passed across these boundaries (e.g. through `any`) never has to be
// converted. Positive integer keys collapse into the dense `array` part so the
// common array iteration path stays a `Vec` walk.
// ──────────────────────────────────────────────────────────────────────────────

/// A hashable key for the map part of a table.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum TableKey {
    Int(i64),
    Str(String),
    Bool(bool),
}

impl TableKey {
    pub fn from_value(v: &Value) -> Option<TableKey> {
        match v {
            Value::Int(i) => Some(TableKey::Int(*i)),
            Value::Str(s) => Some(TableKey::Str((**s).clone())),
            Value::Bool(b) => Some(TableKey::Bool(*b)),
            _ => None,
        }
    }

    pub fn to_value(&self) -> Value {
        match self {
            TableKey::Int(i) => Value::Int(*i),
            TableKey::Str(s) => Value::Str(Rc::new(s.clone())),
            TableKey::Bool(b) => Value::Bool(*b),
        }
    }

    pub fn display(&self) -> String {
        match self {
            TableKey::Int(i) => i.to_string(),
            TableKey::Str(s) => format!("\"{s}\""),
            TableKey::Bool(b) => b.to_string(),
        }
    }
}

#[derive(Debug, Default)]
pub struct TableObject {
    /// 1-based logical indices stored 0-based here.
    pub array: Vec<Value>,
    /// All non-array entries (non-integer keys or sparse integer keys).
    pub map: HashMap<TableKey, Value>,
}

impl TableObject {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn from_array(items: Vec<Value>) -> Self {
        Self {
            array: items,
            map: HashMap::new(),
        }
    }

    /// Array length (Lua-style `#t`). Does not include map entries.
    pub fn array_len(&self) -> usize {
        self.array.len()
    }

    /// Read by arbitrary value index. Returns `Nil` for missing keys.
    pub fn get(&self, key: &Value) -> Value {
        if let Value::Int(i) = key {
            if *i >= 1 && (*i as usize) <= self.array.len() {
                return self.array[(*i as usize) - 1].clone();
            }
        }
        match TableKey::from_value(key) {
            Some(k) => self.map.get(&k).cloned().unwrap_or(Value::Nil),
            None => Value::Nil,
        }
    }

    /// Write by arbitrary value index. Positive integers ≤ len+1 grow the
    /// array part; everything else lands in the map.
    pub fn set(&mut self, key: &Value, value: Value) -> Result<(), String> {
        if let Value::Int(i) = key
            && *i >= 1
        {
            let slot = (*i as usize) - 1;
            if slot < self.array.len() {
                self.array[slot] = value;
                return Ok(());
            }
            if slot == self.array.len() {
                self.array.push(value);
                // Pull any contiguous map entries into the array.
                let mut next = self.array.len() as i64 + 1;
                while let Some(v) = self.map.remove(&TableKey::Int(next)) {
                    self.array.push(v);
                    next += 1;
                }
                return Ok(());
            }
        }
        let Some(k) = TableKey::from_value(key) else {
            return Err(format!(
                "table keys must be integer, string, or boolean, got `{}`",
                key.type_name()
            ));
        };
        self.map.insert(k, value);
        Ok(())
    }
}

//! Runtime values for the Saule interpreter.
//!
//! When adding a new variant, remember to extend [`Value::type_name`],
//! [`Value::is_truthy`], [`Value::to_display_string`], and the `PartialEq`
//! impl below.

use std::cell::RefCell;
use std::collections::HashMap;
use std::fmt;
use std::rc::Rc;

use saule_ast::{Expr, Param, Spanned, Stmt};

use crate::env::Environment;

/// A Saule runtime value.
#[derive(Debug, Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    /// Interned via `Rc` so cloning a value is cheap.
    Str(Rc<String>),
    /// Hybrid table storage: a dense array part plus a hashmap part. `table<T>`
    /// uses only the array; `table<K, V>` uses the map (and may also use the
    /// array when keys happen to be positive integers). Shared by reference so
    /// aliasing behaves like Lua tables.
    Table(Rc<RefCell<TableObject>>),
    /// Built-in function written in Rust (e.g. `print`).
    Native(Rc<NativeFn>),
    /// Built-in function with captured Rust state (e.g. iterators). Same call
    /// shape as `Native` but stateful and may return multiple values.
    NativeClosure(Rc<NativeClosure>),
    /// User-defined function or lambda. The `Rc` makes cloning cheap and
    /// gives recursive closures something stable to point at.
    Function(Rc<FunctionObject>),
    /// A class declaration — carries its statics, instance template, and
    /// optional parent. Compared by identity.
    Class(Rc<ClassObject>),
    /// An instance produced by `new ClassName(args)`. Fields are mutable
    /// behind a `RefCell`; identity is the `Rc` pointer.
    Instance(Rc<RefCell<InstanceObject>>),
    /// An enum variant: carries the enum name, variant name, and optional
    /// value. Compared by identity so each access to `Status.Alive` returns
    /// the same `Rc` pointer.
    EnumVariant(Rc<EnumVariantObject>),
    /// An enum declaration — carries its variants and methods.
    Enum(Rc<EnumObject>),
    /// An interface declaration — carries method signatures.
    Interface(Rc<InterfaceObject>),
    /// An open (or closed) file handle returned by `Io.open` and the
    /// `Io.stdin`/`stdout`/`stderr` statics. Methods are dispatched via a
    /// static table inside `stdlib::io`.
    File(Rc<RefCell<FileHandle>>),
}

/// Backing storage for a `Value::File`. Variants split read- and write-side
/// state so we can buffer line reads via `BufReader` while leaving writes
/// unbuffered (the caller can call `:flush` explicitly when needed).
pub enum FileHandle {
    Stdin(std::io::BufReader<std::io::Stdin>),
    Stdout,
    Stderr,
    Open {
        path: String,
        reader: Option<std::io::BufReader<std::fs::File>>,
        writer: Option<std::fs::File>,
    },
    Closed,
}

impl fmt::Debug for FileHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            FileHandle::Stdin(_) => write!(f, "<file stdin>"),
            FileHandle::Stdout => write!(f, "<file stdout>"),
            FileHandle::Stderr => write!(f, "<file stderr>"),
            FileHandle::Open { path, .. } => write!(f, "<file {path}>"),
            FileHandle::Closed => write!(f, "<closed file>"),
        }
    }
}

#[derive(Debug)]
pub struct EnumVariantObject {
    pub enum_name: String,
    pub variant_name: String,
    pub value: Option<Value>,
    /// Reference to the enum so we can access methods. Stored in RefCell to
    /// allow updating after enum creation (breaking the circular reference issue).
    pub enum_obj: std::cell::RefCell<Option<Rc<EnumObject>>>,
}

#[derive(Debug)]
pub struct EnumObject {
    pub name: String,
    /// Enum variants, keyed by name. Each variant is cached so identity is stable.
    pub variants: HashMap<String, Rc<EnumVariantObject>>,
    /// Tuple-style variants and their arity. These don't have a singleton
    /// instance; each call produces a fresh `EnumVariantObject` whose
    /// `value` is an array-style table of the positional arguments.
    pub tuple_variants: HashMap<String, usize>,
    /// Methods defined on the enum, keyed by name.
    pub methods: HashMap<String, Rc<FunctionObject>>,
}

/// Rust-implemented function exposed to Saule.
///
/// The function returns `Result<Value, String>` where the error string is
/// surfaced as a `RuntimeError::TypeError` at the call site.
pub struct NativeFn {
    pub name: &'static str,
    pub func: fn(&[Value]) -> Result<Value, String>,
}

impl fmt::Debug for NativeFn {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "<native fn {}>", self.name)
    }
}

/// Stateful Rust-implemented function. The closure may capture arbitrary
/// Rust state (e.g. an iterator's cursor) and may return multiple values.
pub struct NativeClosure {
    pub name: &'static str,
    pub func: Box<dyn Fn(&[Value]) -> Result<Vec<Value>, String>>,
}

impl fmt::Debug for NativeClosure {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "<native closure {}>", self.name)
    }
}

/// A user-defined function carrying its body and lexical closure.
#[derive(Debug)]
pub struct FunctionObject {
    /// `Some(name)` for named declarations, `None` for lambdas.
    pub name: Option<String>,
    pub params: Vec<Param>,
    pub body: FunctionBody,
    /// The environment that was in scope when the function was created.
    /// Captured by reference so inner functions see live bindings.
    pub closure: Rc<RefCell<Environment>>,
    /// `Some(class)` when this function is a method (static or instance) of
    /// a class. Set after class construction via [`set_owner_class`]. The
    /// call sites consult this to re-inject the owning class's statics into
    /// the call scope, so a static method can reach sibling statics by their
    /// bare names even when invoked as a plain `Value::Function`.
    pub owner_class: RefCell<Option<std::rc::Weak<ClassObject>>>,
}

impl FunctionObject {
    /// Attach this function to its owning class. No-op when called more than
    /// once; the first owner wins.
    pub fn set_owner_class(&self, class: &Rc<ClassObject>) {
        let mut slot = self.owner_class.borrow_mut();
        if slot.is_none() {
            *slot = Some(Rc::downgrade(class));
        }
    }

    /// Resolve the owning class, if any. Returns `None` once the class has
    /// been dropped (which shouldn't happen in practice because the class
    /// outlives its methods).
    pub fn resolved_owner(&self) -> Option<Rc<ClassObject>> {
        self.owner_class.borrow().as_ref().and_then(|w| w.upgrade())
    }
}

/// Function bodies come in two shapes:
///   * a block of statements (named `fn` decls, block-body lambdas),
///   * a single expression (arrow-style lambdas like `(x) => x + 1`).
#[derive(Debug, Clone)]
pub enum FunctionBody {
    Block(Vec<Spanned<Stmt>>),
    Expr(Box<Spanned<saule_ast::Expr>>),
}

/// Runtime representation of a `class` declaration.
///
/// Instance fields live on the [`InstanceObject`]; statics live here (behind
/// a `RefCell` because they can be reassigned). Methods are stored as
/// already-constructed [`FunctionObject`]s capturing the module-level
/// environment so they can refer to other top-level names (including the
/// class itself for static calls).
#[derive(Debug)]
pub struct ClassObject {
    pub name: String,
    pub parent: Option<Rc<ClassObject>>,
    /// Instance-field templates evaluated on construction.
    pub field_defs: Vec<FieldDef>,
    /// Instance methods, keyed by name. First parameter is the user-written
    /// `self`, so calling `obj:method(a)` is the same as `method(obj, a)`.
    pub methods: HashMap<String, Rc<FunctionObject>>,
    /// Static fields. Mutable through `ClassName.field = …`.
    pub static_fields: RefCell<HashMap<String, Value>>,
    /// Static methods (no implicit `self`).
    pub static_methods: HashMap<String, Rc<FunctionObject>>,
    /// `constructor(args) … end`. None means the class has no explicit
    /// constructor — `new` still produces a valid instance.
    pub constructor: Option<Rc<FunctionObject>>,
}

#[derive(Debug, Clone)]
pub struct FieldDef {
    pub name: String,
    /// Evaluated in the constructor scope each time an instance is built.
    pub default: Option<Spanned<Expr>>,
}

#[derive(Debug)]
pub struct InstanceObject {
    pub class: Rc<ClassObject>,
    pub fields: HashMap<String, Value>,
}

impl ClassObject {
    /// Walk the inheritance chain for a method.
    pub fn lookup_method(self: &Rc<Self>, name: &str) -> Option<Rc<FunctionObject>> {
        if let Some(m) = self.methods.get(name) {
            return Some(m.clone());
        }
        self.parent.as_ref().and_then(|p| p.lookup_method(name))
    }

    /// Walk the inheritance chain for a static method.
    pub fn lookup_static_method(self: &Rc<Self>, name: &str) -> Option<Rc<FunctionObject>> {
        if let Some(m) = self.static_methods.get(name) {
            return Some(m.clone());
        }
        self.parent
            .as_ref()
            .and_then(|p| p.lookup_static_method(name))
    }

    /// Walk the inheritance chain for a static field.
    pub fn lookup_static_field(self: &Rc<Self>, name: &str) -> Option<Value> {
        if let Some(v) = self.static_fields.borrow().get(name) {
            return Some(v.clone());
        }
        self.parent
            .as_ref()
            .and_then(|p| p.lookup_static_field(name))
    }
}

impl Value {
    /// Human-readable type name for error messages — matches the names used
    /// in the README's type system.
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "boolean",
            Value::Int(_) => "integer",
            Value::Float(_) => "float",
            Value::Str(_) => "string",
            Value::Table(_) => "table",
            Value::Native(_) | Value::NativeClosure(_) | Value::Function(_) => "function",
            Value::Class(_) => "class",
            Value::Instance(_) => "instance",
            Value::EnumVariant(_) => "enum",
            Value::Enum(_) => "enum",
            Value::Interface(_) => "interface",
            Value::File(_) => "file",
        }
    }

    /// Lua-style truthiness: only `nil` and `false` are falsy.
    pub fn is_truthy(&self) -> bool {
        !matches!(self, Value::Nil | Value::Bool(false))
    }

    /// Format used by `print` and the `..` operator.
    pub fn to_display_string(&self) -> String {
        match self {
            Value::Nil => "nil".into(),
            Value::Bool(b) => b.to_string(),
            Value::Int(n) => n.to_string(),
            Value::Float(f) => {
                // Always show a decimal point so floats are visually distinct
                // from ints, matching the README's display style.
                if f.fract() == 0.0 && f.is_finite() {
                    format!("{f:.1}")
                } else {
                    f.to_string()
                }
            }
            Value::Str(s) => (**s).clone(),
            Value::Table(items) => {
                let t = items.borrow();
                let array_parts = t.array.iter().map(Value::to_display_string);
                let map_parts = t
                    .map
                    .iter()
                    .map(|(k, v)| format!("{}={}", k.display(), v.to_display_string()));
                let parts: Vec<String> = array_parts.chain(map_parts).collect();
                format!("{{{}}}", parts.join(", "))
            }
            Value::EnumVariant(ev) => {
                format!("{}.{}", ev.enum_name, ev.variant_name)
            }
            Value::Enum(e) => format!("<enum {}>", e.name),
            Value::Interface(iface) => format!("<interface {}>", iface.name),
            Value::Native(nf) => format!("<native fn {}>", nf.name),
            Value::NativeClosure(nc) => format!("<native fn {}>", nc.name),
            Value::Function(f) => match &f.name {
                Some(n) => format!("<fn {n}>"),
                None => "<lambda>".into(),
            },
            Value::Class(c) => format!("<class {}>", c.name),
            Value::Instance(i) => format!("<instance of {}>", i.borrow().class.name),
            Value::File(h) => format!("{:?}", h.borrow()),
        }
    }
}

// Equality is used by tests and by the `==` / `~=` operators. Functions
// (native or user-defined) compare by identity.
impl PartialEq for Value {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Table(a), Value::Table(b)) => Rc::ptr_eq(a, b),
            (Value::Native(a), Value::Native(b)) => Rc::ptr_eq(a, b),
            (Value::NativeClosure(a), Value::NativeClosure(b)) => Rc::ptr_eq(a, b),
            (Value::Function(a), Value::Function(b)) => Rc::ptr_eq(a, b),
            (Value::Class(a), Value::Class(b)) => Rc::ptr_eq(a, b),
            (Value::Instance(a), Value::Instance(b)) => Rc::ptr_eq(a, b),
            (Value::EnumVariant(a), Value::EnumVariant(b)) => Rc::ptr_eq(a, b),
            (Value::Enum(a), Value::Enum(b)) => Rc::ptr_eq(a, b),
            (Value::Interface(a), Value::Interface(b)) => Rc::ptr_eq(a, b),
            (Value::File(a), Value::File(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
}

/// Runtime representation of an `interface` declaration.
///
/// Carries the interface's method signatures. Used for compile-time and
/// runtime verification that implementing classes have the required methods.
#[derive(Debug)]
pub struct InterfaceObject {
    pub name: String,
    /// Parent interfaces (for interface extension).
    pub extends: Vec<String>,
    /// Method signatures required by this interface.
    /// Key is method name, value is (param_count, has_return_type).
    pub methods: HashMap<String, (usize, bool)>,
}

// ──────────────────────────────────────────────────────────────────────────────
// Tables — hybrid array + map storage.
//
// The static type system decides how a table is *typed* (`table<T>` array or
// `table<K, V>` map). At runtime there is a single representation so a table
// passed across these boundaries (e.g. through `any`) never has to be
// converted. Positive integer keys collapse into the dense `array` part so the
// common array iteration path stays a `Vec` walk.
// ──────────────────────────────────────────────────────────────────────────────

/// A hashable key for the map part of a table.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum TableKey {
    Int(i64),
    Str(String),
    Bool(bool),
}

impl TableKey {
    pub fn from_value(v: &Value) -> Option<TableKey> {
        match v {
            Value::Int(i) => Some(TableKey::Int(*i)),
            Value::Str(s) => Some(TableKey::Str((**s).clone())),
            Value::Bool(b) => Some(TableKey::Bool(*b)),
            _ => None,
        }
    }

    pub fn to_value(&self) -> Value {
        match self {
            TableKey::Int(i) => Value::Int(*i),
            TableKey::Str(s) => Value::Str(Rc::new(s.clone())),
            TableKey::Bool(b) => Value::Bool(*b),
        }
    }

    pub fn display(&self) -> String {
        match self {
            TableKey::Int(i) => i.to_string(),
            TableKey::Str(s) => format!("\"{s}\""),
            TableKey::Bool(b) => b.to_string(),
        }
    }
}

#[derive(Debug, Default)]
pub struct TableObject {
    /// 1-based logical indices stored 0-based here.
    pub array: Vec<Value>,
    /// All non-array entries (non-integer keys or sparse integer keys).
    pub map: HashMap<TableKey, Value>,
}

impl TableObject {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn from_array(items: Vec<Value>) -> Self {
        Self {
            array: items,
            map: HashMap::new(),
        }
    }

    /// Array length (Lua-style `#t`). Does not include map entries.
    pub fn array_len(&self) -> usize {
        self.array.len()
    }

    /// Read by arbitrary value index. Returns `Nil` for missing keys.
    pub fn get(&self, key: &Value) -> Value {
        if let Value::Int(i) = key {
            if *i >= 1 && (*i as usize) <= self.array.len() {
                return self.array[(*i as usize) - 1].clone();
            }
        }
        match TableKey::from_value(key) {
            Some(k) => self.map.get(&k).cloned().unwrap_or(Value::Nil),
            None => Value::Nil,
        }
    }

    /// Write by arbitrary value index. Positive integers ≤ len+1 grow the
    /// array part; everything else lands in the map.
    pub fn set(&mut self, key: &Value, value: Value) -> Result<(), String> {
        if let Value::Int(i) = key
            && *i >= 1
        {
            let slot = (*i as usize) - 1;
            if slot < self.array.len() {
                self.array[slot] = value;
                return Ok(());
            }
            if slot == self.array.len() {
                self.array.push(value);
                // Pull any contiguous map entries into the array.
                let mut next = self.array.len() as i64 + 1;
                while let Some(v) = self.map.remove(&TableKey::Int(next)) {
                    self.array.push(v);
                    next += 1;
                }
                return Ok(());
            }
        }
        let Some(k) = TableKey::from_value(key) else {
            return Err(format!(
                "table keys must be integer, string, or boolean, got `{}`",
                key.type_name()
            ));
        };
        self.map.insert(k, value);
        Ok(())
    }
}
